// Linguistics — Chapter 4 shared helpers: embedded public-domain texts, tokenising and rank-frequency tools, a syllable counter,
// a letter-level guessing model (Shannon's game) and a word n-gram model. Re-exports the chapter 3 helpers (and thus chapter 2's).
export * from './ch03.shared.js';

export const TEXT_LABELS = { alice: 'Alice in Wonderland (English)', pride: 'Pride and Prejudice (English)', de: 'Die Verwandlung (German)', fr: 'Candide (French)', es: 'Don Quijote (Spanish)' };
export const TEXT_SHORT = { alice: 'Alice', pride: 'Pride & Prej.', de: 'Deutsch', fr: 'Français', es: 'Español' };

// ------------------------------------------------------------------ words and ranks
export const tokenize = (s) => (s.toLowerCase().match(/[a-zà-ÿœæß]+(?:'[a-zà-ÿ]+)*/g) || []);
/** [[word, count], …] sorted by decreasing count (ties alphabetical). */
export function rankFreq(tokens) {
  const m = new Map(); for (const w of tokens) m.set(w, (m.get(w) || 0) + 1);
  return [...m.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
}
/** Least-squares line of ln f on ln r over ranks r0..r1 (1-based, inclusive): {slope, icpt, r2}. */
export function fitLogLog(rf, r0, r1) {
  r1 = Math.min(r1, rf.length); let n = 0, sx = 0, sy = 0, sxx = 0, sxy = 0, syy = 0;
  for (let r = r0; r <= r1; r++) { const x = Math.log(r), y = Math.log(rf[r - 1][1]); n++; sx += x; sy += y; sxx += x * x; sxy += x * y; syy += y * y; }
  if (n < 2) return { slope: NaN, icpt: NaN, r2: NaN };
  const slope = (n * sxy - sx * sy) / (n * sxx - sx * sx), icpt = (sy - slope * sx) / n;
  const r = (n * sxy - sx * sy) / Math.sqrt((n * sxx - sx * sx) * (n * syy - sy * sy));
  return { slope, icpt, r2: r * r };
}
/** Vocabulary growth: [[N, V(N)], …] at about `pts` log-spaced N (always including the last). */
export function vocabGrowth(tokens, pts = 120) {
  const seen = new Set(), marks = new Set(); const n = tokens.length;
  for (let k = 0; k < pts; k++) marks.add(Math.max(1, Math.round(Math.exp(Math.log(n) * k / (pts - 1)))));
  const out = [];
  for (let i = 0; i < n; i++) { seen.add(tokens[i]); if (marks.has(i + 1)) out.push([i + 1, seen.size]); }
  return out;
}
/** Spearman rank correlation with mid-ranks for ties. */
export function spearman(x, y) {
  const rk = (a) => { const idx = a.map((v, i) => [v, i]).sort((p, q) => p[0] - q[0]); const r = new Array(a.length); let i = 0;
    while (i < idx.length) { let j = i; while (j + 1 < idx.length && idx[j + 1][0] === idx[i][0]) j++; const m = (i + j) / 2 + 1; for (let k = i; k <= j; k++) r[idx[k][1]] = m; i = j + 1; } return r; };
  const a = rk(x), b = rk(y), n = a.length; const ma = a.reduce((s, v) => s + v, 0) / n, mb = b.reduce((s, v) => s + v, 0) / n;
  let sab = 0, saa = 0, sbb = 0; for (let i = 0; i < n; i++) { sab += (a[i] - ma) * (b[i] - mb); saa += (a[i] - ma) ** 2; sbb += (b[i] - mb) ** 2; }
  return sab / Math.sqrt(saa * sbb);
}
/** Rough syllable count: groups of vowel letters, with silent final -e / -es / -ed adjustments (English). A heuristic, not a dictionary. */
export function syllables(w, lang = 'en') {
  w = w.toLowerCase().replace(/[^a-zà-ÿ]/g, ''); if (!w) return 0;
  const V = lang === 'en' ? 'aeiouy' : 'aeiouyäöüéèàáíóúâêîôû';
  let n = 0, prev = false;
  for (const ch of w) { const isV = V.includes(ch); if (isV && !prev) n++; prev = isV; }
  if (lang === 'en') {
    if (/[^aeiouy]e$/.test(w) && !/le$/.test(w) && n > 1) n--;
    else if (/[^aeiouy]ed$/.test(w) && !/[td]ed$/.test(w) && n > 1) n--;
    else if (/[^aeiouyslxzch]es$/.test(w) && n > 1) n--;
  }
  return Math.max(1, n);
}
export const log2 = (x) => Math.log2(x);

// ------------------------------------------------------------------ 27-symbol text (letters and space) and the guessing model
export const SYMS = 'abcdefghijklmnopqrstuvwxyz ';
export function toSyms(text) {
  const s = text.toLowerCase().replace(/[^a-z]+/g, ' ').replace(/^ /, '');
  const out = new Int8Array(s.length); for (let i = 0; i < s.length; i++) out[i] = s[i] === ' ' ? 26 : s.charCodeAt(i) - 97; return out;
}
/** Order-k letter model: counts[o] for o = 0..k is a Float32Array(27^(o+1)) of (context of o letters, next letter). */
export function letterModel(syms, k = 3) {
  const counts = [];
  for (let o = 0; o <= k; o++) {
    const c = new Float32Array(Math.pow(27, o + 1));
    for (let i = o; i < syms.length; i++) { let key = 0; for (let j = i - o; j <= i; j++) key = key * 27 + syms[j]; c[key]++; }
    counts.push(c);
  }
  return { k, counts };
}
/** Scores (higher = guessed earlier) of the 27 symbols given the preceding symbols `ctx` (array, any length) for a model used at order k. */
export function letterScores(model, ctx, k) {
  const sc = new Float64Array(27); k = Math.min(k, model.k, ctx.length);
  for (let o = 0; o <= k; o++) {
    let base = 0; for (let j = ctx.length - o; j < ctx.length; j++) base = base * 27 + ctx[j];
    base *= 27; const c = model.counts[o]; let tot = 0; for (let s = 0; s < 27; s++) tot += c[base + s];
    if (tot === 0) continue; const w = Math.pow(1e-6, k - o);
    for (let s = 0; s < 27; s++) sc[s] += (c[base + s] / tot) * w;
  }
  return sc;
}
/** Guess order of the 27 symbols (best first) for a context. */
export function guessOrder(model, ctx, k) {
  const sc = letterScores(model, ctx, k); return [...Array(27).keys()].sort((a, b) => sc[b] - sc[a] || a - b);
}
/** Run an order-k predictor over `syms`: returns the 27-vector q of relative frequencies of "right on guess i". */
export function guessDistribution(model, syms, k) {
  const q = new Array(27).fill(0);
  for (let i = 0; i < syms.length; i++) { const ord = guessOrder(model, Array.from(syms.subarray(Math.max(0, i - k), i)), k); q[ord.indexOf(syms[i])]++; }
  return q.map((x) => x / syms.length);
}
/** Shannon eq. 17: the lower bound requires ideal probability-ranked guesses. Input is guess-number frequencies q[0..26] (q[i] = freq. of guess number i+1). */
export function shannonBounds(q) {
  let up = 0, lo = 0;
  for (let i = 0; i < q.length; i++) { if (q[i] > 0) up -= q[i] * log2(q[i]); lo += (i + 1) * (q[i] - (q[i + 1] || 0)) * log2(i + 1); }
  return { upper: up, lower: lo };
}
/** Exact ideal-predictor guess profile of the empirical order-k conditional source, not a held-out predictor. */
export function idealGuessProfile(model, k) {
  const c = model.counts[k], q = new Array(27).fill(0); let total = 0, entropy = 0;
  for (let j = 0; j < c.length; j += 27) {
    const row = Array.from(c.subarray(j, j + 27)).sort((a, b) => b - a), mass = row.reduce((a, b) => a + b, 0);
    if (!mass) continue;
    total += mass;
    row.forEach((x, i) => { q[i] += x; if (x) entropy -= x * Math.log2(x / mass); });
  }
  return { q: q.map((x) => x / total), entropy: entropy / total };
}
/** N-gram letter entropies F1, F2, F3 (bits per letter, 27 symbols) estimated from a symbol sequence. */
export function letterEntropies(syms) {
  const H = [0];
  for (let n = 1; n <= 3; n++) {
    const c = new Map(); for (let i = n - 1; i < syms.length; i++) { let key = 0; for (let j = i - n + 1; j <= i; j++) key = key * 27 + syms[j]; c.set(key, (c.get(key) || 0) + 1); }
    const tot = syms.length - n + 1; let h = 0; for (const v of c.values()) h -= (v / tot) * log2(v / tot); H.push(h);
  }
  return [H[1], H[2] - H[1], H[3] - H[2]];
}

// ------------------------------------------------------------------ word n-gram model (4.9)
export function wordModel(tokens, maxN = 4) {
  const cnt = new Map(); for (const w of tokens) cnt.set(w, (cnt.get(w) || 0) + 1);
  const toks = tokens.map((w) => (cnt.get(w) === 1 ? '<unk>' : w));
  const vocab = new Set([...toks, '<unk>']); const grams = [], contexts = [];
  for (let n = 1; n <= maxN; n++) {
    const m = new Map(), totals = new Map();
    for (let i = n - 1; i < toks.length; i++) {
      const h = toks.slice(i - n + 1, i).join(' '), k = (h ? h + ' ' : '') + toks[i];
      m.set(k, (m.get(k) || 0) + 1); totals.set(h, (totals.get(h) || 0) + 1);
    }
    grams.push(m); contexts.push(totals);
  }
  return { toks, vocab, V: vocab.size, N: toks.length, grams, contexts, maxN };
}
const hist = (t, i, len) => t.slice(Math.max(0, i - len), i);
/** Normalized next-word probability; only contexts with a recorded successor count in the denominator. */
export function wordProb(M, t, i, n, mode, lam) {
  n = Math.min(n, M.maxN, i + 1);
  const w = M.vocab.has(t[i]) ? t[i] : '<unk>';
  const row = (o) => {
    const h = hist(t, i, o - 1).map((x) => M.vocab.has(x) ? x : '<unk>').join(' ');
    return [M.grams[o - 1].get((h ? h + ' ' : '') + w) || 0, M.contexts[o - 1].get(h) || 0];
  };
  if (mode === 'add') {
    const [c, ch] = row(n), d = ch + lam * M.V;
    return d ? (c + lam) / d : 0;
  }
  const base = [0.02, 0.2, 0.3, 0.3, 0.3]; let p = base[0] / M.V, wsum = base[0];
  for (let o = 1; o <= n; o++) { const [c, ch] = row(o); if (ch) { p += base[o] * c / ch; wsum += base[o]; } }
  return p / wsum;
}
export function perplexity(M, test, n, mode, lam) {
  const t = test.map((w) => (M.vocab.has(w) ? w : '<unk>')); let s = 0;
  for (let i = 0; i < t.length; i++) { const p = wordProb(M, t, i, n, mode, lam); if (!p) return Infinity; s -= Math.log2(p); }
  return t.length ? Math.pow(2, s / t.length) : NaN;
}
/** Sample the same smoothed distribution used for perplexity, including the explicit unknown token. */
export function generateWords(M, n, len, r, mode = 'interp', lam = 0.05) {
  const out = [], vocab = [...M.vocab];
  for (let i = 0; i < len; i++) {
    let u = r(), chosen = vocab[vocab.length - 1];
    for (const w of vocab) { if ((u -= wordProb(M, [...out, w], i, n, mode, lam)) <= 0) { chosen = w; break; } }
    out.push(chosen);
  }
  return out;
}

// ------------------------------------------------------------------ embedded texts (Project Gutenberg, public domain; whitespace normalised, headers and licence stripped)
// Alice's Adventures in Wonderland (PG 11, complete), Pride and Prejudice (PG 1342, first 22 000 words), Die Verwandlung (PG 22367, first 16 000 words),
// Candide (PG 4650, first 16 000 words), Don Quijote (PG 2000, first 18 000 words); the Frankenstein passage (PG 84) is a held-out test text.
export const TEXTS = {"alice":"CHAPTER I. Down the Rabbit-Hole CHAPTER II. The Pool of Tears CHAPTER III. A Caucus-Race and a Long Tale CHAPTER IV. The Rabbit Sends in a Little Bill CHAPTER V. Advice from a Caterpillar CHAPTER VI. Pig and Pepper CHAPTER VII. A Mad Tea-Party CHAPTER VIII. The Queen's Croquet-Ground CHAPTER IX. The Mock Turtle's Story CHAPTER X. The Lobster Quadrille CHAPTER XI. Who Stole the Tarts? CHAPTER XII. Alice's Evidence CHAPTER I. Down the Rabbit-Hole Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do: once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it, \"and what is the use of a book,\" thought Alice \"without pictures or conversations?\" So she was considering in her own mind (as well as she could, for the hot day made her feel very sleepy and stupid), whether the pleasure of making a daisy-chain would be worth the trouble of getting up and picking the daisies, when suddenly a White Rabbit with pink eyes ran close by her. There was nothing so very remarkable in that; nor did Alice think it so very much out of the way to hear the Rabbit say to itself, \"Oh dear! Oh dear! I shall be late!\" (when she thought it over afterwards, it occurred to her that she ought to have wondered at this, but at the time it all seemed quite natural); but when the Rabbit actually took a watch out of its waistcoat-pocket, and looked at it, and then hurried on, Alice started to her feet, for it flashed across her mind that she had never before seen a rabbit with either a waistcoat-pocket, or a watch to take out of it, and burning with curiosity, she ran across the field after it, and fortunately was just in time to see it pop down a large rabbit-hole under the hedge. In another moment down went Alice after it, never once considering how in the world she was to get out again. The rabbit-hole went straight on like a tunnel for some way, and then dipped suddenly down, so suddenly that Alice had not a moment to think about stopping herself before she found herself falling down a very deep well. Either the well was very deep, or she fell very slowly, for she had plenty of time as she went down to look about her and to wonder what was going to happen next. First, she tried to look down and make out what she was coming to, but it was too dark to see anything; then she looked at the sides of the well, and noticed that they were filled with cupboards and book-shelves; here and there she saw maps and pictures hung upon pegs. She took down a jar from one of the shelves as she passed; it was labelled \"ORANGE MARMALADE\", but to her great disappointment it was empty: she did not like to drop the jar for fear of killing somebody underneath, so managed to put it into one of the cupboards as she fell past it. \"Well!\" thought Alice to herself, \"after such a fall as this, I shall think nothing of tumbling down stairs! How brave they'll all think me at home! Why, I wouldn't say anything about it, even if I fell off the top of the house!\" (Which was very likely true.) Down, down, down. Would the fall never come to an end? \"I wonder how many miles I've fallen by this time?\" she said aloud. \"I must be getting somewhere near the centre of the earth. Let me see: that would be four thousand miles down, I think—\" (for, you see, Alice had learnt several things of this sort in her lessons in the schoolroom, and though this was not a very good opportunity for showing off her knowledge, as there was no one to listen to her, still it was good practice to say it over) \"—yes, that's about the right distance—but then I wonder what Latitude or Longitude I've got to?\" (Alice had no idea what Latitude was, or Longitude either, but thought they were nice grand words to say.) Presently she began again. \"I wonder if I shall fall right through the earth! How funny it'll seem to come out among the people that walk with their heads downward! The Antipathies, I think—\" (she was rather glad there was no one listening, this time, as it didn't sound at all the right word) \"—but I shall have to ask them what the name of the country is, you know. Please, Ma'am, is this New Zealand or Australia?\" (and she tried to curtsey as she spoke—fancy curtseying as you're falling through the air! Do you think you could manage it?) \"And what an ignorant little girl she'll think me for asking! No, it'll never do to ask: perhaps I shall see it written up somewhere.\" Down, down, down. There was nothing else to do, so Alice soon began talking again. \"Dinah'll miss me very much to-night, I should think!\" (Dinah was the cat.) \"I hope they'll remember her saucer of milk at tea-time. Dinah my dear! I wish you were down here with me! There are no mice in the air, I'm afraid, but you might catch a bat, and that's very like a mouse, you know. But do cats eat bats, I wonder?\" And here Alice began to get rather sleepy, and went on saying to herself, in a dreamy sort of way, \"Do cats eat bats? Do cats eat bats?\" and sometimes, \"Do bats eat cats?\" for, you see, as she couldn't answer either question, it didn't much matter which way she put it. She felt that she was dozing off, and had just begun to dream that she was walking hand in hand with Dinah, and saying to her very earnestly, \"Now, Dinah, tell me the truth: did you ever eat a bat?\" when suddenly, thump! thump! down she came upon a heap of sticks and dry leaves, and the fall was over. Alice was not a bit hurt, and she jumped up on to her feet in a moment: she looked up, but it was all dark overhead; before her was another long passage, and the White Rabbit was still in sight, hurrying down it. There was not a moment to be lost: away went Alice like the wind, and was just in time to hear it say, as it turned a corner, \"Oh my ears and whiskers, how late it's getting!\" She was close behind it when she turned the corner, but the Rabbit was no longer to be seen: she found herself in a long, low hall, which was lit up by a row of lamps hanging from the roof. There were doors all round the hall, but they were all locked; and when Alice had been all the way down one side and up the other, trying every door, she walked sadly down the middle, wondering how she was ever to get out again. Suddenly she came upon a little three-legged table, all made of solid glass; there was nothing on it except a tiny golden key, and Alice's first thought was that it might belong to one of the doors of the hall; but, alas! either the locks were too large, or the key was too small, but at any rate it would not open any of them. However, on the second time round, she came upon a low curtain she had not noticed before, and behind it was a little door about fifteen inches high: she tried the little golden key in the lock, and to her great delight it fitted! Alice opened the door and found that it led into a small passage, not much larger than a rat-hole: she knelt down and looked along the passage into the loveliest garden you ever saw. How she longed to get out of that dark hall, and wander about among those beds of bright flowers and those cool fountains, but she could not even get her head through the doorway; \"and even if my head would go through,\" thought poor Alice, \"it would be of very little use without my shoulders. Oh, how I wish I could shut up like a telescope! I think I could, if I only knew how to begin.\" For, you see, so many out-of-the-way things had happened lately, that Alice had begun to think that very few things indeed were really impossible. There seemed to be no use in waiting by the little door, so she went back to the table, half hoping she might find another key on it, or at any rate a book of rules for shutting people up like telescopes: this time she found a little bottle on it, (\"which certainly was not here before,\" said Alice,) and round the neck of the bottle was a paper label, with the words \"DRINK ME,\" beautifully printed on it in large letters. It was all very well to say \"Drink me,\" but the wise little Alice was not going to do that in a hurry. \"No, I'll look first,\" she said, \"and see whether it's marked 'poison' or not\"; for she had read several nice little histories about children who had got burnt, and eaten up by wild beasts and other unpleasant things, all because they would not remember the simple rules their friends had taught them: such as, that a red-hot poker will burn you if you hold it too long; and that if you cut your finger very deeply with a knife, it usually bleeds; and she had never forgotten that, if you drink much from a bottle marked \"poison,\" it is almost certain to disagree with you, sooner or later. However, this bottle was not marked \"poison,\" so Alice ventured to taste it, and finding it very nice, (it had, in fact, a sort of mixed flavour of cherry-tart, custard, pine-apple, roast turkey, toffee, and hot buttered toast,) she very soon finished it off. * * * * * * * * * * * * * * * * * * * * \"What a curious feeling!\" said Alice; \"I must be shutting up like a telescope.\" And so it was indeed: she was now only ten inches high, and her face brightened up at the thought that she was now the right size for going through the little door into that lovely garden. First, however, she waited for a few minutes to see if she was going to shrink any further: she felt a little nervous about this; \"for it might end, you know,\" said Alice to herself, \"in my going out altogether, like a candle. I wonder what I should be like then?\" And she tried to fancy what the flame of a candle is like after the candle is blown out, for she could not remember ever having seen such a thing. After a while, finding that nothing more happened, she decided on going into the garden at once; but, alas for poor Alice! when she got to the door, she found she had forgotten the little golden key, and when she went back to the table for it, she found she could not possibly reach it: she could see it quite plainly through the glass, and she tried her best to climb up one of the legs of the table, but it was too slippery; and when she had tired herself out with trying, the poor little thing sat down and cried. \"Come, there's no use in crying like that!\" said Alice to herself, rather sharply; \"I advise you to leave off this minute!\" She generally gave herself very good advice, (though she very seldom followed it), and sometimes she scolded herself so severely as to bring tears into her eyes; and once she remembered trying to box her own ears for having cheated herself in a game of croquet she was playing against herself, for this curious child was very fond of pretending to be two people. \"But it's no use now,\" thought poor Alice, \"to pretend to be two people! Why, there's hardly enough of me left to make one respectable person!\" Soon her eye fell on a little glass box that was lying under the table: she opened it, and found in it a very small cake, on which the words \"EAT ME\" were beautifully marked in currants. \"Well, I'll eat it,\" said Alice, \"and if it makes me grow larger, I can reach the key; and if it makes me grow smaller, I can creep under the door; so either way I'll get into the garden, and I don't care which happens!\" She ate a little bit, and said anxiously to herself, \"Which way? Which way?\", holding her hand on the top of her head to feel which way it was growing, and she was quite surprised to find that she remained the same size: to be sure, this generally happens when one eats cake, but Alice had got so much into the way of expecting nothing but out-of-the-way things to happen, that it seemed quite dull and stupid for life to go on in the common way. So she set to work, and very soon finished off the cake. * * * * * * * * * * * * * * * * * * * * CHAPTER II. The Pool of Tears \"Curiouser and curiouser!\" cried Alice (she was so much surprised, that for the moment she quite forgot how to speak good English); \"now I'm opening out like the largest telescope that ever was! Good-bye, feet!\" (for when she looked down at her feet, they seemed to be almost out of sight, they were getting so far off). \"Oh, my poor little feet, I wonder who will put on your shoes and stockings for you now, dears? I'm sure I shan't be able! I shall be a great deal too far off to trouble myself about you: you must manage the best way you can;—but I must be kind to them,\" thought Alice, \"or perhaps they won't walk the way I want to go! Let me see: I'll give them a new pair of boots every Christmas.\" And she went on planning to herself how she would manage it. \"They must go by the carrier,\" she thought; \"and how funny it'll seem, sending presents to one's own feet! And how odd the directions will look! Alice's Right Foot, Esq., Hearthrug, near the Fender, (with Alice's love). Oh dear, what nonsense I'm talking!\" Just then her head struck against the roof of the hall: in fact she was now more than nine feet high, and she at once took up the little golden key and hurried off to the garden door. Poor Alice! It was as much as she could do, lying down on one side, to look through into the garden with one eye; but to get through was more hopeless than ever: she sat down and began to cry again. \"You ought to be ashamed of yourself,\" said Alice, \"a great girl like you,\" (she might well say this), \"to go on crying in this way! Stop this moment, I tell you!\" But she went on all the same, shedding gallons of tears, until there was a large pool all round her, about four inches deep and reaching half down the hall. After a time she heard a little pattering of feet in the distance, and she hastily dried her eyes to see what was coming. It was the White Rabbit returning, splendidly dressed, with a pair of white kid gloves in one hand and a large fan in the other: he came trotting along in a great hurry, muttering to himself as he came, \"Oh! the Duchess, the Duchess! Oh! won't she be savage if I've kept her waiting!\" Alice felt so desperate that she was ready to ask help of any one; so, when the Rabbit came near her, she began, in a low, timid voice, \"If you please, sir—\" The Rabbit started violently, dropped the white kid gloves and the fan, and skurried away into the darkness as hard as he could go. Alice took up the fan and gloves, and, as the hall was very hot, she kept fanning herself all the time she went on talking: \"Dear, dear! How queer everything is to-day! And yesterday things went on just as usual. I wonder if I've been changed in the night? Let me think: was I the same when I got up this morning? I almost think I can remember feeling a little different. But if I'm not the same, the next question is, Who in the world am I? Ah, that's the great puzzle!\" And she began thinking over all the children she knew that were of the same age as herself, to see if she could have been changed for any of them. \"I'm sure I'm not Ada,\" she said, \"for her hair goes in such long ringlets, and mine doesn't go in ringlets at all; and I'm sure I can't be Mabel, for I know all sorts of things, and she, oh! she knows such a very little! Besides, she's she, and I'm I, and—oh dear, how puzzling it all is! I'll try if I know all the things I used to know. Let me see: four times five is twelve, and four times six is thirteen, and four times seven is—oh dear! I shall never get to twenty at that rate! However, the Multiplication Table doesn't signify: let's try Geography. London is the capital of Paris, and Paris is the capital of Rome, and Rome—no, that's all wrong, I'm certain! I must have been changed for Mabel! I'll try and say 'How doth the little—'\" and she crossed her hands on her lap as if she were saying lessons, and began to repeat it, but her voice sounded hoarse and strange, and the words did not come the same as they used to do:— \"How doth the little crocodile Improve his shining tail, And pour the waters of the Nile On every golden scale! \"How cheerfully he seems to grin, How neatly spread his claws, And welcome little fishes in With gently smiling jaws!\" \"I'm sure those are not the right words,\" said poor Alice, and her eyes filled with tears again as she went on, \"I must be Mabel after all, and I shall have to go and live in that poky little house, and have next to no toys to play with, and oh! ever so many lessons to learn! No, I've made up my mind about it; if I'm Mabel, I'll stay down here! It'll be no use their putting their heads down and saying 'Come up again, dear!' I shall only look up and say 'Who am I then? Tell me that first, and then, if I like being that person, I'll come up: if not, I'll stay down here till I'm somebody else'—but, oh dear!\" cried Alice, with a sudden burst of tears, \"I do wish they would put their heads down! I am so very tired of being all alone here!\" As she said this she looked down at her hands, and was surprised to see that she had put on one of the Rabbit's little white kid gloves while she was talking. \"How can I have done that?\" she thought. \"I must be growing small again.\" She got up and went to the table to measure herself by it, and found that, as nearly as she could guess, she was now about two feet high, and was going on shrinking rapidly: she soon found out that the cause of this was the fan she was holding, and she dropped it hastily, just in time to avoid shrinking away altogether. \"That was a narrow escape!\" said Alice, a good deal frightened at the sudden change, but very glad to find herself still in existence; \"and now for the garden!\" and she ran with all speed back to the little door: but, alas! the little door was shut again, and the little golden key was lying on the glass table as before, \"and things are worse than ever,\" thought the poor child, \"for I never was so small as this before, never! And I declare it's too bad, that it is!\" As she said these words her foot slipped, and in another moment, splash! she was up to her chin in salt water. Her first idea was that she had somehow fallen into the sea, \"and in that case I can go back by railway,\" she said to herself. (Alice had been to the seaside once in her life, and had come to the general conclusion, that wherever you go to on the English coast you find a number of bathing machines in the sea, some children digging in the sand with wooden spades, then a row of lodging houses, and behind them a railway station.) However, she soon made out that she was in the pool of tears which she had wept when she was nine feet high. \"I wish I hadn't cried so much!\" said Alice, as she swam about, trying to find her way out. \"I shall be punished for it now, I suppose, by being drowned in my own tears! That will be a queer thing, to be sure! However, everything is queer to-day.\" Just then she heard something splashing about in the pool a little way off, and she swam nearer to make out what it was: at first she thought it must be a walrus or hippopotamus, but then she remembered how small she was now, and she soon made out that it was only a mouse that had slipped in like herself. \"Would it be of any use, now,\" thought Alice, \"to speak to this mouse? Everything is so out-of-the-way down here, that I should think very likely it can talk: at any rate, there's no harm in trying.\" So she began: \"O Mouse, do you know the way out of this pool? I am very tired of swimming about here, O Mouse!\" (Alice thought this must be the right way of speaking to a mouse: she had never done such a thing before, but she remembered having seen in her brother's Latin Grammar, \"A mouse—of a mouse—to a mouse—a mouse—O mouse!\") The Mouse looked at her rather inquisitively, and seemed to her to wink with one of its little eyes, but it said nothing. \"Perhaps it doesn't understand English,\" thought Alice; \"I daresay it's a French mouse, come over with William the Conqueror.\" (For, with all her knowledge of history, Alice had no very clear notion how long ago anything had happened.) So she began again: \"Où est ma chatte?\" which was the first sentence in her French lesson-book. The Mouse gave a sudden leap out of the water, and seemed to quiver all over with fright. \"Oh, I beg your pardon!\" cried Alice hastily, afraid that she had hurt the poor animal's feelings. \"I quite forgot you didn't like cats.\" \"Not like cats!\" cried the Mouse, in a shrill, passionate voice. \"Would you like cats if you were me?\" \"Well, perhaps not,\" said Alice in a soothing tone: \"don't be angry about it. And yet I wish I could show you our cat Dinah: I think you'd take a fancy to cats if you could only see her. She is such a dear quiet thing,\" Alice went on, half to herself, as she swam lazily about in the pool, \"and she sits purring so nicely by the fire, licking her paws and washing her face—and she is such a nice soft thing to nurse—and she's such a capital one for catching mice—oh, I beg your pardon!\" cried Alice again, for this time the Mouse was bristling all over, and she felt certain it must be really offended. \"We won't talk about her any more if you'd rather not.\" \"We indeed!\" cried the Mouse, who was trembling down to the end of his tail. \"As if I would talk on such a subject! Our family always hated cats: nasty, low, vulgar things! Don't let me hear the name again!\" \"I won't indeed!\" said Alice, in a great hurry to change the subject of conversation. \"Are you—are you fond—of—of dogs?\" The Mouse did not answer, so Alice went on eagerly: \"There is such a nice little dog near our house I should like to show you! A little bright-eyed terrier, you know, with oh, such long curly brown hair! And it'll fetch things when you throw them, and it'll sit up and beg for its dinner, and all sorts of things—I can't remember half of them—and it belongs to a farmer, you know, and he says it's so useful, it's worth a hundred pounds! He says it kills all the rats and—oh dear!\" cried Alice in a sorrowful tone, \"I'm afraid I've offended it again!\" For the Mouse was swimming away from her as hard as it could go, and making quite a commotion in the pool as it went. So she called softly after it, \"Mouse dear! Do come back again, and we won't talk about cats or dogs either, if you don't like them!\" When the Mouse heard this, it turned round and swam slowly back to her: its face was quite pale (with passion, Alice thought), and it said in a low trembling voice, \"Let us get to the shore, and then I'll tell you my history, and you'll understand why it is I hate cats and dogs.\" It was high time to go, for the pool was getting quite crowded with the birds and animals that had fallen into it: there were a Duck and a Dodo, a Lory and an Eaglet, and several other curious creatures. Alice led the way, and the whole party swam to the shore. CHAPTER III. A Caucus-Race and a Long Tale They were indeed a queer-looking party that assembled on the bank—the birds with draggled feathers, the animals with their fur clinging close to them, and all dripping wet, cross, and uncomfortable. The first question of course was, how to get dry again: they had a consultation about this, and after a few minutes it seemed quite natural to Alice to find herself talking familiarly with them, as if she had known them all her life. Indeed, she had quite a long argument with the Lory, who at last turned sulky, and would only say, \"I am older than you, and must know better;\" and this Alice would not allow without knowing how old it was, and, as the Lory positively refused to tell its age, there was no more to be said. At last the Mouse, who seemed to be a person of authority among them, called out, \"Sit down, all of you, and listen to me! I'll soon make you dry enough!\" They all sat down at once, in a large ring, with the Mouse in the middle. Alice kept her eyes anxiously fixed on it, for she felt sure she would catch a bad cold if she did not get dry very soon. \"Ahem!\" said the Mouse with an important air, \"are you all ready? This is the driest thing I know. Silence all round, if you please! 'William the Conqueror, whose cause was favoured by the pope, was soon submitted to by the English, who wanted leaders, and had been of late much accustomed to usurpation and conquest. Edwin and Morcar, the earls of Mercia and Northumbria—'\" \"Ugh!\" said the Lory, with a shiver. \"I beg your pardon!\" said the Mouse, frowning, but very politely: \"Did you speak?\" \"Not I!\" said the Lory hastily. \"I thought you did,\" said the Mouse. \"—I proceed. 'Edwin and Morcar, the earls of Mercia and Northumbria, declared for him: and even Stigand, the patriotic archbishop of Canterbury, found it advisable—'\" \"Found what?\" said the Duck. \"Found it,\" the Mouse replied rather crossly: \"of course you know what 'it' means.\" \"I know what 'it' means well enough, when I find a thing,\" said the Duck: \"it's generally a frog or a worm. The question is, what did the archbishop find?\" The Mouse did not notice this question, but hurriedly went on, \"'—found it advisable to go with Edgar Atheling to meet William and offer him the crown. William's conduct at first was moderate. But the insolence of his Normans—' How are you getting on now, my dear?\" it continued, turning to Alice as it spoke. \"As wet as ever,\" said Alice in a melancholy tone: \"it doesn't seem to dry me at all.\" \"In that case,\" said the Dodo solemnly, rising to its feet, \"I move that the meeting adjourn, for the immediate adoption of more energetic remedies—\" \"Speak English!\" said the Eaglet. \"I don't know the meaning of half those long words, and, what's more, I don't believe you do either!\" And the Eaglet bent down its head to hide a smile: some of the other birds tittered audibly. \"What I was going to say,\" said the Dodo in an offended tone, \"was, that the best thing to get us dry would be a Caucus-race.\" \"What is a Caucus-race?\" said Alice; not that she wanted much to know, but the Dodo had paused as if it thought that somebody ought to speak, and no one else seemed inclined to say anything. \"Why,\" said the Dodo, \"the best way to explain it is to do it.\" (And, as you might like to try the thing yourself, some winter day, I will tell you how the Dodo managed it.) First it marked out a race-course, in a sort of circle, (\"the exact shape doesn't matter,\" it said,) and then all the party were placed along the course, here and there. There was no \"One, two, three, and away,\" but they began running when they liked, and left off when they liked, so that it was not easy to know when the race was over. However, when they had been running half an hour or so, and were quite dry again, the Dodo suddenly called out \"The race is over!\" and they all crowded round it, panting, and asking, \"But who has won?\" This question the Dodo could not answer without a great deal of thought, and it sat for a long time with one finger pressed upon its forehead (the position in which you usually see Shakespeare, in the pictures of him), while the rest waited in silence. At last the Dodo said, \"Everybody has won, and all must have prizes.\" \"But who is to give the prizes?\" quite a chorus of voices asked. \"Why, she, of course,\" said the Dodo, pointing to Alice with one finger; and the whole party at once crowded round her, calling out in a confused way, \"Prizes! Prizes!\" Alice had no idea what to do, and in despair she put her hand in her pocket, and pulled out a box of comfits, (luckily the salt water had not got into it), and handed them round as prizes. There was exactly one a-piece, all round. \"But she must have a prize herself, you know,\" said the Mouse. \"Of course,\" the Dodo replied very gravely. \"What else have you got in your pocket?\" he went on, turning to Alice. \"Only a thimble,\" said Alice sadly. \"Hand it over here,\" said the Dodo. Then they all crowded round her once more, while the Dodo solemnly presented the thimble, saying \"We beg your acceptance of this elegant thimble;\" and, when it had finished this short speech, they all cheered. Alice thought the whole thing very absurd, but they all looked so grave that she did not dare to laugh; and, as she could not think of anything to say, she simply bowed, and took the thimble, looking as solemn as she could. The next thing was to eat the comfits: this caused some noise and confusion, as the large birds complained that they could not taste theirs, and the small ones choked and had to be patted on the back. However, it was over at last, and they sat down again in a ring, and begged the Mouse to tell them something more. \"You promised to tell me your history, you know,\" said Alice, \"and why it is you hate—C and D,\" she added in a whisper, half afraid that it would be offended again. \"Mine is a long and a sad tale!\" said the Mouse, turning to Alice, and sighing. \"It is a long tail, certainly,\" said Alice, looking down with wonder at the Mouse's tail; \"but why do you call it sad?\" And she kept on puzzling about it while the Mouse was speaking, so that her idea of the tale was something like this:— \"Fury said to a mouse, That he met in the house, 'Let us both go to law: I will prosecute you.—Come, I'll take no denial; We must have a trial: For really this morning I've nothing to do.' Said the mouse to the cur, 'Such a trial, dear sir, With no jury or judge, would be wasting our breath.' 'I'll be judge, I'll be jury,' Said cunning old Fury: 'I'll try the whole cause, and condemn you to death.'\" \"You are not attending!\" said the Mouse to Alice severely. \"What are you thinking of?\" \"I beg your pardon,\" said Alice very humbly: \"you had got to the fifth bend, I think?\" \"I had not!\" cried the Mouse, sharply and very angrily. \"A knot!\" said Alice, always ready to make herself useful, and looking anxiously about her. \"Oh, do let me help to undo it!\" \"I shall do nothing of the sort,\" said the Mouse, getting up and walking away. \"You insult me by talking such nonsense!\" \"I didn't mean it!\" pleaded poor Alice. \"But you're so easily offended, you know!\" The Mouse only growled in reply. \"Please come back and finish your story!\" Alice called after it; and the others all joined in chorus, \"Yes, please do!\" but the Mouse only shook its head impatiently, and walked a little quicker. \"What a pity it wouldn't stay!\" sighed the Lory, as soon as it was quite out of sight; and an old Crab took the opportunity of saying to her daughter \"Ah, my dear! Let this be a lesson to you never to lose your temper!\" \"Hold your tongue, Ma!\" said the young Crab, a little snappishly. \"You're enough to try the patience of an oyster!\" \"I wish I had our Dinah here, I know I do!\" said Alice aloud, addressing nobody in particular. \"She'd soon fetch it back!\" \"And who is Dinah, if I might venture to ask the question?\" said the Lory. Alice replied eagerly, for she was always ready to talk about her pet: \"Dinah's our cat. And she's such a capital one for catching mice you can't think! And oh, I wish you could see her after the birds! Why, she'll eat a little bird as soon as look at it!\" This speech caused a remarkable sensation among the party. Some of the birds hurried off at once: one old Magpie began wrapping itself up very carefully, remarking, \"I really must be getting home; the night-air doesn't suit my throat!\" and a Canary called out in a trembling voice to its children, \"Come away, my dears! It's high time you were all in bed!\" On various pretexts they all moved off, and Alice was soon left alone. \"I wish I hadn't mentioned Dinah!\" she said to herself in a melancholy tone. \"Nobody seems to like her, down here, and I'm sure she's the best cat in the world! Oh, my dear Dinah! I wonder if I shall ever see you any more!\" And here poor Alice began to cry again, for she felt very lonely and low-spirited. In a little while, however, she again heard a little pattering of footsteps in the distance, and she looked up eagerly, half hoping that the Mouse had changed his mind, and was coming back to finish his story. CHAPTER IV. The Rabbit Sends in a Little Bill It was the White Rabbit, trotting slowly back again, and looking anxiously about as it went, as if it had lost something; and she heard it muttering to itself \"The Duchess! The Duchess! Oh my dear paws! Oh my fur and whiskers! She'll get me executed, as sure as ferrets are ferrets! Where can I have dropped them, I wonder?\" Alice guessed in a moment that it was looking for the fan and the pair of white kid gloves, and she very good-naturedly began hunting about for them, but they were nowhere to be seen—everything seemed to have changed since her swim in the pool, and the great hall, with the glass table and the little door, had vanished completely. Very soon the Rabbit noticed Alice, as she went hunting about, and called out to her in an angry tone, \"Why, Mary Ann, what are you doing out here? Run home this moment, and fetch me a pair of gloves and a fan! Quick, now!\" And Alice was so much frightened that she ran off at once in the direction it pointed to, without trying to explain the mistake it had made. \"He took me for his housemaid,\" she said to herself as she ran. \"How surprised he'll be when he finds out who I am! But I'd better take him his fan and gloves—that is, if I can find them.\" As she said this, she came upon a neat little house, on the door of which was a bright brass plate with the name \"W. RABBIT,\" engraved upon it. She went in without knocking, and hurried upstairs, in great fear lest she should meet the real Mary Ann, and be turned out of the house before she had found the fan and gloves. \"How queer it seems,\" Alice said to herself, \"to be going messages for a rabbit! I suppose Dinah'll be sending me on messages next!\" And she began fancying the sort of thing that would happen: \"'Miss Alice! Come here directly, and get ready for your walk!' 'Coming in a minute, nurse! But I've got to see that the mouse doesn't get out.' Only I don't think,\" Alice went on, \"that they'd let Dinah stop in the house if it began ordering people about like that!\" By this time she had found her way into a tidy little room with a table in the window, and on it (as she had hoped) a fan and two or three pairs of tiny white kid gloves: she took up the fan and a pair of the gloves, and was just going to leave the room, when her eye fell upon a little bottle that stood near the looking-glass. There was no label this time with the words \"DRINK ME,\" but nevertheless she uncorked it and put it to her lips. \"I know something interesting is sure to happen,\" she said to herself, \"whenever I eat or drink anything; so I'll just see what this bottle does. I do hope it'll make me grow large again, for really I'm quite tired of being such a tiny little thing!\" It did so indeed, and much sooner than she had expected: before she had drunk half the bottle, she found her head pressing against the ceiling, and had to stoop to save her neck from being broken. She hastily put down the bottle, saying to herself \"That's quite enough—I hope I shan't grow any more—As it is, I can't get out at the door—I do wish I hadn't drunk quite so much!\" Alas! it was too late to wish that! She went on growing, and growing, and very soon had to kneel down on the floor: in another minute there was not even room for this, and she tried the effect of lying down with one elbow against the door, and the other arm curled round her head. Still she went on growing, and, as a last resource, she put one arm out of the window, and one foot up the chimney, and said to herself \"Now I can do no more, whatever happens. What will become of me?\" Luckily for Alice, the little magic bottle had now had its full effect, and she grew no larger: still it was very uncomfortable, and, as there seemed to be no sort of chance of her ever getting out of the room again, no wonder she felt unhappy. \"It was much pleasanter at home,\" thought poor Alice, \"when one wasn't always growing larger and smaller, and being ordered about by mice and rabbits. I almost wish I hadn't gone down that rabbit-hole—and yet—and yet—it's rather curious, you know, this sort of life! I do wonder what can have happened to me! When I used to read fairy-tales, I fancied that kind of thing never happened, and now here I am in the middle of one! There ought to be a book written about me, that there ought! And when I grow up, I'll write one—but I'm grown up now,\" she added in a sorrowful tone; \"at least there's no room to grow up any more here.\" \"But then,\" thought Alice, \"shall I never get any older than I am now? That'll be a comfort, one way—never to be an old woman—but then—always to have lessons to learn! Oh, I shouldn't like that!\" \"Oh, you foolish Alice!\" she answered herself. \"How can you learn lessons in here? Why, there's hardly room for you, and no room at all for any lesson-books!\" And so she went on, taking first one side and then the other, and making quite a conversation of it altogether; but after a few minutes she heard a voice outside, and stopped to listen. \"Mary Ann! Mary Ann!\" said the voice. \"Fetch me my gloves this moment!\" Then came a little pattering of feet on the stairs. Alice knew it was the Rabbit coming to look for her, and she trembled till she shook the house, quite forgetting that she was now about a thousand times as large as the Rabbit, and had no reason to be afraid of it. Presently the Rabbit came up to the door, and tried to open it; but, as the door opened inwards, and Alice's elbow was pressed hard against it, that attempt proved a failure. Alice heard it say to itself \"Then I'll go round and get in at the window.\" \"That you won't!\" thought Alice, and, after waiting till she fancied she heard the Rabbit just under the window, she suddenly spread out her hand, and made a snatch in the air. She did not get hold of anything, but she heard a little shriek and a fall, and a crash of broken glass, from which she concluded that it was just possible it had fallen into a cucumber-frame, or something of the sort. Next came an angry voice—the Rabbit's—\"Pat! Pat! Where are you?\" And then a voice she had never heard before, \"Sure then I'm here! Digging for apples, yer honour!\" \"Digging for apples, indeed!\" said the Rabbit angrily. \"Here! Come and help me out of this!\" (Sounds of more broken glass.) \"Now tell me, Pat, what's that in the window?\" \"Sure, it's an arm, yer honour!\" (He pronounced it \"arrum.\") \"An arm, you goose! Who ever saw one that size? Why, it fills the whole window!\" \"Sure, it does, yer honour: but it's an arm for all that.\" \"Well, it's got no business there, at any rate: go and take it away!\" There was a long silence after this, and Alice could only hear whispers now and then; such as, \"Sure, I don't like it, yer honour, at all, at all!\" \"Do as I tell you, you coward!\" and at last she spread out her hand again, and made another snatch in the air. This time there were two little shrieks, and more sounds of broken glass. \"What a number of cucumber-frames there must be!\" thought Alice. \"I wonder what they'll do next! As for pulling me out of the window, I only wish they could! I'm sure I don't want to stay in here any longer!\" She waited for some time without hearing anything more: at last came a rumbling of little cartwheels, and the sound of a good many voices all talking together: she made out the words: \"Where's the other ladder?—Why, I hadn't to bring but one; Bill's got the other—Bill! fetch it here, lad!—Here, put 'em up at this corner—No, tie 'em together first—they don't reach half high enough yet—Oh! they'll do well enough; don't be particular—Here, Bill! catch hold of this rope—Will the roof bear?—Mind that loose slate—Oh, it's coming down! Heads below!\" (a loud crash)—\"Now, who did that?—It was Bill, I fancy—Who's to go down the chimney?—Nay, I shan't! You do it!—That I won't, then!—Bill's to go down—Here, Bill! the master says you're to go down the chimney!\" \"Oh! So Bill's got to come down the chimney, has he?\" said Alice to herself. \"Shy, they seem to put everything upon Bill! I wouldn't be in Bill's place for a good deal: this fireplace is narrow, to be sure; but I think I can kick a little!\" She drew her foot as far down the chimney as she could, and waited till she heard a little animal (she couldn't guess of what sort it was) scratching and scrambling about in the chimney close above her: then, saying to herself \"This is Bill,\" she gave one sharp kick, and waited to see what would happen next. The first thing she heard was a general chorus of \"There goes Bill!\" then the Rabbit's voice along—\"Catch him, you by the hedge!\" then silence, and then another confusion of voices—\"Hold up his head—Brandy now—Don't choke him—How was it, old fellow? What happened to you? Tell us all about it!\" Last came a little feeble, squeaking voice, (\"That's Bill,\" thought Alice,) \"Well, I hardly know—No more, thank ye; I'm better now—but I'm a deal too flustered to tell you—all I know is, something comes at me like a Jack-in-the-box, and up I goes like a sky-rocket!\" \"So you did, old fellow!\" said the others. \"We must burn the house down!\" said the Rabbit's voice; and Alice called out as loud as she could, \"If you do, I'll set Dinah at you!\" There was a dead silence instantly, and Alice thought to herself, \"I wonder what they will do next! If they had any sense, they'd take the roof off.\" After a minute or two, they began moving about again, and Alice heard the Rabbit say, \"A barrowful will do, to begin with.\" \"A barrowful of what?\" thought Alice; but she had not long to doubt, for the next moment a shower of little pebbles came rattling in at the window, and some of them hit her in the face. \"I'll put a stop to this,\" she said to herself, and shouted out, \"You'd better not do that again!\" which produced another dead silence. Alice noticed with some surprise that the pebbles were all turning into little cakes as they lay on the floor, and a bright idea came into her head. \"If I eat one of these cakes,\" she thought, \"it's sure to make some change in my size; and as it can't possibly make me larger, it must make me smaller, I suppose.\" So she swallowed one of the cakes, and was delighted to find that she began shrinking directly. As soon as she was small enough to get through the door, she ran out of the house, and found quite a crowd of little animals and birds waiting outside. The poor little Lizard, Bill, was in the middle, being held up by two guinea-pigs, who were giving it something out of a bottle. They all made a rush at Alice the moment she appeared; but she ran off as hard as she could, and soon found herself safe in a thick wood. \"The first thing I've got to do,\" said Alice to herself, as she wandered about in the wood, \"is to grow to my right size again; and the second thing is to find my way into that lovely garden. I think that will be the best plan.\" It sounded an excellent plan, no doubt, and very neatly and simply arranged; the only difficulty was, that she had not the smallest idea how to set about it; and while she was peering about anxiously among the trees, a little sharp bark just over her head made her look up in a great hurry. An enormous puppy was looking down at her with large round eyes, and feebly stretching out one paw, trying to touch her. \"Poor little thing!\" said Alice, in a coaxing tone, and she tried hard to whistle to it; but she was terribly frightened all the time at the thought that it might be hungry, in which case it would be very likely to eat her up in spite of all her coaxing. Hardly knowing what she did, she picked up a little bit of stick, and held it out to the puppy; whereupon the puppy jumped into the air off all its feet at once, with a yelp of delight, and rushed at the stick, and made believe to worry it; then Alice dodged behind a great thistle, to keep herself from being run over; and the moment she appeared on the other side, the puppy made another rush at the stick, and tumbled head over heels in its hurry to get hold of it; then Alice, thinking it was very like having a game of play with a cart-horse, and expecting every moment to be trampled under its feet, ran round the thistle again; then the puppy began a series of short charges at the stick, running a very little way forwards each time and a long way back, and barking hoarsely all the while, till at last it sat down a good way off, panting, with its tongue hanging out of its mouth, and its great eyes half shut. This seemed to Alice a good opportunity for making her escape; so she set off at once, and ran till she was quite tired and out of breath, and till the puppy's bark sounded quite faint in the distance. \"And yet what a dear little puppy it was!\" said Alice, as she leant against a buttercup to rest herself, and fanned herself with one of the leaves: \"I should have liked teaching it tricks very much, if—if I'd only been the right size to do it! Oh dear! I'd nearly forgotten that I've got to grow up again! Let me see—how is it to be managed? I suppose I ought to eat or drink something or other; but the great question is, what?\" The great question certainly was, what? Alice looked all round her at the flowers and the blades of grass, but she did not see anything that looked like the right thing to eat or drink under the circumstances. There was a large mushroom growing near her, about the same height as herself; and when she had looked under it, and on both sides of it, and behind it, it occurred to her that she might as well look and see what was on the top of it. She stretched herself up on tiptoe, and peeped over the edge of the mushroom, and her eyes immediately met those of a large blue caterpillar, that was sitting on the top with its arms folded, quietly smoking a long hookah, and taking not the smallest notice of her or of anything else. CHAPTER V. Advice from a Caterpillar The Caterpillar and Alice looked at each other for some time in silence: at last the Caterpillar took the hookah out of its mouth, and addressed her in a languid, sleepy voice. \"Who are you?\" said the Caterpillar. This was not an encouraging opening for a conversation. Alice replied, rather shyly, \"I—I hardly know, sir, just at present—at least I know who I was when I got up this morning, but I think I must have been changed several times since then.\" \"What do you mean by that?\" said the Caterpillar sternly. \"Explain yourself!\" \"I can't explain myself, I'm afraid, sir,\" said Alice, \"because I'm not myself, you see.\" \"I don't see,\" said the Caterpillar. \"I'm afraid I can't put it more clearly,\" Alice replied very politely, \"for I can't understand it myself to begin with; and being so many different sizes in a day is very confusing.\" \"It isn't,\" said the Caterpillar. \"Well, perhaps you haven't found it so yet,\" said Alice; \"but when you have to turn into a chrysalis—you will some day, you know—and then after that into a butterfly, I should think you'll feel it a little queer, won't you?\" \"Not a bit,\" said the Caterpillar. \"Well, perhaps your feelings may be different,\" said Alice; \"all I know is, it would feel very queer to me.\" \"You!\" said the Caterpillar contemptuously. \"Who are you?\" Which brought them back again to the beginning of the conversation. Alice felt a little irritated at the Caterpillar's making such very short remarks, and she drew herself up and said, very gravely, \"I think, you ought to tell me who you are, first.\" \"Why?\" said the Caterpillar. Here was another puzzling question; and as Alice could not think of any good reason, and as the Caterpillar seemed to be in a very unpleasant state of mind, she turned away. \"Come back!\" the Caterpillar called after her. \"I've something important to say!\" This sounded promising, certainly: Alice turned and came back again. \"Keep your temper,\" said the Caterpillar. \"Is that all?\" said Alice, swallowing down her anger as well as she could. \"No,\" said the Caterpillar. Alice thought she might as well wait, as she had nothing else to do, and perhaps after all it might tell her something worth hearing. For some minutes it puffed away without speaking, but at last it unfolded its arms, took the hookah out of its mouth again, and said, \"So you think you're changed, do you?\" \"I'm afraid I am, sir,\" said Alice; \"I can't remember things as I used—and I don't keep the same size for ten minutes together!\" \"Can't remember what things?\" said the Caterpillar. \"Well, I've tried to say \"How doth the little busy bee,\" but it all came different!\" Alice replied in a very melancholy voice. \"Repeat, 'You are old, Father William,'\" said the Caterpillar. Alice folded her hands, and began:— \"You are old, Father William,\" the young man said, \"And your hair has become very white; And yet you incessantly stand on your head— Do you think, at your age, it is right?\" \"In my youth,\" Father William replied to his son, \"I feared it might injure the brain; But, now that I'm perfectly sure I have none, Why, I do it again and again.\" \"You are old,\" said the youth, \"as I mentioned before, And have grown most uncommonly fat; Yet you turned a back-somersault in at the door— Pray, what is the reason of that?\" \"In my youth,\" said the sage, as he shook his grey locks, \"I kept all my limbs very supple By the use of this ointment—one shilling the box— Allow me to sell you a couple?\" \"You are old,\" said the youth, \"and your jaws are too weak For anything tougher than suet; Yet you finished the goose, with the bones and the beak— Pray, how did you manage to do it?\" \"In my youth,\" said his father, \"I took to the law, And argued each case with my wife; And the muscular strength, which it gave to my jaw, Has lasted the rest of my life.\" \"You are old,\" said the youth, \"one would hardly suppose That your eye was as steady as ever; Yet you balanced an eel on the end of your nose— What made you so awfully clever?\" \"I have answered three questions, and that is enough,\" Said his father; \"don't give yourself airs! Do you think I can listen all day to such stuff? Be off, or I'll kick you down stairs!\" \"That is not said right,\" said the Caterpillar. \"Not quite right, I'm afraid,\" said Alice, timidly; \"some of the words have got altered.\" \"It is wrong from beginning to end,\" said the Caterpillar decidedly, and there was silence for some minutes. The Caterpillar was the first to speak. \"What size do you want to be?\" it asked. \"Oh, I'm not particular as to size,\" Alice hastily replied; \"only one doesn't like changing so often, you know.\" \"I don't know,\" said the Caterpillar. Alice said nothing: she had never been so much contradicted in her life before, and she felt that she was losing her temper. \"Are you content now?\" said the Caterpillar. \"Well, I should like to be a little larger, sir, if you wouldn't mind,\" said Alice: \"three inches is such a wretched height to be.\" \"It is a very good height indeed!\" said the Caterpillar angrily, rearing itself upright as it spoke (it was exactly three inches high). \"But I'm not used to it!\" pleaded poor Alice in a piteous tone. And she thought of herself, \"I wish the creatures wouldn't be so easily offended!\" \"You'll get used to it in time,\" said the Caterpillar; and it put the hookah into its mouth and began smoking again. This time Alice waited patiently until it chose to speak again. In a minute or two the Caterpillar took the hookah out of its mouth and yawned once or twice, and shook itself. Then it got down off the mushroom, and crawled away in the grass, merely remarking as it went, \"One side will make you grow taller, and the other side will make you grow shorter.\" \"One side of what? The other side of what?\" thought Alice to herself. \"Of the mushroom,\" said the Caterpillar, just as if she had asked it aloud; and in another moment it was out of sight. Alice remained looking thoughtfully at the mushroom for a minute, trying to make out which were the two sides of it; and as it was perfectly round, she found this a very difficult question. However, at last she stretched her arms round it as far as they would go, and broke off a bit of the edge with each hand. \"And now which is which?\" she said to herself, and nibbled a little of the right-hand bit to try the effect: the next moment she felt a violent blow underneath her chin: it had struck her foot! She was a good deal frightened by this very sudden change, but she felt that there was no time to be lost, as she was shrinking rapidly; so she set to work at once to eat some of the other bit. Her chin was pressed so closely against her foot, that there was hardly room to open her mouth; but she did it at last, and managed to swallow a morsel of the lefthand bit. * * * * * * * * * * * * * * * * * * * * \"Come, my head's free at last!\" said Alice in a tone of delight, which changed into alarm in another moment, when she found that her shoulders were nowhere to be found: all she could see, when she looked down, was an immense length of neck, which seemed to rise like a stalk out of a sea of green leaves that lay far below her. \"What can all that green stuff be?\" said Alice. \"And where have my shoulders got to? And oh, my poor hands, how is it I can't see you?\" She was moving them about as she spoke, but no result seemed to follow, except a little shaking among the distant green leaves. As there seemed to be no chance of getting her hands up to her head, she tried to get her head down to them, and was delighted to find that her neck would bend about easily in any direction, like a serpent. She had just succeeded in curving it down into a graceful zigzag, and was going to dive in among the leaves, which she found to be nothing but the tops of the trees under which she had been wandering, when a sharp hiss made her draw back in a hurry: a large pigeon had flown into her face, and was beating her violently with its wings. \"Serpent!\" screamed the Pigeon. \"I'm not a serpent!\" said Alice indignantly. \"Let me alone!\" \"Serpent, I say again!\" repeated the Pigeon, but in a more subdued tone, and added with a kind of sob, \"I've tried every way, and nothing seems to suit them!\" \"I haven't the least idea what you're talking about,\" said Alice. \"I've tried the roots of trees, and I've tried banks, and I've tried hedges,\" the Pigeon went on, without attending to her; \"but those serpents! There's no pleasing them!\" Alice was more and more puzzled, but she thought there was no use in saying anything more till the Pigeon had finished. \"As if it wasn't trouble enough hatching the eggs,\" said the Pigeon; \"but I must be on the look-out for serpents night and day! Why, I haven't had a wink of sleep these three weeks!\" \"I'm very sorry you've been annoyed,\" said Alice, who was beginning to see its meaning. \"And just as I'd taken the highest tree in the wood,\" continued the Pigeon, raising its voice to a shriek, \"and just as I was thinking I should be free of them at last, they must needs come wriggling down from the sky! Ugh, Serpent!\" \"But I'm not a serpent, I tell you!\" said Alice. \"I'm a—I'm a—\" \"Well! What are you?\" said the Pigeon. \"I can see you're trying to invent something!\" \"I—I'm a little girl,\" said Alice, rather doubtfully, as she remembered the number of changes she had gone through that day. \"A likely story indeed!\" said the Pigeon in a tone of the deepest contempt. \"I've seen a good many little girls in my time, but never one with such a neck as that! No, no! You're a serpent; and there's no use denying it. I suppose you'll be telling me next that you never tasted an egg!\" \"I have tasted eggs, certainly,\" said Alice, who was a very truthful child; \"but little girls eat eggs quite as much as serpents do, you know.\" \"I don't believe it,\" said the Pigeon; \"but if they do, why then they're a kind of serpent, that's all I can say.\" This was such a new idea to Alice, that she was quite silent for a minute or two, which gave the Pigeon the opportunity of adding, \"You're looking for eggs, I know that well enough; and what does it matter to me whether you're a little girl or a serpent?\" \"It matters a good deal to me,\" said Alice hastily; \"but I'm not looking for eggs, as it happens; and if I was, I shouldn't want yours: I don't like them raw.\" \"Well, be off, then!\" said the Pigeon in a sulky tone, as it settled down again into its nest. Alice crouched down among the trees as well as she could, for her neck kept getting entangled among the branches, and every now and then she had to stop and untwist it. After a while she remembered that she still held the pieces of mushroom in her hands, and she set to work very carefully, nibbling first at one and then at the other, and growing sometimes taller and sometimes shorter, until she had succeeded in bringing herself down to her usual height. It was so long since she had been anything near the right size, that it felt quite strange at first; but she got used to it in a few minutes, and began talking to herself, as usual. \"Come, there's half my plan done now! How puzzling all these changes are! I'm never sure what I'm going to be, from one minute to another! However, I've got back to my right size: the next thing is, to get into that beautiful garden—how is that to be done, I wonder?\" As she said this, she came suddenly upon an open place, with a little house in it about four feet high. \"Whoever lives there,\" thought Alice, \"it'll never do to come upon them this size: why, I should frighten them out of their wits!\" So she began nibbling at the righthand bit again, and did not venture to go near the house till she had brought herself down to nine inches high. CHAPTER VI. Pig and Pepper For a minute or two she stood looking at the house, and wondering what to do next, when suddenly a footman in livery came running out of the wood—(she considered him to be a footman because he was in livery: otherwise, judging by his face only, she would have called him a fish)—and rapped loudly at the door with his knuckles. It was opened by another footman in livery, with a round face, and large eyes like a frog; and both footmen, Alice noticed, had powdered hair that curled all over their heads. She felt very curious to know what it was all about, and crept a little way out of the wood to listen. The Fish-Footman began by producing from under his arm a great letter, nearly as large as himself, and this he handed over to the other, saying, in a solemn tone, \"For the Duchess. An invitation from the Queen to play croquet.\" The Frog-Footman repeated, in the same solemn tone, only changing the order of the words a little, \"From the Queen. An invitation for the Duchess to play croquet.\" Then they both bowed low, and their curls got entangled together. Alice laughed so much at this, that she had to run back into the wood for fear of their hearing her; and when she next peeped out the Fish-Footman was gone, and the other was sitting on the ground near the door, staring stupidly up into the sky. Alice went timidly up to the door, and knocked. \"There's no sort of use in knocking,\" said the Footman, \"and that for two reasons. First, because I'm on the same side of the door as you are; secondly, because they're making such a noise inside, no one could possibly hear you.\" And certainly there was a most extraordinary noise going on within—a constant howling and sneezing, and every now and then a great crash, as if a dish or kettle had been broken to pieces. \"Please, then,\" said Alice, \"how am I to get in?\" \"There might be some sense in your knocking,\" the Footman went on without attending to her, \"if we had the door between us. For instance, if you were inside, you might knock, and I could let you out, you know.\" He was looking up into the sky all the time he was speaking, and this Alice thought decidedly uncivil. \"But perhaps he can't help it,\" she said to herself; \"his eyes are so very nearly at the top of his head. But at any rate he might answer questions.—How am I to get in?\" she repeated, aloud. \"I shall sit here,\" the Footman remarked, \"till tomorrow—\" At this moment the door of the house opened, and a large plate came skimming out, straight at the Footman's head: it just grazed his nose, and broke to pieces against one of the trees behind him. \"—or next day, maybe,\" the Footman continued in the same tone, exactly as if nothing had happened. \"How am I to get in?\" asked Alice again, in a louder tone. \"Are you to get in at all?\" said the Footman. \"That's the first question, you know.\" It was, no doubt: only Alice did not like to be told so. \"It's really dreadful,\" she muttered to herself, \"the way all the creatures argue. It's enough to drive one crazy!\" The Footman seemed to think this a good opportunity for repeating his remark, with variations. \"I shall sit here,\" he said, \"on and off, for days and days.\" \"But what am I to do?\" said Alice. \"Anything you like,\" said the Footman, and began whistling. \"Oh, there's no use in talking to him,\" said Alice desperately: \"he's perfectly idiotic!\" And she opened the door and went in. The door led right into a large kitchen, which was full of smoke from one end to the other: the Duchess was sitting on a three-legged stool in the middle, nursing a baby; the cook was leaning over the fire, stirring a large cauldron which seemed to be full of soup. \"There's certainly too much pepper in that soup!\" Alice said to herself, as well as she could for sneezing. There was certainly too much of it in the air. Even the Duchess sneezed occasionally; and as for the baby, it was sneezing and howling alternately without a moment's pause. The only things in the kitchen that did not sneeze, were the cook, and a large cat which was sitting on the hearth and grinning from ear to ear. \"Please would you tell me,\" said Alice, a little timidly, for she was not quite sure whether it was good manners for her to speak first, \"why your cat grins like that?\" \"It's a Cheshire cat,\" said the Duchess, \"and that's why. Pig!\" She said the last word with such sudden violence that Alice quite jumped; but she saw in another moment that it was addressed to the baby, and not to her, so she took courage, and went on again:— \"I didn't know that Cheshire cats always grinned; in fact, I didn't know that cats could grin.\" \"They all can,\" said the Duchess; \"and most of 'em do.\" \"I don't know of any that do,\" Alice said very politely, feeling quite pleased to have got into a conversation. \"You don't know much,\" said the Duchess; \"and that's a fact.\" Alice did not at all like the tone of this remark, and thought it would be as well to introduce some other subject of conversation. While she was trying to fix on one, the cook took the cauldron of soup off the fire, and at once set to work throwing everything within her reach at the Duchess and the baby—the fire-irons came first; then followed a shower of saucepans, plates, and dishes. The Duchess took no notice of them even when they hit her; and the baby was howling so much already, that it was quite impossible to say whether the blows hurt it or not. \"Oh, please mind what you're doing!\" cried Alice, jumping up and down in an agony of terror. \"Oh, there goes his precious nose!\" as an unusually large saucepan flew close by it, and very nearly carried it off. \"If everybody minded their own business,\" the Duchess said in a hoarse growl, \"the world would go round a deal faster than it does.\" \"Which would not be an advantage,\" said Alice, who felt very glad to get an opportunity of showing off a little of her knowledge. \"Just think of what work it would make with the day and night! You see the earth takes twenty-four hours to turn round on its axis—\" \"Talking of axes,\" said the Duchess, \"chop off her head!\" Alice glanced rather anxiously at the cook, to see if she meant to take the hint; but the cook was busily stirring the soup, and seemed not to be listening, so she went on again: \"Twenty-four hours, I think; or is it twelve? I—\" \"Oh, don't bother me,\" said the Duchess; \"I never could abide figures!\" And with that she began nursing her child again, singing a sort of lullaby to it as she did so, and giving it a violent shake at the end of every line: \"Speak roughly to your little boy, And beat him when he sneezes: He only does it to annoy, Because he knows it teases.\" CHORUS. (In which the cook and the baby joined): \"Wow! wow! wow!\" While the Duchess sang the second verse of the song, she kept tossing the baby violently up and down, and the poor little thing howled so, that Alice could hardly hear the words:— \"I speak severely to my boy, I beat him when he sneezes; For he can thoroughly enjoy The pepper when he pleases!\" CHORUS. \"Wow! wow! wow!\" \"Here! you may nurse it a bit, if you like!\" the Duchess said to Alice, flinging the baby at her as she spoke. \"I must go and get ready to play croquet with the Queen,\" and she hurried out of the room. The cook threw a frying-pan after her as she went out, but it just missed her. Alice caught the baby with some difficulty, as it was a queer-shaped little creature, and held out its arms and legs in all directions, \"just like a star-fish,\" thought Alice. The poor little thing was snorting like a steam-engine when she caught it, and kept doubling itself up and straightening itself out again, so that altogether, for the first minute or two, it was as much as she could do to hold it. As soon as she had made out the proper way of nursing it, (which was to twist it up into a sort of knot, and then keep tight hold of its right ear and left foot, so as to prevent its undoing itself,) she carried it out into the open air. \"If I don't take this child away with me,\" thought Alice, \"they're sure to kill it in a day or two: wouldn't it be murder to leave it behind?\" She said the last words out loud, and the little thing grunted in reply (it had left off sneezing by this time). \"Don't grunt,\" said Alice; \"that's not at all a proper way of expressing yourself.\" The baby grunted again, and Alice looked very anxiously into its face to see what was the matter with it. There could be no doubt that it had a very turn-up nose, much more like a snout than a real nose; also its eyes were getting extremely small for a baby: altogether Alice did not like the look of the thing at all. \"But perhaps it was only sobbing,\" she thought, and looked into its eyes again, to see if there were any tears. No, there were no tears. \"If you're going to turn into a pig, my dear,\" said Alice, seriously, \"I'll have nothing more to do with you. Mind now!\" The poor little thing sobbed again (or grunted, it was impossible to say which), and they went on for some while in silence. Alice was just beginning to think to herself, \"Now, what am I to do with this creature when I get it home?\" when it grunted again, so violently, that she looked down into its face in some alarm. This time there could be no mistake about it: it was neither more nor less than a pig, and she felt that it would be quite absurd for her to carry it further. So she set the little creature down, and felt quite relieved to see it trot away quietly into the wood. \"If it had grown up,\" she said to herself, \"it would have made a dreadfully ugly child: but it makes rather a handsome pig, I think.\" And she began thinking over other children she knew, who might do very well as pigs, and was just saying to herself, \"if one only knew the right way to change them—\" when she was a little startled by seeing the Cheshire Cat sitting on a bough of a tree a few yards off. The Cat only grinned when it saw Alice. It looked good-natured, she thought: still it had very long claws and a great many teeth, so she felt that it ought to be treated with respect. \"Cheshire Puss,\" she began, rather timidly, as she did not at all know whether it would like the name: however, it only grinned a little wider. \"Come, it's pleased so far,\" thought Alice, and she went on. \"Would you tell me, please, which way I ought to go from here?\" \"That depends a good deal on where you want to get to,\" said the Cat. \"I don't much care where—\" said Alice. \"Then it doesn't matter which way you go,\" said the Cat. \"—so long as I get somewhere,\" Alice added as an explanation. \"Oh, you're sure to do that,\" said the Cat, \"if you only walk long enough.\" Alice felt that this could not be denied, so she tried another question. \"What sort of people live about here?\" \"In that direction,\" the Cat said, waving its right paw round, \"lives a Hatter: and in that direction,\" waving the other paw, \"lives a March Hare. Visit either you like: they're both mad.\" \"But I don't want to go among mad people,\" Alice remarked. \"Oh, you can't help that,\" said the Cat: \"we're all mad here. I'm mad. You're mad.\" \"How do you know I'm mad?\" said Alice. \"You must be,\" said the Cat, \"or you wouldn't have come here.\" Alice didn't think that proved it at all; however, she went on \"And how do you know that you're mad?\" \"To begin with,\" said the Cat, \"a dog's not mad. You grant that?\" \"I suppose so,\" said Alice. \"Well, then,\" the Cat went on, \"you see, a dog growls when it's angry, and wags its tail when it's pleased. Now I growl when I'm pleased, and wag my tail when I'm angry. Therefore I'm mad.\" \"I call it purring, not growling,\" said Alice. \"Call it what you like,\" said the Cat. \"Do you play croquet with the Queen to-day?\" \"I should like it very much,\" said Alice, \"but I haven't been invited yet.\" \"You'll see me there,\" said the Cat, and vanished. Alice was not much surprised at this, she was getting so used to queer things happening. While she was looking at the place where it had been, it suddenly appeared again. \"By-the-bye, what became of the baby?\" said the Cat. \"I'd nearly forgotten to ask.\" \"It turned into a pig,\" Alice quietly said, just as if it had come back in a natural way. \"I thought it would,\" said the Cat, and vanished again. Alice waited a little, half expecting to see it again, but it did not appear, and after a minute or two she walked on in the direction in which the March Hare was said to live. \"I've seen hatters before,\" she said to herself; \"the March Hare will be much the most interesting, and perhaps as this is May it won't be raving mad—at least not so mad as it was in March.\" As she said this, she looked up, and there was the Cat again, sitting on a branch of a tree. \"Did you say pig, or fig?\" said the Cat. \"I said pig,\" replied Alice; \"and I wish you wouldn't keep appearing and vanishing so suddenly: you make one quite giddy.\" \"All right,\" said the Cat; and this time it vanished quite slowly, beginning with the end of the tail, and ending with the grin, which remained some time after the rest of it had gone. \"Well! I've often seen a cat without a grin,\" thought Alice; \"but a grin without a cat! It's the most curious thing I ever saw in my life!\" She had not gone much farther before she came in sight of the house of the March Hare: she thought it must be the right house, because the chimneys were shaped like ears and the roof was thatched with fur. It was so large a house, that she did not like to go nearer till she had nibbled some more of the lefthand bit of mushroom, and raised herself to about two feet high: even then she walked up towards it rather timidly, saying to herself \"Suppose it should be raving mad after all! I almost wish I'd gone to see the Hatter instead!\" CHAPTER VII. A Mad Tea-Party There was a table set out under a tree in front of the house, and the March Hare and the Hatter were having tea at it: a Dormouse was sitting between them, fast asleep, and the other two were using it as a cushion, resting their elbows on it, and talking over its head. \"Very uncomfortable for the Dormouse,\" thought Alice; \"only, as it's asleep, I suppose it doesn't mind.\" The table was a large one, but the three were all crowded together at one corner of it: \"No room! No room!\" they cried out when they saw Alice coming. \"There's plenty of room!\" said Alice indignantly, and she sat down in a large arm-chair at one end of the table. \"Have some wine,\" the March Hare said in an encouraging tone. Alice looked all round the table, but there was nothing on it but tea. \"I don't see any wine,\" she remarked. \"There isn't any,\" said the March Hare. \"Then it wasn't very civil of you to offer it,\" said Alice angrily. \"It wasn't very civil of you to sit down without being invited,\" said the March Hare. \"I didn't know it was your table,\" said Alice; \"it's laid for a great many more than three.\" \"Your hair wants cutting,\" said the Hatter. He had been looking at Alice for some time with great curiosity, and this was his first speech. \"You should learn not to make personal remarks,\" Alice said with some severity; \"it's very rude.\" The Hatter opened his eyes very wide on hearing this; but all he said was, \"Why is a raven like a writing-desk?\" \"Come, we shall have some fun now!\" thought Alice. \"I'm glad they've begun asking riddles.—I believe I can guess that,\" she added aloud. \"Do you mean that you think you can find out the answer to it?\" said the March Hare. \"Exactly so,\" said Alice. \"Then you should say what you mean,\" the March Hare went on. \"I do,\" Alice hastily replied; \"at least—at least I mean what I say—that's the same thing, you know.\" \"Not the same thing a bit!\" said the Hatter. \"You might just as well say that 'I see what I eat' is the same thing as 'I eat what I see'!\" \"You might just as well say,\" added the March Hare, \"that 'I like what I get' is the same thing as 'I get what I like'!\" \"You might just as well say,\" added the Dormouse, who seemed to be talking in his sleep, \"that 'I breathe when I sleep' is the same thing as 'I sleep when I breathe'!\" \"It is the same thing with you,\" said the Hatter, and here the conversation dropped, and the party sat silent for a minute, while Alice thought over all she could remember about ravens and writing-desks, which wasn't much. The Hatter was the first to break the silence. \"What day of the month is it?\" he said, turning to Alice: he had taken his watch out of his pocket, and was looking at it uneasily, shaking it every now and then, and holding it to his ear. Alice considered a little, and then said \"The fourth.\" \"Two days wrong!\" sighed the Hatter. \"I told you butter wouldn't suit the works!\" he added looking angrily at the March Hare. \"It was the best butter,\" the March Hare meekly replied. \"Yes, but some crumbs must have got in as well,\" the Hatter grumbled: \"you shouldn't have put it in with the bread-knife.\" The March Hare took the watch and looked at it gloomily: then he dipped it into his cup of tea, and looked at it again: but he could think of nothing better to say than his first remark, \"It was the best butter, you know.\" Alice had been looking over his shoulder with some curiosity. \"What a funny watch!\" she remarked. \"It tells the day of the month, and doesn't tell what o'clock it is!\" \"Why should it?\" muttered the Hatter. \"Does your watch tell you what year it is?\" \"Of course not,\" Alice replied very readily: \"but that's because it stays the same year for such a long time together.\" \"Which is just the case with mine,\" said the Hatter. Alice felt dreadfully puzzled, The Hatter's remark seemed to have no sort of meaning in it, and yet it was certainly English. \"I don't quite understand you,\" she said, as politely as she could. \"The Dormouse is asleep again,\" said the Hatter, and he poured a little hot tea upon its nose. The Dormouse shook its head impatiently, and said, without opening its eyes, \"Of course, of course; just what I was going to remark myself.\" \"Have you guessed the riddle yet?\" the Hatter said, turning to Alice again. \"No, I give it up,\" Alice replied: \"what's the answer?\" \"I haven't the slightest idea,\" said the Hatter. \"Nor I,\" said the March Hare. Alice sighed wearily. \"I think you might do something better with the time,\" she said, \"than waste it in asking riddles that have no answers.\" \"If you knew Time as well as I do,\" said the Hatter, \"you wouldn't talk about wasting it. It's him.\" \"I don't know what you mean,\" said Alice. \"Of course you don't!\" the Hatter said, tossing his head contemptuously. \"I dare say you never even spoke to Time!\" \"Perhaps not,\" Alice cautiously replied: \"but I know I have to beat time when I learn music.\" \"Ah! that accounts for it,\" said the Hatter. \"He won't stand beating. Now, if you only kept on good terms with him, he'd do almost anything you liked with the clock. For instance, suppose it were nine o'clock in the morning, just time to begin lessons: you'd only have to whisper a hint to Time, and round goes the clock in a twinkling! Half-past one, time for dinner!\" (\"I only wish it was,\" the March Hare said to itself in a whisper.) \"That would be grand, certainly,\" said Alice thoughtfully: \"but then—I shouldn't be hungry for it, you know.\" \"Not at first, perhaps,\" said the Hatter: \"but you could keep it to half-past one as long as you liked.\" \"Is that the way you manage?\" Alice asked. The Hatter shook his head mournfully. \"Not I!\" he replied. \"We quarrelled last March—just before he went mad, you know—\" (pointing with his tea spoon at the March Hare,) \"—it was at the great concert given by the Queen of Hearts, and I had to sing 'Twinkle, twinkle, little bat! How I wonder what you're at!' You know the song, perhaps?\" \"I've heard something like it,\" said Alice. \"It goes on, you know,\" the Hatter continued, \"in this way:— 'Up above the world you fly, Like a tea-tray in the sky. Twinkle, twinkle—'\" Here the Dormouse shook itself, and began singing in its sleep \"Twinkle, twinkle, twinkle, twinkle—\" and went on so long that they had to pinch it to make it stop. \"Well, I'd hardly finished the first verse,\" said the Hatter, \"when the Queen jumped up and bawled out, 'He's murdering the time! Off with his head!'\" \"How dreadfully savage!\" exclaimed Alice. \"And ever since that,\" the Hatter went on in a mournful tone, \"he won't do a thing I ask! It's always six o'clock now.\" A bright idea came into Alice's head. \"Is that the reason so many tea-things are put out here?\" she asked. \"Yes, that's it,\" said the Hatter with a sigh: \"it's always tea-time, and we've no time to wash the things between whiles.\" \"Then you keep moving round, I suppose?\" said Alice. \"Exactly so,\" said the Hatter: \"as the things get used up.\" \"But what happens when you come to the beginning again?\" Alice ventured to ask. \"Suppose we change the subject,\" the March Hare interrupted, yawning. \"I'm getting tired of this. I vote the young lady tells us a story.\" \"I'm afraid I don't know one,\" said Alice, rather alarmed at the proposal. \"Then the Dormouse shall!\" they both cried. \"Wake up, Dormouse!\" And they pinched it on both sides at once. The Dormouse slowly opened his eyes. \"I wasn't asleep,\" he said in a hoarse, feeble voice: \"I heard every word you fellows were saying.\" \"Tell us a story!\" said the March Hare. \"Yes, please do!\" pleaded Alice. \"And be quick about it,\" added the Hatter, \"or you'll be asleep again before it's done.\" \"Once upon a time there were three little sisters,\" the Dormouse began in a great hurry; \"and their names were Elsie, Lacie, and Tillie; and they lived at the bottom of a well—\" \"What did they live on?\" said Alice, who always took a great interest in questions of eating and drinking. \"They lived on treacle,\" said the Dormouse, after thinking a minute or two. \"They couldn't have done that, you know,\" Alice gently remarked; \"they'd have been ill.\" \"So they were,\" said the Dormouse; \"very ill.\" Alice tried to fancy to herself what such an extraordinary way of living would be like, but it puzzled her too much, so she went on: \"But why did they live at the bottom of a well?\" \"Take some more tea,\" the March Hare said to Alice, very earnestly. \"I've had nothing yet,\" Alice replied in an offended tone, \"so I can't take more.\" \"You mean you can't take less,\" said the Hatter: \"it's very easy to take more than nothing.\" \"Nobody asked your opinion,\" said Alice. \"Who's making personal remarks now?\" the Hatter asked triumphantly. Alice did not quite know what to say to this: so she helped herself to some tea and bread-and-butter, and then turned to the Dormouse, and repeated her question. \"Why did they live at the bottom of a well?\" The Dormouse again took a minute or two to think about it, and then said, \"It was a treacle-well.\" \"There's no such thing!\" Alice was beginning very angrily, but the Hatter and the March Hare went \"Sh! sh!\" and the Dormouse sulkily remarked, \"If you can't be civil, you'd better finish the story for yourself.\" \"No, please go on!\" Alice said very humbly; \"I won't interrupt again. I dare say there may be one.\" \"One, indeed!\" said the Dormouse indignantly. However, he consented to go on. \"And so these three little sisters—they were learning to draw, you know—\" \"What did they draw?\" said Alice, quite forgetting her promise. \"Treacle,\" said the Dormouse, without considering at all this time. \"I want a clean cup,\" interrupted the Hatter: \"let's all move one place on.\" He moved on as he spoke, and the Dormouse followed him: the March Hare moved into the Dormouse's place, and Alice rather unwillingly took the place of the March Hare. The Hatter was the only one who got any advantage from the change: and Alice was a good deal worse off than before, as the March Hare had just upset the milk-jug into his plate. Alice did not wish to offend the Dormouse again, so she began very cautiously: \"But I don't understand. Where did they draw the treacle from?\" \"You can draw water out of a water-well,\" said the Hatter; \"so I should think you could draw treacle out of a treacle-well—eh, stupid?\" \"But they were in the well,\" Alice said to the Dormouse, not choosing to notice this last remark. \"Of course they were,\" said the Dormouse; \"—well in.\" This answer so confused poor Alice, that she let the Dormouse go on for some time without interrupting it. \"They were learning to draw,\" the Dormouse went on, yawning and rubbing its eyes, for it was getting very sleepy; \"and they drew all manner of things—everything that begins with an M—\" \"Why with an M?\" said Alice. \"Why not?\" said the March Hare. Alice was silent. The Dormouse had closed its eyes by this time, and was going off into a doze; but, on being pinched by the Hatter, it woke up again with a little shriek, and went on: \"—that begins with an M, such as mouse-traps, and the moon, and memory, and muchness—you know you say things are \"much of a muchness\"—did you ever see such a thing as a drawing of a muchness?\" \"Really, now you ask me,\" said Alice, very much confused, \"I don't think—\" \"Then you shouldn't talk,\" said the Hatter. This piece of rudeness was more than Alice could bear: she got up in great disgust, and walked off; the Dormouse fell asleep instantly, and neither of the others took the least notice of her going, though she looked back once or twice, half hoping that they would call after her: the last time she saw them, they were trying to put the Dormouse into the teapot. \"At any rate I'll never go there again!\" said Alice as she picked her way through the wood. \"It's the stupidest tea-party I ever was at in all my life!\" Just as she said this, she noticed that one of the trees had a door leading right into it. \"That's very curious!\" she thought. \"But everything's curious today. I think I may as well go in at once.\" And in she went. Once more she found herself in the long hall, and close to the little glass table. \"Now, I'll manage better this time,\" she said to herself, and began by taking the little golden key, and unlocking the door that led into the garden. Then she went to work nibbling at the mushroom (she had kept a piece of it in her pocket) till she was about a foot high: then she walked down the little passage: and then—she found herself at last in the beautiful garden, among the bright flower-beds and the cool fountains. CHAPTER VIII. The Queen's Croquet-Ground A large rose-tree stood near the entrance of the garden: the roses growing on it were white, but there were three gardeners at it, busily painting them red. Alice thought this a very curious thing, and she went nearer to watch them, and just as she came up to them she heard one of them say, \"Look out now, Five! Don't go splashing paint over me like that!\" \"I couldn't help it,\" said Five, in a sulky tone; \"Seven jogged my elbow.\" On which Seven looked up and said, \"That's right, Five! Always lay the blame on others!\" \"You'd better not talk!\" said Five. \"I heard the Queen say only yesterday you deserved to be beheaded!\" \"What for?\" said the one who had spoken first. \"That's none of your business, Two!\" said Seven. \"Yes, it is his business!\" said Five, \"and I'll tell him—it was for bringing the cook tulip-roots instead of onions.\" Seven flung down his brush, and had just begun \"Well, of all the unjust things—\" when his eye chanced to fall upon Alice, as she stood watching them, and he checked himself suddenly: the others looked round also, and all of them bowed low. \"Would you tell me,\" said Alice, a little timidly, \"why you are painting those roses?\" Five and Seven said nothing, but looked at Two. Two began in a low voice, \"Why the fact is, you see, Miss, this here ought to have been a red rose-tree, and we put a white one in by mistake; and if the Queen was to find it out, we should all have our heads cut off, you know. So you see, Miss, we're doing our best, afore she comes, to—\" At this moment Five, who had been anxiously looking across the garden, called out \"The Queen! The Queen!\" and the three gardeners instantly threw themselves flat upon their faces. There was a sound of many footsteps, and Alice looked round, eager to see the Queen. First came ten soldiers carrying clubs; these were all shaped like the three gardeners, oblong and flat, with their hands and feet at the corners: next the ten courtiers; these were ornamented all over with diamonds, and walked two and two, as the soldiers did. After these came the royal children; there were ten of them, and the little dears came jumping merrily along hand in hand, in couples: they were all ornamented with hearts. Next came the guests, mostly Kings and Queens, and among them Alice recognised the White Rabbit: it was talking in a hurried nervous manner, smiling at everything that was said, and went by without noticing her. Then followed the Knave of Hearts, carrying the King's crown on a crimson velvet cushion; and, last of all this grand procession, came THE KING AND QUEEN OF HEARTS. Alice was rather doubtful whether she ought not to lie down on her face like the three gardeners, but she could not remember ever having heard of such a rule at processions; \"and besides, what would be the use of a procession,\" thought she, \"if people had all to lie down upon their faces, so that they couldn't see it?\" So she stood still where she was, and waited. When the procession came opposite to Alice, they all stopped and looked at her, and the Queen said severely \"Who is this?\" She said it to the Knave of Hearts, who only bowed and smiled in reply. \"Idiot!\" said the Queen, tossing her head impatiently; and, turning to Alice, she went on, \"What's your name, child?\" \"My name is Alice, so please your Majesty,\" said Alice very politely; but she added, to herself, \"Why, they're only a pack of cards, after all. I needn't be afraid of them!\" \"And who are these?\" said the Queen, pointing to the three gardeners who were lying round the rose-tree; for, you see, as they were lying on their faces, and the pattern on their backs was the same as the rest of the pack, she could not tell whether they were gardeners, or soldiers, or courtiers, or three of her own children. \"How should I know?\" said Alice, surprised at her own courage. \"It's no business of mine.\" The Queen turned crimson with fury, and, after glaring at her for a moment like a wild beast, screamed \"Off with her head! Off—\" \"Nonsense!\" said Alice, very loudly and decidedly, and the Queen was silent. The King laid his hand upon her arm, and timidly said \"Consider, my dear: she is only a child!\" The Queen turned angrily away from him, and said to the Knave \"Turn them over!\" The Knave did so, very carefully, with one foot. \"Get up!\" said the Queen, in a shrill, loud voice, and the three gardeners instantly jumped up, and began bowing to the King, the Queen, the royal children, and everybody else. \"Leave off that!\" screamed the Queen. \"You make me giddy.\" And then, turning to the rose-tree, she went on, \"What have you been doing here?\" \"May it please your Majesty,\" said Two, in a very humble tone, going down on one knee as he spoke, \"we were trying—\" \"I see!\" said the Queen, who had meanwhile been examining the roses. \"Off with their heads!\" and the procession moved on, three of the soldiers remaining behind to execute the unfortunate gardeners, who ran to Alice for protection. \"You shan't be beheaded!\" said Alice, and she put them into a large flower-pot that stood near. The three soldiers wandered about for a minute or two, looking for them, and then quietly marched off after the others. \"Are their heads off?\" shouted the Queen. \"Their heads are gone, if it please your Majesty!\" the soldiers shouted in reply. \"That's right!\" shouted the Queen. \"Can you play croquet?\" The soldiers were silent, and looked at Alice, as the question was evidently meant for her. \"Yes!\" shouted Alice. \"Come on, then!\" roared the Queen, and Alice joined the procession, wondering very much what would happen next. \"It's—it's a very fine day!\" said a timid voice at her side. She was walking by the White Rabbit, who was peeping anxiously into her face. \"Very,\" said Alice: \"—where's the Duchess?\" \"Hush! Hush!\" said the Rabbit in a low, hurried tone. He looked anxiously over his shoulder as he spoke, and then raised himself upon tiptoe, put his mouth close to her ear, and whispered \"She's under sentence of execution.\" \"What for?\" said Alice. \"Did you say 'What a pity!'?\" the Rabbit asked. \"No, I didn't,\" said Alice: \"I don't think it's at all a pity. I said 'What for?'\" \"She boxed the Queen's ears—\" the Rabbit began. Alice gave a little scream of laughter. \"Oh, hush!\" the Rabbit whispered in a frightened tone. \"The Queen will hear you! You see, she came rather late, and the Queen said—\" \"Get to your places!\" shouted the Queen in a voice of thunder, and people began running about in all directions, tumbling up against each other; however, they got settled down in a minute or two, and the game began. Alice thought she had never seen such a curious croquet-ground in her life; it was all ridges and furrows; the balls were live hedgehogs, the mallets live flamingoes, and the soldiers had to double themselves up and to stand on their hands and feet, to make the arches. The chief difficulty Alice found at first was in managing her flamingo: she succeeded in getting its body tucked away, comfortably enough, under her arm, with its legs hanging down, but generally, just as she had got its neck nicely straightened out, and was going to give the hedgehog a blow with its head, it would twist itself round and look up in her face, with such a puzzled expression that she could not help bursting out laughing: and when she had got its head down, and was going to begin again, it was very provoking to find that the hedgehog had unrolled itself, and was in the act of crawling away: besides all this, there was generally a ridge or furrow in the way wherever she wanted to send the hedgehog to, and, as the doubled-up soldiers were always getting up and walking off to other parts of the ground, Alice soon came to the conclusion that it was a very difficult game indeed. The players all played at once without waiting for turns, quarrelling all the while, and fighting for the hedgehogs; and in a very short time the Queen was in a furious passion, and went stamping about, and shouting \"Off with his head!\" or \"Off with her head!\" about once in a minute. Alice began to feel very uneasy: to be sure, she had not as yet had any dispute with the Queen, but she knew that it might happen any minute, \"and then,\" thought she, \"what would become of me? They're dreadfully fond of beheading people here; the great wonder is, that there's any one left alive!\" She was looking about for some way of escape, and wondering whether she could get away without being seen, when she noticed a curious appearance in the air: it puzzled her very much at first, but, after watching it a minute or two, she made it out to be a grin, and she said to herself \"It's the Cheshire Cat: now I shall have somebody to talk to.\" \"How are you getting on?\" said the Cat, as soon as there was mouth enough for it to speak with. Alice waited till the eyes appeared, and then nodded. \"It's no use speaking to it,\" she thought, \"till its ears have come, or at least one of them.\" In another minute the whole head appeared, and then Alice put down her flamingo, and began an account of the game, feeling very glad she had someone to listen to her. The Cat seemed to think that there was enough of it now in sight, and no more of it appeared. \"I don't think they play at all fairly,\" Alice began, in rather a complaining tone, \"and they all quarrel so dreadfully one can't hear oneself speak—and they don't seem to have any rules in particular; at least, if there are, nobody attends to them—and you've no idea how confusing it is all the things being alive; for instance, there's the arch I've got to go through next walking about at the other end of the ground—and I should have croqueted the Queen's hedgehog just now, only it ran away when it saw mine coming!\" \"How do you like the Queen?\" said the Cat in a low voice. \"Not at all,\" said Alice: \"she's so extremely—\" Just then she noticed that the Queen was close behind her, listening: so she went on, \"—likely to win, that it's hardly worth while finishing the game.\" The Queen smiled and passed on. \"Who are you talking to?\" said the King, going up to Alice, and looking at the Cat's head with great curiosity. \"It's a friend of mine—a Cheshire Cat,\" said Alice: \"allow me to introduce it.\" \"I don't like the look of it at all,\" said the King: \"however, it may kiss my hand if it likes.\" \"I'd rather not,\" the Cat remarked. \"Don't be impertinent,\" said the King, \"and don't look at me like that!\" He got behind Alice as he spoke. \"A cat may look at a king,\" said Alice. \"I've read that in some book, but I don't remember where.\" \"Well, it must be removed,\" said the King very decidedly, and he called the Queen, who was passing at the moment, \"My dear! I wish you would have this cat removed!\" The Queen had only one way of settling all difficulties, great or small. \"Off with his head!\" she said, without even looking round. \"I'll fetch the executioner myself,\" said the King eagerly, and he hurried off. Alice thought she might as well go back, and see how the game was going on, as she heard the Queen's voice in the distance, screaming with passion. She had already heard her sentence three of the players to be executed for having missed their turns, and she did not like the look of things at all, as the game was in such confusion that she never knew whether it was her turn or not. So she went in search of her hedgehog. The hedgehog was engaged in a fight with another hedgehog, which seemed to Alice an excellent opportunity for croqueting one of them with the other: the only difficulty was, that her flamingo was gone across to the other side of the garden, where Alice could see it trying in a helpless sort of way to fly up into a tree. By the time she had caught the flamingo and brought it back, the fight was over, and both the hedgehogs were out of sight: \"but it doesn't matter much,\" thought Alice, \"as all the arches are gone from this side of the ground.\" So she tucked it away under her arm, that it might not escape again, and went back for a little more conversation with her friend. When she got back to the Cheshire Cat, she was surprised to find quite a large crowd collected round it: there was a dispute going on between the executioner, the King, and the Queen, who were all talking at once, while all the rest were quite silent, and looked very uncomfortable. The moment Alice appeared, she was appealed to by all three to settle the question, and they repeated their arguments to her, though, as they all spoke at once, she found it very hard indeed to make out exactly what they said. The executioner's argument was, that you couldn't cut off a head unless there was a body to cut it off from: that he had never had to do such a thing before, and he wasn't going to begin at his time of life. The King's argument was, that anything that had a head could be beheaded, and that you weren't to talk nonsense. The Queen's argument was, that if something wasn't done about it in less than no time she'd have everybody executed, all round. (It was this last remark that had made the whole party look so grave and anxious.) Alice could think of nothing else to say but \"It belongs to the Duchess: you'd better ask her about it.\" \"She's in prison,\" the Queen said to the executioner: \"fetch her here.\" And the executioner went off like an arrow. The Cat's head began fading away the moment he was gone, and, by the time he had come back with the Duchess, it had entirely disappeared; so the King and the executioner ran wildly up and down looking for it, while the rest of the party went back to the game. CHAPTER IX. The Mock Turtle's Story \"You can't think how glad I am to see you again, you dear old thing!\" said the Duchess, as she tucked her arm affectionately into Alice's, and they walked off together. Alice was very glad to find her in such a pleasant temper, and thought to herself that perhaps it was only the pepper that had made her so savage when they met in the kitchen. \"When I'm a Duchess,\" she said to herself, (not in a very hopeful tone though), \"I won't have any pepper in my kitchen at all. Soup does very well without—Maybe it's always pepper that makes people hot-tempered,\" she went on, very much pleased at having found out a new kind of rule, \"and vinegar that makes them sour—and camomile that makes them bitter—and—and barley-sugar and such things that make children sweet-tempered. I only wish people knew that: then they wouldn't be so stingy about it, you know—\" She had quite forgotten the Duchess by this time, and was a little startled when she heard her voice close to her ear. \"You're thinking about something, my dear, and that makes you forget to talk. I can't tell you just now what the moral of that is, but I shall remember it in a bit.\" \"Perhaps it hasn't one,\" Alice ventured to remark. \"Tut, tut, child!\" said the Duchess. \"Everything's got a moral, if only you can find it.\" And she squeezed herself up closer to Alice's side as she spoke. Alice did not much like keeping so close to her: first, because the Duchess was very ugly; and secondly, because she was exactly the right height to rest her chin upon Alice's shoulder, and it was an uncomfortably sharp chin. However, she did not like to be rude, so she bore it as well as she could. \"The game's going on rather better now,\" she said, by way of keeping up the conversation a little. \"'Tis so,\" said the Duchess: \"and the moral of that is—'Oh, 'tis love, 'tis love, that makes the world go round!'\" \"Somebody said,\" Alice whispered, \"that it's done by everybody minding their own business!\" \"Ah, well! It means much the same thing,\" said the Duchess, digging her sharp little chin into Alice's shoulder as she added, \"and the moral of that is—'Take care of the sense, and the sounds will take care of themselves.'\" \"How fond she is of finding morals in things!\" Alice thought to herself. \"I dare say you're wondering why I don't put my arm round your waist,\" the Duchess said after a pause: \"the reason is, that I'm doubtful about the temper of your flamingo. Shall I try the experiment?\" \"He might bite,\" Alice cautiously replied, not feeling at all anxious to have the experiment tried. \"Very true,\" said the Duchess: \"flamingoes and mustard both bite. And the moral of that is—'Birds of a feather flock together.'\" \"Only mustard isn't a bird,\" Alice remarked. \"Right, as usual,\" said the Duchess: \"what a clear way you have of putting things!\" \"It's a mineral, I think,\" said Alice. \"Of course it is,\" said the Duchess, who seemed ready to agree to everything that Alice said; \"there's a large mustard-mine near here. And the moral of that is—'The more there is of mine, the less there is of yours.'\" \"Oh, I know!\" exclaimed Alice, who had not attended to this last remark, \"it's a vegetable. It doesn't look like one, but it is.\" \"I quite agree with you,\" said the Duchess; \"and the moral of that is—'Be what you would seem to be'—or if you'd like it put more simply—'Never imagine yourself not to be otherwise than what it might appear to others that what you were or might have been was not otherwise than what you had been would have appeared to them to be otherwise.'\" \"I think I should understand that better,\" Alice said very politely, \"if I had it written down: but I can't quite follow it as you say it.\" \"That's nothing to what I could say if I chose,\" the Duchess replied, in a pleased tone. \"Pray don't trouble yourself to say it any longer than that,\" said Alice. \"Oh, don't talk about trouble!\" said the Duchess. \"I make you a present of everything I've said as yet.\" \"A cheap sort of present!\" thought Alice. \"I'm glad they don't give birthday presents like that!\" But she did not venture to say it out loud. \"Thinking again?\" the Duchess asked, with another dig of her sharp little chin. \"I've a right to think,\" said Alice sharply, for she was beginning to feel a little worried. \"Just about as much right,\" said the Duchess, \"as pigs have to fly; and the m—\" But here, to Alice's great surprise, the Duchess's voice died away, even in the middle of her favourite word 'moral,' and the arm that was linked into hers began to tremble. Alice looked up, and there stood the Queen in front of them, with her arms folded, frowning like a thunderstorm. \"A fine day, your Majesty!\" the Duchess began in a low, weak voice. \"Now, I give you fair warning,\" shouted the Queen, stamping on the ground as she spoke; \"either you or your head must be off, and that in about half no time! Take your choice!\" The Duchess took her choice, and was gone in a moment. \"Let's go on with the game,\" the Queen said to Alice; and Alice was too much frightened to say a word, but slowly followed her back to the croquet-ground. The other guests had taken advantage of the Queen's absence, and were resting in the shade: however, the moment they saw her, they hurried back to the game, the Queen merely remarking that a moment's delay would cost them their lives. All the time they were playing the Queen never left off quarrelling with the other players, and shouting \"Off with his head!\" or \"Off with her head!\" Those whom she sentenced were taken into custody by the soldiers, who of course had to leave off being arches to do this, so that by the end of half an hour or so there were no arches left, and all the players, except the King, the Queen, and Alice, were in custody and under sentence of execution. Then the Queen left off, quite out of breath, and said to Alice, \"Have you seen the Mock Turtle yet?\" \"No,\" said Alice. \"I don't even know what a Mock Turtle is.\" \"It's the thing Mock Turtle Soup is made from,\" said the Queen. \"I never saw one, or heard of one,\" said Alice. \"Come on, then,\" said the Queen, \"and he shall tell you his history.\" As they walked off together, Alice heard the King say in a low voice, to the company generally, \"You are all pardoned.\" \"Come, that's a good thing!\" she said to herself, for she had felt quite unhappy at the number of executions the Queen had ordered. They very soon came upon a Gryphon, lying fast asleep in the sun. (If you don't know what a Gryphon is, look at the picture.) \"Up, lazy thing!\" said the Queen, \"and take this young lady to see the Mock Turtle, and to hear his history. I must go back and see after some executions I have ordered;\" and she walked off, leaving Alice alone with the Gryphon. Alice did not quite like the look of the creature, but on the whole she thought it would be quite as safe to stay with it as to go after that savage Queen: so she waited. The Gryphon sat up and rubbed its eyes: then it watched the Queen till she was out of sight: then it chuckled. \"What fun!\" said the Gryphon, half to itself, half to Alice. \"What is the fun?\" said Alice. \"Why, she,\" said the Gryphon. \"It's all her fancy, that: they never executes nobody, you know. Come on!\" \"Everybody says 'come on!' here,\" thought Alice, as she went slowly after it: \"I never was so ordered about in all my life, never!\" They had not gone far before they saw the Mock Turtle in the distance, sitting sad and lonely on a little ledge of rock, and, as they came nearer, Alice could hear him sighing as if his heart would break. She pitied him deeply. \"What is his sorrow?\" she asked the Gryphon, and the Gryphon answered, very nearly in the same words as before, \"It's all his fancy, that: he hasn't got no sorrow, you know. Come on!\" So they went up to the Mock Turtle, who looked at them with large eyes full of tears, but said nothing. \"This here young lady,\" said the Gryphon, \"she wants for to know your history, she do.\" \"I'll tell it her,\" said the Mock Turtle in a deep, hollow tone: \"sit down, both of you, and don't speak a word till I've finished.\" So they sat down, and nobody spoke for some minutes. Alice thought to herself, \"I don't see how he can ever finish, if he doesn't begin.\" But she waited patiently. \"Once,\" said the Mock Turtle at last, with a deep sigh, \"I was a real Turtle.\" These words were followed by a very long silence, broken only by an occasional exclamation of \"Hjckrrh!\" from the Gryphon, and the constant heavy sobbing of the Mock Turtle. Alice was very nearly getting up and saying, \"Thank you, sir, for your interesting story,\" but she could not help thinking there must be more to come, so she sat still and said nothing. \"When we were little,\" the Mock Turtle went on at last, more calmly, though still sobbing a little now and then, \"we went to school in the sea. The master was an old Turtle—we used to call him Tortoise—\" \"Why did you call him Tortoise, if he wasn't one?\" Alice asked. \"We called him Tortoise because he taught us,\" said the Mock Turtle angrily: \"really you are very dull!\" \"You ought to be ashamed of yourself for asking such a simple question,\" added the Gryphon; and then they both sat silent and looked at poor Alice, who felt ready to sink into the earth. At last the Gryphon said to the Mock Turtle, \"Drive on, old fellow! Don't be all day about it!\" and he went on in these words: \"Yes, we went to school in the sea, though you mayn't believe it—\" \"I never said I didn't!\" interrupted Alice. \"You did,\" said the Mock Turtle. \"Hold your tongue!\" added the Gryphon, before Alice could speak again. The Mock Turtle went on. \"We had the best of educations—in fact, we went to school every day—\" \"I've been to a day-school, too,\" said Alice; \"you needn't be so proud as all that.\" \"With extras?\" asked the Mock Turtle a little anxiously. \"Yes,\" said Alice, \"we learned French and music.\" \"And washing?\" said the Mock Turtle. \"Certainly not!\" said Alice indignantly. \"Ah! then yours wasn't a really good school,\" said the Mock Turtle in a tone of great relief. \"Now at ours they had at the end of the bill, 'French, music, and washing—extra.'\" \"You couldn't have wanted it much,\" said Alice; \"living at the bottom of the sea.\" \"I couldn't afford to learn it.\" said the Mock Turtle with a sigh. \"I only took the regular course.\" \"What was that?\" inquired Alice. \"Reeling and Writhing, of course, to begin with,\" the Mock Turtle replied; \"and then the different branches of Arithmetic—Ambition, Distraction, Uglification, and Derision.\" \"I never heard of 'Uglification,'\" Alice ventured to say. \"What is it?\" The Gryphon lifted up both its paws in surprise. \"What! Never heard of uglifying!\" it exclaimed. \"You know what to beautify is, I suppose?\" \"Yes,\" said Alice doubtfully: \"it means—to—make—anything—prettier.\" \"Well, then,\" the Gryphon went on, \"if you don't know what to uglify is, you are a simpleton.\" Alice did not feel encouraged to ask any more questions about it, so she turned to the Mock Turtle, and said \"What else had you to learn?\" \"Well, there was Mystery,\" the Mock Turtle replied, counting off the subjects on his flappers, \"—Mystery, ancient and modern, with Seaography: then Drawling—the Drawling-master was an old conger-eel, that used to come once a week: he taught us Drawling, Stretching, and Fainting in Coils.\" \"What was that like?\" said Alice. \"Well, I can't show it you myself,\" the Mock Turtle said: \"I'm too stiff. And the Gryphon never learnt it.\" \"Hadn't time,\" said the Gryphon: \"I went to the Classics master, though. He was an old crab, he was.\" \"I never went to him,\" the Mock Turtle said with a sigh: \"he taught Laughing and Grief, they used to say.\" \"So he did, so he did,\" said the Gryphon, sighing in his turn; and both creatures hid their faces in their paws. \"And how many hours a day did you do lessons?\" said Alice, in a hurry to change the subject. \"Ten hours the first day,\" said the Mock Turtle: \"nine the next, and so on.\" \"What a curious plan!\" exclaimed Alice. \"That's the reason they're called lessons,\" the Gryphon remarked: \"because they lessen from day to day.\" This was quite a new idea to Alice, and she thought it over a little before she made her next remark. \"Then the eleventh day must have been a holiday?\" \"Of course it was,\" said the Mock Turtle. \"And how did you manage on the twelfth?\" Alice went on eagerly. \"That's enough about lessons,\" the Gryphon interrupted in a very decided tone: \"tell her something about the games now.\" CHAPTER X. The Lobster Quadrille The Mock Turtle sighed deeply, and drew the back of one flapper across his eyes. He looked at Alice, and tried to speak, but for a minute or two sobs choked his voice. \"Same as if he had a bone in his throat,\" said the Gryphon: and it set to work shaking him and punching him in the back. At last the Mock Turtle recovered his voice, and, with tears running down his cheeks, he went on again:— \"You may not have lived much under the sea—\" (\"I haven't,\" said Alice)—\"and perhaps you were never even introduced to a lobster—\" (Alice began to say \"I once tasted—\" but checked herself hastily, and said \"No, never\") \"—so you can have no idea what a delightful thing a Lobster Quadrille is!\" \"No, indeed,\" said Alice. \"What sort of a dance is it?\" \"Why,\" said the Gryphon, \"you first form into a line along the sea-shore—\" \"Two lines!\" cried the Mock Turtle. \"Seals, turtles, salmon, and so on; then, when you've cleared all the jelly-fish out of the way—\" \"That generally takes some time,\" interrupted the Gryphon. \"—you advance twice—\" \"Each with a lobster as a partner!\" cried the Gryphon. \"Of course,\" the Mock Turtle said: \"advance twice, set to partners—\" \"—change lobsters, and retire in same order,\" continued the Gryphon. \"Then, you know,\" the Mock Turtle went on, \"you throw the—\" \"The lobsters!\" shouted the Gryphon, with a bound into the air. \"—as far out to sea as you can—\" \"Swim after them!\" screamed the Gryphon. \"Turn a somersault in the sea!\" cried the Mock Turtle, capering wildly about. \"Change lobsters again!\" yelled the Gryphon at the top of its voice. \"Back to land again, and that's all the first figure,\" said the Mock Turtle, suddenly dropping his voice; and the two creatures, who had been jumping about like mad things all this time, sat down again very sadly and quietly, and looked at Alice. \"It must be a very pretty dance,\" said Alice timidly. \"Would you like to see a little of it?\" said the Mock Turtle. \"Very much indeed,\" said Alice. \"Come, let's try the first figure!\" said the Mock Turtle to the Gryphon. \"We can do without lobsters, you know. Which shall sing?\" \"Oh, you sing,\" said the Gryphon. \"I've forgotten the words.\" So they began solemnly dancing round and round Alice, every now and then treading on her toes when they passed too close, and waving their forepaws to mark the time, while the Mock Turtle sang this, very slowly and sadly:— \"Will you walk a little faster?\" said a whiting to a snail. \"There's a porpoise close behind us, and he's treading on my tail. See how eagerly the lobsters and the turtles all advance! They are waiting on the shingle—will you come and join the dance? Will you, won't you, will you, won't you, will you join the dance? Will you, won't you, will you, won't you, won't you join the dance? \"You can really have no notion how delightful it will be When they take us up and throw us, with the lobsters, out to sea!\" But the snail replied \"Too far, too far!\" and gave a look askance— Said he thanked the whiting kindly, but he would not join the dance. Would not, could not, would not, could not, would not join the dance. Would not, could not, would not, could not, could not join the dance. \"What matters it how far we go?\" his scaly friend replied. \"There is another shore, you know, upon the other side. The further off from England the nearer is to France— Then turn not pale, beloved snail, but come and join the dance. Will you, won't you, will you, won't you, will you join the dance? Will you, won't you, will you, won't you, won't you join the dance?\" \"Thank you, it's a very interesting dance to watch,\" said Alice, feeling very glad that it was over at last: \"and I do so like that curious song about the whiting!\" \"Oh, as to the whiting,\" said the Mock Turtle, \"they—you've seen them, of course?\" \"Yes,\" said Alice, \"I've often seen them at dinn—\" she checked herself hastily. \"I don't know where Dinn may be,\" said the Mock Turtle, \"but if you've seen them so often, of course you know what they're like.\" \"I believe so,\" Alice replied thoughtfully. \"They have their tails in their mouths—and they're all over crumbs.\" \"You're wrong about the crumbs,\" said the Mock Turtle: \"crumbs would all wash off in the sea. But they have their tails in their mouths; and the reason is—\" here the Mock Turtle yawned and shut his eyes.—\"Tell her about the reason and all that,\" he said to the Gryphon. \"The reason is,\" said the Gryphon, \"that they would go with the lobsters to the dance. So they got thrown out to sea. So they had to fall a long way. So they got their tails fast in their mouths. So they couldn't get them out again. That's all.\" \"Thank you,\" said Alice, \"it's very interesting. I never knew so much about a whiting before.\" \"I can tell you more than that, if you like,\" said the Gryphon. \"Do you know why it's called a whiting?\" \"I never thought about it,\" said Alice. \"Why?\" \"It does the boots and shoes,\" the Gryphon replied very solemnly. Alice was thoroughly puzzled. \"Does the boots and shoes!\" she repeated in a wondering tone. \"Why, what are your shoes done with?\" said the Gryphon. \"I mean, what makes them so shiny?\" Alice looked down at them, and considered a little before she gave her answer. \"They're done with blacking, I believe.\" \"Boots and shoes under the sea,\" the Gryphon went on in a deep voice, \"are done with a whiting. Now you know.\" \"And what are they made of?\" Alice asked in a tone of great curiosity. \"Soles and eels, of course,\" the Gryphon replied rather impatiently: \"any shrimp could have told you that.\" \"If I'd been the whiting,\" said Alice, whose thoughts were still running on the song, \"I'd have said to the porpoise, 'Keep back, please: we don't want you with us!'\" \"They were obliged to have him with them,\" the Mock Turtle said: \"no wise fish would go anywhere without a porpoise.\" \"Wouldn't it really?\" said Alice in a tone of great surprise. \"Of course not,\" said the Mock Turtle: \"why, if a fish came to me, and told me he was going a journey, I should say 'With what porpoise?'\" \"Don't you mean 'purpose'?\" said Alice. \"I mean what I say,\" the Mock Turtle replied in an offended tone. And the Gryphon added \"Come, let's hear some of your adventures.\" \"I could tell you my adventures—beginning from this morning,\" said Alice a little timidly: \"but it's no use going back to yesterday, because I was a different person then.\" \"Explain all that,\" said the Mock Turtle. \"No, no! The adventures first,\" said the Gryphon in an impatient tone: \"explanations take such a dreadful time.\" So Alice began telling them her adventures from the time when she first saw the White Rabbit. She was a little nervous about it just at first, the two creatures got so close to her, one on each side, and opened their eyes and mouths so very wide, but she gained courage as she went on. Her listeners were perfectly quiet till she got to the part about her repeating \"You are old, Father William,\" to the Caterpillar, and the words all coming different, and then the Mock Turtle drew a long breath, and said \"That's very curious.\" \"It's all about as curious as it can be,\" said the Gryphon. \"It all came different!\" the Mock Turtle repeated thoughtfully. \"I should like to hear her try and repeat something now. Tell her to begin.\" He looked at the Gryphon as if he thought it had some kind of authority over Alice. \"Stand up and repeat ''Tis the voice of the sluggard,'\" said the Gryphon. \"How the creatures order one about, and make one repeat lessons!\" thought Alice; \"I might as well be at school at once.\" However, she got up, and began to repeat it, but her head was so full of the Lobster Quadrille, that she hardly knew what she was saying, and the words came very queer indeed:— \"'Tis the voice of the Lobster; I heard him declare, \"You have baked me too brown, I must sugar my hair.\" As a duck with its eyelids, so he with his nose Trims his belt and his buttons, and turns out his toes.\" [later editions continued as follows When the sands are all dry, he is gay as a lark, And will talk in contemptuous tones of the Shark, But, when the tide rises and sharks are around, His voice has a timid and tremulous sound.] \"That's different from what I used to say when I was a child,\" said the Gryphon. \"Well, I never heard it before,\" said the Mock Turtle; \"but it sounds uncommon nonsense.\" Alice said nothing; she had sat down with her face in her hands, wondering if anything would ever happen in a natural way again. \"I should like to have it explained,\" said the Mock Turtle. \"She can't explain it,\" said the Gryphon hastily. \"Go on with the next verse.\" \"But about his toes?\" the Mock Turtle persisted. \"How could he turn them out with his nose, you know?\" \"It's the first position in dancing.\" Alice said; but was dreadfully puzzled by the whole thing, and longed to change the subject. \"Go on with the next verse,\" the Gryphon repeated impatiently: \"it begins 'I passed by his garden.'\" Alice did not dare to disobey, though she felt sure it would all come wrong, and she went on in a trembling voice:— \"I passed by his garden, and marked, with one eye, How the Owl and the Panther were sharing a pie—\" [later editions continued as follows The Panther took pie-crust, and gravy, and meat, While the Owl had the dish as its share of the treat. When the pie was all finished, the Owl, as a boon, Was kindly permitted to pocket the spoon: While the Panther received knife and fork with a growl, And concluded the banquet—] \"What is the use of repeating all that stuff,\" the Mock Turtle interrupted, \"if you don't explain it as you go on? It's by far the most confusing thing I ever heard!\" \"Yes, I think you'd better leave off,\" said the Gryphon: and Alice was only too glad to do so. \"Shall we try another figure of the Lobster Quadrille?\" the Gryphon went on. \"Or would you like the Mock Turtle to sing you a song?\" \"Oh, a song, please, if the Mock Turtle would be so kind,\" Alice replied, so eagerly that the Gryphon said, in a rather offended tone, \"Hm! No accounting for tastes! Sing her 'Turtle Soup,' will you, old fellow?\" The Mock Turtle sighed deeply, and began, in a voice sometimes choked with sobs, to sing this:— \"Beautiful Soup, so rich and green, Waiting in a hot tureen! Who for such dainties would not stoop? Soup of the evening, beautiful Soup! Soup of the evening, beautiful Soup! Beau—ootiful Soo—oop! Beau—ootiful Soo—oop! Soo—oop of the e—e—evening, Beautiful, beautiful Soup! \"Beautiful Soup! Who cares for fish, Game, or any other dish? Who would not give all else for two p ennyworth only of beautiful Soup? Pennyworth only of beautiful Soup? Beau—ootiful Soo—oop! Beau—ootiful Soo—oop! Soo—oop of the e—e—evening, Beautiful, beauti—FUL SOUP!\" \"Chorus again!\" cried the Gryphon, and the Mock Turtle had just begun to repeat it, when a cry of \"The trial's beginning!\" was heard in the distance. \"Come on!\" cried the Gryphon, and, taking Alice by the hand, it hurried off, without waiting for the end of the song. \"What trial is it?\" Alice panted as she ran; but the Gryphon only answered \"Come on!\" and ran the faster, while more and more faintly came, carried on the breeze that followed them, the melancholy words:— \"Soo—oop of the e—e—evening, Beautiful, beautiful Soup!\" CHAPTER XI. Who Stole the Tarts? The King and Queen of Hearts were seated on their throne when they arrived, with a great crowd assembled about them—all sorts of little birds and beasts, as well as the whole pack of cards: the Knave was standing before them, in chains, with a soldier on each side to guard him; and near the King was the White Rabbit, with a trumpet in one hand, and a scroll of parchment in the other. In the very middle of the court was a table, with a large dish of tarts upon it: they looked so good, that it made Alice quite hungry to look at them—\"I wish they'd get the trial done,\" she thought, \"and hand round the refreshments!\" But there seemed to be no chance of this, so she began looking at everything about her, to pass away the time. Alice had never been in a court of justice before, but she had read about them in books, and she was quite pleased to find that she knew the name of nearly everything there. \"That's the judge,\" she said to herself, \"because of his great wig.\" The judge, by the way, was the King; and as he wore his crown over the wig, (look at the frontispiece if you want to see how he did it,) he did not look at all comfortable, and it was certainly not becoming. \"And that's the jury-box,\" thought Alice, \"and those twelve creatures,\" (she was obliged to say \"creatures,\" you see, because some of them were animals, and some were birds,) \"I suppose they are the jurors.\" She said this last word two or three times over to herself, being rather proud of it: for she thought, and rightly too, that very few little girls of her age knew the meaning of it at all. However, \"jury-men\" would have done just as well. The twelve jurors were all writing very busily on slates. \"What are they doing?\" Alice whispered to the Gryphon. \"They can't have anything to put down yet, before the trial's begun.\" \"They're putting down their names,\" the Gryphon whispered in reply, \"for fear they should forget them before the end of the trial.\" \"Stupid things!\" Alice began in a loud, indignant voice, but she stopped hastily, for the White Rabbit cried out, \"Silence in the court!\" and the King put on his spectacles and looked anxiously round, to make out who was talking. Alice could see, as well as if she were looking over their shoulders, that all the jurors were writing down \"stupid things!\" on their slates, and she could even make out that one of them didn't know how to spell \"stupid,\" and that he had to ask his neighbour to tell him. \"A nice muddle their slates'll be in before the trial's over!\" thought Alice. One of the jurors had a pencil that squeaked. This of course, Alice could not stand, and she went round the court and got behind him, and very soon found an opportunity of taking it away. She did it so quickly that the poor little juror (it was Bill, the Lizard) could not make out at all what had become of it; so, after hunting all about for it, he was obliged to write with one finger for the rest of the day; and this was of very little use, as it left no mark on the slate. \"Herald, read the accusation!\" said the King. On this the White Rabbit blew three blasts on the trumpet, and then unrolled the parchment scroll, and read as follows:— \"The Queen of Hearts, she made some tarts, All on a summer day: The Knave of Hearts, he stole those tarts, And took them quite away!\" \"Consider your verdict,\" the King said to the jury. \"Not yet, not yet!\" the Rabbit hastily interrupted. \"There's a great deal to come before that!\" \"Call the first witness,\" said the King; and the White Rabbit blew three blasts on the trumpet, and called out, \"First witness!\" The first witness was the Hatter. He came in with a teacup in one hand and a piece of bread-and-butter in the other. \"I beg pardon, your Majesty,\" he began, \"for bringing these in: but I hadn't quite finished my tea when I was sent for.\" \"You ought to have finished,\" said the King. \"When did you begin?\" The Hatter looked at the March Hare, who had followed him into the court, arm-in-arm with the Dormouse. \"Fourteenth of March, I think it was,\" he said. \"Fifteenth,\" said the March Hare. \"Sixteenth,\" added the Dormouse. \"Write that down,\" the King said to the jury, and the jury eagerly wrote down all three dates on their slates, and then added them up, and reduced the answer to shillings and pence. \"Take off your hat,\" the King said to the Hatter. \"It isn't mine,\" said the Hatter. \"Stolen!\" the King exclaimed, turning to the jury, who instantly made a memorandum of the fact. \"I keep them to sell,\" the Hatter added as an explanation; \"I've none of my own. I'm a hatter.\" Here the Queen put on her spectacles, and began staring at the Hatter, who turned pale and fidgeted. \"Give your evidence,\" said the King; \"and don't be nervous, or I'll have you executed on the spot.\" This did not seem to encourage the witness at all: he kept shifting from one foot to the other, looking uneasily at the Queen, and in his confusion he bit a large piece out of his teacup instead of the bread-and-butter. Just at this moment Alice felt a very curious sensation, which puzzled her a good deal until she made out what it was: she was beginning to grow larger again, and she thought at first she would get up and leave the court; but on second thoughts she decided to remain where she was as long as there was room for her. \"I wish you wouldn't squeeze so,\" said the Dormouse, who was sitting next to her. \"I can hardly breathe.\" \"I can't help it,\" said Alice very meekly: \"I'm growing.\" \"You've no right to grow here,\" said the Dormouse. \"Don't talk nonsense,\" said Alice more boldly: \"you know you're growing too.\" \"Yes, but I grow at a reasonable pace,\" said the Dormouse: \"not in that ridiculous fashion.\" And he got up very sulkily and crossed over to the other side of the court. All this time the Queen had never left off staring at the Hatter, and, just as the Dormouse crossed the court, she said to one of the officers of the court, \"Bring me the list of the singers in the last concert!\" on which the wretched Hatter trembled so, that he shook both his shoes off. \"Give your evidence,\" the King repeated angrily, \"or I'll have you executed, whether you're nervous or not.\" \"I'm a poor man, your Majesty,\" the Hatter began, in a trembling voice, \"—and I hadn't begun my tea—not above a week or so—and what with the bread-and-butter getting so thin—and the twinkling of the tea—\" \"The twinkling of the what?\" said the King. \"It began with the tea,\" the Hatter replied. \"Of course twinkling begins with a T!\" said the King sharply. \"Do you take me for a dunce? Go on!\" \"I'm a poor man,\" the Hatter went on, \"and most things twinkled after that—only the March Hare said—\" \"I didn't!\" the March Hare interrupted in a great hurry. \"You did!\" said the Hatter. \"I deny it!\" said the March Hare. \"He denies it,\" said the King: \"leave out that part.\" \"Well, at any rate, the Dormouse said—\" the Hatter went on, looking anxiously round to see if he would deny it too: but the Dormouse denied nothing, being fast asleep. \"After that,\" continued the Hatter, \"I cut some more bread-and-butter—\" \"But what did the Dormouse say?\" one of the jury asked. \"That I can't remember,\" said the Hatter. \"You must remember,\" remarked the King, \"or I'll have you executed.\" The miserable Hatter dropped his teacup and bread-and-butter, and went down on one knee. \"I'm a poor man, your Majesty,\" he began. \"You're a very poor speaker,\" said the King. Here one of the guinea-pigs cheered, and was immediately suppressed by the officers of the court. (As that is rather a hard word, I will just explain to you how it was done. They had a large canvas bag, which tied up at the mouth with strings: into this they slipped the guinea-pig, head first, and then sat upon it.) \"I'm glad I've seen that done,\" thought Alice. \"I've so often read in the newspapers, at the end of trials, \"There was some attempts at applause, which was immediately suppressed by the officers of the court,\" and I never understood what it meant till now.\" \"If that's all you know about it, you may stand down,\" continued the King. \"I can't go no lower,\" said the Hatter: \"I'm on the floor, as it is.\" \"Then you may sit down,\" the King replied. Here the other guinea-pig cheered, and was suppressed. \"Come, that finished the guinea-pigs!\" thought Alice. \"Now we shall get on better.\" \"I'd rather finish my tea,\" said the Hatter, with an anxious look at the Queen, who was reading the list of singers. \"You may go,\" said the King, and the Hatter hurriedly left the court, without even waiting to put his shoes on. \"—and just take his head off outside,\" the Queen added to one of the officers: but the Hatter was out of sight before the officer could get to the door. \"Call the next witness!\" said the King. The next witness was the Duchess's cook. She carried the pepper-box in her hand, and Alice guessed who it was, even before she got into the court, by the way the people near the door began sneezing all at once. \"Give your evidence,\" said the King. \"Shan't,\" said the cook. The King looked anxiously at the White Rabbit, who said in a low voice, \"Your Majesty must cross-examine this witness.\" \"Well, if I must, I must,\" the King said, with a melancholy air, and, after folding his arms and frowning at the cook till his eyes were nearly out of sight, he said in a deep voice, \"What are tarts made of?\" \"Pepper, mostly,\" said the cook. \"Treacle,\" said a sleepy voice behind her. \"Collar that Dormouse,\" the Queen shrieked out. \"Behead that Dormouse! Turn that Dormouse out of court! Suppress him! Pinch him! Off with his whiskers!\" For some minutes the whole court was in confusion, getting the Dormouse turned out, and, by the time they had settled down again, the cook had disappeared. \"Never mind!\" said the King, with an air of great relief. \"Call the next witness.\" And he added in an undertone to the Queen, \"Really, my dear, you must cross-examine the next witness. It quite makes my forehead ache!\" Alice watched the White Rabbit as he fumbled over the list, feeling very curious to see what the next witness would be like, \"—for they haven't got much evidence yet,\" she said to herself. Imagine her surprise, when the White Rabbit read out, at the top of his shrill little voice, the name \"Alice!\" CHAPTER XII. Alice's Evidence \"Here!\" cried Alice, quite forgetting in the flurry of the moment how large she had grown in the last few minutes, and she jumped up in such a hurry that she tipped over the jury-box with the edge of her skirt, upsetting all the jurymen on to the heads of the crowd below, and there they lay sprawling about, reminding her very much of a globe of goldfish she had accidentally upset the week before. \"Oh, I beg your pardon!\" she exclaimed in a tone of great dismay, and began picking them up again as quickly as she could, for the accident of the goldfish kept running in her head, and she had a vague sort of idea that they must be collected at once and put back into the jury-box, or they would die. \"The trial cannot proceed,\" said the King in a very grave voice, \"until all the jurymen are back in their proper places—all,\" he repeated with great emphasis, looking hard at Alice as he said so. Alice looked at the jury-box, and saw that, in her haste, she had put the Lizard in head downwards, and the poor little thing was waving its tail about in a melancholy way, being quite unable to move. She soon got it out again, and put it right; \"not that it signifies much,\" she said to herself; \"I should think it would be quite as much use in the trial one way up as the other.\" As soon as the jury had a little recovered from the shock of being upset, and their slates and pencils had been found and handed back to them, they set to work very diligently to write out a history of the accident, all except the Lizard, who seemed too much overcome to do anything but sit with its mouth open, gazing up into the roof of the court. \"What do you know about this business?\" the King said to Alice. \"Nothing,\" said Alice. \"Nothing whatever?\" persisted the King. \"Nothing whatever,\" said Alice. \"That's very important,\" the King said, turning to the jury. They were just beginning to write this down on their slates, when the White Rabbit interrupted: \"Unimportant, your Majesty means, of course,\" he said in a very respectful tone, but frowning and making faces at him as he spoke. \"Unimportant, of course, I meant,\" the King hastily said, and went on to himself in an undertone, \"important—unimportant—unimportant—important—\" as if he were trying which word sounded best. Some of the jury wrote it down \"important,\" and some \"unimportant.\" Alice could see this, as she was near enough to look over their slates; \"but it doesn't matter a bit,\" she thought to herself. At this moment the King, who had been for some time busily writing in his note-book, cackled out \"Silence!\" and read out from his book, \"Rule Forty-two. All persons more than a mile high to leave the court.\" Everybody looked at Alice. \"I'm not a mile high,\" said Alice. \"You are,\" said the King. \"Nearly two miles high,\" added the Queen. \"Well, I shan't go, at any rate,\" said Alice: \"besides, that's not a regular rule: you invented it just now.\" \"It's the oldest rule in the book,\" said the King. \"Then it ought to be Number One,\" said Alice. The King turned pale, and shut his note-book hastily. \"Consider your verdict,\" he said to the jury, in a low, trembling voice. \"There's more evidence to come yet, please your Majesty,\" said the White Rabbit, jumping up in a great hurry; \"this paper has just been picked up.\" \"What's in it?\" said the Queen. \"I haven't opened it yet,\" said the White Rabbit, \"but it seems to be a letter, written by the prisoner to—to somebody.\" \"It must have been that,\" said the King, \"unless it was written to nobody, which isn't usual, you know.\" \"Who is it directed to?\" said one of the jurymen. \"It isn't directed at all,\" said the White Rabbit; \"in fact, there's nothing written on the outside.\" He unfolded the paper as he spoke, and added \"It isn't a letter, after all: it's a set of verses.\" \"Are they in the prisoner's handwriting?\" asked another of the jurymen. \"No, they're not,\" said the White Rabbit, \"and that's the queerest thing about it.\" (The jury all looked puzzled.) \"He must have imitated somebody else's hand,\" said the King. (The jury all brightened up again.) \"Please your Majesty,\" said the Knave, \"I didn't write it, and they can't prove I did: there's no name signed at the end.\" \"If you didn't sign it,\" said the King, \"that only makes the matter worse. You must have meant some mischief, or else you'd have signed your name like an honest man.\" There was a general clapping of hands at this: it was the first really clever thing the King had said that day. \"That proves his guilt,\" said the Queen. \"It proves nothing of the sort!\" said Alice. \"Why, you don't even know what they're about!\" \"Read them,\" said the King. The White Rabbit put on his spectacles. \"Where shall I begin, please your Majesty?\" he asked. \"Begin at the beginning,\" the King said gravely, \"and go on till you come to the end: then stop.\" These were the verses the White Rabbit read:— \"They told me you had been to her, And mentioned me to him: She gave me a good character, But said I could not swim. He sent them word I had not gone (We know it to be true): If she should push the matter on, What would become of you? I gave her one, they gave him two, You gave us three or more; They all returned from him to you, Though they were mine before. If I or she should chance to be Involved in this affair, He trusts to you to set them free, Exactly as we were. My notion was that you had been (Before she had this fit) An obstacle that came between Him, and ourselves, and it. Don't let him know she liked them best, For this must ever be A secret, kept from all the rest, Between yourself and me.\" \"That's the most important piece of evidence we've heard yet,\" said the King, rubbing his hands; \"so now let the jury—\" \"If any one of them can explain it,\" said Alice, (she had grown so large in the last few minutes that she wasn't a bit afraid of interrupting him,) \"I'll give him sixpence. I don't believe there's an atom of meaning in it.\" The jury all wrote down on their slates, \"She doesn't believe there's an atom of meaning in it,\" but none of them attempted to explain the paper. \"If there's no meaning in it,\" said the King, \"that saves a world of trouble, you know, as we needn't try to find any. And yet I don't know,\" he went on, spreading out the verses on his knee, and looking at them with one eye; \"I seem to see some meaning in them, after all. \"—said I could not swim—\" you can't swim, can you?\" he added, turning to the Knave. The Knave shook his head sadly. \"Do I look like it?\" he said. (Which he certainly did not, being made entirely of cardboard.) \"All right, so far,\" said the King, and he went on muttering over the verses to himself: \"'We know it to be true—' that's the jury, of course—'I gave her one, they gave him two—' why, that must be what he did with the tarts, you know—\" \"But, it goes on 'they all returned from him to you,'\" said Alice. \"Why, there they are!\" said the King triumphantly, pointing to the tarts on the table. \"Nothing can be clearer than that. Then again—'before she had this fit—' you never had fits, my dear, I think?\" he said to the Queen. \"Never!\" said the Queen furiously, throwing an inkstand at the Lizard as she spoke. (The unfortunate little Bill had left off writing on his slate with one finger, as he found it made no mark; but he now hastily began again, using the ink, that was trickling down his face, as long as it lasted.) \"Then the words don't fit you,\" said the King, looking round the court with a smile. There was a dead silence. \"It's a pun!\" the King added in an offended tone, and everybody laughed, \"Let the jury consider their verdict,\" the King said, for about the twentieth time that day. \"No, no!\" said the Queen. \"Sentence first—verdict afterwards.\" \"Stuff and nonsense!\" said Alice loudly. \"The idea of having the sentence first!\" \"Hold your tongue!\" said the Queen, turning purple. \"I won't!\" said Alice. \"Off with her head!\" the Queen shouted at the top of her voice. Nobody moved. \"Who cares for you?\" said Alice, (she had grown to her full size by this time.) \"You're nothing but a pack of cards!\" At this the whole pack rose up into the air, and came flying down upon her: she gave a little scream, half of fright and half of anger, and tried to beat them off, and found herself lying on the bank, with her head in the lap of her sister, who was gently brushing away some dead leaves that had fluttered down from the trees upon her face. \"Wake up, Alice dear!\" said her sister; \"Why, what a long sleep you've had!\" \"Oh, I've had such a curious dream!\" said Alice, and she told her sister, as well as she could remember them, all these strange Adventures of hers that you have just been reading about; and when she had finished, her sister kissed her, and said, \"It was a curious dream, dear, certainly: but now run in to your tea; it's getting late.\" So Alice got up and ran off, thinking while she ran, as well she might, what a wonderful dream it had been. But her sister sat still just as she left her, leaning her head on her hand, watching the setting sun, and thinking of little Alice and all her wonderful Adventures, till she too began dreaming after a fashion, and this was her dream:— First, she dreamed of little Alice herself, and once again the tiny hands were clasped upon her knee, and the bright eager eyes were looking up into hers—she could hear the very tones of her voice, and see that queer little toss of her head to keep back the wandering hair that would always get into her eyes—and still as she listened, or seemed to listen, the whole place around her became alive with the strange creatures of her little sister's dream. The long grass rustled at her feet as the White Rabbit hurried by—the frightened Mouse splashed his way through the neighbouring pool—she could hear the rattle of the teacups as the March Hare and his friends shared their never-ending meal, and the shrill voice of the Queen ordering off her unfortunate guests to execution—once more the pig-baby was sneezing on the Duchess's knee, while plates and dishes crashed around it—once more the shriek of the Gryphon, the squeaking of the Lizard's slate-pencil, and the choking of the suppressed guinea-pigs, filled the air, mixed up with the distant sobs of the miserable Mock Turtle. So she sat on, with closed eyes, and half believed herself in Wonderland, though she knew she had but to open them again, and all would change to dull reality—the grass would be only rustling in the wind, and the pool rippling to the waving of the reeds—the rattling teacups would change to tinkling sheep-bells, and the Queen's shrill cries to the voice of the shepherd boy—and the sneeze of the baby, the shriek of the Gryphon, and all the other queer noises, would change (she knew) to the confused clamour of the busy farm-yard—while the lowing of the cattle in the distance would take the place of the Mock Turtle's heavy sobs. Lastly, she pictured to herself how this same little sister of hers would, in the after-time, be herself a grown woman; and how she would keep, through all her riper years, the simple and loving heart of her childhood: and how she would gather about her other little children, and make their eyes bright and eager with many a strange tale, perhaps even with the dream of Wonderland of long ago: and how she would feel with all their simple sorrows, and find a pleasure in all their simple joys, remembering her own child-life, and the happy summer days. THE END","pride":"It is a truth universally acknowledged, that a single man in possession of a good fortune must be in want of a wife. However little known the feelings or views of such a man may be on his first entering a neighbourhood, this truth is so well fixed in the minds of the surrounding families, that he is considered as the rightful property of some one or other of their daughters. \"My dear Mr. Bennet,\" said his lady to him one day, \"have you heard that Netherfield Park is let at last?\" Mr. Bennet replied that he had not. \"But it is,\" returned she; \"for Mrs. Long has just been here, and she told me all about it.\" Mr. Bennet made no answer. \"Do not you want to know who has taken it?\" cried his wife, impatiently. \"You want to tell me, and I have no objection to hearing it.\" [Illustration: \"He came down to see the place\" [Copyright 1894 by George Allen.]] This was invitation enough. \"Why, my dear, you must know, Mrs. Long says that Netherfield is taken by a young man of large fortune from the north of England; that he came down on Monday in a chaise and four to see the place, and was so much delighted with it that he agreed with Mr. Morris immediately; that he is to take possession before Michaelmas, and some of his servants are to be in the house by the end of next week.\" \"What is his name?\" \"Bingley.\" \"Is he married or single?\" \"Oh, single, my dear, to be sure! A single man of large fortune; four or five thousand a year. What a fine thing for our girls!\" \"How so? how can it affect them?\" \"My dear Mr. Bennet,\" replied his wife, \"how can you be so tiresome? You must know that I am thinking of his marrying one of them.\" \"Is that his design in settling here?\" \"Design? Nonsense, how can you talk so! But it is very likely that he may fall in love with one of them, and therefore you must visit him as soon as he comes.\" \"I see no occasion for that. You and the girls may go--or you may send them by themselves, which perhaps will be still better; for as you are as handsome as any of them, Mr. Bingley might like you the best of the party.\" \"My dear, you flatter me. I certainly have had my share of beauty, but I do not pretend to be anything extraordinary now. When a woman has five grown-up daughters, she ought to give over thinking of her own beauty.\" \"In such cases, a woman has not often much beauty to think of.\" \"But, my dear, you must indeed go and see Mr. Bingley when he comes into the neighbourhood.\" \"It is more than I engage for, I assure you.\" \"But consider your daughters. Only think what an establishment it would be for one of them. Sir William and Lady Lucas are determined to go, merely on that account; for in general, you know, they visit no new comers. Indeed you must go, for it will be impossible for us to visit him, if you do not.\" \"You are over scrupulous, surely. I dare say Mr. Bingley will be very glad to see you; and I will send a few lines by you to assure him of my hearty consent to his marrying whichever he chooses of the girls--though I must throw in a good word for my little Lizzy.\" \"I desire you will do no such thing. Lizzy is not a bit better than the others: and I am sure she is not half so handsome as Jane, nor half so good-humoured as Lydia. But you are always giving her the preference.\" \"They have none of them much to recommend them,\" replied he: \"they are all silly and ignorant like other girls; but Lizzy has something more of quickness than her sisters.\" \"Mr. Bennet, how can you abuse your own children in such a way? You take delight in vexing me. You have no compassion on my poor nerves.\" \"You mistake me, my dear. I have a high respect for your nerves. They are my old friends. I have heard you mention them with consideration these twenty years at least.\" \"Ah, you do not know what I suffer.\" \"But I hope you will get over it, and live to see many young men of four thousand a year come into the neighbourhood.\" \"It will be no use to us, if twenty such should come, since you will not visit them.\" \"Depend upon it, my dear, that when there are twenty, I will visit them all.\" Mr. Bennet was so odd a mixture of quick parts, sarcastic humour, reserve, and caprice, that the experience of three-and-twenty years had been insufficient to make his wife understand his character. Her mind was less difficult to develope. She was a woman of mean understanding, little information, and uncertain temper. When she was discontented, she fancied herself nervous. The business of her life was to get her daughters married: its solace was visiting and news. [Illustration: M^{r.} & M^{rs.} Bennet [Copyright 1894 by George Allen.]] [Illustration: \"I hope Mr. Bingley will like it\" [Copyright 1894 by George Allen.]] CHAPTER II. [Illustration] Mr. Bennet was among the earliest of those who waited on Mr. Bingley. He had always intended to visit him, though to the last always assuring his wife that he should not go; and till the evening after the visit was paid she had no knowledge of it. It was then disclosed in the following manner. Observing his second daughter employed in trimming a hat, he suddenly addressed her with,-- \"I hope Mr. Bingley will like it, Lizzy.\" \"We are not in a way to know what Mr. Bingley likes,\" said her mother, resentfully, \"since we are not to visit.\" \"But you forget, mamma,\" said Elizabeth, \"that we shall meet him at the assemblies, and that Mrs. Long has promised to introduce him.\" \"I do not believe Mrs. Long will do any such thing. She has two nieces of her own. She is a selfish, hypocritical woman, and I have no opinion of her.\" \"No more have I,\" said Mr. Bennet; \"and I am glad to find that you do not depend on her serving you.\" Mrs. Bennet deigned not to make any reply; but, unable to contain herself, began scolding one of her daughters. \"Don't keep coughing so, Kitty, for heaven's sake! Have a little compassion on my nerves. You tear them to pieces.\" \"Kitty has no discretion in her coughs,\" said her father; \"she times them ill.\" \"I do not cough for my own amusement,\" replied Kitty, fretfully. \"When is your next ball to be, Lizzy?\" \"To-morrow fortnight.\" \"Ay, so it is,\" cried her mother, \"and Mrs. Long does not come back till the day before; so, it will be impossible for her to introduce him, for she will not know him herself.\" \"Then, my dear, you may have the advantage of your friend, and introduce Mr. Bingley to her.\" \"Impossible, Mr. Bennet, impossible, when I am not acquainted with him myself; how can you be so teasing?\" \"I honour your circumspection. A fortnight's acquaintance is certainly very little. One cannot know what a man really is by the end of a fortnight. But if we do not venture, somebody else will; and after all, Mrs. Long and her nieces must stand their chance; and, therefore, as she will think it an act of kindness, if you decline the office, I will take it on myself.\" The girls stared at their father. Mrs. Bennet said only, \"Nonsense, nonsense!\" \"What can be the meaning of that emphatic exclamation?\" cried he. \"Do you consider the forms of introduction, and the stress that is laid on them, as nonsense? I cannot quite agree with you there. What say you, Mary? For you are a young lady of deep reflection, I know, and read great books, and make extracts.\" Mary wished to say something very sensible, but knew not how. \"While Mary is adjusting her ideas,\" he continued, \"let us return to Mr. Bingley.\" \"I am sick of Mr. Bingley,\" cried his wife. \"I am sorry to hear that; but why did you not tell me so before? If I had known as much this morning, I certainly would not have called on him. It is very unlucky; but as I have actually paid the visit, we cannot escape the acquaintance now.\" The astonishment of the ladies was just what he wished--that of Mrs. Bennet perhaps surpassing the rest; though when the first tumult of joy was over, she began to declare that it was what she had expected all the while. \"How good it was in you, my dear Mr. Bennet! But I knew I should persuade you at last. I was sure you loved your girls too well to neglect such an acquaintance. Well, how pleased I am! And it is such a good joke, too, that you should have gone this morning, and never said a word about it till now.\" \"Now, Kitty, you may cough as much as you choose,\" said Mr. Bennet; and, as he spoke, he left the room, fatigued with the raptures of his wife. \"What an excellent father you have, girls,\" said she, when the door was shut. \"I do not know how you will ever make him amends for his kindness; or me either, for that matter. At our time of life, it is not so pleasant, I can tell you, to be making new acquaintances every day; but for your sakes we would do anything. Lydia, my love, though you are the youngest, I dare say Mr. Bingley will dance with you at the next ball.\" \"Oh,\" said Lydia, stoutly, \"I am not afraid; for though I am the youngest, I'm the tallest.\" The rest of the evening was spent in conjecturing how soon he would return Mr. Bennet's visit, and determining when they should ask him to dinner. [Illustration: \"I'm the tallest\"] [Illustration: \"He rode a black horse\" ] CHAPTER III. [Illustration] Not all that Mrs. Bennet, however, with the assistance of her five daughters, could ask on the subject, was sufficient to draw from her husband any satisfactory description of Mr. Bingley. They attacked him in various ways, with barefaced questions, ingenious suppositions, and distant surmises; but he eluded the skill of them all; and they were at last obliged to accept the second-hand intelligence of their neighbour, Lady Lucas. Her report was highly favourable. Sir William had been delighted with him. He was quite young, wonderfully handsome, extremely agreeable, and, to crown the whole, he meant to be at the next assembly with a large party. Nothing could be more delightful! To be fond of dancing was a certain step towards falling in love; and very lively hopes of Mr. Bingley's heart were entertained. \"If I can but see one of my daughters happily settled at Netherfield,\" said Mrs. Bennet to her husband, \"and all the others equally well married, I shall have nothing to wish for.\" In a few days Mr. Bingley returned Mr. Bennet's visit, and sat about ten minutes with him in his library. He had entertained hopes of being admitted to a sight of the young ladies, of whose beauty he had heard much; but he saw only the father. The ladies were somewhat more fortunate, for they had the advantage of ascertaining, from an upper window, that he wore a blue coat and rode a black horse. An invitation to dinner was soon afterwards despatched; and already had Mrs. Bennet planned the courses that were to do credit to her housekeeping, when an answer arrived which deferred it all. Mr. Bingley was obliged to be in town the following day, and consequently unable to accept the honour of their invitation, etc. Mrs. Bennet was quite disconcerted. She could not imagine what business he could have in town so soon after his arrival in Hertfordshire; and she began to fear that he might always be flying about from one place to another, and never settled at Netherfield as he ought to be. Lady Lucas quieted her fears a little by starting the idea of his [Illustration: \"When the Party entered\" [Copyright 1894 by George Allen.]] being gone to London only to get a large party for the ball; and a report soon followed that Mr. Bingley was to bring twelve ladies and seven gentlemen with him to the assembly. The girls grieved over such a number of ladies; but were comforted the day before the ball by hearing that, instead of twelve, he had brought only six with him from London, his five sisters and a cousin. And when the party entered the assembly-room, it consisted of only five altogether: Mr. Bingley, his two sisters, the husband of the eldest, and another young man. Mr. Bingley was good-looking and gentlemanlike: he had a pleasant countenance, and easy, unaffected manners. His sisters were fine women, with an air of decided fashion. His brother-in-law, Mr. Hurst, merely looked the gentleman; but his friend Mr. Darcy soon drew the attention of the room by his fine, tall person, handsome features, noble mien, and the report, which was in general circulation within five minutes after his entrance, of his having ten thousand a year. The gentlemen pronounced him to be a fine figure of a man, the ladies declared he was much handsomer than Mr. Bingley, and he was looked at with great admiration for about half the evening, till his manners gave a disgust which turned the tide of his popularity; for he was discovered to be proud, to be above his company, and above being pleased; and not all his large estate in Derbyshire could save him from having a most forbidding, disagreeable countenance, and being unworthy to be compared with his friend. Mr. Bingley had soon made himself acquainted with all the principal people in the room: he was lively and unreserved, danced every dance, was angry that the ball closed so early, and talked of giving one himself at Netherfield. Such amiable qualities must speak for themselves. What a contrast between him and his friend! Mr. Darcy danced only once with Mrs. Hurst and once with Miss Bingley, declined being introduced to any other lady, and spent the rest of the evening in walking about the room, speaking occasionally to one of his own party. His character was decided. He was the proudest, most disagreeable man in the world, and everybody hoped that he would never come there again. Amongst the most violent against him was Mrs. Bennet, whose dislike of his general behaviour was sharpened into particular resentment by his having slighted one of her daughters. Elizabeth Bennet had been obliged, by the scarcity of gentlemen, to sit down for two dances; and during part of that time, Mr. Darcy had been standing near enough for her to overhear a conversation between him and Mr. Bingley, who came from the dance for a few minutes to press his friend to join it. \"Come, Darcy,\" said he, \"I must have you dance. I hate to see you standing about by yourself in this stupid manner. You had much better dance.\" \"I certainly shall not. You know how I detest it, unless I am particularly acquainted with my partner. At such an assembly as this, it would be insupportable. Your sisters are engaged, and there is not another woman in the room whom it would not be a punishment to me to stand up with.\" \"I would not be so fastidious as you are,\" cried Bingley, \"for a kingdom! Upon my honour, I never met with so many pleasant girls in my life as I have this evening; and there are several of them, you see, uncommonly pretty.\" \"You are dancing with the only handsome girl in the room,\" said Mr. Darcy, looking at the eldest Miss Bennet. \"Oh, she is the most beautiful creature I ever beheld! But there is one of her sisters sitting down just behind you, who is very pretty, and I dare say very agreeable. Do let me ask my partner to introduce you.\" [Illustration: \"She is tolerable\" [Copyright 1894 by George Allen.]] \"Which do you mean?\" and turning round, he looked for a moment at Elizabeth, till, catching her eye, he withdrew his own, and coldly said, \"She is tolerable: but not handsome enough to tempt me; and I am in no humour at present to give consequence to young ladies who are slighted by other men. You had better return to your partner and enjoy her smiles, for you are wasting your time with me.\" Mr. Bingley followed his advice. Mr. Darcy walked off; and Elizabeth remained with no very cordial feelings towards him. She told the story, however, with great spirit among her friends; for she had a lively, playful disposition, which delighted in anything ridiculous. The evening altogether passed off pleasantly to the whole family. Mrs. Bennet had seen her eldest daughter much admired by the Netherfield party. Mr. Bingley had danced with her twice, and she had been distinguished by his sisters. Jane was as much gratified by this as her mother could be, though in a quieter way. Elizabeth felt Jane's pleasure. Mary had heard herself mentioned to Miss Bingley as the most accomplished girl in the neighbourhood; and Catherine and Lydia had been fortunate enough to be never without partners, which was all that they had yet learnt to care for at a ball. They returned, therefore, in good spirits to Longbourn, the village where they lived, and of which they were the principal inhabitants. They found Mr. Bennet still up. With a book, he was regardless of time; and on the present occasion he had a good deal of curiosity as to the event of an evening which had raised such splendid expectations. He had rather hoped that all his wife's views on the stranger would be disappointed; but he soon found that he had a very different story to hear. \"Oh, my dear Mr. Bennet,\" as she entered the room, \"we have had a most delightful evening, a most excellent ball. I wish you had been there. Jane was so admired, nothing could be like it. Everybody said how well she looked; and Mr. Bingley thought her quite beautiful, and danced with her twice. Only think of that, my dear: he actually danced with her twice; and she was the only creature in the room that he asked a second time. First of all, he asked Miss Lucas. I was so vexed to see him stand up with her; but, however, he did not admire her at all; indeed, nobody can, you know; and he seemed quite struck with Jane as she was going down the dance. So he inquired who she was, and got introduced, and asked her for the two next. Then, the two third he danced with Miss King, and the two fourth with Maria Lucas, and the two fifth with Jane again, and the two sixth with Lizzy, and the Boulanger----\" \"If he had had any compassion for me,\" cried her husband impatiently, \"he would not have danced half so much! For God's sake, say no more of his partners. O that he had sprained his ancle in the first dance!\" \"Oh, my dear,\" continued Mrs. Bennet, \"I am quite delighted with him. He is so excessively handsome! and his sisters are charming women. I never in my life saw anything more elegant than their dresses. I dare say the lace upon Mrs. Hurst's gown----\" Here she was interrupted again. Mr. Bennet protested against any description of finery. She was therefore obliged to seek another branch of the subject, and related, with much bitterness of spirit, and some exaggeration, the shocking rudeness of Mr. Darcy. \"But I can assure you,\" she added, \"that Lizzy does not lose much by not suiting his fancy; for he is a most disagreeable, horrid man, not at all worth pleasing. So high and so conceited, that there was no enduring him! He walked here, and he walked there, fancying himself so very great! Not handsome enough to dance with! I wish you had been there, my dear, to have given him one of your set-downs. I quite detest the man.\" [Illustration] CHAPTER IV. [Illustration] When Jane and Elizabeth were alone, the former, who had been cautious in her praise of Mr. Bingley before, expressed to her sister how very much she admired him. \"He is just what a young man ought to be,\" said she, \"sensible, good-humoured, lively; and I never saw such happy manners! so much ease, with such perfect good breeding!\" \"He is also handsome,\" replied Elizabeth, \"which a young man ought likewise to be if he possibly can. His character is thereby complete.\" \"I was very much flattered by his asking me to dance a second time. I did not expect such a compliment.\" \"Did not you? I did for you. But that is one great difference between us. Compliments always take you by surprise, and me never. What could be more natural than his asking you again? He could not help seeing that you were about five times as pretty as every other woman in the room. No thanks to his gallantry for that. Well, he certainly is very agreeable, and I give you leave to like him. You have liked many a stupider person.\" \"Dear Lizzy!\" \"Oh, you are a great deal too apt, you know, to like people in general. You never see a fault in anybody. All the world are good and agreeable in your eyes. I never heard you speak ill of a human being in my life.\" \"I would wish not to be hasty in censuring anyone; but I always speak what I think.\" \"I know you do: and it is that which makes the wonder. With your good sense, to be so honestly blind to the follies and nonsense of others! Affectation of candour is common enough; one meets with it everywhere. But to be candid without ostentation or design,--to take the good of everybody's character and make it still better, and say nothing of the bad,--belongs to you alone. And so, you like this man's sisters, too, do you? Their manners are not equal to his.\" \"Certainly not, at first; but they are very pleasing women when you converse with them. Miss Bingley is to live with her brother, and keep his house; and I am much mistaken if we shall not find a very charming neighbour in her.\" Elizabeth listened in silence, but was not convinced: their behaviour at the assembly had not been calculated to please in general; and with more quickness of observation and less pliancy of temper than her sister, and with a judgment, too, unassailed by any attention to herself, she was very little disposed to approve them. They were, in fact, very fine ladies; not deficient in good-humour when they were pleased, nor in the power of being agreeable where they chose it; but proud and conceited. They were rather handsome; had been educated in one of the first private seminaries in town; had a fortune of twenty thousand pounds; were in the habit of spending more than they ought, and of associating with people of rank; and were, therefore, in every respect entitled to think well of themselves and meanly of others. They were of a respectable family in the north of England; a circumstance more deeply impressed on their memories than that their brother's fortune and their own had been acquired by trade. Mr. Bingley inherited property to the amount of nearly a hundred thousand pounds from his father, who had intended to purchase an estate, but did not live to do it. Mr. Bingley intended it likewise, and sometimes made choice of his county; but, as he was now provided with a good house and the liberty of a manor, it was doubtful to many of those who best knew the easiness of his temper, whether he might not spend the remainder of his days at Netherfield, and leave the next generation to purchase. His sisters were very anxious for his having an estate of his own; but though he was now established only as a tenant, Miss Bingley was by no means unwilling to preside at his table; nor was Mrs. Hurst, who had married a man of more fashion than fortune, less disposed to consider his house as her home when it suited her. Mr. Bingley had not been of age two years when he was tempted, by an accidental recommendation, to look at Netherfield House. He did look at it, and into it, for half an hour; was pleased with the situation and the principal rooms, satisfied with what the owner said in its praise, and took it immediately. Between him and Darcy there was a very steady friendship, in spite of a great opposition of character. Bingley was endeared to Darcy by the easiness, openness, and ductility of his temper, though no disposition could offer a greater contrast to his own, and though with his own he never appeared dissatisfied. On the strength of Darcy's regard, Bingley had the firmest reliance, and of his judgment the highest opinion. In understanding, Darcy was the superior. Bingley was by no means deficient; but Darcy was clever. He was at the same time haughty, reserved, and fastidious; and his manners, though well bred, were not inviting. In that respect his friend had greatly the advantage. Bingley was sure of being liked wherever he appeared; Darcy was continually giving offence. The manner in which they spoke of the Meryton assembly was sufficiently characteristic. Bingley had never met with pleasanter people or prettier girls in his life; everybody had been most kind and attentive to him; there had been no formality, no stiffness; he had soon felt acquainted with all the room; and as to Miss Bennet, he could not conceive an angel more beautiful. Darcy, on the contrary, had seen a collection of people in whom there was little beauty and no fashion, for none of whom he had felt the smallest interest, and from none received either attention or pleasure. Miss Bennet he acknowledged to be pretty; but she smiled too much. Mrs. Hurst and her sister allowed it to be so; but still they admired her and liked her, and pronounced her to be a sweet girl, and one whom they should not object to know more of. Miss Bennet was therefore established as a sweet girl; and their brother felt authorized by such commendation to think of her as he chose. [Illustration: [Copyright 1894 by George Allen.]] CHAPTER V. [Illustration] Within a short walk of Longbourn lived a family with whom the Bennets were particularly intimate. Sir William Lucas had been formerly in trade in Meryton, where he had made a tolerable fortune, and risen to the honour of knighthood by an address to the king during his mayoralty. The distinction had, perhaps, been felt too strongly. It had given him a disgust to his business and to his residence in a small market town; and, quitting them both, he had removed with his family to a house about a mile from Meryton, denominated from that period Lucas Lodge; where he could think with pleasure of his own importance, and, unshackled by business, occupy himself solely in being civil to all the world. For, though elated by his rank, it did not render him supercilious; on the contrary, he was all attention to everybody. By nature inoffensive, friendly, and obliging, his presentation at St. James's had made him courteous. Lady Lucas was a very good kind of woman, not too clever to be a valuable neighbour to Mrs. Bennet. They had several children. The eldest of them, a sensible, intelligent young woman, about twenty-seven, was Elizabeth's intimate friend. That the Miss Lucases and the Miss Bennets should meet to talk over a ball was absolutely necessary; and the morning after the assembly brought the former to Longbourn to hear and to communicate. \"You began the evening well, Charlotte,\" said Mrs. Bennet, with civil self-command, to Miss Lucas. \"You were Mr. Bingley's first choice.\" \"Yes; but he seemed to like his second better.\" \"Oh, you mean Jane, I suppose, because he danced with her twice. To be sure that did seem as if he admired her--indeed, I rather believe he did--I heard something about it--but I hardly know what--something about Mr. Robinson.\" \"Perhaps you mean what I overheard between him and Mr. Robinson: did not I mention it to you? Mr. Robinson's asking him how he liked our Meryton assemblies, and whether he did not think there were a great many pretty women in the room, and which he thought the prettiest? and his answering immediately to the last question, 'Oh, the eldest Miss Bennet, beyond a doubt: there cannot be two opinions on that point.'\" \"Upon my word! Well, that was very decided, indeed--that does seem as if--but, however, it may all come to nothing, you know.\" \"My overhearings were more to the purpose than yours, Eliza,\" said Charlotte. \"Mr. Darcy is not so well worth listening to as his friend, is he? Poor Eliza! to be only just tolerable.\" \"I beg you will not put it into Lizzy's head to be vexed by his ill-treatment, for he is such a disagreeable man that it would be quite a misfortune to be liked by him. Mrs. Long told me last night that he sat close to her for half an hour without once opening his lips.\" [Illustration: \"Without once opening his lips\" [Copyright 1894 by George Allen.]] \"Are you quite sure, ma'am? Is not there a little mistake?\" said Jane. \"I certainly saw Mr. Darcy speaking to her.\" \"Ay, because she asked him at last how he liked Netherfield, and he could not help answering her; but she said he seemed very angry at being spoke to.\" \"Miss Bingley told me,\" said Jane, \"that he never speaks much unless among his intimate acquaintance. With them he is remarkably agreeable.\" \"I do not believe a word of it, my dear. If he had been so very agreeable, he would have talked to Mrs. Long. But I can guess how it was; everybody says that he is eat up with pride, and I dare say he had heard somehow that Mrs. Long does not keep a carriage, and had to come to the ball in a hack chaise.\" \"I do not mind his not talking to Mrs. Long,\" said Miss Lucas, \"but I wish he had danced with Eliza.\" \"Another time, Lizzy,\" said her mother, \"I would not dance with him, if I were you.\" \"I believe, ma'am, I may safely promise you never to dance with him.\" \"His pride,\" said Miss Lucas, \"does not offend me so much as pride often does, because there is an excuse for it. One cannot wonder that so very fine a young man, with family, fortune, everything in his favour, should think highly of himself. If I may so express it, he has a right to be proud.\" \"That is very true,\" replied Elizabeth, \"and I could easily forgive his pride, if he had not mortified mine.\" \"Pride,\" observed Mary, who piqued herself upon the solidity of her reflections, \"is a very common failing, I believe. By all that I have ever read, I am convinced that it is very common indeed; that human nature is particularly prone to it, and that there are very few of us who do not cherish a feeling of self-complacency on the score of some quality or other, real or imaginary. Vanity and pride are different things, though the words are often used synonymously. A person may be proud without being vain. Pride relates more to our opinion of ourselves; vanity to what we would have others think of us.\" \"If I were as rich as Mr. Darcy,\" cried a young Lucas, who came with his sisters, \"I should not care how proud I was. I would keep a pack of foxhounds, and drink a bottle of wine every day.\" \"Then you would drink a great deal more than you ought,\" said Mrs. Bennet; \"and if I were to see you at it, I should take away your bottle directly.\" The boy protested that she should not; she continued to declare that she would; and the argument ended only with the visit. [Illustration] [Illustration] CHAPTER VI. [Illustration] The ladies of Longbourn soon waited on those of Netherfield. The visit was returned in due form. Miss Bennet's pleasing manners grew on the good-will of Mrs. Hurst and Miss Bingley; and though the mother was found to be intolerable, and the younger sisters not worth speaking to, a wish of being better acquainted with them was expressed towards the two eldest. By Jane this attention was received with the greatest pleasure; but Elizabeth still saw superciliousness in their treatment of everybody, hardly excepting even her sister, and could not like them; though their kindness to Jane, such as it was, had a value, as arising, in all probability, from the influence of their brother's admiration. It was generally evident, whenever they met, that he did admire her; and to her it was equally evident that Jane was yielding to the preference which she had begun to entertain for him from the first, and was in a way to be very much in love; but she considered with pleasure that it was not likely to be discovered by the world in general, since Jane united with great strength of feeling, a composure of temper and an uniform cheerfulness of manner, which would guard her from the suspicions of the impertinent. She mentioned this to her friend, Miss Lucas. \"It may, perhaps, be pleasant,\" replied Charlotte, \"to be able to impose on the public in such a case; but it is sometimes a disadvantage to be so very guarded. If a woman conceals her affection with the same skill from the object of it, she may lose the opportunity of fixing him; and it will then be but poor consolation to believe the world equally in the dark. There is so much of gratitude or vanity in almost every attachment, that it is not safe to leave any to itself. We can all begin freely--a slight preference is natural enough; but there are very few of us who have heart enough to be really in love without encouragement. In nine cases out of ten, a woman had better show more affection than she feels. Bingley likes your sister undoubtedly; but he may never do more than like her, if she does not help him on.\" \"But she does help him on, as much as her nature will allow. If I can perceive her regard for him, he must be a simpleton indeed not to discover it too.\" \"Remember, Eliza, that he does not know Jane's disposition as you do.\" \"But if a woman is partial to a man, and does not endeavor to conceal it, he must find it out.\" \"Perhaps he must, if he sees enough of her. But though Bingley and Jane meet tolerably often, it is never for many hours together; and as they always see each other in large mixed parties, it is impossible that every moment should be employed in conversing together. Jane should therefore make the most of every half hour in which she can command his attention. When she is secure of him, there will be leisure for falling in love as much as she chooses.\" \"Your plan is a good one,\" replied Elizabeth, \"where nothing is in question but the desire of being well married; and if I were determined to get a rich husband, or any husband, I dare say I should adopt it. But these are not Jane's feelings; she is not acting by design. As yet she cannot even be certain of the degree of her own regard, nor of its reasonableness. She has known him only a fortnight. She danced four dances with him at Meryton; she saw him one morning at his own house, and has since dined in company with him four times. This is not quite enough to make her understand his character.\" \"Not as you represent it. Had she merely dined with him, she might only have discovered whether he had a good appetite; but you must remember that four evenings have been also spent together--and four evenings may do a great deal.\" \"Yes: these four evenings have enabled them to ascertain that they both like Vingt-un better than Commerce, but with respect to any other leading characteristic, I do not imagine that much has been unfolded.\" \"Well,\" said Charlotte, \"I wish Jane success with all my heart; and if she were married to him to-morrow, I should think she had as good a chance of happiness as if she were to be studying his character for a twelvemonth. Happiness in marriage is entirely a matter of chance. If the dispositions of the parties are ever so well known to each other, or ever so similar beforehand, it does not advance their felicity in the least. They always continue to grow sufficiently unlike afterwards to have their share of vexation; and it is better to know as little as possible of the defects of the person with whom you are to pass your life.\" \"You make me laugh, Charlotte; but it is not sound. You know it is not sound, and that you would never act in this way yourself.\" Occupied in observing Mr. Bingley's attention to her sister, Elizabeth was far from suspecting that she was herself becoming an object of some interest in the eyes of his friend. Mr. Darcy had at first scarcely allowed her to be pretty: he had looked at her without admiration at the ball; and when they next met, he looked at her only to criticise. But no sooner had he made it clear to himself and his friends that she had hardly a good feature in her face, than he began to find it was rendered uncommonly intelligent by the beautiful expression of her dark eyes. To this discovery succeeded some others equally mortifying. Though he had detected with a critical eye more than one failure of perfect symmetry in her form, he was forced to acknowledge her figure to be light and pleasing; and in spite of his asserting that her manners were not those of the fashionable world, he was caught by their easy playfulness. Of this she was perfectly unaware: to her he was only the man who made himself agreeable nowhere, and who had not thought her handsome enough to dance with. He began to wish to know more of her; and, as a step towards conversing with her himself, attended to her conversation with others. His doing so drew her notice. It was at Sir William Lucas's, where a large party were assembled. \"What does Mr. Darcy mean,\" said she to Charlotte, \"by listening to my conversation with Colonel Forster?\" \"That is a question which Mr. Darcy only can answer.\" \"But if he does it any more, I shall certainly let him know that I see what he is about. He has a very satirical eye, and if I do not begin by being impertinent myself, I shall soon grow afraid of him.\" [Illustration: \"The entreaties of several\" [Copyright 1894 by George Allen.]] On his approaching them soon afterwards, though without seeming to have any intention of speaking, Miss Lucas defied her friend to mention such a subject to him, which immediately provoking Elizabeth to do it, she turned to him and said,-- \"Did not you think, Mr. Darcy, that I expressed myself uncommonly well just now, when I was teasing Colonel Forster to give us a ball at Meryton?\" \"With great energy; but it is a subject which always makes a lady energetic.\" \"You are severe on us.\" \"It will be her turn soon to be teased,\" said Miss Lucas. \"I am going to open the instrument, Eliza, and you know what follows.\" \"You are a very strange creature by way of a friend!--always wanting me to play and sing before anybody and everybody! If my vanity had taken a musical turn, you would have been invaluable; but as it is, I would really rather not sit down before those who must be in the habit of hearing the very best performers.\" On Miss Lucas's persevering, however, she added, \"Very well; if it must be so, it must.\" And gravely glancing at Mr. Darcy, \"There is a very fine old saying, which everybody here is of course familiar with--'Keep your breath to cool your porridge,'--and I shall keep mine to swell my song.\" Her performance was pleasing, though by no means capital. After a song or two, and before she could reply to the entreaties of several that she would sing again, she was eagerly succeeded at the instrument by her sister Mary, who having, in consequence of being the only plain one in the family, worked hard for knowledge and accomplishments, was always impatient for display. Mary had neither genius nor taste; and though vanity had given her application, it had given her likewise a pedantic air and conceited manner, which would have injured a higher degree of excellence than she had reached. Elizabeth, easy and unaffected, had been listened to with much more pleasure, though not playing half so well; and Mary, at the end of a long concerto, was glad to purchase praise and gratitude by Scotch and Irish airs, at the request of her younger sisters, who with some of the Lucases, and two or three officers, joined eagerly in dancing at one end of the room. Mr. Darcy stood near them in silent indignation at such a mode of passing the evening, to the exclusion of all conversation, and was too much engrossed by his own thoughts to perceive that Sir William Lucas was his neighbour, till Sir William thus began:-- \"What a charming amusement for young people this is, Mr. Darcy! There is nothing like dancing, after all. I consider it as one of the first refinements of polished societies.\" \"Certainly, sir; and it has the advantage also of being in vogue amongst the less polished societies of the world: every savage can dance.\" Sir William only smiled. \"Your friend performs delightfully,\" he continued, after a pause, on seeing Bingley join the group; \"and I doubt not that you are an adept in the science yourself, Mr. Darcy.\" \"You saw me dance at Meryton, I believe, sir.\" \"Yes, indeed, and received no inconsiderable pleasure from the sight. Do you often dance at St. James's?\" \"Never, sir.\" \"Do you not think it would be a proper compliment to the place?\" \"It is a compliment which I never pay to any place if I can avoid it.\" \"You have a house in town, I conclude?\" Mr. Darcy bowed. \"I had once some thoughts of fixing in town myself, for I am fond of superior society; but I did not feel quite certain that the air of London would agree with Lady Lucas.\" He paused in hopes of an answer: but his companion was not disposed to make any; and Elizabeth at that instant moving towards them, he was struck with the notion of doing a very gallant thing, and called out to her,-- \"My dear Miss Eliza, why are not you dancing? Mr. Darcy, you must allow me to present this young lady to you as a very desirable partner. You cannot refuse to dance, I am sure, when so much beauty is before you.\" And, taking her hand, he would have given it to Mr. Darcy, who, though extremely surprised, was not unwilling to receive it, when she instantly drew back, and said with some discomposure to Sir William,-- \"Indeed, sir, I have not the least intention of dancing. I entreat you not to suppose that I moved this way in order to beg for a partner.\" Mr. Darcy, with grave propriety, requested to be allowed the honour of her hand, but in vain. Elizabeth was determined; nor did Sir William at all shake her purpose by his attempt at persuasion. \"You excel so much in the dance, Miss Eliza, that it is cruel to deny me the happiness of seeing you; and though this gentleman dislikes the amusement in general, he can have no objection, I am sure, to oblige us for one half hour.\" \"Mr. Darcy is all politeness,\" said Elizabeth, smiling. \"He is, indeed: but considering the inducement, my dear Miss Eliza, we cannot wonder at his complaisance; for who would object to such a partner?\" Elizabeth looked archly, and turned away. Her resistance had not injured her with the gentleman, and he was thinking of her with some complacency, when thus accosted by Miss Bingley,-- \"I can guess the subject of your reverie.\" \"I should imagine not.\" \"You are considering how insupportable it would be to pass many evenings in this manner,--in such society; and, indeed, I am quite of your opinion. I was never more annoyed! The insipidity, and yet the noise--the nothingness, and yet the self-importance, of all these people! What would I give to hear your strictures on them!\" \"Your conjecture is totally wrong, I assure you. My mind was more agreeably engaged. I have been meditating on the very great pleasure which a pair of fine eyes in the face of a pretty woman can bestow.\" Miss Bingley immediately fixed her eyes on his face, and desired he would tell her what lady had the credit of inspiring such reflections. Mr. Darcy replied, with great intrepidity,-- \"Miss Elizabeth Bennet.\" \"Miss Elizabeth Bennet!\" repeated Miss Bingley. \"I am all astonishment. How long has she been such a favourite? and pray when am I to wish you joy?\" \"That is exactly the question which I expected you to ask. A lady's imagination is very rapid; it jumps from admiration to love, from love to matrimony, in a moment. I knew you would be wishing me joy.\" \"Nay, if you are so serious about it, I shall consider the matter as absolutely settled. You will have a charming mother-in-law, indeed, and of course she will be always at Pemberley with you.\" He listened to her with perfect indifference, while she chose to entertain herself in this manner; and as his composure convinced her that all was safe, her wit flowed along. [Illustration: \"A note for Miss Bennet\" [Copyright 1894 by George Allen.]] CHAPTER VII. [Illustration] Mr. Bennet's property consisted almost entirely in an estate of two thousand a year, which, unfortunately for his daughters, was entailed, in default of heirs male, on a distant relation; and their mother's fortune, though ample for her situation in life, could but ill supply the deficiency of his. Her father had been an attorney in Meryton, and had left her four thousand pounds. She had a sister married to a Mr. Philips, who had been a clerk to their father and succeeded him in the business, and a brother settled in London in a respectable line of trade. The village of Longbourn was only one mile from Meryton; a most convenient distance for the young ladies, who were usually tempted thither three or four times a week, to pay their duty to their aunt, and to a milliner's shop just over the way. The two youngest of the family, Catherine and Lydia, were particularly frequent in these attentions: their minds were more vacant than their sisters', and when nothing better offered, a walk to Meryton was necessary to amuse their morning hours and furnish conversation for the evening; and, however bare of news the country in general might be, they always contrived to learn some from their aunt. At present, indeed, they were well supplied both with news and happiness by the recent arrival of a militia regiment in the neighbourhood; it was to remain the whole winter, and Meryton was the head-quarters. Their visits to Mrs. Philips were now productive of the most interesting intelligence. Every day added something to their knowledge of the officers' names and connections. Their lodgings were not long a secret, and at length they began to know the officers themselves. Mr. Philips visited them all, and this opened to his nieces a source of felicity unknown before. They could talk of nothing but officers; and Mr. Bingley's large fortune, the mention of which gave animation to their mother, was worthless in their eyes when opposed to the regimentals of an ensign. After listening one morning to their effusions on this subject, Mr. Bennet coolly observed,-- \"From all that I can collect by your manner of talking, you must be two of the silliest girls in the country. I have suspected it some time, but I am now convinced.\" Catherine was disconcerted, and made no answer; but Lydia, with perfect indifference, continued to express her admiration of Captain Carter, and her hope of seeing him in the course of the day, as he was going the next morning to London. \"I am astonished, my dear,\" said Mrs. Bennet, \"that you should be so ready to think your own children silly. If I wished to think slightingly of anybody's children, it should not be of my own, however.\" \"If my children are silly, I must hope to be always sensible of it.\" \"Yes; but as it happens, they are all of them very clever.\" \"This is the only point, I flatter myself, on which we do not agree. I had hoped that our sentiments coincided in every particular, but I must so far differ from you as to think our two youngest daughters uncommonly foolish.\" \"My dear Mr. Bennet, you must not expect such girls to have the sense of their father and mother. When they get to our age, I dare say they will not think about officers any more than we do. I remember the time when I liked a red coat myself very well--and, indeed, so I do still at my heart; and if a smart young colonel, with five or six thousand a year, should want one of my girls, I shall not say nay to him; and I thought Colonel Forster looked very becoming the other night at Sir William's in his regimentals.\" \"Mamma,\" cried Lydia, \"my aunt says that Colonel Forster and Captain Carter do not go so often to Miss Watson's as they did when they first came; she sees them now very often standing in Clarke's library.\" Mrs. Bennet was prevented replying by the entrance of the footman with a note for Miss Bennet; it came from Netherfield, and the servant waited for an answer. Mrs. Bennet's eyes sparkled with pleasure, and she was eagerly calling out, while her daughter read,-- \"Well, Jane, who is it from? What is it about? What does he say? Well, Jane, make haste and tell us; make haste, my love.\" \"It is from Miss Bingley,\" said Jane, and then read it aloud. /* NIND \"My dear friend, */ \"If you are not so compassionate as to dine to-day with Louisa and me, we shall be in danger of hating each other for the rest of our lives; for a whole day's tête-à-tête between two women can never end without a quarrel. Come as soon as you can on the receipt of this. My brother and the gentlemen are to dine with the officers. Yours ever, \"CAROLINE BINGLEY.\" \"With the officers!\" cried Lydia: \"I wonder my aunt did not tell us of that.\" \"Dining out,\" said Mrs. Bennet; \"that is very unlucky.\" \"Can I have the carriage?\" said Jane. \"No, my dear, you had better go on horseback, because it seems likely to rain; and then you must stay all night.\" \"That would be a good scheme,\" said Elizabeth, \"if you were sure that they would not offer to send her home.\" \"Oh, but the gentlemen will have Mr. Bingley's chaise to go to Meryton; and the Hursts have no horses to theirs.\" \"I had much rather go in the coach.\" \"But, my dear, your father cannot spare the horses, I am sure. They are wanted in the farm, Mr. Bennet, are not they?\" [Illustration: Cheerful prognostics] \"They are wanted in the farm much oftener than I can get them.\" \"But if you have got them to-day,\" said Elizabeth, \"my mother's purpose will be answered.\" She did at last extort from her father an acknowledgment that the horses were engaged; Jane was therefore obliged to go on horseback, and her mother attended her to the door with many cheerful prognostics of a bad day. Her hopes were answered; Jane had not been gone long before it rained hard. Her sisters were uneasy for her, but her mother was delighted. The rain continued the whole evening without intermission; Jane certainly could not come back. \"This was a lucky idea of mine, indeed!\" said Mrs. Bennet, more than once, as if the credit of making it rain were all her own. Till the next morning, however, she was not aware of all the felicity of her contrivance. Breakfast was scarcely over when a servant from Netherfield brought the following note for Elizabeth:-- /* NIND \"My dearest Lizzie, */ \"I find myself very unwell this morning, which, I suppose, is to be imputed to my getting wet through yesterday. My kind friends will not hear of my returning home till I am better. They insist also on my seeing Mr. Jones--therefore do not be alarmed if you should hear of his having been to me--and, excepting a sore throat and a headache, there is not much the matter with me. \"Yours, etc.\" \"Well, my dear,\" said Mr. Bennet, when Elizabeth had read the note aloud, \"if your daughter should have a dangerous fit of illness--if she should die--it would be a comfort to know that it was all in pursuit of Mr. Bingley, and under your orders.\" \"Oh, I am not at all afraid of her dying. People do not die of little trifling colds. She will be taken good care of. As long as she stays there, it is all very well. I would go and see her if I could have the carriage.\" Elizabeth, feeling really anxious, determined to go to her, though the carriage was not to be had: and as she was no horsewoman, walking was her only alternative. She declared her resolution. \"How can you be so silly,\" cried her mother, \"as to think of such a thing, in all this dirt! You will not be fit to be seen when you get there.\" \"I shall be very fit to see Jane--which is all I want.\" \"Is this a hint to me, Lizzy,\" said her father, \"to send for the horses?\" \"No, indeed. I do not wish to avoid the walk. The distance is nothing, when one has a motive; only three miles. I shall be back by dinner.\" \"I admire the activity of your benevolence,\" observed Mary, \"but every impulse of feeling should be guided by reason; and, in my opinion, exertion should always be in proportion to what is required.\" \"We will go as far as Meryton with you,\" said Catherine and Lydia. Elizabeth accepted their company, and the three young ladies set off together. \"If we make haste,\" said Lydia, as they walked along, \"perhaps we may see something of Captain Carter, before he goes.\" In Meryton they parted: the two youngest repaired to the lodgings of one of the officers' wives, and Elizabeth continued her walk alone, crossing field after field at a quick pace, jumping over stiles and springing over puddles, with impatient activity, and finding herself at last within view of the house, with weary ancles, dirty stockings, and a face glowing with the warmth of exercise. She was shown into the breakfast parlour, where all but Jane were assembled, and where her appearance created a great deal of surprise. That she should have walked three miles so early in the day in such dirty weather, and by herself, was almost incredible to Mrs. Hurst and Miss Bingley; and Elizabeth was convinced that they held her in contempt for it. She was received, however, very politely by them; and in their brother's manners there was something better than politeness--there was good-humour and kindness. Mr. Darcy said very little, and Mr. Hurst nothing at all. The former was divided between admiration of the brilliancy which exercise had given to her complexion and doubt as to the occasion's justifying her coming so far alone. The latter was thinking only of his breakfast. Her inquiries after her sister were not very favourably answered. Miss Bennet had slept ill, and though up, was very feverish, and not well enough to leave her room. Elizabeth was glad to be taken to her immediately; and Jane, who had only been withheld by the fear of giving alarm or inconvenience, from expressing in her note how much she longed for such a visit, was delighted at her entrance. She was not equal, however, to much conversation; and when Miss Bingley left them together, could attempt little beside expressions of gratitude for the extraordinary kindness she was treated with. Elizabeth silently attended her. When breakfast was over, they were joined by the sisters; and Elizabeth began to like them herself, when she saw how much affection and solicitude they showed for Jane. The apothecary came; and having examined his patient, said, as might be supposed, that she had caught a violent cold, and that they must endeavour to get the better of it; advised her to return to bed, and promised her some draughts. The advice was followed readily, for the feverish symptoms increased, and her head ached acutely. Elizabeth did not quit her room for a moment, nor were the other ladies often absent; the gentlemen being out, they had in fact nothing to do elsewhere. When the clock struck three, Elizabeth felt that she must go, and very unwillingly said so. Miss Bingley offered her the carriage, and she only wanted a little pressing to accept it, when Jane testified such concern at parting with her that Miss Bingley was obliged to convert the offer of the chaise into an invitation to remain at Netherfield for the present. Elizabeth most thankfully consented, and a servant was despatched to Longbourn, to acquaint the family with her stay, and bring back a supply of clothes. [Illustration: \"The Apothecary came\" ] [Illustration: \"covering a screen\" ] CHAPTER VIII. [Illustration] At five o'clock the two ladies retired to dress, and at half-past six Elizabeth was summoned to dinner. To the civil inquiries which then poured in, and amongst which she had the pleasure of distinguishing the much superior solicitude of Mr. Bingley, she could not make a very favourable answer. Jane was by no means better. The sisters, on hearing this, repeated three or four times how much they were grieved, how shocking it was to have a bad cold, and how excessively they disliked being ill themselves; and then thought no more of the matter: and their indifference towards Jane, when not immediately before them, restored Elizabeth to the enjoyment of all her original dislike. Their brother, indeed, was the only one of the party whom she could regard with any complacency. His anxiety for Jane was evident, and his attentions to herself most pleasing; and they prevented her feeling herself so much an intruder as she believed she was considered by the others. She had very little notice from any but him. Miss Bingley was engrossed by Mr. Darcy, her sister scarcely less so; and as for Mr. Hurst, by whom Elizabeth sat, he was an indolent man, who lived only to eat, drink, and play at cards, who, when he found her prefer a plain dish to a ragout, had nothing to say to her. When dinner was over, she returned directly to Jane, and Miss Bingley began abusing her as soon as she was out of the room. Her manners were pronounced to be very bad indeed,--a mixture of pride and impertinence: she had no conversation, no style, no taste, no beauty. Mrs. Hurst thought the same, and added,-- \"She has nothing, in short, to recommend her, but being an excellent walker. I shall never forget her appearance this morning. She really looked almost wild.\" \"She did indeed, Louisa. I could hardly keep my countenance. Very nonsensical to come at all! Why must she be scampering about the country, because her sister had a cold? Her hair so untidy, so blowzy!\" \"Yes, and her petticoat; I hope you saw her petticoat, six inches deep in mud, I am absolutely certain, and the gown which had been let down to hide it not doing its office.\" \"Your picture may be very exact, Louisa,\" said Bingley; \"but this was all lost upon me. I thought Miss Elizabeth Bennet looked remarkably well when she came into the room this morning. Her dirty petticoat quite escaped my notice.\" \"You observed it, Mr. Darcy, I am sure,\" said Miss Bingley; \"and I am inclined to think that you would not wish to see your sister make such an exhibition.\" \"Certainly not.\" \"To walk three miles, or four miles, or five miles, or whatever it is, above her ancles in dirt, and alone, quite alone! what could she mean by it? It seems to me to show an abominable sort of conceited independence, a most country-town indifference to decorum.\" \"It shows an affection for her sister that is very pleasing,\" said Bingley. \"I am afraid, Mr. Darcy,\" observed Miss Bingley, in a half whisper, \"that this adventure has rather affected your admiration of her fine eyes.\" \"Not at all,\" he replied: \"they were brightened by the exercise.\" A short pause followed this speech, and Mrs. Hurst began again,-- \"I have an excessive regard for Jane Bennet,--she is really a very sweet girl,--and I wish with all my heart she were well settled. But with such a father and mother, and such low connections, I am afraid there is no chance of it.\" \"I think I have heard you say that their uncle is an attorney in Meryton?\" \"Yes; and they have another, who lives somewhere near Cheapside.\" \"That is capital,\" added her sister; and they both laughed heartily. \"If they had uncles enough to fill all Cheapside,\" cried Bingley, \"it would not make them one jot less agreeable.\" \"But it must very materially lessen their chance of marrying men of any consideration in the world,\" replied Darcy. To this speech Bingley made no answer; but his sisters gave it their hearty assent, and indulged their mirth for some time at the expense of their dear friend's vulgar relations. With a renewal of tenderness, however, they repaired to her room on leaving the dining-parlour, and sat with her till summoned to coffee. She was still very poorly, and Elizabeth would not quit her at all, till late in the evening, when she had the comfort of seeing her asleep, and when it appeared to her rather right than pleasant that she should go down stairs herself. On entering the drawing-room, she found the whole party at loo, and was immediately invited to join them; but suspecting them to be playing high, she declined it, and making her sister the excuse, said she would amuse herself, for the short time she could stay below, with a book. Mr. Hurst looked at her with astonishment. \"Do you prefer reading to cards?\" said he; \"that is rather singular.\" \"Miss Eliza Bennet,\" said Miss Bingley, \"despises cards. She is a great reader, and has no pleasure in anything else.\" \"I deserve neither such praise nor such censure,\" cried Elizabeth; \"I am not a great reader, and I have pleasure in many things.\" \"In nursing your sister I am sure you have pleasure,\" said Bingley; \"and I hope it will soon be increased by seeing her quite well.\" Elizabeth thanked him from her heart, and then walked towards a table where a few books were lying. He immediately offered to fetch her others; all that his library afforded. \"And I wish my collection were larger for your benefit and my own credit; but I am an idle fellow; and though I have not many, I have more than I ever looked into.\" Elizabeth assured him that she could suit herself perfectly with those in the room. \"I am astonished,\" said Miss Bingley, \"that my father should have left so small a collection of books. What a delightful library you have at Pemberley, Mr. Darcy!\" \"It ought to be good,\" he replied: \"it has been the work of many generations.\" \"And then you have added so much to it yourself--you are always buying books.\" \"I cannot comprehend the neglect of a family library in such days as these.\" \"Neglect! I am sure you neglect nothing that can add to the beauties of that noble place. Charles, when you build your house, I wish it may be half as delightful as Pemberley.\" \"I wish it may.\" \"But I would really advise you to make your purchase in that neighbourhood, and take Pemberley for a kind of model. There is not a finer county in England than Derbyshire.\" \"With all my heart: I will buy Pemberley itself, if Darcy will sell it.\" \"I am talking of possibilities, Charles.\" \"Upon my word, Caroline, I should think it more possible to get Pemberley by purchase than by imitation.\" Elizabeth was so much caught by what passed, as to leave her very little attention for her book; and, soon laying it wholly aside, she drew near the card-table, and stationed herself between Mr. Bingley and his eldest sister, to observe the game. \"Is Miss Darcy much grown since the spring?\" said Miss Bingley: \"will she be as tall as I am?\" \"I think she will. She is now about Miss Elizabeth Bennet's height, or rather taller.\" \"How I long to see her again! I never met with anybody who delighted me so much. Such a countenance, such manners, and so extremely accomplished for her age! Her performance on the pianoforte is exquisite.\" \"It is amazing to me,\" said Bingley, \"how young ladies can have patience to be so very accomplished as they all are.\" \"All young ladies accomplished! My dear Charles, what do you mean?\" \"Yes, all of them, I think. They all paint tables, cover screens, and net purses. I scarcely know any one who cannot do all this; and I am sure I never heard a young lady spoken of for the first time, without being informed that she was very accomplished.\" \"Your list of the common extent of accomplishments,\" said Darcy, \"has too much truth. The word is applied to many a woman who deserves it no otherwise than by netting a purse or covering a screen; but I am very far from agreeing with you in your estimation of ladies in general. I cannot boast of knowing more than half-a-dozen in the whole range of my acquaintance that are really accomplished.\" \"Nor I, I am sure,\" said Miss Bingley. \"Then,\" observed Elizabeth, \"you must comprehend a great deal in your idea of an accomplished woman.\" \"Yes; I do comprehend a great deal in it.\" \"Oh, certainly,\" cried his faithful assistant, \"no one can be really esteemed accomplished who does not greatly surpass what is usually met with. A woman must have a thorough knowledge of music, singing, drawing, dancing, and the modern languages, to deserve the word; and, besides all this, she must possess a certain something in her air and manner of walking, the tone of her voice, her address and expressions, or the word will be but half deserved.\" \"All this she must possess,\" added Darcy; \"and to all she must yet add something more substantial in the improvement of her mind by extensive reading.\" \"I am no longer surprised at your knowing only six accomplished women. I rather wonder now at your knowing any.\" \"Are you so severe upon your own sex as to doubt the possibility of all this?\" \"I never saw such a woman. I never saw such capacity, and taste, and application, and elegance, as you describe, united.\" Mrs. Hurst and Miss Bingley both cried out against the injustice of her implied doubt, and were both protesting that they knew many women who answered this description, when Mr. Hurst called them to order, with bitter complaints of their inattention to what was going forward. As all conversation was thereby at an end, Elizabeth soon afterwards left the room. \"Eliza Bennet,\" said Miss Bingley, when the door was closed on her, \"is one of those young ladies who seek to recommend themselves to the other sex by undervaluing their own; and with many men, I daresay, it succeeds; but, in my opinion, it is a paltry device, a very mean art.\" \"Undoubtedly,\" replied Darcy, to whom this remark was chiefly addressed, \"there is meanness in all the arts which ladies sometimes condescend to employ for captivation. Whatever bears affinity to cunning is despicable.\" Miss Bingley was not so entirely satisfied with this reply as to continue the subject. Elizabeth joined them again only to say that her sister was worse, and that she could not leave her. Bingley urged Mr. Jones's being sent for immediately; while his sisters, convinced that no country advice could be of any service, recommended an express to town for one of the most eminent physicians. This she would not hear of; but she was not so unwilling to comply with their brother's proposal; and it was settled that Mr. Jones should be sent for early in the morning, if Miss Bennet were not decidedly better. Bingley was quite uncomfortable; his sisters declared that they were miserable. They solaced their wretchedness, however, by duets after supper; while he could find no better relief to his feelings than by giving his housekeeper directions that every possible attention might be paid to the sick lady and her sister. [Illustration: M^{rs} Bennet and her two youngest girls [Copyright 1894 by George Allen.]] CHAPTER IX. [Illustration] Elizabeth passed the chief of the night in her sister's room, and in the morning had the pleasure of being able to send a tolerable answer to the inquiries which she very early received from Mr. Bingley by a housemaid, and some time afterwards from the two elegant ladies who waited on his sisters. In spite of this amendment, however, she requested to have a note sent to Longbourn, desiring her mother to visit Jane, and form her own judgment of her situation. The note was immediately despatched, and its contents as quickly complied with. Mrs. Bennet, accompanied by her two youngest girls, reached Netherfield soon after the family breakfast. Had she found Jane in any apparent danger, Mrs. Bennet would have been very miserable; but being satisfied on seeing her that her illness was not alarming, she had no wish of her recovering immediately, as her restoration to health would probably remove her from Netherfield. She would not listen, therefore, to her daughter's proposal of being carried home; neither did the apothecary, who arrived about the same time, think it at all advisable. After sitting a little while with Jane, on Miss Bingley's appearance and invitation, the mother and three daughters all attended her into the breakfast parlour. Bingley met them with hopes that Mrs. Bennet had not found Miss Bennet worse than she expected. \"Indeed I have, sir,\" was her answer. \"She is a great deal too ill to be moved. Mr. Jones says we must not think of moving her. We must trespass a little longer on your kindness.\" \"Removed!\" cried Bingley. \"It must not be thought of. My sister, I am sure, will not hear of her removal.\" \"You may depend upon it, madam,\" said Miss Bingley, with cold civility, \"that Miss Bennet shall receive every possible attention while she remains with us.\" Mrs. Bennet was profuse in her acknowledgments. \"I am sure,\" she added, \"if it was not for such good friends, I do not know what would become of her, for she is very ill indeed, and suffers a vast deal, though with the greatest patience in the world, which is always the way with her, for she has, without exception, the sweetest temper I ever met with. I often tell my other girls they are nothing to her. You have a sweet room here, Mr. Bingley, and a charming prospect over that gravel walk. I do not know a place in the country that is equal to Netherfield. You will not think of quitting it in a hurry, I hope, though you have but a short lease.\" \"Whatever I do is done in a hurry,\" replied he; \"and therefore if I should resolve to quit Netherfield, I should probably be off in five minutes. At present, however, I consider myself as quite fixed here.\" \"That is exactly what I should have supposed of you,\" said Elizabeth. \"You begin to comprehend me, do you?\" cried he, turning towards her. \"Oh yes--I understand you perfectly.\" \"I wish I might take this for a compliment; but to be so easily seen through, I am afraid, is pitiful.\" \"That is as it happens. It does not necessarily follow that a deep, intricate character is more or less estimable than such a one as yours.\" \"Lizzy,\" cried her mother, \"remember where you are, and do not run on in the wild manner that you are suffered to do at home.\" \"I did not know before,\" continued Bingley, immediately, \"that you were a studier of character. It must be an amusing study.\" \"Yes; but intricate characters are the most amusing. They have at least that advantage.\" \"The country,\" said Darcy, \"can in general supply but few subjects for such a study. In a country neighbourhood you move in a very confined and unvarying society.\" \"But people themselves alter so much, that there is something new to be observed in them for ever.\" \"Yes, indeed,\" cried Mrs. Bennet, offended by his manner of mentioning a country neighbourhood. \"I assure you there is quite as much of that going on in the country as in town.\" Everybody was surprised; and Darcy, after looking at her for a moment, turned silently away. Mrs. Bennet, who fancied she had gained a complete victory over him, continued her triumph,-- \"I cannot see that London has any great advantage over the country, for my part, except the shops and public places. The country is a vast deal pleasanter, is not it, Mr. Bingley?\" \"When I am in the country,\" he replied, \"I never wish to leave it; and when I am in town, it is pretty much the same. They have each their advantages, and I can be equally happy in either.\" \"Ay, that is because you have the right disposition. But that gentleman,\" looking at Darcy, \"seemed to think the country was nothing at all.\" \"Indeed, mamma, you are mistaken,\" said Elizabeth, blushing for her mother. \"You quite mistook Mr. Darcy. He only meant that there was not such a variety of people to be met with in the country as in town, which you must acknowledge to be true.\" \"Certainly, my dear, nobody said there were; but as to not meeting with many people in this neighbourhood, I believe there are few neighbourhoods larger. I know we dine with four-and-twenty families.\" Nothing but concern for Elizabeth could enable Bingley to keep his countenance. His sister was less delicate, and directed her eye towards Mr. Darcy with a very expressive smile. Elizabeth, for the sake of saying something that might turn her mother's thoughts, now asked her if Charlotte Lucas had been at Longbourn since her coming away. \"Yes, she called yesterday with her father. What an agreeable man Sir William is, Mr. Bingley--is not he? so much the man of fashion! so genteel and so easy! He has always something to say to everybody. That is my idea of good breeding; and those persons who fancy themselves very important and never open their mouths quite mistake the matter.\" \"Did Charlotte dine with you?\" \"No, she would go home. I fancy she was wanted about the mince-pies. For my part, Mr. Bingley, I always keep servants that can do their own work; my daughters are brought up differently. But everybody is to judge for themselves, and the Lucases are a very good sort of girls, I assure you. It is a pity they are not handsome! Not that I think Charlotte so very plain; but then she is our particular friend.\" \"She seems a very pleasant young woman,\" said Bingley. \"Oh dear, yes; but you must own she is very plain. Lady Lucas herself has often said so, and envied me Jane's beauty. I do not like to boast of my own child; but to be sure, Jane--one does not often see anybody better looking. It is what everybody says. I do not trust my own partiality. When she was only fifteen there was a gentleman at my brother Gardiner's in town so much in love with her, that my sister-in-law was sure he would make her an offer before we came away. But, however, he did not. Perhaps he thought her too young. However, he wrote some verses on her, and very pretty they were.\" \"And so ended his affection,\" said Elizabeth, impatiently. \"There has been many a one, I fancy, overcome in the same way. I wonder who first discovered the efficacy of poetry in driving away love!\" \"I have been used to consider poetry as the food of love,\" said Darcy. \"Of a fine, stout, healthy love it may. Everything nourishes what is strong already. But if it be only a slight, thin sort of inclination, I am convinced that one good sonnet will starve it entirely away.\" Darcy only smiled; and the general pause which ensued made Elizabeth tremble lest her mother should be exposing herself again. She longed to speak, but could think of nothing to say; and after a short silence Mrs. Bennet began repeating her thanks to Mr. Bingley for his kindness to Jane, with an apology for troubling him also with Lizzy. Mr. Bingley was unaffectedly civil in his answer, and forced his younger sister to be civil also, and say what the occasion required. She performed her part, indeed, without much graciousness, but Mrs. Bennet was satisfied, and soon afterwards ordered her carriage. Upon this signal, the youngest of her daughters put herself forward. The two girls had been whispering to each other during the whole visit; and the result of it was, that the youngest should tax Mr. Bingley with having promised on his first coming into the country to give a ball at Netherfield. Lydia was a stout, well-grown girl of fifteen, with a fine complexion and good-humoured countenance; a favourite with her mother, whose affection had brought her into public at an early age. She had high animal spirits, and a sort of natural self-consequence, which the attentions of the officers, to whom her uncle's good dinners and her own easy manners recommended her, had increased into assurance. She was very equal, therefore, to address Mr. Bingley on the subject of the ball, and abruptly reminded him of his promise; adding, that it would be the most shameful thing in the world if he did not keep it. His answer to this sudden attack was delightful to her mother's ear. \"I am perfectly ready, I assure you, to keep my engagement; and, when your sister is recovered, you shall, if you please, name the very day of the ball. But you would not wish to be dancing while she is ill?\" Lydia declared herself satisfied. \"Oh yes--it would be much better to wait till Jane was well; and by that time, most likely, Captain Carter would be at Meryton again. And when you have given your ball,\" she added, \"I shall insist on their giving one also. I shall tell Colonel Forster it will be quite a shame if he does not.\" Mrs. Bennet and her daughters then departed, and Elizabeth returned instantly to Jane, leaving her own and her relations' behaviour to the remarks of the two ladies and Mr. Darcy; the latter of whom, however, could not be prevailed on to join in their censure of her, in spite of all Miss Bingley's witticisms on fine eyes. [Illustration] CHAPTER X. [Illustration] The day passed much as the day before had done. Mrs. Hurst and Miss Bingley had spent some hours of the morning with the invalid, who continued, though slowly, to mend; and, in the evening, Elizabeth joined their party in the drawing-room. The loo table, however, did not appear. Mr. Darcy was writing, and Miss Bingley, seated near him, was watching the progress of his letter, and repeatedly calling off his attention by messages to his sister. Mr. Hurst and Mr. Bingley were at piquet, and Mrs. Hurst was observing their game. Elizabeth took up some needlework, and was sufficiently amused in attending to what passed between Darcy and his companion. The perpetual commendations of the lady either on his hand-writing, or on the evenness of his lines, or on the length of his letter, with the perfect unconcern with which her praises were received, formed a curious dialogue, and was exactly in unison with her opinion of each. \"How delighted Miss Darcy will be to receive such a letter!\" He made no answer. \"You write uncommonly fast.\" \"You are mistaken. I write rather slowly.\" \"How many letters you must have occasion to write in the course of a year! Letters of business, too! How odious I should think them!\" \"It is fortunate, then, that they fall to my lot instead of to yours.\" \"Pray tell your sister that I long to see her.\" \"I have already told her so once, by your desire.\" \"I am afraid you do not like your pen. Let me mend it for you. I mend pens remarkably well.\" \"Thank you--but I always mend my own.\" \"How can you contrive to write so even?\" He was silent. \"Tell your sister I am delighted to hear of her improvement on the harp, and pray let her know that I am quite in raptures with her beautiful little design for a table, and I think it infinitely superior to Miss Grantley's.\" \"Will you give me leave to defer your raptures till I write again? At present I have not room to do them justice.\" \"Oh, it is of no consequence. I shall see her in January. But do you always write such charming long letters to her, Mr. Darcy?\" \"They are generally long; but whether always charming, it is not for me to determine.\" \"It is a rule with me, that a person who can write a long letter with ease cannot write ill.\" \"That will not do for a compliment to Darcy, Caroline,\" cried her brother, \"because he does not write with ease. He studies too much for words of four syllables. Do not you, Darcy?\" \"My style of writing is very different from yours.\" \"Oh,\" cried Miss Bingley, \"Charles writes in the most careless way imaginable. He leaves out half his words, and blots the rest.\" \"My ideas flow so rapidly that I have not time to express them; by which means my letters sometimes convey no ideas at all to my correspondents.\" \"Your humility, Mr. Bingley,\" said Elizabeth, \"must disarm reproof.\" \"Nothing is more deceitful,\" said Darcy, \"than the appearance of humility. It is often only carelessness of opinion, and sometimes an indirect boast.\" \"And which of the two do you call my little recent piece of modesty?\" \"The indirect boast; for you are really proud of your defects in writing, because you consider them as proceeding from a rapidity of thought and carelessness of execution, which, if not estimable, you think at least highly interesting. The power of doing anything with quickness is always much prized by the possessor, and often without any attention to the imperfection of the performance. When you told Mrs. Bennet this morning, that if you ever resolved on quitting Netherfield you should be gone in five minutes, you meant it to be a sort of panegyric, of compliment to yourself; and yet what is there so very laudable in a precipitance which must leave very necessary business undone, and can be of no real advantage to yourself or anyone else?\" \"Nay,\" cried Bingley, \"this is too much, to remember at night all the foolish things that were said in the morning. And yet, upon my honour, I believed what I said of myself to be true, and I believe it at this moment. At least, therefore, I did not assume the character of needless precipitance merely to show off before the ladies.\" \"I daresay you believed it; but I am by no means convinced that you would be gone with such celerity. Your conduct would be quite as dependent on chance as that of any man I know; and if, as you were mounting your horse, a friend were to say, 'Bingley, you had better stay till next week,' you would probably do it--you would probably not go--and, at another word, might stay a month.\" \"You have only proved by this,\" cried Elizabeth, \"that Mr. Bingley did not do justice to his own disposition. You have shown him off now much more than he did himself.\" \"I am exceedingly gratified,\" said Bingley, \"by your converting what my friend says into a compliment on the sweetness of my temper. But I am afraid you are giving it a turn which that gentleman did by no means intend; for he would certainly think the better of me if, under such a circumstance, I were to give a flat denial, and ride off as fast as I could.\" \"Would Mr. Darcy then consider the rashness of your original intention as atoned for by your obstinacy in adhering to it?\" \"Upon my word, I cannot exactly explain the matter--Darcy must speak for himself.\" \"You expect me to account for opinions which you choose to call mine, but which I have never acknowledged. Allowing the case, however, to stand according to your representation, you must remember, Miss Bennet, that the friend who is supposed to desire his return to the house, and the delay of his plan, has merely desired it, asked it without offering one argument in favour of its propriety.\" \"To yield readily--easily--to the persuasion of a friend is no merit with you.\" \"To yield without conviction is no compliment to the understanding of either.\" \"You appear to me, Mr. Darcy, to allow nothing for the influence of friendship and affection. A regard for the requester would often make one readily yield to a request, without waiting for arguments to reason one into it. I am not particularly speaking of such a case as you have supposed about Mr. Bingley. We may as well wait, perhaps, till the circumstance occurs, before we discuss the discretion of his behaviour thereupon. But in general and ordinary cases, between friend and friend, where one of them is desired by the other to change a resolution of no very great moment, should you think ill of that person for complying with the desire, without waiting to be argued into it?\" \"Will it not be advisable, before we proceed on this subject, to arrange with rather more precision the degree of importance which is to appertain to this request, as well as the degree of intimacy subsisting between the parties?\" \"By all means,\" cried Bingley; \"let us hear all the particulars, not forgetting their comparative height and size, for that will have more weight in the argument, Miss Bennet, than you may be aware of. I assure you that if Darcy were not such a great tall fellow, in comparison with myself, I should not pay him half so much deference. I declare I do not know a more awful object than Darcy on particular occasions, and in particular places; at his own house especially, and of a Sunday evening, when he has nothing to do.\" Mr. Darcy smiled; but Elizabeth thought she could perceive that he was rather offended, and therefore checked her laugh. Miss Bingley warmly resented the indignity he had received, in an expostulation with her brother for talking such nonsense. \"I see your design, Bingley,\" said his friend. \"You dislike an argument, and want to silence this.\" \"Perhaps I do. Arguments are too much like disputes. If you and Miss Bennet will defer yours till I am out of the room, I shall be very thankful; and then you may say whatever you like of me.\" \"What you ask,\" said Elizabeth, \"is no sacrifice on my side; and Mr. Darcy had much better finish his letter.\" Mr. Darcy took her advice, and did finish his letter. When that business was over, he applied to Miss Bingley and Elizabeth for the indulgence of some music. Miss Bingley moved with alacrity to the pianoforte, and after a polite request that Elizabeth would lead the way, which the other as politely and more earnestly negatived, she seated herself. Mrs. Hurst sang with her sister; and while they were thus employed, Elizabeth could not help observing, as she turned over some music-books that lay on the instrument, how frequently Mr. Darcy's eyes were fixed on her. She hardly knew how to suppose that she could be an object of admiration to so great a man, and yet that he should look at her because he disliked her was still more strange. She could only imagine, however, at last, that she drew his notice because there was something about her more wrong and reprehensible, according to his ideas of right, than in any other person present. The supposition did not pain her. She liked him too little to care for his approbation. After playing some Italian songs, Miss Bingley varied the charm by a lively Scotch air; and soon afterwards Mr. Darcy, drawing near Elizabeth, said to her,-- \"Do you not feel a great inclination, Miss Bennet, to seize such an opportunity of dancing a reel?\" She smiled, but made no answer. He repeated the question, with some surprise at her silence. \"Oh,\" said she, \"I heard you before; but I could not immediately determine what to say in reply. You wanted me, I know, to say 'Yes,' that you might have the pleasure of despising my taste; but I always delight in overthrowing those kind of schemes, and cheating a person of their premeditated contempt. I have, therefore, made up my mind to tell you that I do not want to dance a reel at all; and now despise me if you dare.\" \"Indeed I do not dare.\" Elizabeth, having rather expected to affront him, was amazed at his gallantry; but there was a mixture of sweetness and archness in her manner which made it difficult for her to affront anybody, and Darcy had never been so bewitched by any woman as he was by her. He really believed that, were it not for the inferiority of her connections, he should be in some danger. Miss Bingley saw, or suspected, enough to be jealous; and her great anxiety for the recovery of her dear friend Jane received some assistance from her desire of getting rid of Elizabeth. She often tried to provoke Darcy into disliking her guest, by talking of their supposed marriage, and planning his happiness in such an alliance. \"I hope,\" said she, as they were walking together in the shrubbery the next day, \"you will give your mother-in-law a few hints, when this desirable event takes place, as to the advantage of holding her tongue; and if you can compass it, to cure the younger girls of running after the officers. And, if I may mention so delicate a subject, endeavour to check that little something, bordering on conceit and impertinence, which your lady possesses.\" [Illustration: \"No, no; stay where you are\" [Copyright 1894 by George Allen.]] \"Have you anything else to propose for my domestic felicity?\" \"Oh yes. Do let the portraits of your uncle and aunt Philips be placed in the gallery at Pemberley. Put them next to your great-uncle the judge. They are in the same profession, you know, only in different lines. As for your Elizabeth's picture, you must not attempt to have it taken, for what painter could do justice to those beautiful eyes?\" \"It would not be easy, indeed, to catch their expression; but their colour and shape, and the eyelashes, so remarkably fine, might be copied.\" At that moment they were met from another walk by Mrs. Hurst and Elizabeth herself. \"I did not know that you intended to walk,\" said Miss Bingley, in some confusion, lest they had been overheard. \"You used us abominably ill,\" answered Mrs. Hurst, \"running away without telling us that you were coming out.\" Then taking the disengaged arm of Mr. Darcy, she left Elizabeth to walk by herself. The path just admitted three. Mr. Darcy felt their rudeness, and immediately said,-- \"This walk is not wide enough for our party. We had better go into the avenue.\" But Elizabeth, who had not the least inclination to remain with them, laughingly answered,-- \"No, no; stay where you are. You are charmingly grouped, and appear to uncommon advantage. The picturesque would be spoilt by admitting a fourth. Good-bye.\" She then ran gaily off, rejoicing, as she rambled about, in the hope of being at home again in a day or two. Jane was already so much recovered as to intend leaving her room for a couple of hours that evening. [Illustration: \"Piling up the fire\" [Copyright 1894 by George Allen.]] CHAPTER XI. [Illustration] When the ladies removed after dinner Elizabeth ran up to her sister, and seeing her well guarded from cold, attended her into the drawing-room, where she was welcomed by her two friends with many professions of pleasure; and Elizabeth had never seen them so agreeable as they were during the hour which passed before the gentlemen appeared. Their powers of conversation were considerable. They could describe an entertainment with accuracy, relate an anecdote with humour, and laugh at their acquaintance with spirit. But when the gentlemen entered, Jane was no longer the first object; Miss Bingley's eyes were instantly turned towards Darcy, and she had something to say to him before he had advanced many steps. He addressed himself directly to Miss Bennet with a polite congratulation; Mr. Hurst also made her a slight bow, and said he was \"very glad;\" but diffuseness and warmth remained for Bingley's salutation. He was full of joy and attention. The first half hour was spent in piling up the fire, lest she should suffer from the change of room; and she removed, at his desire, to the other side of the fireplace, that she might be farther from the door. He then sat down by her, and talked scarcely to anyone else. Elizabeth, at work in the opposite corner, saw it all with great delight. When tea was over Mr. Hurst reminded his sister-in-law of the card-table--but in vain. She had obtained private intelligence that Mr. Darcy did not wish for cards, and Mr. Hurst soon found even his open petition rejected. She assured him that no one intended to play, and the silence of the whole party on the subject seemed to justify her. Mr. Hurst had, therefore, nothing to do but to stretch himself on one of the sofas and go to sleep. Darcy took up a book. Miss Bingley did the same; and Mrs. Hurst, principally occupied in playing with her bracelets and rings, joined now and then in her brother's conversation with Miss Bennet. Miss Bingley's attention was quite as much engaged in watching Mr. Darcy's progress through his book, as in reading her own; and she was perpetually either making some inquiry, or looking at his page. She could not win him, however, to any conversation; he merely answered her question and read on. At length, quite exhausted by the attempt to be amused with her own book, which she had only chosen because it was the second volume of his, she gave a great yawn and said, \"How pleasant it is to spend an evening in this way! I declare, after all, there is no enjoyment like reading! How much sooner one tires of anything than of a book! When I have a house of my own, I shall be miserable if I have not an excellent library.\" No one made any reply. She then yawned again, threw aside her book, and cast her eyes round the room in quest of some amusement; when, hearing her brother mentioning a ball to Miss Bennet, she turned suddenly towards him and said,-- \"By the bye Charles, are you really serious in meditating a dance at Netherfield? I would advise you, before you determine on it, to consult the wishes of the present party; I am much mistaken if there are not some among us to whom a ball would be rather a punishment than a pleasure.\" \"If you mean Darcy,\" cried her brother, \"he may go to bed, if he chooses, before it begins; but as for the ball, it is quite a settled thing, and as soon as Nicholls has made white soup enough I shall send round my cards.\" \"I should like balls infinitely better,\" she replied, \"if they were carried on in a different manner; but there is something insufferably tedious in the usual process of such a meeting. It would surely be much more rational if conversation instead of dancing made the order of the day.\" \"Much more rational, my dear Caroline, I dare say; but it would not be near so much like a ball.\" Miss Bingley made no answer, and soon afterwards got up and walked about the room. Her figure was elegant, and she walked well; but Darcy, at whom it was all aimed, was still inflexibly studious. In the desperation of her feelings, she resolved on one effort more; and, turning to Elizabeth, said,-- \"Miss Eliza Bennet, let me persuade you to follow my example, and take a turn about the room. I assure you it is very refreshing after sitting so long in one attitude.\" Elizabeth was surprised, but agreed to it immediately. Miss Bingley succeeded no less in the real object of her civility: Mr. Darcy looked up. He was as much awake to the novelty of attention in that quarter as Elizabeth herself could be, and unconsciously closed his book. He was directly invited to join their party, but he declined it, observing that he could imagine but two motives for their choosing to walk up and down the room together, with either of which motives his joining them would interfere. What could he mean? She was dying to know what could be his meaning--and asked Elizabeth whether she could at all understand him. \"Not at all,\" was her answer; \"but, depend upon it, he means to be severe on us, and our surest way of disappointing him will be to ask nothing about it.\" Miss Bingley, however, was incapable of disappointing Mr. Darcy in anything, and persevered, therefore, in requiring an explanation of his two motives. \"I have not the smallest objection to explaining them,\" said he, as soon as she allowed him to speak. \"You either choose this method of passing the evening because you are in each other's confidence, and have secret affairs to discuss, or because you are conscious that your figures appear to the greatest advantage in walking: if the first, I should be completely in your way; and if the second, I can admire you much better as I sit by the fire.\" \"Oh, shocking!\" cried Miss Bingley. \"I never heard anything so abominable. How shall we punish him for such a speech?\" \"Nothing so easy, if you have but the inclination,\" said Elizabeth. \"We can all plague and punish one another. Tease him--laugh at him. Intimate as you are, you must know how it is to be done.\" \"But upon my honour I do not. I do assure you that my intimacy has not yet taught me that. Tease calmness of temper and presence of mind! No, no; I feel he may defy us there. And as to laughter, we will not expose ourselves, if you please, by attempting to laugh without a subject. Mr. Darcy may hug himself.\" \"Mr. Darcy is not to be laughed at!\" cried Elizabeth. \"That is an uncommon advantage, and uncommon I hope it will continue, for it would be a great loss to me to have many such acquaintance. I dearly love a laugh.\" \"Miss Bingley,\" said he, \"has given me credit for more than can be. The wisest and best of men,--nay, the wisest and best of their actions,--may be rendered ridiculous by a person whose first object in life is a joke.\" \"Certainly,\" replied Elizabeth, \"there are such people, but I hope I am not one of them. I hope I never ridicule what is wise or good. Follies and nonsense, whims and inconsistencies, do divert me, I own, and I laugh at them whenever I can. But these, I suppose, are precisely what you are without.\" \"Perhaps that is not possible for anyone. But it has been the study of my life to avoid those weaknesses which often expose a strong understanding to ridicule.\" \"Such as vanity and pride.\" \"Yes, vanity is a weakness indeed. But pride--where there is a real superiority of mind--pride will be always under good regulation.\" Elizabeth turned away to hide a smile. \"Your examination of Mr. Darcy is over, I presume,\" said Miss Bingley; \"and pray what is the result?\" \"I am perfectly convinced by it that Mr. Darcy has no defect. He owns it himself without disguise.\" \"No,\" said Darcy, \"I have made no such pretension. I have faults enough, but they are not, I hope, of understanding. My temper I dare not vouch for. It is, I believe, too little yielding; certainly too little for the convenience of the world. I cannot forget the follies and vices of others so soon as I ought, nor their offences against myself. My feelings are not puffed about with every attempt to move them. My temper would perhaps be called resentful. My good opinion once lost is lost for ever.\" \"That is a failing, indeed!\" cried Elizabeth. \"Implacable resentment is a shade in a character. But you have chosen your fault well. I really cannot laugh at it. You are safe from me.\" \"There is, I believe, in every disposition a tendency to some particular evil, a natural defect, which not even the best education can overcome.\" \"And your defect is a propensity to hate everybody.\" \"And yours,\" he replied, with a smile, \"is wilfully to misunderstand them.\" \"Do let us have a little music,\" cried Miss Bingley, tired of a conversation in which she had no share. \"Louisa, you will not mind my waking Mr. Hurst.\" Her sister made not the smallest objection, and the pianoforte was opened; and Darcy, after a few moments' recollection, was not sorry for it. He began to feel the danger of paying Elizabeth too much attention. [Illustration] CHAPTER XII. [Illustration] In consequence of an agreement between the sisters, Elizabeth wrote the next morning to her mother, to beg that the carriage might be sent for them in the course of the day. But Mrs. Bennet, who had calculated on her daughters remaining at Netherfield till the following Tuesday, which would exactly finish Jane's week, could not bring herself to receive them with pleasure before. Her answer, therefore, was not propitious, at least not to Elizabeth's wishes, for she was impatient to get home. Mrs. Bennet sent them word that they could not possibly have the carriage before Tuesday; and in her postscript it was added, that if Mr. Bingley and his sister pressed them to stay longer, she could spare them very well. Against staying longer, however, Elizabeth was positively resolved--nor did she much expect it would be asked; and fearful, on the contrary, of being considered as intruding themselves needlessly long, she urged Jane to borrow Mr. Bingley's carriage immediately, and at length it was settled that their original design of leaving Netherfield that morning should be mentioned, and the request made. The communication excited many professions of concern; and enough was said of wishing them to stay at least till the following day to work on Jane; and till the morrow their going was deferred. Miss Bingley was then sorry that she had proposed the delay; for her jealousy and dislike of one sister much exceeded her affection for the other. The master of the house heard with real sorrow that they were to go so soon, and repeatedly tried to persuade Miss Bennet that it would not be safe for her--that she was not enough recovered; but Jane was firm where she felt herself to be right. To Mr. Darcy it was welcome intelligence: Elizabeth had been at Netherfield long enough. She attracted him more than he liked; and Miss Bingley was uncivil to her and more teasing than usual to himself. He wisely resolved to be particularly careful that no sign of admiration should now escape him--nothing that could elevate her with the hope of influencing his felicity; sensible that, if such an idea had been suggested, his behaviour during the last day must have material weight in confirming or crushing it. Steady to his purpose, he scarcely spoke ten words to her through the whole of Saturday: and though they were at one time left by themselves for half an hour, he adhered most conscientiously to his book, and would not even look at her. On Sunday, after morning service, the separation, so agreeable to almost all, took place. Miss Bingley's civility to Elizabeth increased at last very rapidly, as well as her affection for Jane; and when they parted, after assuring the latter of the pleasure it would always give her to see her either at Longbourn or Netherfield, and embracing her most tenderly, she even shook hands with the former. Elizabeth took leave of the whole party in the liveliest spirits. They were not welcomed home very cordially by their mother. Mrs. Bennet wondered at their coming, and thought them very wrong to give so much trouble, and was sure Jane would have caught cold again. But their father, though very laconic in his expressions of pleasure, was really glad to see them; he had felt their importance in the family circle. The evening conversation, when they were all assembled, had lost much of its animation, and almost all its sense, by the absence of Jane and Elizabeth. They found Mary, as usual, deep in the study of thorough bass and human nature; and had some new extracts to admire and some new observations of threadbare morality to listen to. Catherine and Lydia had information for them of a different sort. Much had been done, and much had been said in the regiment since the preceding Wednesday; several of the officers had dined lately with their uncle; a private had been flogged; and it had actually been hinted that Colonel Forster was going to be married. [Illustration] CHAPTER XIII [Illustration] \"I hope, my dear,\" said Mr. Bennet to his wife, as they were at breakfast the next morning, \"that you have ordered a good dinner to-day, because I have reason to expect an addition to our family party.\" \"Who do you mean, my dear? I know of nobody that is coming, I am sure, unless Charlotte Lucas should happen to call in; and I hope my dinners are good enough for her. I do not believe she often sees such at home.\" \"The person of whom I speak is a gentleman and a stranger.\" Mrs. Bennet's eyes sparkled. \"A gentleman and a stranger! It is Mr. Bingley, I am sure. Why, Jane--you never dropped a word of this--you sly thing! Well, I am sure I shall be extremely glad to see Mr. Bingley. But--good Lord! how unlucky! there is not a bit of fish to be got to-day. Lydia, my love, ring the bell. I must speak to Hill this moment.\" \"It is not Mr. Bingley,\" said her husband; \"it is a person whom I never saw in the whole course of my life.\" This roused a general astonishment; and he had the pleasure of being eagerly questioned by his wife and five daughters at once. After amusing himself some time with their curiosity, he thus explained:--\"About a month ago I received this letter, and about a fortnight ago I answered it; for I thought it a case of some delicacy, and requiring early attention. It is from my cousin, Mr. Collins, who, when I am dead, may turn you all out of this house as soon as he pleases.\" \"Oh, my dear,\" cried his wife, \"I cannot bear to hear that mentioned. Pray do not talk of that odious man. I do think it is the hardest thing in the world, that your estate should be entailed away from your own children; and I am sure, if I had been you, I should have tried long ago to do something or other about it.\" Jane and Elizabeth attempted to explain to her the nature of an entail. They had often attempted it before: but it was a subject on which Mrs. Bennet was beyond the reach of reason; and she continued to rail bitterly against the cruelty of settling an estate away from a family of five daughters, in favour of a man whom nobody cared anything about. \"It certainly is a most iniquitous affair,\" said Mr. Bennet; \"and nothing can clear Mr. Collins from the guilt of inheriting Longbourn. But if you will listen to his letter, you may, perhaps, be a little softened by his manner of expressing himself.\" \"No, that I am sure I shall not: and I think it was very impertinent of him to write to you at all, and very hypocritical. I hate such false friends. Why could not he keep on quarrelling with you, as his father did before him?\" \"Why, indeed, he does seem to have had some filial scruples on that head, as you will hear.\" /* RIGHT \"Hunsford, near Westerham, Kent, 15th October. */ \"Dear Sir, \"The disagreement subsisting between yourself and my late honoured father always gave me much uneasiness; and, since I have had the misfortune to lose him, I have frequently wished to heal the breach: but, for some time, I was kept back by my own doubts, fearing lest it might seem disrespectful to his memory for me to be on good terms with anyone with whom it had always pleased him to be at variance.\"--'There, Mrs. Bennet.'--\"My mind, however, is now made up on the subject; for, having received ordination at Easter, I have been so fortunate as to be distinguished by the patronage of the Right Honourable Lady Catherine de Bourgh, widow of Sir Lewis de Bourgh, whose bounty and beneficence has preferred me to the valuable rectory of this parish, where it shall be my earnest endeavour to demean myself with grateful respect towards her Ladyship, and be ever ready to perform those rites and ceremonies which are instituted by the Church of England. As a clergyman, moreover, I feel it my duty to promote and establish the blessing of peace in all families within the reach of my influence; and on these grounds I flatter myself that my present overtures of good-will are highly commendable, and that the circumstance of my being next in the entail of Longbourn estate will be kindly overlooked on your side, and not lead you to reject the offered olive branch. I cannot be otherwise than concerned at being the means of injuring your amiable daughters, and beg leave to apologize for it, as well as to assure you of my readiness to make them every possible amends; but of this hereafter. If you should have no objection to receive me into your house, I propose myself the satisfaction of waiting on you and your family, Monday, November 18th, by four o'clock, and shall probably trespass on your hospitality till the Saturday se'nnight following, which I can do without any inconvenience, as Lady Catherine is far from objecting to my occasional absence on a Sunday, provided that some other clergyman is engaged to do the duty of the day. I remain, dear sir, with respectful compliments to your lady and daughters, your well-wisher and friend, \"WILLIAM COLLINS.\" \"At four o'clock, therefore, we may expect this peace-making gentleman,\" said Mr. Bennet, as he folded up the letter. \"He seems to be a most conscientious and polite young man, upon my word; and, I doubt not, will prove a valuable acquaintance, especially if Lady Catherine should be so indulgent as to let him come to us again.\" \"There is some sense in what he says about the girls, however; and, if he is disposed to make them any amends, I shall not be the person to discourage him.\" \"Though it is difficult,\" said Jane, \"to guess in what way he can mean to make us the atonement he thinks our due, the wish is certainly to his credit.\" Elizabeth was chiefly struck with his extraordinary deference for Lady Catherine, and his kind intention of christening, marrying, and burying his parishioners whenever it were required. \"He must be an oddity, I think,\" said she. \"I cannot make him out. There is something very pompous in his style. And what can he mean by apologizing for being next in the entail? We cannot suppose he would help it, if he could. Can he be a sensible man, sir?\" \"No, my dear; I think not. I have great hopes of finding him quite the reverse. There is a mixture of servility and self-importance in his letter which promises well. I am impatient to see him.\" \"In point of composition,\" said Mary, \"his letter does not seem defective. The idea of the olive branch perhaps is not wholly new, yet I think it is well expressed.\" To Catherine and Lydia neither the letter nor its writer were in any degree interesting. It was next to impossible that their cousin should come in a scarlet coat, and it was now some weeks since they had received pleasure from the society of a man in any other colour. As for their mother, Mr. Collins's letter had done away much of her ill-will, and she was preparing to see him with a degree of composure which astonished her husband and daughters. Mr. Collins was punctual to his time, and was received with great politeness by the whole family. Mr. Bennet indeed said little; but the ladies were ready enough to talk, and Mr. Collins seemed neither in need of encouragement, nor inclined to be silent himself. He was a tall, heavy-looking young man of five-and-twenty. His air was grave and stately, and his manners were very formal. He had not been long seated before he complimented Mrs. Bennet on having so fine a family of daughters, said he had heard much of their beauty, but that, in this instance, fame had fallen short of the truth; and added, that he did not doubt her seeing them all in due time well disposed of in marriage. This gallantry was not much to the taste of some of his hearers; but Mrs. Bennet, who quarrelled with no compliments, answered most readily,-- \"You are very kind, sir, I am sure; and I wish with all my heart it may prove so; for else they will be destitute enough. Things are settled so oddly.\" \"You allude, perhaps, to the entail of this estate.\" \"Ah, sir, I do indeed. It is a grievous affair to my poor girls, you must confess. Not that I mean to find fault with you, for such things, I know, are all chance in this world. There is no knowing how estates will go when once they come to be entailed.\" \"I am very sensible, madam, of the hardship to my fair cousins, and could say much on the subject, but that I am cautious of appearing forward and precipitate. But I can assure the young ladies that I come prepared to admire them. At present I will not say more, but, perhaps, when we are better acquainted----\" He was interrupted by a summons to dinner; and the girls smiled on each other. They were not the only objects of Mr. Collins's admiration. The hall, the dining-room, and all its furniture, were examined and praised; and his commendation of everything would have touched Mrs. Bennet's heart, but for the mortifying supposition of his viewing it all as his own future property. The dinner, too, in its turn, was highly admired; and he begged to know to which of his fair cousins the excellence of its cookery was owing. But here he was set right by Mrs. Bennet, who assured him, with some asperity, that they were very well able to keep a good cook, and that her daughters had nothing to do in the kitchen. He begged pardon for having displeased her. In a softened tone she declared herself not at all offended; but he continued to apologize for about a quarter of an hour. [Illustration] CHAPTER XIV [Illustration] During dinner, Mr. Bennet scarcely spoke at all; but when the servants were withdrawn, he thought it time to have some conversation with his guest, and therefore started a subject in which he expected him to shine, by observing that he seemed very fortunate in his patroness. Lady Catherine de Bourgh's attention to his wishes, and consideration for his comfort, appeared very remarkable. Mr. Bennet could not have chosen better. Mr. Collins was eloquent in her praise. The subject elevated him to more than usual solemnity of manner; and with a most important aspect he protested that he had never in his life witnessed such behaviour in a person of rank--such affability and condescension, as he had himself experienced from Lady Catherine. She had been graciously pleased to approve of both the discourses which he had already had the honour of preaching before her. She had also asked him twice to dine at Rosings, and had sent for him only the Saturday before, to make up her pool of quadrille in the evening. Lady Catherine was reckoned proud by many people, he knew, but he had never seen anything but affability in her. She had always spoken to him as she would to any other gentleman; she made not the smallest objection to his joining in the society of the neighbourhood, nor to his leaving his parish occasionally for a week or two to visit his relations. She had even condescended to advise him to marry as soon as he could, provided he chose with discretion; and had once paid him a visit in his humble parsonage, where she had perfectly approved all the alterations he had been making, and had even vouchsafed to suggest some herself,--some shelves in the closets upstairs. \"That is all very proper and civil, I am sure,\" said Mrs. Bennet, \"and I dare say she is a very agreeable woman. It is a pity that great ladies in general are not more like her. Does she live near you, sir?\" \"The garden in which stands my humble abode is separated only by a lane from Rosings Park, her Ladyship's residence.\" \"I think you said she was a widow, sir? has she any family?\" \"She has one only daughter, the heiress of Rosings, and of very extensive property.\" \"Ah,\" cried Mrs. Bennet, shaking her head, \"then she is better off than many girls. And what sort of young lady is she? Is she handsome?\" \"She is a most charming young lady, indeed. Lady Catherine herself says that, in point of true beauty, Miss de Bourgh is far superior to the handsomest of her sex; because there is that in her features which marks the young woman of distinguished birth. She is unfortunately of a sickly constitution, which has prevented her making that progress in many accomplishments which she could not otherwise have failed of, as I am informed by the lady who superintended her education, and who still resides with them. But she is perfectly amiable, and often condescends to drive by my humble abode in her little phaeton and ponies.\" \"Has she been presented? I do not remember her name among the ladies at court.\" \"Her indifferent state of health unhappily prevents her being in town; and by that means, as I told Lady Catherine myself one day, has deprived the British Court of its brightest ornament. Her Ladyship seemed pleased with the idea; and you may imagine that I am happy on every occasion to offer those little delicate compliments which are always acceptable to ladies. I have more than once observed to Lady Catherine, that her charming daughter seemed born to be a duchess; and that the most elevated rank, instead of giving her consequence, would be adorned by her. These are the kind of little things which please her Ladyship, and it is a sort of attention which I conceive myself peculiarly bound to pay.\" \"You judge very properly,\" said Mr. Bennet; \"and it is happy for you that you possess the talent of flattering with delicacy. May I ask whether these pleasing attentions proceed from the impulse of the moment, or are the result of previous study?\" \"They arise chiefly from what is passing at the time; and though I sometimes amuse myself with suggesting and arranging such little elegant compliments as may be adapted to ordinary occasions, I always wish to give them as unstudied an air as possible.\" Mr. Bennet's expectations were fully answered. His cousin was as absurd as he had hoped; and he listened to him with the keenest enjoyment, maintaining at the same time the most resolute composure of countenance, and, except in an occasional glance at Elizabeth, requiring no partner in his pleasure. By tea-time, however, the dose had been enough, and Mr. Bennet was glad to take his guest into the drawing-room again, and when tea was over, glad to invite him [Illustration: \"Protested that he never read novels\" H.T Feb 94 ] to read aloud to the ladies. Mr. Collins readily assented, and a book was produced; but on beholding it (for everything announced it to be from a circulating library) he started back, and, begging pardon, protested that he never read novels. Kitty stared at him, and Lydia exclaimed. Other books were produced, and after some deliberation he chose \"Fordyce's Sermons.\" Lydia gaped as he opened the volume; and before he had, with very monotonous solemnity, read three pages, she interrupted him with,-- \"Do you know, mamma, that my uncle Philips talks of turning away Richard? and if he does, Colonel Forster will hire him. My aunt told me so herself on Saturday. I shall walk to Meryton to-morrow to hear more about it, and to ask when Mr. Denny comes back from town.\" Lydia was bid by her two eldest sisters to hold her tongue; but Mr. Collins, much offended, laid aside his book, and said,-- \"I have often observed how little young ladies are interested by books of a serious stamp, though written solely for their benefit. It amazes me, I confess; for certainly there can be nothing so advantageous to them as instruction. But I will no longer importune my young cousin.\" Then, turning to Mr. Bennet, he offered himself as his antagonist at backgammon. Mr. Bennet accepted the challenge, observing that he acted very wisely in leaving the girls to their own trifling amusements. Mrs. Bennet and her daughters apologized most civilly for Lydia's interruption, and promised that it should not occur again, if he would resume his book; but Mr. Collins, after assuring them that he bore his young cousin no ill-will, and should never resent her behaviour as any affront, seated himself at another table with Mr. Bennet, and prepared for backgammon. [Illustration] CHAPTER XV. [Illustration] Mr. Collins was not a sensible man, and the deficiency of nature had been but little assisted by education or society; the greatest part of his life having been spent under the guidance of an illiterate and miserly father; and though he belonged to one of the universities, he had merely kept the necessary terms without forming at it any useful acquaintance. The subjection in which his father had brought him up had given him originally great humility of manner; but it was now a good deal counteracted by the self-conceit of a weak head, living in retirement, and the consequential feelings of early and unexpected prosperity. A fortunate chance had recommended him to Lady Catherine de Bourgh when the living of Hunsford was vacant; and the respect which he felt for her high rank, and his veneration for her as his patroness, mingling with a very good opinion of himself, of his authority as a clergyman, and his right as a rector, made him altogether a mixture of pride and obsequiousness, self-importance and humility. Having now a good house and a very sufficient income, he intended to marry; and in seeking a reconciliation with the Longbourn family he had a wife in view, as he meant to choose one of the daughters, if he found them as handsome and amiable as they were represented by common report. This was his plan of amends--of atonement--for inheriting their father's estate; and he thought it an excellent one, full of eligibility and suitableness, and excessively generous and disinterested on his own part. His plan did not vary on seeing them. Miss Bennet's lovely face confirmed his views, and established all his strictest notions of what was due to seniority; and for the first evening she was his settled choice. The next morning, however, made an alteration; for in a quarter of an hour's tête-à-tête with Mrs. Bennet before breakfast, a conversation beginning with his parsonage-house, and leading naturally to the avowal of his hopes, that a mistress for it might be found at Longbourn, produced from her, amid very complaisant smiles and general encouragement, a caution against the very Jane he had fixed on. \"As to her younger daughters, she could not take upon her to say--she could not positively answer--but she did not know of any prepossession;--her eldest daughter she must just mention--she felt it incumbent on her to hint, was likely to be very soon engaged.\" Mr. Collins had only to change from Jane to Elizabeth--and it was soon done--done while Mrs. Bennet was stirring the fire. Elizabeth, equally next to Jane in birth and beauty, succeeded her of course. Mrs. Bennet treasured up the hint, and trusted that she might soon have two daughters married; and the man whom she could not bear to speak of the day before, was now high in her good graces. Lydia's intention of walking to Meryton was not forgotten: every sister except Mary agreed to go with her; and Mr. Collins was to attend them, at the request of Mr. Bennet, who was most anxious to get rid of him, and have his library to himself; for thither Mr. Collins had followed him after breakfast, and there he would continue, nominally engaged with one of the largest folios in the collection, but really talking to Mr. Bennet, with little cessation, of his house and garden at Hunsford. Such doings discomposed Mr. Bennet exceedingly. In his library he had been always sure of leisure and tranquillity; and though prepared, as he told Elizabeth, to meet with folly and conceit in every other room in the house, he was used to be free from them there: his civility, therefore, was most prompt in inviting Mr. Collins to join his daughters in their walk; and Mr. Collins, being in fact much better fitted for a walker than a reader, was extremely well pleased to close his large book, and go. In pompous nothings on his side, and civil assents on that of his cousins, their time passed till they entered Meryton. The attention of the younger ones was then no longer to be gained by him. Their eyes were immediately wandering up the street in quest of the officers, and nothing less than a very smart bonnet, indeed, or a really new muslin in a shop window, could recall them. But the attention of every lady was soon caught by a young man, whom they had never seen before, of most gentlemanlike appearance, walking with an officer on the other side of the way. The officer was the very Mr. Denny concerning whose return from London Lydia came to inquire, and he bowed as they passed. All were struck with the stranger's air, all wondered who he could be; and Kitty and Lydia, determined if possible to find out, led the way across the street, under pretence of wanting something in an opposite shop, and fortunately had just gained the pavement, when the two gentlemen, turning back, had reached the same spot. Mr. Denny addressed them directly, and entreated permission to introduce his friend, Mr. Wickham, who had returned with him the day before from town, and, he was happy to say, had accepted a commission in their corps. This was exactly as it should be; for the young man wanted only regimentals to make him completely charming. His appearance was greatly in his favour: he had all the best parts of beauty, a fine countenance, a good figure, and very pleasing address. The introduction was followed up on his side by a happy readiness of conversation--a readiness at the same time perfectly correct and unassuming; and the whole party were still standing and talking together very agreeably, when the sound of horses drew their notice, and Darcy and Bingley were seen riding down the street. On distinguishing the ladies of the group the two gentlemen came directly towards them, and began the usual civilities. Bingley was the principal spokesman, and Miss Bennet the principal object. He was then, he said, on his way to Longbourn on purpose to inquire after her. Mr. Darcy corroborated it with a bow, and was beginning to determine not to fix his eyes on Elizabeth, when they were suddenly arrested by the sight of the stranger; and Elizabeth happening to see the countenance of both as they looked at each other, was all astonishment at the effect of the meeting. Both changed colour, one looked white, the other red. Mr. Wickham, after a few moments, touched his hat--a salutation which Mr. Darcy just deigned to return. What could be the meaning of it? It was impossible to imagine; it was impossible not to long to know. In another minute Mr. Bingley, but without seeming to have noticed what passed, took leave and rode on with his friend. Mr. Denny and Mr. Wickham walked with the young ladies to the door of Mr. Philips's house, and then made their bows, in spite of Miss Lydia's pressing entreaties that they would come in, and","de":"Als Gregor Samsa eines Morgens aus unruhigen Träumen erwachte, fand er sich in seinem Bett zu einem ungeheueren Ungeziefer verwandelt. Er lag auf seinem panzerartig harten Rücken und sah, wenn er den Kopf ein wenig hob, seinen gewölbten, braunen, von bogenförmigen Versteifungen geteilten Bauch, auf dessen Höhe sich die Bettdecke, zum gänzlichen Niedergleiten bereit, kaum noch erhalten konnte. Seine vielen, im Vergleich zu seinem sonstigen Umfang kläglich dünnen Beine flimmerten ihm hilflos vor den Augen. »Was ist mit mir geschehen?« dachte er. Es war kein Traum. Sein Zimmer, ein richtiges, nur etwas zu kleines Menschenzimmer, lag ruhig zwischen den vier wohlbekannten Wänden. Über dem Tisch, auf dem eine auseinandergepackte Musterkollektion von Tuchwaren ausgebreitet war -- Samsa war Reisender --, hing das Bild, das er vor kurzem aus einer illustrierten Zeitschrift ausgeschnitten und in einem hübschen, vergoldeten Rahmen untergebracht hatte. Es stellte eine Dame dar, die, mit einem Pelzhut und einer Pelzboa versehen, aufrecht dasaß und einen schweren Pelzmuff, in dem ihr ganzer Unterarm verschwunden war, dem Beschauer entgegenhob. Gregors Blick richtete sich dann zum Fenster, und das trübe Wetter -- man hörte Regentropfen auf das Fensterblech aufschlagen -- machte ihn ganz melancholisch. »Wie wäre es, wenn ich noch ein wenig weiterschliefe und alle Narrheiten vergäße,« dachte er, aber das war gänzlich undurchführbar, denn er war gewöhnt, auf der rechten Seite zu schlafen, konnte sich aber in seinem gegenwärtigen Zustand nicht in diese Lage bringen. Mit welcher Kraft er sich auch auf die rechte Seite warf, immer wieder schaukelte er in die Rückenlage zurück. Er versuchte es wohl hundertmal, schloß die Augen, um die zappelnden Beine nicht sehen zu müssen, und ließ erst ab, als er in der Seite einen noch nie gefühlten, leichten, dumpfen Schmerz zu fühlen begann. »Ach Gott,« dachte er, »was für einen anstrengenden Beruf habe ich gewählt! Tag aus, Tag ein auf der Reise. Die geschäftlichen Aufregungen sind viel größer, als im eigentlichen Geschäft zu Hause, und außerdem ist mir noch diese Plage des Reisens auferlegt, die Sorgen um die Zuganschlüsse, das unregelmäßige, schlechte Essen, ein immer wechselnder, nie andauernder, nie herzlich werdender menschlicher Verkehr. Der Teufel soll das alles holen!« Er fühlte ein leichtes Jucken oben auf dem Bauch; schob sich auf dem Rücken langsam näher zum Bettpfosten, um den Kopf besser heben zu können; fand die juckende Stelle, die mit lauter kleinen weißen Pünktchen besetzt war, die er nicht zu beurteilen verstand; und wollte mit einem Bein die Stelle betasten, zog es aber gleich zurück, denn bei der Berührung umwehten ihn Kälteschauer. Er glitt wieder in seine frühere Lage zurück. »Dies frühzeitige Aufstehen«, dachte er, »macht einen ganz blödsinnig. Der Mensch muß seinen Schlaf haben. Andere Reisende leben wie Haremsfrauen. Wenn ich zum Beispiel im Laufe des Vormittags ins Gasthaus zurückgehe, um die erlangten Aufträge zu überschreiben, sitzen diese Herren erst beim Frühstück. Das sollte ich bei meinem Chef versuchen; ich würde auf der Stelle hinausfliegen. Wer weiß übrigens, ob das nicht sehr gut für mich wäre. Wenn ich mich nicht wegen meiner Eltern zurückhielte, ich hätte längst gekündigt, ich wäre vor den Chef hingetreten und hätte ihm meine Meinung von Grund des Herzens aus gesagt. Vom Pult hätte er fallen müssen! Es ist auch eine sonderbare Art, sich auf das Pult zu setzen und von der Höhe herab mit dem Angestellten zu reden, der überdies wegen der Schwerhörigkeit des Chefs ganz nahe herantreten muß. Nun, die Hoffnung ist noch nicht gänzlich aufgegeben, habe ich einmal das Geld beisammen, um die Schuld der Eltern an ihn abzuzahlen -- es dürfte noch fünf bis sechs Jahre dauern --, mache ich die Sache unbedingt. Dann wird der große Schnitt gemacht. Vorläufig allerdings muß ich aufstehen, denn mein Zug fährt um fünf.« Und er sah zur Weckuhr hinüber, die auf dem Kasten tickte. »Himmlischer Vater!« dachte er, Es war halb sieben Uhr, und die Zeiger gingen ruhig vorwärts, es war sogar halb vorüber, es näherte sich schon dreiviertel. Sollte der Wecker nicht geläutet haben? Man sah vom Bett aus, daß er auf vier Uhr richtig eingestellt war; gewiß hatte er auch geläutet. Ja, aber war es möglich, dieses möbelerschütternde Läuten ruhig zu verschlafen? Nun, ruhig hatte er ja nicht geschlafen, aber wahrscheinlich desto fester. Was aber sollte er jetzt tun? Der nächste Zug ging um sieben Uhr; um den einzuholen, hätte er sich unsinnig beeilen müssen, und die Kollektion war noch nicht eingepackt, und er selbst fühlte sich durchaus nicht besonders frisch und beweglich. Und selbst wenn er den Zug einholte, ein Donnerwetter des Chefs war nicht zu vermeiden, denn der Geschäftsdiener hatte beim Fünfuhrzug gewartet und die Meldung von seiner Versäumnis längst erstattet. Es war eine Kreatur des Chefs, ohne Rückgrat und Verstand. Wie nun, wenn er sich krank meldete? Das wäre aber äußerst peinlich und verdächtig, denn Gregor war während seines fünfjährigen Dienstes noch nicht einmal krank gewesen. Gewiß würde der Chef mit dem Krankenkassenarzt kommen, würde den Eltern wegen des faulen Sohnes Vorwürfe machen und alle Einwände durch den Hinweis auf den Krankenkassenarzt abschneiden, für den es ja überhaupt nur ganz gesunde, aber arbeitsscheue Menschen gibt. Und hätte er übrigens in diesem Falle so ganz unrecht? Gregor fühlte sich tatsächlich, abgesehen von einer nach dem langen Schlaf wirklich überflüssigen Schläfrigkeit, ganz wohl und hatte sogar einen besonders kräftigen Hunger. Als er dies alles in größter Eile überlegte, ohne sich entschließen zu können, das Bett zu verlassen -- gerade schlug der Wecker dreiviertel sieben -- klopfte es vorsichtig an die Tür am Kopfende seines Bettes. »Gregor,« rief es -- es war die Mutter --, »es ist dreiviertel sieben. Wolltest du nicht wegfahren?« Die sanfte Stimme! Gregor erschrak, als er seine antwortende Stimme hörte, die wohl unverkennbar seine frühere war, in die sich aber, wie von unten her, ein nicht zu unterdrückendes, schmerzliches Piepsen mischte, das die Worte förmlich nur im ersten Augenblick in ihrer Deutlichkeit beließ, um sie im Nachklang derart zu zerstören, daß man nicht wußte, ob man recht gehört hatte. Gregor hatte ausführlich antworten und alles erklären wollen, beschränkte sich aber bei diesen Umständen darauf, zu sagen: »Ja, ja, danke, Mutter, ich stehe schon auf.« Infolge der Holztür war die Veränderung in Gregors Stimme draußen wohl nicht zu merken, denn die Mutter beruhigte sich mit dieser Erklärung und schlürfte davon. Aber durch das kleine Gespräch waren die anderen Familienmitglieder darauf aufmerksam geworden, daß Gregor wider Erwarten noch zu Hause war, und schon klopfte an der einen Seitentür der Vater, schwach, aber mit der Faust. »Gregor, Gregor,« rief er, »was ist denn?« Und nach einer kleinen Weile mahnte er nochmals mit tieferer Stimme: »Gregor! Gregor!« An der anderen Seitentür aber klagte leise die Schwester: »Gregor? Ist dir nicht wohl? Brauchst du etwas?« Nach beiden Seiten hin antwortete Gregor: »Bin schon fertig,« und bemühte sich, durch die sorgfältigste Aussprache und durch Einschaltung von langen Pausen zwischen den einzelnen Worten seiner Stimme alles Auffallende zu nehmen. Der Vater kehrte auch zu seinem Frühstück zurück, die Schwester aber flüsterte: »Gregor, mach auf, ich beschwöre dich.« Gregor aber dachte gar nicht daran aufzumachen, sondern lobte die vom Reisen her übernommene Vorsicht, auch zu Hause alle Türen während der Nacht zu versperren. Zunächst wollte er ruhig und ungestört aufstehen, sich anziehen und vor allem frühstücken, und dann erst das Weitere überlegen, denn, das merkte er wohl, im Bett würde er mit dem Nachdenken zu keinem vernünftigen Ende kommen. Er erinnerte sich, schon öfters im Bett irgendeinen vielleicht durch ungeschicktes Liegen erzeugten, leichten Schmerz empfunden zu haben, der sich dann beim Aufstehen als reine Einbildung herausstellte, und er war gespannt, wie sich seine heutigen Vorstellungen allmählich auflösen würden. Daß die Veränderung der Stimme nichts anderes war als der Vorbote einer tüchtigen Verkühlung, einer Berufskrankheit der Reisenden, daran zweifelte er nicht im geringsten. Die Decke abzuwerfen war ganz einfach; er brauchte sich nur ein wenig aufzublasen und sie fiel von selbst. Aber weiterhin wurde es schwierig, besonders weil er so ungemein breit war. Er hätte Arme und Hände gebraucht, um sich aufzurichten; statt dessen aber hatte er nur die vielen Beinchen, die ununterbrochen in der verschiedensten Bewegung waren und die er überdies nicht beherrschen konnte. Wollte er eines einmal einknicken, so war es das erste, daß er sich streckte; und gelang es ihm endlich, mit diesem Bein das auszuführen, was er wollte, so arbeiteten inzwischen alle anderen, wie freigelassen, in höchster, schmerzlicher Aufregung. »Nur sich nicht im Bett unnütz aufhalten,« sagte sich Gregor. Zuerst wollte er mit dem unteren Teil seines Körpers aus dem Bett hinauskommen, aber dieser untere Teil, den er übrigens noch nicht gesehen hatte und von dem er sich auch keine rechte Vorstellung machen konnte, erwies sich als zu schwer beweglich; es ging so langsam; und als er schließlich, fast wild geworden, mit gesammelter Kraft, ohne Rücksicht sich vorwärtsstieß, hatte er die Richtung falsch gewählt, schlug an den unteren Bettpfosten heftig an, und der brennende Schmerz, den er empfand, belehrte ihn, daß gerade der untere Teil seines Körpers augenblicklich vielleicht der empfindlichste war. Er versuchte es daher, zuerst den Oberkörper aus dem Bett zu bekommen, und drehte vorsichtig den Kopf dem Bettrand zu. Dies gelang auch leicht, und trotz ihrer Breite und Schwere folgte schließlich die Körpermasse langsam der Wendung des Kopfes. Aber als er den Kopf endlich außerhalb des Bettes in der freien Luft hielt, bekam er Angst, weiter auf diese Weise vorzurücken, denn wenn er sich schließlich so fallen ließ, mußte geradezu ein Wunder geschehen wenn der Kopf nicht verletzt werden sollte. Und die Besinnung durfte er gerade jetzt um keinen Preis verlieren; lieber wollte er im Bett bleiben. Aber als er wieder nach gleicher Mühe aufseufzend so dalag wie früher, und wieder seine Beinchen womöglich noch ärger gegeneinander kämpfen sah und keine Möglichkeit fand, in diese Willkür Ruhe und Ordnung zu bringen, sagte er sich wieder, daß er unmöglich im Bett bleiben könne und daß es das Vernünftigste sei, alles zu opfern, wenn auch nur die kleinste Hoffnung bestünde, sich dadurch vom Bett zu befreien. Gleichzeitig aber vergaß er nicht, sich zwischendurch daran zu erinnern, daß viel besser als verzweifelte Entschlüsse ruhige und ruhigste Überlegung sei. In solchen Augenblicken richtete er die Augen möglichst scharf auf das Fenster, aber leider war aus dem Anblick des Morgennebels, der sogar die andere Seite der engen Straße verhüllte, wenig Zuversicht und Munterkeit zu holen. »Schon sieben Uhr,« sagte er sich beim neuerlichen Schlagen des Weckers, »schon sieben Uhr und noch immer ein solcher Nebel.« Und ein Weilchen lang lag er ruhig mit schwachem Atem, als erwarte er vielleicht von der völligen Stille die Wiederkehr der wirklichen und selbstverständlichen Verhältnisse. Dann aber sagte er sich: »Ehe es einviertel acht schlägt, muß ich unbedingt das Bett vollständig verlassen haben. Im übrigen wird auch bis dahin jemand aus dem Geschäft kommen, um nach mir zu fragen, denn das Geschäft wird vor sieben Uhr geöffnet.« Und er machte sich nun daran, den Körper in seiner ganzen Länge vollständig gleichmäßig aus dem Bett hinauszuschaukeln. Wenn er sich auf diese Weise aus dem Bett fallen ließ, blieb der Kopf, den er beim Fall scharf heben wollte, voraussichtlich unverletzt. Der Rücken schien hart zu sein; dem würde wohl bei dem Fall auf den Teppich nichts geschehen. Das größte Bedenken machte ihm die Rücksicht auf den lauten Krach, den es geben müßte und der wahrscheinlich hinter allen Türen wenn nicht Schrecken, so doch Besorgnisse erregen würde. Das mußte aber gewagt werden. Als Gregor schon zur Hälfte aus dem Bette ragte -- die neue Methode war mehr ein Spiel als eine Anstrengung, er brauchte immer nur ruckweise zu schaukeln --, fiel ihm ein, wie einfach alles wäre, wenn man ihm zu Hilfe käme. Zwei starke Leute -- er dachte an seinen Vater und das Dienstmädchen -- hätten vollständig genügt; sie hätten ihre Arme nur unter seinen gewölbten Rücken schieben, ihn so aus dem Bett schälen, sich mit der Last niederbeugen und dann bloß vorsichtig dulden müssen, daß er den Überschwung auf dem Fußboden vollzog, wo dann die Beinchen hoffentlich einen Sinn bekommen würden. Nun, ganz abgesehen davon, daß die Türen versperrt waren, hätte er wirklich um Hilfe rufen sollen? Trotz aller Not konnte er bei diesem Gedanken ein Lächeln nicht unterdrücken. Schon war er so weit, daß er bei stärkerem Schaukeln kaum das Gleichgewicht noch erhielt, und sehr bald mußte er sich nun endgültig entscheiden, denn es war in fünf Minuten einviertel acht, -- als es an der Wohnungstür läutete. »Das ist jemand aus dem Geschäft,« sagte er sich und erstarrte fast, während seine Beinchen nur desto eiliger tanzten. Einen Augenblick blieb alles still. »Sie öffnen nicht,« sagte sich Gregor, befangen in irgendeiner unsinnigen Hoffnung. Aber dann ging natürlich wie immer das Dienstmädchen festen Schrittes zur Tür und öffnete. Gregor brauchte nur das erste Grußwort des Besuchers zu hören und wußte schon, wer es war -- der Prokurist selbst. Warum war nur Gregor dazu verurteilt, bei einer Firma zu dienen, wo man bei der kleinsten Versäumnis gleich den größten Verdacht faßte? Waren denn alle Angestellten samt und sonders Lumpen, gab es denn unter ihnen keinen treuen ergebenen Menschen, den, wenn er auch nur ein paar Morgenstunden für das Geschäft nicht ausgenützt hatte, vor Gewissensbissen närrisch wurde und geradezu nicht imstande war, das Bett zu verlassen? Genügte es wirklich nicht, einen Lehrjungen nachfragen zu lassen -- wenn überhaupt diese Fragerei nötig war --, mußte da der Prokurist selbst kommen, und mußte dadurch der ganzen unschuldigen Familie gezeigt werden, daß die Untersuchung dieser verdächtigen Angelegenheit nur dem Verstand des Prokuristen anvertraut werden konnte? Und mehr infolge der Erregung, in welche Gregor durch diese Überlegungen versetzt wurde, als infolge eines richtigen Entschlusses, schwang er sich mit aller Macht aus dem Bett. Es gab einen lauten Schlag, aber ein eigentlicher Krach war es nicht. Ein wenig wurde der Fall durch den Teppich abgeschwächt, auch war der Rücken elastischer, als Gregor gedacht hatte, daher kam der nicht gar so auffallende dumpfe Klang. Nur den Kopf hatte er nicht vorsichtig genug gehalten und ihn angeschlagen; er drehte ihn und rieb ihn an dem Teppich vor Ärger und Schmerz. »Da drin ist etwas gefallen,« sagte der Prokurist im Nebenzimmer links. Gregor suchte sich vorzustellen, ob nicht auch einmal dem Prokuristen etwas Ähnliches passieren könnte, wie heute ihm; die Möglichkeit dessen mußte man doch eigentlich zugeben. Aber wie zur rohen Antwort auf diese Frage machte jetzt der Prokurist im Nebenzimmer ein paar bestimmte Schritte und ließ seine Lackstiefel knarren. Aus dem Nebenzimmer rechts flüsterte die Schwester, um Gregor zu verständigen: »Gregor, der Prokurist ist da.« »Ich weiß,« sagte Gregor vor sich hin; aber so laut, daß es die Schwester hätte hören können, wagte er die Stimme nicht zu erheben. »Gregor,« sagte nun der Vater aus dem Nebenzimmer links, »der Herr Prokurist ist gekommen und erkundigt sich, warum du nicht mit dem Frühzug weggefahren bist. Wir wissen nicht, was wir ihm sagen sollen. Übrigens will er auch mit dir persönlich sprechen. Also bitte mach die Tür auf. Er wird die Unordnung im Zimmer zu entschuldigen schon die Güte haben.« »Guten Morgen, Herr Samsa,« rief der Prokurist freundlich dazwischen. »Ihm ist nicht wohl,« sagte die Mutter zum Prokuristen, während der Vater noch an der Tür redete, »ihm ist nicht wohl, glauben Sie mir, Herr Prokurist. Wie würde denn Gregor sonst einen Zug versäumen! Der Junge hat ja nichts im Kopf als das Geschäft. Ich ärgere mich schon fast, daß er abends niemals ausgeht; jetzt war er doch acht Tage in der Stadt, aber jeden Abend war er zu Hause. Da sitzt er bei uns am Tisch und liest still die Zeitung oder studiert Fahrpläne. Es ist schon eine Zerstreuung für ihn, wenn er sich mit Laubsägearbeiten beschäftigt. Da hat er zum Beispiel im Laufe von zwei, drei Abenden einen kleinen Rahmen geschnitzt; Sie werden staunen, wie hübsch er ist; er hängt drin im Zimmer; Sie werden ihn gleich sehen, wenn Gregor aufmacht. Ich bin übrigens glücklich, daß Sie da sind, Herr Prokurist; wir allein hätten Gregor nicht dazu gebracht, die Tür zu öffnen; er ist so hartnäckig; und bestimmt ist ihm nicht wohl, trotzdem er es am Morgen geleugnet hat.« »Ich komme gleich,« sagte Gregor langsam und bedächtig und rührte sich nicht, um kein Wort der Gespräche zu verlieren. »Anders, gnädige Frau, kann ich es mir auch nicht erklären,« sagte der Prokurist, »hoffentlich ist es nichts Ernstes. Wenn ich auch andererseits sagen muß, daß wir Geschäftsleute -- wie man will, leider oder glücklicherweise -- ein leichtes Unwohlsein sehr oft aus geschäftlichen Rücksichten einfach überwinden müssen.« »Also kann der Herr Prokurist schon zu dir hinein?« fragte der ungeduldige Vater und klopfte wiederum an die Tür. »Nein,« sagte Gregor. Im Nebenzimmer links trat eine peinliche Stille ein, im Nebenzimmer rechts begann die Schwester zu schluchzen. Warum ging denn die Schwester nicht zu den anderen? Sie war wohl erst jetzt aus dem Bett aufgestanden und hatte noch gar nicht angefangen sich anzuziehen. Und warum weinte sie denn? Weil er nicht aufstand und den Prokuristen nicht hereinließ, weil er in Gefahr war, den Posten zu verlieren und weil dann der Chef die Eltern mit den alten Forderungen wieder verfolgen würde? Das waren doch vorläufig wohl unnötige Sorgen. Noch war Gregor hier und dachte nicht im geringsten daran, seine Familie zu verlassen. Augenblicklich lag er wohl da auf dem Teppich, und niemand, der seinen Zustand gekannt hätte, hätte im Ernst von ihm verlangt, daß er den Prokuristen hereinlasse. Aber wegen dieser kleinen Unhöflichkeit, für die sich ja später leicht eine passende Ausrede finden würde, konnte Gregor doch nicht gut sofort weggeschickt werden. Und Gregor schien es, daß es viel vernünftiger wäre, ihn jetzt in Ruhe zu lassen, statt ihn mit Weinen und Zureden zu stören. Aber es war eben die Ungewißheit, welche die anderen bedrängte und ihr Benehmen entschuldigte. »Herr Samsa,« rief nun der Prokurist mit erhobener Stimme, »was ist denn los? Sie verbarrikadieren sich da in Ihrem Zimmer, antworten bloß mit ja und nein, machen Ihren Eltern schwere, unnötige Sorgen und versäumen -- dies nur nebenbei erwähnt -- Ihre geschäftlichen Pflichten in einer eigentlich unerhörten Weise. Ich spreche hier im Namen Ihrer Eltern und Ihres Chefs und bitte Sie ganz ernsthaft um eine augenblickliche, deutliche Erklärung. Ich staune, ich staune. Ich glaubte Sie als einen ruhigen, vernünftigen Menschen zu kennen, und nun scheinen Sie plötzlich anfangen zu wollen, mit sonderbaren Launen zu paradieren. Der Chef deutete mir zwar heute früh eine mögliche Erklärung für Ihre Versäumnis an -- sie betraf das Ihnen seit kurzem anvertraute Inkasso --, aber ich legte wahrhaftig fast mein Ehrenwort dafür ein, daß diese Erklärung nicht zutreffen könne. Nun aber sehe ich hier Ihren unbegreiflichen Starrsinn und verliere ganz und gar jede Lust, mich auch nur im geringsten für Sie einzusetzen. Und Ihre Stellung ist durchaus nicht die festeste. Ich hatte ursprünglich die Absicht, Ihnen das alles unter vier Augen zu sagen, aber da Sie mich hier nutzlos meine Zeit versäumen lassen, weiß ich nicht, warum es nicht auch Ihre Herren Eltern erfahren sollen. Ihre Leistungen in der letzten Zeit waren also sehr unbefriedigend; es ist zwar nicht die Jahreszeit, um besondere Geschäfte zu machen, das erkennen wir an; aber eine Jahreszeit, um keine Geschäfte zu machen, gibt es überhaupt nicht, Herr Samsa, darf es nicht geben.« »Aber Herr Prokurist,« rief Gregor außer sich und vergaß in der Aufregung alles andere, »ich mache ja sofort, augenblicklich auf. Ein leichtes Unwohlsein, ein Schwindelanfall, haben mich verhindert aufzustehen. Ich liege noch jetzt im Bett. Jetzt bin ich aber schon wieder ganz frisch. Eben steige ich aus dem Bett. Nur einen kleinen Augenblick Geduld! Es geht noch nicht so gut, wie ich dachte. Es ist mir aber schon wohl. Wie das nur einen Menschen so überfallen kann! Noch gestern abend war mir ganz gut, meine Eltern wissen es ja, oder besser, schon gestern abend hatte ich eine kleine Vorahnung. Man hätte es mir ansehen müssen. Warum habe ich es nur im Geschäfte nicht gemeldet! Aber man denkt eben immer, daß man die Krankheit ohne Zuhausebleiben überstehen wird. Herr Prokurist! Schonen Sie meine Eltern! Für alle die Vorwürfe, die Sie mir jetzt machen, ist ja kein Grund; man hat mir ja davon auch kein Wort gesagt. Sie haben vielleicht die letzten Aufträge, die ich geschickt habe, nicht gelesen. Übrigens, noch mit dem Achtuhrzug fahre ich auf die Reise, die paar Stunden Ruhe haben mich gekräftigt. Halten Sie sich nur nicht auf, Herr Prokurist; ich bin gleich selbst im Geschäft, und haben Sie die Güte, das zu sagen und mich dem Herrn Chef zu empfehlen!« Und während Gregor dies alles hastig ausstieß und kaum wußte, was er sprach, hatte er sich leicht, wohl infolge der im Bett bereits erlangten Übung, dem Kasten genähert und versuchte nun, an ihm sich aufzurichten. Er wollte tatsächlich die Tür aufmachen, tatsächlich sich sehen lassen und mit dem Prokuristen sprechen; er war begierig zu erfahren, was die anderen, die jetzt so nach ihm verlangten, bei seinem Anblick sagen würden. Würden sie erschrecken, dann hatte Gregor keine Verantwortung mehr und konnte ruhig sein. Würden sie aber alles ruhig hinnehmen, dann hatte auch er keinen Grund sich aufzuregen, und konnte, wenn er sich beeilte, um acht Uhr tatsächlich auf dem Bahnhof sein. Zuerst glitt er nun einigemale von dem glatten Kasten ab, aber endlich gab er sich einen letzten Schwung und stand aufrecht da; auf die Schmerzen im Unterleib achtete er gar nicht mehr, so sehr sie auch brannten. Nun ließ er sich gegen die Rücklehne eines nahen Stuhles fallen, an deren Rändern er sich mit seinen Beinchen festhielt. Damit hatte er aber auch die Herrschaft über sich erlangt und verstummte, denn nun konnte er den Prokuristen anhören. »Haben Sie auch nur ein Wort verstanden?« fragte der Prokurist die Eltern, »er macht sich doch wohl nicht einen Narren aus uns?« »Um Gottes willen,« rief die Mutter schon unter Weinen, »er ist vielleicht schwer krank, und wir quälen ihn. Grete! Grete!« schrie sie dann. »Mutter?« rief die Schwester von der anderen Seite. Sie verständigten sich durch Gregors Zimmer. »Du mußt augenblicklich zum Arzt. Gregor ist krank. Rasch um den Arzt. Hast du Gregor jetzt reden hören?« »Das war eine Tierstimme,« sagte der Prokurist, auffallend leise gegenüber dem Schreien der Mutter. »Anna! Anna!« rief der Vater durch das Vorzimmer in die Küche und klatschte in die Hände, »sofort einen Schlosser holen!« Und schon liefen die zwei Mädchen mit rauschenden Röcken durch das Vorzimmer -- wie hatte sich die Schwester denn so schnell angezogen? -- und rissen die Wohnungstüre auf. Man hörte gar nicht die Türe zuschlagen; sie hatten sie wohl offen gelassen, wie es in Wohnungen zu sein pflegt, in denen ein großes Unglück geschehen ist. Gregor war aber viel ruhiger geworden. Man verstand zwar also seine Worte nicht mehr, trotzdem sie ihm genug klar, klarer als früher, vorgekommen waren, vielleicht infolge der Gewöhnung des Ohres. Aber immerhin glaubte man nun schon daran, daß es mit ihm nicht ganz in Ordnung war, und war bereit, ihm zu helfen. Die Zuversicht und Sicherheit, womit die ersten Anordnungen getroffen worden waren, taten ihm wohl. Er fühlte sich wieder einbezogen in den menschlichen Kreis und erhoffte von beiden, vom Arzt und vom Schlosser, ohne sie eigentlich genau zu scheiden, großartige und überraschende Leistungen. Um für die sich nähernden entscheidenden Besprechungen eine möglichst klare Stimme zu bekommen, hustete er ein wenig ab, allerdings bemüht, dies ganz gedämpft zu tun, da möglicherweise auch schon dieses Geräusch anders als menschlicher Husten klang, was er selbst zu entscheiden sich nicht mehr getraute. Im Nebenzimmer war es inzwischen ganz still geworden. Vielleicht saßen die Eltern mit dem Prokuristen beim Tisch und tuschelten, vielleicht lehnten alle an der Türe und horchten. Gregor schob sich langsam mit dem Sessel zur Tür hin, ließ ihn dort los, warf sich gegen die Tür, hielt sich an ihr aufrecht -- die Ballen seiner Beinchen hatten ein wenig Klebstoff -- und ruhte sich dort einen Augenblick lang von der Anstrengung aus. Dann aber machte er sich daran, mit dem Mund den Schlüssel im Schloß umzudrehen. Es schien leider, daß er keine eigentlichen Zähne hatte, -- womit sollte er gleich den Schlüssel fassen? -- aber dafür waren die Kiefer freilich sehr stark, mit ihrer Hilfe brachte er auch wirklich den Schlüssel in Bewegung und achtete nicht darauf, daß er sich zweifellos irgendeinen Schaden zufügte, denn eine braune Flüssigkeit kam ihm aus dem Mund, floß über den Schlüssel und tropfte auf den Boden. »Hören Sie nur,« sagte der Prokurist im Nebenzimmer, »er dreht den Schlüssel um.« Das war für Gregor eine große Aufmunterung; aber alle hätten ihm zurufen sollen, auch der Vater und die Mutter: »Frisch, Gregor,« hätten sie rufen sollen, »immer nur heran, fest an das Schloß heran!« Und in der Vorstellung, daß alle seine Bemühungen mit Spannung verfolgten, verbiß er sich mit allem, was er an Kraft aufbringen konnte, besinnungslos in den Schlüssel. Je nach dem Fortschreiten der Drehung des Schlüssels umtanzte er das Schloß, hielt sich jetzt nur noch mit dem Munde aufrecht, und je nach Bedarf hing er sich an den Schlüssel oder drückte ihn dann wieder nieder mit der ganzen Last seines Körpers. Der hellere Klang des endlich zurückschnappenden Schlosses erweckte Gregor förmlich. Aufatmend sagte er sich: »Ich habe also den Schlosser nicht gebraucht,« und legte den Kopf auf die Klinke, um die Türe gänzlich zu öffnen. Da er die Türe auf diese Weise öffnen mußte, war sie eigentlich schon recht weit geöffnet, und er selbst noch nicht zu sehen. Er mußte sich erst langsam um den einen Türflügel herumdrehen, und zwar sehr vorsichtig, wenn er nicht gerade vor dem Eintritt ins Zimmer plump auf den Rücken fallen wollte. Er war noch mit jener schwierigen Bewegung beschäftigt und hatte nicht Zeit, auf anderes zu achten, da hörte er schon den Prokuristen ein lautes »Oh!« ausstoßen -- es klang, wie wenn der Wind saust -- und nun sah er ihn auch, wie er, der der Nächste an der Türe war, die Hand gegen den offenen Mund drückte und langsam zurückwich, als vertreibe ihn eine unsichtbare, gleichmäßig fortwirkende Kraft. Die Mutter -- sie stand hier trotz der Anwesenheit des Prokuristen mit von der Nacht her noch aufgelösten, hoch sich sträubenden Haaren -- sah zuerst mit gefalteten Händen den Vater an, ging dann zwei Schritte zu Gregor hin und fiel inmitten ihrer rings um sie herum sich ausbreitenden Röcke nieder, das Gesicht ganz unauffindbar zu ihrer Brust gesenkt. Der Vater ballte mit feindseligem Ausdruck die Faust, als wolle er Gregor in sein Zimmer zurückstoßen, sah sich dann unsicher im Wohnzimmer um, beschattete dann mit den Händen die Augen und weinte, daß sich seine mächtige Brust schüttelte. Gregor trat nun gar nicht in das Zimmer, sondern lehnte sich von innen an den festgeriegelten Türflügel, so daß sein Leib nur zur Hälfte und darüber der seitlich geneigte Kopf zu sehen war, mit dem er zu den anderen hinüberlugte. Es war inzwischen viel heller geworden; klar stand auf der anderen Straßenseite ein Ausschnitt des gegenüberliegenden, endlosen, grauschwarzen Hauses -- es war ein Krankenhaus -- mit seinen hart die Front durchbrechenden regelmäßigen Fenstern; der Regen fiel noch nieder, aber nur mit großen, einzeln sichtbaren und förmlich auch einzelnweise auf die Erde hinuntergeworfenen Tropfen. Das Frühstücksgeschirr stand in überreicher Zahl auf dem Tisch, denn für den Vater war das Frühstück die wichtigste Mahlzeit des Tages, die er bei der Lektüre verschiedener Zeitungen stundenlang hinzog. Gerade an der gegenüberliegenden Wand hing eine Photographie Gregors aus seiner Militärzeit, die ihn als Leutnant darstellte, wie er, die Hand am Degen, sorglos lächelnd, Respekt für seine Haltung und Uniform verlangte. Die Tür zum Vorzimmer war geöffnet, und man sah, da auch die Wohnungstür offen war, auf den Vorplatz der Wohnung hinaus und auf den Beginn der abwärts führenden Treppe. »Nun,« sagte Gregor und war sich dessen wohl bewußt, daß er der einzige war, der die Ruhe bewahrt hatte, »ich werde mich gleich anziehen, die Kollektion zusammenpacken und wegfahren. Wollt ihr, wollt ihr mich wegfahren lassen? Nun, Herr Prokurist, Sie sehen, ich bin nicht starrköpfig und ich arbeite gern; das Reisen ist beschwerlich, aber ich könnte ohne das Reisen nicht leben. Wohin gehen Sie denn, Herr Prokurist? Ins Geschäft? Ja? Werden Sie alles wahrheitsgetreu berichten? Man kann im Augenblick unfähig sein zu arbeiten, aber dann ist gerade der richtige Zeitpunkt, sich an die früheren Leistungen zu erinnern und zu bedenken, daß man später, nach Beseitigung des Hindernisses, gewiß desto fleißiger und gesammelter arbeiten wird. Ich bin ja dem Herrn Chef so sehr verpflichtet, das wissen Sie doch recht gut. Andererseits habe ich die Sorge um meine Eltern und die Schwester. Ich bin in der Klemme, ich werde mich aber auch wieder herausarbeiten. Machen Sie es mir aber nicht schwieriger, als es schon ist. Halten Sie im Geschäft meine Partei! Man liebt den Reisenden nicht, ich weiß. Man denkt, er verdient ein Heidengeld und führt dabei ein schönes Leben. Man hat eben keine besondere Veranlassung, dieses Vorurteil besser zu durchdenken. Sie aber, Herr Prokurist, Sie haben einen besseren Überblick über die Verhältnisse, als das sonstige Personal, ja sogar, ganz im Vertrauen gesagt, einen besseren Überblick, als der Herr Chef selbst, der in seiner Eigenschaft als Unternehmer sich in seinem Urteil leicht zuungunsten eines Angestellten beirren läßt. Sie wissen auch sehr wohl, daß der Reisende, der fast das ganze Jahr außerhalb des Geschäftes ist, so leicht ein Opfer von Klatschereien, Zufälligkeiten und grundlosen Beschwerden werden kann, gegen die sich zu wehren ihm ganz unmöglich ist, da er von ihnen meistens gar nichts erfährt und nur dann, wenn er erschöpft eine Reise beendet hat, zu Hause die schlimmen, auf ihre Ursachen hin nicht mehr zu durchschauenden Folgen am eigenen Leibe zu spüren bekommt. Herr Prokurist, gehen Sie nicht weg, ohne mir ein Wort gesagt zu haben, das mir zeigt, daß Sie mir wenigstens zu einem kleinen Teil recht geben!« Aber der Prokurist hatte sich schon bei den ersten Worten Gregors abgewendet, und nur über die zuckende Schulter hinweg sah er mit aufgeworfenen Lippen nach Gregor zurück. Und während Gregors Rede stand er keinen Augenblick still, sondern verzog sich, ohne Gregor aus den Augen zu lassen, gegen die Tür, aber ganz allmählich, als bestehe ein geheimes Verbot, das Zimmer zu verlassen. Schon war er im Vorzimmer, und nach der plötzlichen Bewegung, mit der er zum letztenmal den Fuß aus dem Wohnzimmer zog, hätte man glauben können, er habe sich soeben die Sohle verbrannt. Im Vorzimmer aber streckte er die rechte Hand weit von sich zur Treppe hin, als warte dort auf ihn eine geradezu überirdische Erlösung. Gregor sah ein, daß er den Prokuristen in dieser Stimmung auf keinen Fall weggehen lassen dürfe, wenn dadurch seine Stellung im Geschäft nicht aufs äußerste gefährdet werden sollte. Die Eltern verstanden das alles nicht so gut; sie hatten sich in den langen Jahren die Überzeugung gebildet, daß Gregor in diesem Geschäft für sein Leben versorgt war, und hatten außerdem jetzt mit den augenblicklichen Sorgen so viel zu tun, daß ihnen jede Voraussicht abhanden gekommen war. Aber Gregor hatte diese Voraussicht. Der Prokurist mußte gehalten, beruhigt, überzeugt und schließlich gewonnen werden; die Zukunft Gregors und seiner Familie hing doch davon ab! Wäre doch die Schwester hier gewesen! Sie war klug; sie hatte schon geweint, als Gregor noch ruhig auf dem Rücken lag. Und gewiß hätte der Prokurist, dieser Damenfreund, sich von ihr lenken lassen; sie hätte die Wohnungstür zugemacht und ihm im Vorzimmer den Schrecken ausgeredet. Aber die Schwester war eben nicht da, Gregor selbst mußte handeln. Und ohne daran zu denken, daß er seine gegenwärtigen Fähigkeiten, sich zu bewegen, noch gar nicht kannte, ohne auch daran zu denken, daß seine Rede möglicher- ja wahrscheinlicherweise wieder nicht verstanden worden war, verließ er den Türflügel; schob sich durch die Öffnung; wollte zum Prokuristen hingehen, der sich schon am Geländer des Vorplatzes lächerlicherweise mit beiden Händen festhielt; fiel aber sofort, nach einem Halt suchend, mit einem kleinen Schrei auf seine vielen Beinchen nieder. Kaum war das geschehen, fühlte er zum erstenmal an diesem Morgen ein körperliches Wohlbehagen; die Beinchen hatten festen Boden unter sich; sie gehorchten vollkommen, wie er zu seiner Freude merkte; strebten sogar darnach, ihn fortzutragen, wohin er wollte; und schon glaubte er, die endgültige Besserung alles Leidens stehe unmittelbar bevor. Aber im gleichen Augenblick, als er da schaukelnd vor verhaltener Bewegung, gar nicht weit von seiner Mutter entfernt, ihr gerade gegenüber auf dem Boden lag, sprang diese, die doch so ganz in sich versunken schien, mit einemmale in die Höhe, die Arme weit ausgestreckt, die Finger gespreizt, rief: »Hilfe, um Gottes willen Hilfe!«, hielt den Kopf geneigt, als wolle sie Gregor besser sehen, lief aber, im Widerspruch dazu, sinnlos zurück; hatte vergessen, daß hinter ihr der gedeckte Tisch stand; setzte sich, als sie bei ihm angekommen war, wie in Zerstreutheit, eilig auf ihn, und schien gar nicht zu merken, daß neben ihr aus der umgeworfenen großen Kanne der Kaffee in vollem Strome auf den Teppich sich ergoß. »Mutter, Mutter,« sagte Gregor leise und sah zu ihr hinauf. Der Prokurist war ihm für einen Augenblick ganz aus dem Sinn gekommen; dagegen konnte er sich nicht versagen, im Anblick des fließenden Kaffees mehrmals mit den Kiefern ins Leere zu schnappen. Darüber schrie die Mutter neuerdings auf, flüchtete vom Tisch und fiel dem ihr entgegeneilenden Vater in die Arme. Aber Gregor hatte jetzt keine Zeit für seine Eltern; der Prokurist war schon auf der Treppe; das Kinn auf dem Geländer, sah er noch zum letzten Male zurück. Gregor nahm einen Anlauf, um ihn möglichst sicher einzuholen; der Prokurist mußte etwas ahnen, denn er machte einen Sprung über mehrere Stufen und verschwand; »Huh!« aber schrie er noch, es klang durchs ganze Treppenhaus. Leider schien nun auch diese Flucht des Prokuristen den Vater, der bisher verhältnismäßig gefaßt gewesen war, völlig zu verwirren, denn statt selbst dem Prokuristen nachzulaufen oder wenigstens Gregor in der Verfolgung nicht zu hindern, packte er mit der Rechten den Stock des Prokuristen, den dieser mit Hut und Überzieher auf einem Sessel zurückgelassen hatte, holte mit der Linken eine große Zeitung vom Tisch und machte sich unter Füßestampfen daran, Gregor durch Schwenken des Stockes und der Zeitung in sein Zimmer zurückzutreiben. Kein Bitten Gregors half, kein Bitten wurde auch verstanden, er mochte den Kopf noch so demütig drehen, der Vater stampfte nur stärker mit den Füßen. Drüben hatte die Mutter trotz des kühlen Wetters ein Fenster aufgerissen, und hinausgelehnt drückte sie ihr Gesicht weit außerhalb des Fensters in ihre Hände. Zwischen Gasse und Treppenhaus entstand eine starke Zugluft, die Fenstervorhänge flogen auf, die Zeitungen auf dem Tische rauschten, einzelne Blätter wehten über den Boden hin. Unerbittlich drängte der Vater und stieß Zischlaute aus, wie ein Wilder. Nun hatte aber Gregor noch gar keine Übung im Rückwärtsgehen, es ging wirklich sehr langsam. Wenn sich Gregor nur hätte umdrehen dürfen, er wäre gleich in seinem Zimmer gewesen, aber er fürchtete sich, den Vater durch die zeitraubende Umdrehung ungeduldig zu machen, und jeden Augenblick drohte ihm doch von dem Stock in des Vaters Hand der tödliche Schlag auf den Rücken oder auf den Kopf. Endlich aber blieb Gregor doch nichts anderes übrig, denn er merkte mit Entsetzen, daß er im Rückwärtsgehen nicht einmal die Richtung einzuhalten verstand; und so begann er, unter unaufhörlichen ängstlichen Seitenblicken nach dem Vater, sich nach Möglichkeit rasch, in Wirklichkeit aber doch nur sehr langsam umzudrehen. Vielleicht merkte der Vater seinen guten Willen, denn er störte ihn hierbei nicht, sondern dirigierte sogar hie und da die Drehbewegung von der Ferne mit der Spitze seines Stockes. Wenn nur nicht dieses unerträgliche Zischen des Vaters gewesen wäre! Gregor verlor darüber ganz den Kopf. Er war schon fast ganz umgedreht, als er sich, immer auf dieses Zischen horchend, sogar irrte und sich wieder ein Stück zurückdrehte. Als er aber endlich glücklich mit dem Kopf vor der Türöffnung war, zeigte es sich, daß sein Körper zu breit war, um ohne weiteres durchzukommen. Dem Vater fiel es natürlich in seiner gegenwärtigen Verfassung auch nicht entfernt ein, etwa den anderen Türflügel zu öffnen, um für Gregor einen genügenden Durchgang zu schaffen. Seine fixe Idee war bloß, daß Gregor so rasch als möglich in sein Zimmer müsse. Niemals hätte er auch die umständlichen Vorbereitungen gestattet, die Gregor brauchte, um sich aufzurichten und vielleicht auf diese Weise durch die Tür zu kommen. Vielleicht trieb er, als gäbe es kein Hindernis, Gregor jetzt unter besonderem Lärm vorwärts; es klang schon hinter Gregor gar nicht mehr wie die Stimme bloß eines einzigen Vaters; nun gab es wirklich keinen Spaß mehr, und Gregor drängte sich -- geschehe was wolle -- in die Tür. Die eine Seite seines Körpers hob sich, er lag schief in der Türöffnung, seine eine Flanke war ganz wundgerieben, an der weißen Tür blieben häßliche Flecke, bald steckte er fest und hätte sich allein nicht mehr rühren können, die Beinchen auf der einen Seite hingen zitternd oben in der Luft, die auf der anderen waren schmerzhaft zu Boden gedrückt -- da gab ihm der Vater von hinten einen jetzt wahrhaftig erlösenden starken Stoß, und er flog, heftig blutend, weit in sein Zimmer hinein. Die Tür wurde noch mit dem Stock zugeschlagen, dann war es endlich still. II. Erst in der Abenddämmerung erwachte Gregor aus seinem schweren ohnmachtähnlichen Schlaf. Er wäre gewiß nicht viel später auch ohne Störung erwacht, denn er fühlte sich genügend ausgeruht und ausgeschlafen, doch schien es ihm, als hätte ihn ein flüchtiger Schritt und ein vorsichtiges Schließen der zum Vorzimmer führenden Tür geweckt. Der Schein der elektrischen Straßenbahn lag bleich hier und da auf der Zimmerdecke und auf den höheren Teilen der Möbel, aber unten bei Gregor war es finster. Langsam schob er sich, noch ungeschickt mit seinen Fühlern tastend, die er jetzt erst schätzen lernte, zur Türe hin, um nachzusehen, was dort geschehen war. Seine linke Seite schien eine einzige lange, unangenehm spannende Narbe, und er mußte auf seinen zwei Beinreihen regelrecht hinken. Ein Beinchen war übrigens im Laufe der vormittägigen Vorfälle schwer verletzt worden -- es war fast ein Wunder, daß nur eines verletzt worden war -- und schleppte leblos nach. Erst bei der Tür merkte er, was ihn dorthin eigentlich gelockt hatte; es war der Geruch von etwas Eßbarem gewesen. Denn dort stand ein Napf mit süßer Milch gefüllt, in der kleine Schnitte von Weißbrot schwammen. Fast hätte er vor Freude gelacht, denn er hatte noch größeren Hunger als am Morgen, und gleich tauchte er seinen Kopf fast bis über die Augen in die Milch hinein. Aber bald zog er ihn enttäuscht wieder zurück; nicht nur, daß ihm das Essen wegen seiner heiklen linken Seite Schwierigkeiten machte -- und er konnte nur essen, wenn der ganze Körper schnaufend mitarbeitete --, so schmeckte ihm überdies die Milch, die sonst sein Lieblingsgetränk war und die ihm gewiß die Schwester deshalb hereingestellt hatte, gar nicht, ja er wandte sich fast mit Widerwillen von dem Napf ab und kroch in die Zimmermitte zurück. Im Wohnzimmer war, wie Gregor durch die Türspalte sah, das Gas angezündet, aber während sonst zu dieser Tageszeit der Vater seine nachmittags erscheinende Zeitung der Mutter und manchmal auch der Schwester mit erhobener Stimme vorzulesen pflegte, hörte man jetzt keinen Laut. Nun vielleicht war dieses Vorlesen, von dem ihm die Schwester immer erzählte und schrieb, in der letzten Zeit überhaupt aus der Übung gekommen. Aber auch ringsherum war es so still, trotzdem doch gewiß die Wohnung nicht leer war. »Was für ein stilles Leben die Familie doch führte,« sagte sich Gregor und fühlte, während er starr vor sich ins Dunkle sah, einen großen Stolz darüber, daß er seinen Eltern und seiner Schwester ein solches Leben in einer so schönen Wohnung hatte verschaffen können. Wie aber, wenn jetzt alle Ruhe, aller Wohlstand, alle Zufriedenheit ein Ende mit Schrecken nehmen sollte? Um sich nicht in solche Gedanken zu verlieren, setzte sich Gregor lieber in Bewegung und kroch im Zimmer auf und ab. Einmal während des langen Abends wurde die eine Seitentüre und einmal die andere bis zu einer kleinen Spalte geöffnet und rasch wieder geschlossen; jemand hatte wohl das Bedürfnis hereinzukommen, aber auch wieder zu viele Bedenken. Gregor machte nun unmittelbar bei der Wohnzimmertür Halt, entschlossen, den zögernden Besucher doch irgendwie hereinzubringen oder doch wenigstens zu erfahren, wer es sei; aber nun wurde die Tür nicht mehr geöffnet und Gregor wartete vergebens. Früh, als die Türen versperrt waren, hatten alle zu ihm hereinkommen wollen, jetzt, da er die eine Tür geöffnet hatte und die anderen offenbar während des Tages geöffnet worden waren, kam keiner mehr, und die Schlüssel steckten nun auch von außen. Spät erst in der Nacht wurde das Licht im Wohnzimmer ausgelöscht, und nun war leicht festzustellen, daß die Eltern und die Schwester so lange wachgeblieben waren, denn wie man genau hören konnte, entfernten sich jetzt alle drei auf den Fußspitzen. Nun kam gewiß bis zum Morgen niemand mehr zu Gregor herein; er hatte also eine lange Zeit, um ungestört zu überlegen, wie er sein Leben jetzt neu ordnen sollte. Aber das hohe freie Zimmer, in dem er gezwungen war, flach auf dem Boden zu liegen, ängstigte ihn, ohne daß er die Ursache herausfinden konnte, denn es war ja sein seit fünf Jahren von ihm bewohntes Zimmer -- und mit einer halb unbewußten Wendung und nicht ohne eine leichte Scham eilte er unter das Kanapee, wo er sich, trotzdem sein Rücken ein wenig gedrückt wurde und trotzdem er den Kopf nicht mehr erheben konnte, gleich sehr behaglich fühlte und nur bedauerte, daß sein Körper zu breit war, um vollständig unter dem Kanapee untergebracht zu werden. Dort blieb er die ganze Nacht, die er zum Teil im Halbschlaf, aus dem ihn der Hunger immer wieder aufschreckte, verbrachte, zum Teil aber in Sorgen und undeutlichen Hoffnungen, die aber alle zu dem Schlusse führten, daß er sich vorläufig ruhig verhalten und durch Geduld und größte Rücksichtnahme der Familie die Unannehmlichkeiten erträglich machen müsse, die er ihr in seinem gegenwärtigen Zustand nun einmal zu verursachen gezwungen war. Schon am frühen Morgen, es war fast noch Nacht, hatte Gregor Gelegenheit, die Kraft seiner eben gefaßten Entschlüsse zu prüfen, denn vom Vorzimmer her öffnete die Schwester, fast völlig angezogen, die Tür und sah mit Spannung herein. Sie fand ihn nicht gleich, aber als sie ihn unter dem Kanapee bemerkte -- Gott, er mußte doch irgendwo sein, er hatte doch nicht wegfliegen können -- erschrak sie so sehr, daß sie, ohne sich beherrschen zu können, die Tür von außen wieder zuschlug. Aber als bereue sie ihr Benehmen, öffnete sie die Tür sofort wieder und trat, als sei sie bei einem Schwerkranken oder gar bei einem Fremden, auf den Fußspitzen herein. Gregor hatte den Kopf bis knapp zum Rande des Kanapees vorgeschoben und beobachtete sie. Ob sie wohl bemerken würde, daß er die Milch stehen gelassen hatte, und zwar keineswegs aus Mangel an Hunger, und ob sie eine andere Speise hereinbringen würde, die ihm besser entsprach? Täte sie es nicht von selbst, er wollte lieber verhungern, als sie darauf aufmerksam machen, trotzdem es ihn eigentlich ungeheuer drängte, unterm Kanapee vorzuschießen, sich der Schwester zu Füßen zu werfen und sie um irgend etwas Gutes zum Essen zu bitten. Aber die Schwester bemerkte sofort mit Verwunderung den noch vollen Napf, aus dem nur ein wenig Milch ringsherum verschüttet war, sie hob ihn gleich auf, zwar nicht mit den bloßen Händen, sondern mit einem Fetzen, und trug ihn hinaus. Gregor war äußerst neugierig, was sie zum Ersatze bringen würde, und er machte sich die verschiedensten Gedanken darüber. Niemals aber hätte er erraten können, was die Schwester in ihrer Güte wirklich tat. Sie brachte ihm, um seinen Geschmack zu prüfen, eine ganze Auswahl, alles auf einer alten Zeitung ausgebreitet. Da war altes halbverfaultes Gemüse; Knochen vom Nachtmahl her, die von festgewordener weißer Sauce umgeben waren; ein paar Rosinen und Mandeln; ein Käse, den Gregor vor zwei Tagen für ungenießbar erklärt hatte; ein trockenes Brot, ein mit Butter beschmiertes Brot und ein mit Butter beschmiertes und gesalzenes Brot. Außerdem stellte sie zu dem allen noch den wahrscheinlich ein für allemal für Gregor bestimmten Napf, in den sie Wasser gegossen hatte. Und aus Zartgefühl, da sie wußte, daß Gregor vor ihr nicht essen würde, entfernte sie sich eiligst und drehte sogar den Schlüssel um, damit nur Gregor merken könne, daß er es sich so behaglich machen dürfe, wie er wolle. Gregors Beinchen schwirrten, als es jetzt zum Essen ging. Seine Wunden mußten übrigens auch schon vollständig geheilt sein, er fühlte keine Behinderung mehr, er staunte darüber und dachte daran, wie er vor mehr als einem Monat sich mit dem Messer ganz wenig in den Finger geschnitten, und wie ihm diese Wunde noch vorgestern genug wehgetan hatte. »Sollte ich jetzt weniger Feingefühl haben?« dachte er und saugte schon gierig an dem Käse, zu dem es ihn vor allen anderen Speisen sofort und nachdrücklich gezogen hatte. Rasch hintereinander und mit vor Befriedigung tränenden Augen verzehrte er den Käse, das Gemüse und die Sauce; die frischen Speisen dagegen schmeckten ihm nicht, er konnte nicht einmal ihren Geruch vertragen und schleppte sogar die Sachen, die er essen wollte, ein Stückchen weiter weg. Er war schon längst mit allem fertig und lag nur noch faul auf der gleichen Stelle, als die Schwester zum Zeichen, daß er sich zurückziehen solle, langsam den Schlüssel umdrehte. Das schreckte ihn sofort auf, trotzdem er schon fast schlummerte, und er eilte wieder unter das Kanapee. Aber es kostete ihn große Selbstüberwindung, auch nur die kurze Zeit, während welcher die Schwester im Zimmer war, unter dem Kanapee zu bleiben, denn von dem reichlichen Essen hatte sich sein Leib ein wenig gerundet, und er konnte dort in der Enge kaum atmen. Unter kleinen Erstickungsanfällen sah er mit etwas hervorgequollenen Augen zu, wie die nichtsahnende Schwester mit einem Besen nicht nur die Überbleibsel zusammenkehrte, sondern selbst die von Gregor gar nicht berührten Speisen, als seien also auch diese nicht mehr zu gebrauchen, und wie sie alles hastig in einen Kübel schüttete, den sie mit einem Holzdeckel schloß, worauf sie alles hinaustrug. Kaum hatte sie sich umgedreht, zog sich schon Gregor unter dem Kanapee hervor und streckte und blähte sich. Auf diese Weise bekam nun Gregor täglich sein Essen, einmal am Morgen, wenn die Eltern und das Dienstmädchen noch schliefen, das zweitemal nach dem allgemeinen Mittagessen, denn dann schliefen die Eltern gleichfalls noch ein Weilchen, und das Dienstmädchen wurde von der Schwester mit irgendeiner Besorgung weggeschickt. Gewiß wollten auch sie nicht, daß Gregor verhungere, aber vielleicht hätten sie es nicht ertragen können, von seinem Essen mehr als durch Hörensagen zu erfahren, vielleicht wollte die Schwester ihnen auch eine möglicherweise nur kleine Trauer ersparen, denn tatsächlich litten sie ja gerade genug. Mit welchen Ausreden man an jenem ersten Vormittag den Arzt und den Schlosser wieder aus der Wohnung geschafft hatte, konnte Gregor gar nicht erfahren, denn da er nicht verstanden wurde, dachte niemand daran, auch die Schwester nicht, daß er die anderen verstehen könne, und so mußte er sich, wenn die Schwester in seinem Zimmer war, damit begnügen, nur hier und da ihre Seufzer und Anrufe der Heiligen zu hören. Erst später, als sie sich ein wenig an alles gewöhnt hatte -- von vollständiger Gewöhnung konnte natürlich niemals die Rede sein --, erhaschte Gregor manchmal eine Bemerkung, die freundlich gemeint war oder so gedeutet werden konnte. »Heute hat es ihm aber geschmeckt,« sagte sie, wenn Gregor unter dem Essen tüchtig aufgeräumt hatte, während sie im gegenteiligen Fall, der sich allmählich immer häufiger wiederholte, fast traurig zu sagen pflegte: »Nun ist wieder alles stehengeblieben.« Während aber Gregor unmittelbar keine Neuigkeit erfahren konnte, erhorchte er manches aus den Nebenzimmern, und wo er nun einmal Stimmen hörte, lief er gleich zu der betreffenden Tür und drückte sich mit ganzem Leib an sie. Besonders in der ersten Zeit gab es kein Gespräch, das nicht irgendwie wenn auch nur im geheimen, von ihm handelte. Zwei Tage lang waren bei allen Mahlzeiten Beratungen darüber zu hören, wie man sich jetzt verhalten solle; aber auch zwischen den Mahlzeiten sprach man über das gleiche Thema, denn immer waren zumindest zwei Familienmitglieder zu Hause, da wohl niemand allein zu Hause bleiben wollte und man die Wohnung doch auf keinen Fall gänzlich verlassen konnte. Auch hatte das Dienstmädchen gleich am ersten Tag -- es war nicht ganz klar, was und wieviel sie von dem Vorgefallenen wußte -- kniefällig die Mutter gebeten, sie sofort zu entlassen, und als sie sich eine Viertelstunde danach verabschiedete, dankte sie für die Entlassung unter Tränen, wie für die größte Wohltat, die man ihr hier erwiesen hatte, und gab, ohne daß man es von ihr verlangte, einen fürchterlichen Schwur ab, niemandem auch nur das geringste zu verraten. Nun mußte die Schwester im Verein mit der Mutter auch kochen; allerdings machte das nicht viel Mühe, denn man aß fast nichts. Immer wieder hörte Gregor, wie der eine den anderen vergebens zum Essen aufforderte und keine andere Antwort bekam, als: »Danke ich habe genug« oder etwas Ähnliches. Getrunken wurde vielleicht auch nichts. Öfters fragte die Schwester den Vater, ob er Bier haben wolle, und herzlich erbot sie sich, es selbst zu holen, und als der Vater schwieg, sagte sie, um ihm jedes Bedenken zu nehmen, sie könne auch die Hausmeisterin darum schicken, aber dann sagte der Vater schließlich ein großes »Nein«, und es wurde nicht mehr davon gesprochen. Schon im Laufe des ersten Tages legte der Vater die ganzen Vermögensverhältnisse und Aussichten sowohl der Mutter als auch der Schwester dar. Hie und da stand er vom Tische auf und holte aus seiner kleinen Wertheimkassa, die er aus dem vor fünf Jahren erfolgten Zusammenbruch seines Geschäftes gerettet hatte, irgendeinen Beleg oder irgendein Vormerkbuch. Man hörte, wie er das komplizierte Schloß aufsperrte und nach Entnahme des Gesuchten wieder verschloß. Diese Erklärungen des Vaters waren zum Teil das erste Erfreuliche, was Gregor seit seiner Gefangenschaft zu hören bekam. Er war der Meinung gewesen, daß dem Vater von jenem Geschäft her nicht das Geringste übriggeblieben war, zumindest hatte ihm der Vater nichts Gegenteiliges gesagt, und Gregor allerdings hatte ihn auch nicht darum gefragt. Gregors Sorge war damals nur gewesen, alles daranzusetzen, um die Familie das geschäftliche Unglück, das alle in eine vollständige Hoffnungslosigkeit gebracht hatte, möglichst rasch vergessen zu lassen. Und so hatte er damals mit ganz besonderem Feuer zu arbeiten angefangen und war fast über Nacht aus einem kleinen Kommis ein Reisender geworden, der natürlich ganz andere Möglichkeiten des Geldverdienens hatte, und dessen Arbeitserfolge sich sofort in Form der Provision zu Bargeld verwandelten, das der erstaunten und beglückten Familie zu Hause auf den Tisch gelegt werden konnte. Es waren schöne Zeiten gewesen, und niemals nachher hatten sie sich, wenigstens in diesem Glanze, wiederholt, trotzdem Gregor später so viel Geld verdiente, daß er den Aufwand der ganzen Familie zu tragen imstande war und auch trug. Man hatte sich eben daran gewöhnt, sowohl die Familie, als auch Gregor, man nahm das Geld dankbar an, er lieferte es gern ab, aber eine besondere Wärme wollte sich nicht mehr ergeben. Nur die Schwester war Gregor doch noch nahe geblieben, und es war sein geheimer Plan, sie, die zum Unterschied von Gregor Musik sehr liebte und rührend Violine zu spielen verstand, nächstes Jahr, ohne Rücksicht auf die großen Kosten, die das verursachen mußte, und die man schon auf andere Weise hereinbringen würde, auf das Konservatorium zu schicken. Öfters während der kurzen Aufenthalte Gregors in der Stadt wurde in den Gesprächen mit der Schwester das Konservatorium erwähnt, aber immer nur als schöner Traum, an dessen Verwirklichung nicht zu denken war, und die Eltern hörten nicht einmal diese unschuldigen Erwähnungen gern; aber Gregor dachte sehr bestimmt daran und beabsichtigte, es am Weihnachtsabend feierlich zu erklären. Solche in seinem gegenwärtigen Zustand ganz nutzlose Gedanken gingen ihm durch den Kopf, während er dort aufrecht an der Türe klebte und horchte. Manchmal konnte er vor allgemeiner Müdigkeit gar nicht mehr zuhören und ließ den Kopf nachlässig gegen die Tür schlagen, hielt ihn aber sofort wieder fest, denn selbst das kleine Geräusch, das er damit verursacht hatte, war nebenan gehört worden und hatte alle verstummen lassen. »Was er nur wieder treibt,« sagte der Vater nach einer Weile, offenbar zur Türe hingewendet, und dann erst wurde das unterbrochene Gespräch allmählich wieder aufgenommen. Gregor erfuhr nun zur Genüge -- denn der Vater pflegte sich in seinen Erklärungen öfters zu wiederholen, teils, weil er selbst sich mit diesen Dingen schon lange nicht beschäftigt hatte, teils auch, weil die Mutter nicht alles gleich beim erstenmal verstand --, daß trotz allen Unglücks ein allerdings ganz kleines Vermögen aus der alten Zeit noch vorhanden war, das die nicht angerührten Zinsen in der Zwischenzeit ein wenig hatten anwachsen lassen. Außerdem aber war das Geld, das Gregor allmonatlich nach Hause gebracht hatte -- er selbst hatte nur ein paar Gulden für sich behalten --, nicht vollständig aufgebraucht worden und hatte sich zu einem kleinen Kapital angesammelt. Gregor, hinter seiner Türe, nickte eifrig, erfreut über diese unerwartete Vorsicht und Sparsamkeit. Eigentlich hätte er ja mit diesen überschüssigen Geldern die Schuld des Vaters gegenüber dem Chef weiter abgetragen haben können, und jener Tag, an dem er diesen Posten hätte loswerden können, wäre weit näher gewesen, aber jetzt war es zweifellos besser so, wie es der Vater eingerichtet hatte. Nun genügte dieses Geld aber ganz und gar nicht, um die Familie etwa von den Zinsen leben zu lassen; es genügte vielleicht, um die Familie ein, höchstens zwei Jahre zu erhalten, mehr war es nicht. Es war also bloß eine Summe, die man eigentlich nicht angreifen durfte, und die für den Notfall zurückgelegt werden mußte; das Geld zum Leben aber mußte man verdienen. Nun war aber der Vater ein zwar gesunder, aber alter Mann, der schon fünf Jahre nichts gearbeitet hatte und sich jedenfalls nicht viel zutrauen durfte; er hatte in diesen fünf Jahren, welche die ersten Ferien seines mühevollen und doch erfolglosen Lebens waren, viel Fett angesetzt und war dadurch recht schwerfällig geworden. Und die alte Mutter sollte nun vielleicht Geld verdienen, die an Asthma litt, der eine Wanderung durch die Wohnung schon Anstrengung verursachte, und die jeden zweiten Tag in Atembeschwerden auf dem Sofa beim offenen Fenster verbrachte? Und die Schwester sollte Geld verdienen, die noch ein Kind war mit ihren siebzehn Jahren, und der ihre bisherige Lebensweise so sehr zu gönnen war, die daraus bestanden hatte, sich nett zu kleiden, lange zu schlafen, in der Wirtschaft mitzuhelfen, an ein paar bescheidenen Vergnügungen sich zu beteiligen und vor allem Violine zu spielen? Wenn die Rede auf diese Notwendigkeit des Geldverdienens kam, ließ zuerst immer Gregor die Türe los und warf sich auf das neben der Tür befindliche kühle Ledersofa, denn ihm war ganz heiß vor Beschämung und Trauer. Oft lag er dort die ganzen langen Nächte über, schlief keinen Augenblick und scharrte nur stundenlang auf dem Leder. Oder er scheute nicht die große Mühe, einen Sessel zum Fenster zu schieben, dann die Fensterbrüstung hinaufzukriechen und, in den Sessel gestemmt, sich ans Fenster zu lehnen, offenbar nur in irgendeiner Erinnerung an das Befreiende, das früher für ihn darin gelegen war, aus dem Fenster zu schauen. Denn tatsächlich sah er von Tag zu Tag die auch nur ein wenig entfernten Dinge immer undeutlicher; das gegenüberliegende Krankenhaus, dessen nur allzu häufigen Anblick er früher verflucht hatte, bekam er überhaupt nicht mehr zu Gesicht, und wenn er nicht genau gewußt hätte, daß er in der stillen, aber völlig städtischen Charlottenstraße wohnte, hätte er glauben können, von seinem Fenster aus in eine Einöde zu schauen in welcher der graue Himmel und die graue Erde ununterscheidbar sich vereinigten. Nur zweimal hatte die aufmerksame Schwester sehen müssen, daß der Sessel beim Fenster stand, als sie schon jedesmal, nachdem sie das Zimmer aufgeräumt hatte, den Sessel wieder genau zum Fenster hinschob, ja sogar von nun ab den inneren Fensterflügel offen ließ. Hätte Gregor nur mit der Schwester sprechen und ihr für alles danken können, was sie für ihn machen mußte, er hätte ihre Dienste leichter ertragen; so aber litt er darunter. Die Schwester suchte freilich die Peinlichkeit des Ganzen möglichst zu verwischen, und je längere Zeit verging, desto besser gelang es ihr natürlich auch, aber auch Gregor durchschaute mit der Zeit alles viel genauer. Schon ihr Eintritt war für ihn schrecklich. Kaum war sie eingetreten, lief sie, ohne sich Zeit zu nehmen, die Türe zu schließen, so sehr sie sonst darauf achtete, jedem den Anblick von Gregors Zimmer zu ersparen, geradewegs zum Fenster und riß es, als ersticke sie fast, mit hastigen Händen auf, blieb auch, selbst wenn es noch so kalt war, ein Weilchen beim Fenster und atmete tief. Mit diesem Laufen und Lärmen erschreckte sie Gregor täglich zweimal; die ganze Zeit über zitterte er unter dem Kanapee und wußte doch sehr gut, daß sie ihn gewiß gerne damit verschont hätte, wenn es ihr nur möglich gewesen wäre, sich in einem Zimmer, in dem sich Gregor befand, bei geschlossenem Fenster aufzuhalten. Einmal, es war wohl schon ein Monat seit Gregors Verwandlung vergangen, und es war doch schon für die Schwester kein besonderer Grund mehr, über Gregors Aussehen in Erstaunen zu geraten, kam sie ein wenig früher als sonst und traf Gregor noch an, wie er, unbeweglich und so recht zum Erschrecken aufgestellt, aus dem Fenster schaute. Es wäre für Gregor nicht unerwartet gewesen, wenn sie nicht eingetreten wäre, da er sie durch seine Stellung verhinderte, sofort das Fenster zu öffnen, aber sie trat nicht nur nicht ein, sie fuhr sogar zurück und schloß die Tür; ein Fremder hätte geradezu denken können, Gregor habe ihr aufgelauert und habe sie beißen wollen. Gregor versteckte sich natürlich sofort unter dem Kanapee, aber er mußte bis zum Mittag warten, ehe die Schwester wiederkam, und sie schien viel unruhiger als sonst. Er erkannte daraus, daß ihr sein Anblick noch immer unerträglich war und ihr auch weiterhin unerträglich bleiben müsse, und daß sie sich wohl sehr überwinden mußte, vor dem Anblick auch nur der kleinen Partie seines Körpers nicht davonzulaufen, mit der er unter dem Kanapee hervorragte. Um ihr auch diesen Anblick zu ersparen, trug er eines Tages auf seinem Rücken -- er brauchte zu dieser Arbeit vier Stunden -- das Leintuch auf das Kanapee und ordnete es in einer solchen Weise an, daß er nun gänzlich verdeckt war, und daß die Schwester, selbst wenn sie sich bückte, ihn nicht sehen konnte. Wäre dieses Leintuch ihrer Meinung nach nicht nötig gewesen, dann hätte sie es ja entfernen können, denn daß es nicht zum Vergnügen Gregors gehören konnte, sich so ganz und gar abzusperren, war doch klar genug, aber sie ließ das Leintuch, so wie es war, und Gregor glaubte sogar einen dankbaren Blick erhascht zu haben, als er einmal mit dem Kopf vorsichtig das Leintuch ein wenig lüftete, um nachzusehen, wie die Schwester die neue Einrichtung aufnahm. In den ersten vierzehn Tagen konnten es die Eltern nicht über sich bringen, zu ihm hereinzukommen, und er hörte oft, wie sie die jetzige Arbeit der Schwester völlig anerkannten, während sie sich bisher häufig über die Schwester geärgert hatten, weil sie ihnen als ein etwas nutzloses Mädchen erschienen war. Nun aber warteten oft beide, der Vater und die Mutter, vor Gregors Zimmer, während die Schwester dort aufräumte, und kaum war sie herausgekommen, mußte sie ganz genau erzählen, wie es in dem Zimmer aussah, was Gregor gegessen hatte, wie er sich diesmal benommen hatte, und ob vielleicht eine kleine Besserung zu bemerken war. Die Mutter übrigens wollte verhältnismäßig bald Gregor besuchen, aber der Vater und die Schwester hielten sie zuerst mit Vernunftgründen zurück, denen Gregor sehr aufmerksam zuhörte, und die er vollständig billigte. Später aber mußte man sie mit Gewalt zurückhalten, und wenn sie dann rief: »Laßt mich doch zu Gregor, er ist ja mein unglücklicher Sohn! Begreift ihr es denn nicht, daß ich zu ihm muß?«, dann dachte Gregor, daß es vielleicht doch gut wäre, wenn die Mutter hereinkäme, nicht jeden Tag natürlich, aber vielleicht einmal in der Woche; sie verstand doch alles viel besser als die Schwester, die trotz all ihrem Mute doch nur ein Kind war und im letzten Grunde vielleicht nur aus kindlichem Leichtsinn eine so schwere Aufgabe übernommen hatte. Der Wunsch Gregors, die Mutter zu sehen, ging bald in Erfüllung. Während des Tages wollte Gregor schon aus Rücksicht auf seine Eltern sich nicht beim Fenster zeigen, kriechen konnte er aber auf den paar Quadratmetern des Fußbodens auch nicht viel, das ruhige Liegen ertrug er schon während der Nacht schwer, das Essen machte ihm bald nicht mehr das geringste Vergnügen, und so nahm er zur Zerstreuung die Gewohnheit an, kreuz und quer über Wände und Plafond zu kriechen. Besonders oben an der Decke hing er gern; es war ganz anders, als das Liegen auf dem Fußboden; man atmete freier; ein leichtes Schwingen ging durch den Körper, und in der fast glücklichen Zerstreutheit, in der sich Gregor dort oben befand, konnte es geschehen, daß er zu seiner eigenen Überraschung sich losließ und auf den Boden klatschte. Aber nun hatte er natürlich seinen Körper ganz anders in der Gewalt als früher und beschädigte sich selbst bei einem so großen Falle nicht. Die Schwester nun bemerkte sofort die neue Unterhaltung, die Gregor für sich gefunden hatte -- er hinterließ ja auch beim Kriechen hie und da Spuren seines Klebstoffes --, und da setzte sie es sich in den Kopf, Gregor das Kriechen in größtem Ausmaße zu ermöglichen und die Möbel, die es verhinderten, also vor allem den Kasten und den Schreibtisch, wegzuschaffen. Nun war sie aber nicht imstande, dies allein zu tun; den Vater wagte sie nicht um Hilfe zu bitten; das Dienstmädchen hätte ihr ganz gewiß nicht geholfen, denn dieses etwa sechzehnjährige Mädchen harrte zwar tapfer seit Entlassung der früheren Köchin aus, hatte aber um die Vergünstigung gebeten, die Küche unaufhörlich versperrt halten zu dürfen und nur auf besonderen Anruf öffnen zu müssen; so blieb der Schwester also nichts übrig, als einmal in Abwesenheit des Vaters die Mutter zu holen. Mit Ausrufen erregter Freude kam die Mutter auch heran, verstummte aber an der Tür vor Gregors Zimmer. Zuerst sah natürlich die Schwester nach, ob alles im Zimmer in Ordnung war; dann erst ließ sie die Mutter eintreten. Gregor hatte in größter Eile das Leintuch noch tiefer und mehr in Falten gezogen, das Ganze sah wirklich nur wie ein zufällig über das Kanapee geworfenes Leintuch aus. Gregor unterließ auch diesmal, unter dem Leintuch zu spionieren; er verzichtete darauf, die Mutter schon diesmal zu sehen, und war nur froh, daß sie nun doch gekommen war. »Komm nur, man sieht ihn nicht,« sagte die Schwester, und offenbar führte sie die Mutter an der Hand. Gregor hörte nun, wie die zwei schwachen Frauen den immerhin schweren alten Kasten von seinem Platze rückten, und wie die Schwester immerfort den größten Teil der Arbeit für sich beanspruchte, ohne auf die Warnungen der Mutter zu hören, welche fürchtete, daß sie sich überanstrengen werde. Es dauerte sehr lange. Wohl nach schon viertelstündiger Arbeit sagte die Mutter, man solle den Kasten doch lieber hier lassen, denn erstens sei er zu schwer, sie würden vor Ankunft des Vaters nicht fertig werden und mit dem Kasten in der Mitte des Zimmers Gregor jeden Weg verrammeln, zweitens aber sei es doch gar nicht sicher, daß Gregor mit der Entfernung der Möbel ein Gefallen geschehe. Ihr scheine das Gegenteil der Fall zu sein; ihr bedrücke der Anblick der leeren Wand geradezu das Herz; und warum solle nicht auch Gregor diese Empfindung haben, da er doch an die Zimmermöbel längst gewöhnt sei und sich deshalb im leeren Zimmer verlassen fühlen werde. »Und ist es dann nicht so,« schloß die Mutter ganz leise, wie sie überhaupt fast flüsterte, als wolle sie vermeiden, daß Gregor, dessen genauen Aufenthalt sie ja nicht kannte, auch nur den Klang der Stimme höre, denn daß er die Worte nicht verstand, davon war sie überzeugt, »und ist es nicht so, als ob wir durch die Entfernung der Möbel zeigten, daß wir jede Hoffnung auf Besserung aufgeben und ihn rücksichtslos sich selbst überlassen? Ich glaube, es wäre das beste, wir suchen das Zimmer genau in dem Zustand zu erhalten, in dem es früher war, damit Gregor, wenn er wieder zu uns zurückkommt, alles unverändert findet und um so leichter die Zwischenzeit vergessen kann.« Beim Anhören dieser Worte der Mutter erkannte Gregor, daß der Mangel jeder unmittelbaren menschlichen Ansprache, verbunden mit dem einförmigen Leben inmitten der Familie, im Laufe dieser zwei Monate seinen Verstand hatte verwirren müssen, denn anders konnte er es sich nicht erklären, daß er ernsthaft darnach hatte verlangen können, daß sein Zimmer ausgeleert würde. Hatte er wirklich Lust, das warme, mit ererbten Möbeln gemütlich ausgestattete Zimmer in eine Höhle verwandeln zu lassen, in der er dann freilich nach allen Richtungen ungestört würde kriechen können, jedoch auch unter gleichzeitigem, schnellen, gänzlichen Vergessen seiner menschlichen Vergangenheit? War er doch jetzt schon nahe daran, zu vergessen, und nur die seit langem nicht gehörte Stimme der Mutter hatte ihn aufgerüttelt. Nichts sollte entfernt werden, alles mußte bleiben, die guten Einwirkungen der Möbel auf seinen Zustand konnte er nicht entbehren; und wenn die Möbel ihn hinderten, das sinnlose Herumkriechen zu betreiben, so war es kein Schaden, sondern ein großer Vorteil. Aber die Schwester war leider anderer Meinung; sie hatte sich, allerdings nicht ganz unberechtigt, angewöhnt, bei Besprechung der Angelegenheiten Gregors als besonders Sachverständige gegenüber den Eltern aufzutreten, und so war auch jetzt der Rat der Mutter für die Schwester Grund genug, auf der Entfernung nicht nur des Kastens und des Schreibtisches, an die sie zuerst allein gedacht hatte, sondern auf der Entfernung sämtlicher Möbel, mit Ausnahme des unentbehrlichen Kanapees, zu bestehen. Es war natürlich nicht nur kindlicher Trotz und das in der letzten Zeit so unerwartet und schwer erworbene Selbstvertrauen, das sie zu dieser Forderung bestimmte; sie hatte doch auch tatsächlich beobachtet, daß Gregor viel Raum zum Kriechen brauchte, dagegen die Möbel, soweit man sehen konnte, nicht im geringsten benützte. Vielleicht aber spielte auch der schwärmerische Sinn der Mädchen ihres Alters mit, der bei jeder Gelegenheit seine Befriedigung sucht, und durch den Grete jetzt sich dazu verlocken ließ, die Lage Gregors noch schreckenerregender machen zu wollen, um dann noch mehr als bis jetzt für ihn leisten zu können. Denn in einem Raum, in dem Gregor ganz allein die leeren Wände beherrschte, würde wohl kein Mensch außer Grete jemals einzutreten sich getrauen. Und so ließ sie sich von ihrem Entschlusse durch die Mutter nicht abbringen, die auch in diesem Zimmer vor lauter Unruhe unsicher schien, bald verstummte und der Schwester nach Kräften beim Hinausschaffen des Kastens half. Nun, den Kasten konnte Gregor im Notfall noch entbehren, aber schon der Schreibtisch mußte bleiben. Und kaum hatten die Frauen mit dem Kasten, an dem sie sich ächzend drückten, das Zimmer verlassen, als Gregor den Kopf unter dem Kanapee hervorstieß, um zu sehen, wie er vorsichtig und möglichst rücksichtsvoll eingreifen könnte. Aber zum Unglück war es gerade die Mutter, welche zuerst zurückkehrte, während Grete im Nebenzimmer den Kasten umfangen hielt und ihn allein hin und her schwang, ohne ihn natürlich von der Stelle zu bringen. Die Mutter aber war Gregors Anblick nicht gewöhnt, er hätte sie krank machen können, und so eilte Gregor erschrocken im Rückwärtslauf bis an das andere Ende des Kanapees, konnte es aber nicht mehr verhindern, daß das Leintuch vorne ein wenig sich bewegte. Das genügte, um die Mutter aufmerksam zu machen. Sie stockte, stand einen Augenblick still und ging dann zu Grete zurück. Trotzdem sich Gregor immer wieder sagte, daß ja nichts Außergewöhnliches geschehe, sondern nur ein paar Möbel umgestellt würden, wirkte doch, wie er sich bald eingestehen mußte, dieses Hin- und Hergehen der Frauen, ihre kleinen Zurufe, das Kratzen der Möbel auf dem Boden, wie ein großer, von allen Seiten genährter Trubel auf ihn, und er mußte sich, so fest er Kopf und Beine an sich zog und den Leib bis an den Boden drückte, unweigerlich sagen, daß er das Ganze nicht lange aushalten werde. Sie räumten ihm sein Zimmer aus; nahmen ihm alles, was ihm lieb war; den Kasten, in dem die Laubsäge und andere Werkzeuge lagen, hatten sie schon hinausgetragen; lockerten jetzt den schon im Boden fest eingegrabenen Schreibtisch, an dem er als Handelsakademiker, als Bürgerschüler, ja sogar schon als Volksschüler seine Aufgaben geschrieben hatte, -- da hatte er wirklich keine Zeit mehr, die guten Absichten zu prüfen, welche die zwei Frauen hatten, deren Existenz er übrigens fast vergessen hatte, denn vor Erschöpfung arbeiteten sie schon stumm, und man hörte nur das schwere Tappen ihrer Füße. Und so brach er denn hervor -- die Frauen stützten sich gerade im Nebenzimmer an den Schreibtisch, um ein wenig zu verschnaufen --, wechselte viermal die Richtung des Laufes, er wußte wirklich nicht, was er zuerst retten sollte, da sah er an der im übrigen schon leeren Wand auffallend das Bild der in lauter Pelzwerk gekleideten Dame hängen, kroch eilends hinauf und preßte sich an das Glas, das ihn festhielt und seinem heißen Bauch wohltat. Dieses Bild wenigstens, das Gregor jetzt ganz verdeckte, würde nun gewiß niemand wegnehmen. Er verdrehte den Kopf nach der Tür des Wohnzimmers, um die Frauen bei ihrer Rückkehr zu beobachten. Sie hatten sich nicht viel Ruhe gegönnt und kamen schon wieder; Grete hatte den Arm um die Mutter gelegt und trug sie fast. »Also was nehmen wir jetzt?« sagte Grete und sah sich um, Da kreuzten sich ihre Blicke mit denen Gregors an der Wand. Wohl nur infolge der Gegenwart der Mutter behielt sie ihre Fassung, beugte ihr Gesicht zur Mutter, um diese vom Herumschauen abzuhalten, und sagte, allerdings zitternd und unüberlegt: »Komm, wollen wir nicht lieber auf einen Augenblick noch ins Wohnzimmer zurückgehen?« Die Absicht Gretes war für Gregor klar, sie wollte die Mutter in Sicherheit bringen und dann ihn von der Wand hinunterjagen. Nun, sie konnte es ja immerhin versuchen! Er saß auf seinem Bild und gab es nicht her. Lieber würde er Grete ins Gesicht springen. Aber Gretes Worte hatten die Mutter erst recht beunruhigt, sie trat zur Seite, erblickte den riesigen braunen Fleck auf der geblümten Tapete, rief, ehe ihr eigentlich zum Bewußtsein kam, daß das Gregor war, was sie sah, mit schreiender, rauher Stimme: »Ach Gott, ach Gott!« und fiel mit ausgebreiteten Armen, als gebe sie alles auf, über das Kanapee hin und rührte sich nicht. »Du, Gregor!« rief die Schwester mit erhobener Faust und eindringlichen Blicken. Es waren seit der Verwandlung die ersten Worte, die sie unmittelbar an ihn gerichtet hatte. Sie lief ins Nebenzimmer, um irgendeine Essenz zu holen, mit der sie die Mutter aus ihrer Ohnmacht wecken könnte; Gregor wollte auch helfen -- zur Rettung des Bildes war noch Zeit --; er klebte aber fest an dem Glas und mußte sich mit Gewalt losreißen; er lief dann auch ins Nebenzimmer, als könne er der Schwester irgendeinen Rat geben, wie in früherer Zeit; mußte aber dann untätig hinter ihr stehen; während sie in verschiedenen Fläschchen kramte, erschreckte sie noch, als sie sich umdrehte; eine Flasche fiel auf den Boden und zerbrach; ein Splitter verletzte Gregor im Gesicht, irgendeine ätzende Medizin umfloß ihn; Grete nahm nun, ohne sich länger aufzuhalten, so viele Fläschchen, als sie nur halten konnte, und rannte mit ihnen zur Mutter hinein; die Tür schlug sie mit dem Fuße zu. Gregor war nun von der Mutter abgeschlossen, die durch seine Schuld vielleicht dem Tode nahe war; die Tür durfte er nicht öffnen, wollte er die Schwester, die bei der Mutter bleiben mußte, nicht verjagen; er hatte jetzt nichts zu tun, als zu warten; und von Selbstvorwürfen und Besorgnis bedrängt, begann er zu kriechen, überkroch alles, Wände, Möbel und Zimmerdecke und fiel endlich in seiner Verzweiflung, als sich das ganze Zimmer schon um ihn zu drehen anfing, mitten auf den großen Tisch. Es verging eine kleine Weile, Gregor lag matt da, ringsherum war es still, vielleicht war das ein gutes Zeichen. Da läutete es. Das Mädchen war natürlich in ihrer Küche eingesperrt und Grete mußte daher öffnen gehen. Der Vater war gekommen. »Was ist geschehen?« waren seine ersten Worte; Gretes Aussehen hatte ihm wohl alles verraten. Grete antwortete mit dumpfer Stimme, offenbar drückte sie ihr Gesicht an des Vaters Brust: »Die Mutter war ohnmächtig, aber es geht ihr schon besser. Gregor ist ausgebrochen.« »Ich habe es ja erwartet,« sagte der Vater, »ich habe es euch ja immer gesagt, aber ihr Frauen wollt nicht hören.« Gregor war es klar, daß der Vater Gretes allzukurze Mitteilung schlecht gedeutet hatte und annahm, daß Gregor sich irgendeine Gewalttat habe zuschulden kommen lassen. Deshalb mußte Gregor den Vater jetzt zu besänftigen suchen, denn ihn aufzuklären hatte er weder Zeit noch Möglichkeit. Und so flüchtete er sich zur Tür seines Zimmers und drückte sich an sie, damit der Vater beim Eintritt vom Vorzimmer her gleich sehen könne, daß Gregor die beste Absicht habe, sofort in sein Zimmer zurückzukehren, und daß es nicht nötig sei, ihn zurückzutreiben, sondern daß man nur die Tür zu öffnen brauchte, und gleich werde er verschwinden. Aber der Vater war nicht in der Stimmung, solche Feinheiten zu bemerken. »Ah!« rief er gleich beim Eintritt in einem Tone, als sei er gleichzeitig wütend und froh. Gregor zog den Kopf von der Tür zurück und hob ihn gegen den Vater. So hatte er sich den Vater wirklich nicht vorgestellt, wie er jetzt dastand; allerdings hatte er in der letzten Zeit über dem neuartigen Herumkriechen versäumt, sich so wie früher um die Vorgänge in der übrigen Wohnung zu kümmern, und hätte eigentlich darauf gefaßt sein müssen, veränderte Verhältnisse anzutreffen. Trotzdem, trotzdem, war das noch der Vater? Der gleiche Mann, der müde im Bett vergraben lag, wenn früher Gregor zu einer Geschäftsreise ausgerückt war; der ihn an Abenden der Heimkehr im Schlafrock im Lehnstuhl empfangen hatte; gar nicht recht imstande war, aufzustehen, sondern zum Zeichen der Freude nur die Arme gehoben hatte, und der bei den seltenen gemeinsamen Spaziergängen an ein paar Sonntagen im Jahr und an den höchsten Feiertagen zwischen Gregor und der Mutter, die schon an und für sich langsam gingen, immer noch ein wenig langsamer, in seinen alten Mantel eingepackt, mit stets vorsichtig aufgesetztem Krückstock sich vorwärts arbeitete und, wenn er etwas sagen wollte, fast immer stillstand und seine Begleitung um sich versammelte? Nun aber war er doch gut aufgerichtet; in eine straffe blaue Uniform mit Goldknöpfen gekleidet, wie sie Diener der Bankinstitute tragen; über dem hohen steifen Kragen des Rockes entwickelte sich sein starkes Doppelkinn; unter den buschigen Augenbrauen drang der Blick der schwarzen Augen frisch und aufmerksam hervor; das sonst zerzauste weiße Haar war zu einer peinlich genauen, leuchtenden Scheitelfrisur niedergekämmt. Er warf seine Mütze, auf der ein Goldmonogramm, wahrscheinlich das einer Bank, angebracht war, über das ganze Zimmer im Bogen auf das Kanapee hin und ging, die Enden seines langen Uniformrockes zurückgeschlagen, die Hände in den Hosentaschen, mit verbissenem Gesicht auf Gregor zu. Er wußte wohl selbst nicht, was er vorhatte; immerhin hob er die Füße ungewöhnlich hoch, und Gregor staunte über die Riesengröße seiner Stiefelsohlen. Doch hielt er sich dabei nicht auf, er wußte ja noch vom ersten Tage seines neuen Lebens her, daß der Vater ihm gegenüber nur die größte Strenge für angebracht ansah. Und so lief er vor dem Vater her, stockte, wenn der Vater stehen blieb, und eilte schon wieder vorwärts, wenn sich der Vater nur rührte. So machten sie mehrmals die Runde um das Zimmer, ohne daß sich etwas Entscheidendes ereignete, ja ohne daß das Ganze infolge seines langsamen Tempos den Anschein einer Verfolgung gehabt hätte. Deshalb blieb auch Gregor vorläufig auf dem Fußboden, zumal er fürchtete, der Vater könnte eine Flucht auf die Wände oder den Plafond für besondere Bosheit halten. Allerdings mußte sich Gregor sagen, daß er sogar dieses Laufen nicht lange aushalten würde, denn während der Vater einen Schritt machte, mußte er eine Unzahl von Bewegungen ausführen. Atemnot begann sich schon bemerkbar zu machen, wie er ja auch in seiner früheren Zeit keine ganz vertrauenswürdige Lunge besessen hatte. Als er nun so dahintorkelte, um alle Kräfte für den Lauf zu sammeln, kaum die Augen offenhielt; in seiner Stumpfheit an eine andere Rettung als durch Laufen gar nicht dachte; und fast schon vergessen hatte, daß ihm die Wände freistanden, die hier allerdings mit sorgfältig geschnitzten Möbeln voll Zacken und Spitzen verstellt waren -- da flog knapp neben ihm, leicht geschleudert, irgend etwas nieder und rollte vor ihm her. Es war ein Apfel; gleich flog ihm ein zweiter nach; Gregor blieb vor Schrecken stehen; ein Weiterlaufen war nutzlos, denn der Vater hatte sich entschlossen, ihn zu bombardieren. Aus der Obstschale auf der Kredenz hatte er sich die Taschen gefüllt und warf nun, ohne vorläufig scharf zu zielen, Apfel für Apfel. Diese kleinen roten Äpfel rollten wie elektrisiert auf dem Boden herum und stießen aneinander. Ein schwach geworfener Apfel streifte Gregors Rücken, glitt aber unschädlich ab. Ein ihm sofort nachfliegender drang dagegen förmlich in Gregors Rücken ein; Gregor wollte sich weiterschleppen, als könne der überraschende unglaubliche Schmerz mit dem Ortswechsel vergehen; doch fühlte er sich wie festgenagelt und streckte sich in vollständiger Verwirrung aller Sinne. Nur mit dem letzten Blick sah er noch, wie die Tür seines Zimmers aufgerissen wurde, und vor der schreienden Schwester die Mutter hervoreilte, im Hemd, denn die Schwester hatte sie entkleidet, um ihr in der Ohnmacht Atemfreiheit zu verschaffen, wie dann die Mutter auf den Vater zulief und ihr auf dem Weg die aufgebundenen Röcke einer nach dem anderen zu Boden glitten, und wie sie stolpernd über die Röcke auf den Vater eindrang und ihn umarmend, in gänzlicher Vereinigung mit ihm -- nun versagte aber Gregors Sehkraft schon -- die Hände an des Vaters Hinterkopf um Schonung von Gregors Leben bat. III. Die schwere Verwundung Gregors, an der er über einen Monat litt -- der Apfel blieb, da ihn niemand zu entfernen wagte, als sichtbares Andenken im Fleische sitzen --, schien selbst den Vater daran erinnert zu haben, daß Gregor trotz seiner gegenwärtigen traurigen und ekelhaften Gestalt ein Familienglied war, das man nicht wie einen Feind behandeln durfte, sondern dem gegenüber es das Gebot der Familienpflicht war, den Widerwillen hinunterzuschlucken und zu dulden, nichts als dulden. Und wenn nun auch Gregor durch seine Wunde an Beweglichkeit wahrscheinlich für immer verloren hatte und vorläufig zur Durchquerung seines Zimmers wie ein alter Invalide lange, lange Minuten brauchte -- an das Kriechen in der Höhe war nicht zu denken --, so bekam er für diese Verschlimmerung seines Zustandes einen seiner Meinung nach vollständig genügenden Ersatz dadurch, daß immer gegen Abend die Wohnzimmertür, die er schon ein bis zwei Stunden vorher scharf zu beobachten pflegte, geöffnet wurde, so daß er, im Dunkel seines Zimmers liegend, vom Wohnzimmer aus unsichtbar, die ganze Familie beim beleuchteten Tische sehen und ihre Reden, gewissermaßen mit allgemeiner Erlaubnis, also ganz anders als früher, anhören durfte. Freilich waren es nicht mehr die lebhaften Unterhaltungen der früheren Zeiten, an die Gregor in den kleinen Hotelzimmern stets mit einigem Verlangen gedacht hatte, wenn er sich müde in das feuchte Bettzeug hatte werfen müssen. Es ging jetzt meist nur sehr still zu. Der Vater schlief bald nach dem Nachtessen in seinem Sessel ein; die Mutter und Schwester ermahnten einander zur Stille; die Mutter nähte, weit über das Licht vorgebeugt, feine Wäsche für ein Modengeschäft; die Schwester, die eine Stellung als Verkäuferin angenommen hatte, lernte am Abend Stenographie und Französisch, um vielleicht später einmal einen besseren Posten zu erreichen. Manchmal wachte der Vater auf, und als wisse er gar nicht, daß er geschlafen habe, sagte er zur Mutter: »Wie lange du heute schon wieder nähst!« und schlief sofort wieder ein, während Mutter und Schwester einander müde zulächelten. Mit einer Art Eigensinn weigerte sich der Vater, auch zu Hause seine Dieneruniform abzulegen; und während der Schlafrock nutzlos am Kleiderhaken hing, schlummerte der Vater vollständig angezogen auf seinem Platz, als sei er immer zu seinem Dienste bereit und warte auch hier auf die Stimme des Vorgesetzten. Infolgedessen verlor die gleich anfangs nicht neue Uniform trotz aller Sorgfalt von Mutter und Schwester an Reinlichkeit, und Gregor sah oft ganze Abende lang auf dieses über und über fleckige, mit seinen stets geputzten Goldknöpfen leuchtende Kleid, in dem der alte Mann höchst unbequem und doch ruhig schlief. Sobald die Uhr zehn schlug, suchte die Mutter durch leise Zusprache den Vater zu wecken und dann zu überreden, ins Bett zu gehen, denn hier war es doch kein richtiger Schlaf und diesen hatte der Vater, der um sechs Uhr seinen Dienst antreten mußte, äußerst nötig. Aber in dem Eigensinn, der ihn, seitdem er Diener war, ergriffen hatte, bestand er immer darauf, noch länger bei Tisch zu bleiben, trotzdem er regelmäßig einschlief, und war dann überdies nur mit der größten Mühe zu bewegen, den Sessel mit dem Bett zu vertauschen. Da mochten Mutter und Schwester mit kleinen Ermahnungen noch so sehr auf ihn eindringen, viertelstundenlang schüttelte er langsam den Kopf, hielt die Augen geschlossen und stand nicht auf. Die Mutter zupfte ihn am Ärmel, sagte ihm Schmeichelworte ins Ohr, die Schwester verließ ihre Aufgabe, um der Mutter zu helfen, aber beim Vater verfing das nicht. Er versank nur noch tiefer in seinen Sessel. Erst bis ihn die Frauen unter den Achseln faßten, schlug er die Augen auf, sah abwechselnd die Mutter und die Schwester an und pflegte zu sagen: »Das ist ein Leben. Das ist die Ruhe meiner alten Tage.« Und auf die beiden Frauen gestützt, erhob er sich, umständlich, als sei er für sich selbst die größte Last, ließ sich von den Frauen bis zur Türe führen, winkte ihnen dort ab und ging nun selbständig weiter, während die Mutter ihr Nähzeug, die Schwester ihre Feder eiligst hinwarfen, um hinter dem Vater zu laufen und ihm weiter behilflich zu sein. Wer hatte in dieser abgearbeiteten und übermüdeten Familie Zeit, sich um Gregor mehr zu kümmern, als unbedingt nötig war? Der Haushalt wurde immer mehr eingeschränkt; das Dienstmädchen wurde nun doch entlassen; eine riesige knochige Bedienerin mit weißem, den Kopf umflatterndem Haar kam des Morgens und des Abends, um die schwerste Arbeit zu leisten; alles andere besorgte die Mutter neben ihrer vielen Näharbeit. Es geschah sogar, daß verschiedene Familienschmuckstücke, welche früher die Mutter und die Schwester überglücklich bei Unterhaltungen und Feierlichkeiten getragen hatten, verkauft wurden, wie Gregor am Abend aus der allgemeinen Besprechung der erzielten Preise erfuhr. Die größte Klage war aber stets, daß man diese für die gegenwärtigen Verhältnisse allzugroße Wohnung nicht verlassen konnte, da es nicht auszudenken war, wie man Gregor übersiedeln sollte. Aber Gregor sah wohl ein, daß es nicht nur die Rücksicht auf ihn war, welche eine Übersiedlung verhinderte, denn ihn hätte man doch in einer passenden Kiste mit ein paar Luftlöchern leicht transportieren können; was die Familie hauptsächlich vom Wohnungswechsel abhielt, war vielmehr die völlige Hoffnungslosigkeit und der Gedanke daran, daß sie mit einem Unglück geschlagen war, wie niemand sonst im ganzen Verwandten- und Bekanntenkreis. Was die Welt von armen Leuten verlangt, erfüllten sie bis zum äußersten, der Vater holte den kleinen Bankbeamten das Frühstück, die Mutter opferte sich für die Wäsche fremder Leute, die Schwester lief nach dem Befehl der Kunden hinter dem Pulte hin und her, aber weiter reichten die Kräfte der Familie schon nicht. Und die Wunde im Rücken fing Gregor wie neu zu schmerzen an, wenn Mutter und Schwester, nachdem sie den Vater zu Bett gebracht hatten, nun zurückkehrten, die Arbeit liegen ließen, nahe zusammenrückten, schon Wange an Wange saßen; wenn jetzt die Mutter, auf Gregors Zimmer zeigend, sagte: »Mach' dort die Tür zu, Grete,« und wenn nun Gregor wieder im Dunkel war, während nebenan die Frauen ihre Tränen vermischten oder gar tränenlos den Tisch anstarrten. Die Nächte und Tage verbrachte Gregor fast ganz ohne Schlaf. Manchmal dachte er daran, beim nächsten Öffnen der Tür die Angelegenheiten der Familie ganz so wie früher wieder in die Hand zu nehmen; in seinen Gedanken erschienen wieder nach langer Zeit der Chef und der Prokurist, die Kommis und die Lehrjungen, der so begriffsstützige Hausknecht, zwei drei Freunde aus anderen Geschäften, ein Stubenmädchen aus einem Hotel in der Provinz, eine liebe, flüchtige Erinnerung, eine Kassiererin aus einem Hutgeschäft, um die er sich ernsthaft, aber zu langsam beworben hatte -- sie alle erschienen untermischt mit Fremden oder schon Vergessenen, aber statt ihm und seiner Familie zu helfen, waren sie sämtlich unzugänglich, und er war froh, wenn sie verschwanden. Dann aber war er wieder gar nicht in der Laune, sich um seine Familie zu sorgen, bloß Wut über die schlechte Wartung erfüllte ihn, und trotzdem er sich nichts vorstellen konnte, worauf er Appetit gehabt hätte, machte er doch Pläne, wie er in die Speisekammer gelangen könnte, um dort zu nehmen, was ihm, auch wenn er keinen Hunger hatte, immerhin gebührte. Ohne jetzt mehr nachzudenken, womit man Gregor einen besonderen Gefallen machen könnte, schob die Schwester eiligst, ehe sie morgens und mittags ins Geschäft lief, mit dem Fuß irgendeine beliebige Speise in Gregors Zimmer hinein, um sie am Abend, gleichgültig dagegen, ob die Speise vielleicht nur gekostet oder -- der häufigste Fall -- gänzlich unberührt war, mit einem Schwenken des Besens hinauszukehren. Das Aufräumen des Zimmers, das sie nun immer abends besorgte, konnte gar nicht mehr schneller getan sein. Schmutzstreifen zogen sich die Wände entlang, hie und da lagen Knäuel von Staub und Unrat. In der ersten Zeit stellte sich Gregor bei der Ankunft der Schwester in derartige besonders bezeichnende Winkel, um ihr durch diese Stellung gewissermaßen einen Vorwurf zu machen. Aber er hätte wohl wochenlang dort bleiben können, ohne daß sich die Schwester gebessert hätte; sie sah ja den Schmutz genau so wie er, aber sie hatte sich eben entschlossen, ihn zu lassen. Dabei wachte sie mit einer an ihr ganz neuen Empfindlichkeit, die überhaupt die ganze Familie ergriffen hatte, darüber, daß das Aufräumen von Gregors Zimmer ihr vorbehalten blieb. Einmal hatte die Mutter Gregors Zimmer einer großen Reinigung unterzogen, die ihr nur nach Verbrauch einiger Kübel Wasser gelungen war -- die viele Feuchtigkeit kränkte allerdings Gregor auch und er lag breit, verbittert und unbeweglich auf dem Kanapee --, aber die Strafe blieb für die Mutter nicht aus. Denn kaum hatte am Abend die Schwester die Veränderung in Gregors Zimmer bemerkt, als sie, aufs höchste beleidigt, ins Wohnzimmer lief und, trotz der beschwörend erhobenen Hände der Mutter, in einen Weinkrampf ausbrach, dem die Eltern -- der Vater war natürlich aus seinem Sessel aufgeschreckt worden -- zuerst erstaunt und hilflos zusahen; bis auch sie sich zu rühren anfingen; der Vater rechts der Mutter Vorwürfe machte, daß sie Gregors Zimmer nicht der Schwester zur Reinigung überließ; links dagegen die Schwester anschrie, sie werde niemals mehr Gregors Zimmer reinigen dürfen; während die Mutter den Vater, der sich vor Erregung nicht mehr kannte, ins Schlafzimmer zu schleppen suchte; die Schwester, von Schluchzen geschüttelt, mit ihren kleinen Fäusten den Tisch bearbeitete; und Gregor laut vor Wut darüber zischte, daß es keinem einfiel, die Tür zu schließen und ihm diesen Anblick und Lärm zu ersparen. Aber selbst wenn die Schwester, erschöpft von ihrer Berufsarbeit, dessen überdrüssig geworden war, für Gregor, wie früher, zu sorgen, so hätte noch keineswegs die Mutter für sie eintreten müssen und Gregor hätte doch nicht vernachlässigt zu werden brauchen. Denn nun war die Bedienerin da. Diese alte Witwe, die in ihrem langen Leben mit Hilfe ihres starken Knochenbaues das Ärgste überstanden haben mochte, hatte keinen eigentlichen Abscheu vor Gregor. Ohne irgendwie neugierig zu sein, hatte sie zufällig einmal die Tür von Gregors Zimmer aufgemacht und war im Anblick Gregors, der, gänzlich überrascht, trotzdem ihn niemand jagte, hin- und herzulaufen begann, die Hände im Schoß gefaltet staunend stehen geblieben. Seitdem versäumte sie nicht, stets flüchtig morgens und abends die Tür ein wenig zu öffnen und zu Gregor hineinzuschauen. Anfangs rief sie ihn auch zu sich herbei, mit Worten, die sie wahrscheinlich für freundlich hielt, wie »Komm mal herüber, alter Mistkäfer!« oder »Seht mal den alten Mistkäfer!« Auf solche Ansprachen antwortete Gregor mit nichts, sondern blieb unbeweglich auf seinem Platz, als sei die Tür gar nicht geöffnet worden. Hätte man doch dieser Bedienerin, statt sie nach ihrer Laune ihn nutzlos stören zu lassen, lieber den Befehl gegeben, sein Zimmer täglich zu reinigen! Einmal am frühen Morgen -- ein heftiger Regen, vielleicht schon ein Zeichen des kommenden Frühjahrs, schlug an die Scheiben -- war Gregor, als die Bedienerin mit ihren Redensarten wieder begann, derartig erbittert, daß er, wie zum Angriff, allerdings langsam und hinfällig, sich gegen sie wendete. Die Bedienerin aber, statt sich zu fürchten, hob bloß einen in der Nähe der Tür befindlichen Stuhl hoch empor, und wie sie mit groß geöffnetem Munde dastand, war ihre Absicht klar, den Mund erst zu schließen, wenn der Sessel in ihrer Hand auf Gregors Rücken niederschlagen würde. »Also weiter geht es nicht?« fragte sie, als Gregor sich wieder umdrehte, und stellte den Sessel ruhig in die Ecke zurück. Gregor aß nun fast gar nichts mehr. Nur wenn er zufällig an der vorbereiteten Speise vorüberkam, nahm er zum Spiel einen Bissen in den Mund, hielt ihn dort stundenlang und spie ihn dann meist wieder aus. Zuerst dachte er, es sei die Trauer über den Zustand seines Zimmers, die ihn vom Essen abhalte, aber gerade mit den Veränderungen des Zimmers söhnte er sich sehr bald aus. Man hatte sich angewöhnt, Dinge, die man anderswo nicht unterbringen konnte, in dieses Zimmer hineinzustellen, und solcher Dinge gab es nun viele, da man ein Zimmer der Wohnung an drei Zimmerherren vermietet hatte. Diese ernsten Herren, -- alle drei hatten Vollbärte, wie Gregor einmal durch eine Türspalte feststellte -- waren peinlich auf Ordnung, nicht nur in ihrem Zimmer, sondern, da sie sich nun einmal hier eingemietet hatten, in der ganzen Wirtschaft, also insbesondere in der Küche, bedacht. Unnützen oder gar schmutzigen Kram ertrugen sie nicht. Überdies hatten sie zum größten Teil ihre eigenen Einrichtungsstücke mitgebracht. Aus diesem Grunde waren viele Dinge überflüssig geworden, die zwar nicht verkäuflich waren, die man aber auch nicht wegwerfen wollte. Alle diese wanderten in Gregors Zimmer. Ebenso auch die Aschenkiste und die Abfallkiste aus der Küche. Was nur im Augenblick unbrauchbar war, schleuderte die Bedienerin, die es immer sehr eilig hatte, einfach in Gregors Zimmer; Gregor sah glücklicherweise meist nur den betreffenden Gegenstand und die Hand, die ihn hielt. Die Bedienerin hatte vielleicht die Absicht, bei Zeit und Gelegenheit die Dinge wieder zu holen oder alle insgesamt mit einemmal hinauszuwerfen, tatsächlich aber blieben sie dort liegen, wohin sie durch den ersten Wurf gekommen waren, wenn nicht Gregor sich durch das Rumpelzeug wand und es in Bewegung brachte, zuerst gezwungen, weil kein sonstiger Platz zum Kriechen frei war, später aber mit wachsendem Vergnügen, obwohl er nach solchen Wanderungen, zum Sterben müde und traurig, wieder stundenlang sich nicht rührte. Da die Zimmerherren manchmal auch ihr Abendessen zu Hause im gemeinsamen Wohnzimmer einnahmen, blieb die Wohnzimmertür an manchen Abenden geschlossen, aber Gregor verzichtete ganz leicht auf das Öffnen der Tür, hatte er doch schon manche Abende, an denen sie geöffnet war, nicht ausgenützt, sondern war, ohne daß es die Familie merkte, im dunkelsten Winkel seines Zimmers gelegen. Einmal aber hatte die Bedienerin die Tür zum Wohnzimmer ein wenig offen gelassen, und sie blieb so offen, auch als die Zimmerherren am Abend eintraten und Licht gemacht wurde. Sie setzten sich oben an den Tisch, wo in früheren Zeiten der Vater, die Mutter und Gregor gesessen hatten, entfalteten die Servietten und nahmen Messer und Gabel in die Hand. Sofort erschien in der Tür die Mutter mit einer Schüssel Fleisch und knapp hinter ihr die Schwester mit einer Schüssel hochgeschichteter Kartoffeln. Das Essen dampfte mit starkem Rauch. Die Zimmerherren beugten sich über die vor sie hingestellten Schüsseln, als wollten sie sie vor dem Essen prüfen, und tatsächlich zerschnitt der, welcher in der Mitte saß und den anderen zwei als Autorität zu gelten schien, ein Stück Fleisch noch auf der Schüssel, offenbar um festzustellen, ob es mürbe genug sei und ob es nicht etwa in die Küche zurückgeschickt werden solle. Er war befriedigt, und Mutter und Schwester, die gespannt zugesehen hatten, begannen aufatmend zu lächeln. Die Familie selbst aß in der Küche. Trotzdem kam der Vater, ehe er in die Küche ging, in dieses Zimmer herein und machte mit einer einzigen Verbeugung, die Kappe in der Hand, einen Rundgang um den Tisch. Die Zimmerherren erhoben sich sämtlich und murmelten etwas in ihre Bärte. Als sie dann allein waren, aßen sie fast unter vollkommenem Stillschweigen. Sonderbar schien es Gregor, daß man aus allen mannigfachen Geräuschen des Essens immer wieder ihre kauenden Zähne heraushörte, als ob damit Gregor gezeigt werden sollte, daß man Zähne brauche, um zu essen, und daß man auch mit den schönsten zahnlosen Kiefern nichts ausrichten könne. »Ich habe ja Appetit,« sagte sich Gregor sorgenvoll, »aber nicht auf diese Dinge. Wie sich diese Zimmerherren nähren, und ich komme um!« Gerade an diesem Abend -- Gregor erinnerte sich nicht, während der ganzen Zeit die Violine gehört zu haben -- ertönte sie von der Küche her. Die Zimmerherren hatten schon ihr Nachtmahl beendet, der mittlere hatte eine Zeitung hervorgezogen, den zwei anderen je ein Blatt gegeben, und nun lasen sie zurückgelehnt und rauchten. Als die Violine zu spielen begann, wurden sie aufmerksam, erhoben sich und gingen auf den Fußspitzen zur Vorzimmertür, in der sie aneinandergedrängt stehen blieben. Man mußte sie von der Küche aus gehört haben, denn der Vater rief: »Ist den Herren das Spiel vielleicht unangenehm? Es kann sofort eingestellt werden.« »Im Gegenteil,« sagte der mittlere der Herren, »möchte das Fräulein nicht zu uns hereinkommen und hier im Zimmer spielen, wo es doch viel bequemer und gemütlicher ist?« »O bitte,« rief der Vater, als sei er der Violinspieler. Die Herren traten ins Zimmer zurück und warteten. Bald kam der Vater mit dem Notenpult, die Mutter mit den Noten und die Schwester mit der Violine. Die Schwester bereitete alles ruhig zum Spiele vor; die Eltern, die niemals früher Zimmer vermietet hatten und deshalb die Höflichkeit gegen die Zimmerherren übertrieben, wagten gar nicht, sich auf ihre eigenen Sessel zu setzen; der Vater lehnte an der Tür, die rechte Hand zwischen zwei Knöpfe des geschlossenen Livreerockes gesteckt; die Mutter aber erhielt von einem Herrn einen Sessel angeboten und saß, da sie den Sessel dort ließ, wohin ihn der Herr zufällig gestellt hatte, abseits in einem Winkel. Die Schwester begann zu spielen; Vater und Mutter verfolgten, jeder von seiner Seite, aufmerksam die Bewegungen ihrer Hände. Gregor hatte, von dem Spiele angezogen, sich ein wenig weiter vorgewagt und war schon mit dem Kopf im Wohnzimmer. Er wunderte sich kaum darüber, daß er in letzter Zeit so wenig Rücksicht auf die andern nahm; früher war diese Rücksichtnahme sein Stolz gewesen. Und dabei hätte er gerade jetzt mehr Grund gehabt, sich zu verstecken, denn infolge des Staubes, der in seinem Zimmer überall lag und bei der kleinsten Bewegung umherflog, war auch er ganz staubbedeckt; Fäden, Haare, Speiseüberreste schleppte er auf seinem Rücken und an den Seiten mit sich herum; seine Gleichgültigkeit gegen alles war viel zu groß, als daß er sich, wie früher mehrmals während des Tages, auf den Rücken gelegt und am Teppich gescheuert hätte. Und trotz dieses Zustandes hatte er keine Scheu, ein Stück auf dem makellosen Fußboden des Wohnzimmers vorzurücken. Allerdings achtete auch niemand auf ihn. Die Familie war gänzlich vom Violinspiel in Anspruch genommen; die Zimmerherren dagegen, die zunächst, die Hände in den Hosentaschen, viel zu nahe hinter dem Notenpult der Schwester sich aufgestellt hatten, so daß sie alle in die Noten hätte sehen können, was sicher die Schwester stören mußte, zogen sich bald unter halblauten Gesprächen mit gesenkten Köpfen zum Fenster zurück, wo sie, vom Vater besorgt beobachtet, auch blieben. Es hatte nun wirklich den überdeutlichen Anschein, als wären sie in ihrer Annahme, ein schönes oder unterhaltendes Violinspiel zu hören, enttäuscht, hätten die ganze Vorführung satt und ließen sich nur aus Höflichkeit noch in ihrer Ruhe stören. Besonders die Art, wie sie alle aus Nase und Mund den Rauch ihrer Zigarren in die Höhe bliesen, ließ auf große Nervosität schließen. Und doch spielte die Schwester so schön. Ihr Gesicht war zur Seite geneigt, prüfend und traurig folgten ihre Blicke den Notenzeilen. Gregor kroch noch ein Stück vorwärts und hielt den Kopf eng an den Boden, um möglicherweise ihren Blicken begegnen zu können. War er ein Tier, da ihn Musik so ergriff? Ihm war, als zeige sich ihm der Weg zu der ersehnten unbekannten Nahrung. Er war entschlossen, bis zur Schwester vorzudringen, sie am Rock zu zupfen und ihr dadurch anzudeuten, sie möge doch mit ihrer Violine in sein Zimmer kommen, denn niemand lohnte hier das Spiel so, wie er es lohnen wollte. Er wollte sie nicht mehr aus seinem Zimmer lassen, wenigstens nicht, solange er lebte; seine Schreckgestalt sollte ihm zum erstenmal nützlich werden; an allen Türen seines Zimmers wollte er gleichzeitig sein und den Angreifern entgegenfauchen; die Schwester aber sollte nicht gezwungen, sondern","fr":"Il y avait en Vestphalie, dans le château de M. le baron de Thunder-ten-tronckh, un jeune garçon à qui la nature avait donné les moeurs les plus douces. Sa physionomie annonçait son âme. Il avait le jugement assez droit, avec l'esprit le plus simple; c'est, je crois, pour cette raison qu'on le nommait Candide. Les anciens domestiques de la maison soupçonnaient qu'il était fils de la soeur de monsieur le baron et d'un bon et honnête gentilhomme du voisinage, que cette demoiselle ne voulut jamais épouser parce qu'il n'avait pu prouver que soixante et onze quartiers, et que le reste de son arbre généalogique avait été perdu par l'injure du temps. Monsieur le baron était un des plus puissants seigneurs de la Westphalie, car son château avait une porte et des fenêtres. Sa grande salle même était ornée d'une tapisserie. Tous les chiens de ses basses-cours composaient une meute dans le besoin; ses palefreniers étaient ses piqueurs; le vicaire du village était son grand-aumônier. Ils l'appelaient tous monseigneur, et ils riaient quand il fesait des contes. Madame la baronne, qui pesait environ trois cent cinquante livres, s'attirait par là une très grande considération, et fesait les honneurs de la maison avec une dignité qui la rendait encore plus respectable. Sa fille Cunégonde, âgée de dix-sept ans, était haute en couleur, fraîche, grasse, appétissante. Le fils du baron paraissait en tout digne de son père. Le précepteur Pangloss[1] était l'oracle de la maison, et le petit Candide écoutait ses leçons avec toute la bonne foi de son âge et de son caractère. [1] De pan, tout, et glossa, langue. B. Pangloss enseignait la métaphysico-théologo-cosmolonigologie. Il prouvait admirablement qu'il n'y a point d'effet sans cause, et que, dans ce meilleur des mondes possibles, le château de monseigneur le baron était le plus beau des châteaux, et madame la meilleure des baronnes possibles. Il est démontré, disait-il, que les choses ne peuvent être autrement; car tout étant fait pour une fin, tout est nécessairement pour la meilleure fin. Remarquez bien que les nez ont été faits pour porter des lunettes; aussi avons-nous des lunettes[2]. Les jambes sont visiblement instituées pour être chaussées, et nous avons des chausses. Les pierres ont été formées pour être taillées et pour en faire des châteaux; aussi monseigneur a un très beau château: le plus grand baron de la province doit être le mieux logé; et les cochons étant faits pour être mangés, nous mangeons du porc toute l'année: par conséquent, ceux qui ont avancé que tout est bien ont dit une sottise; il fallait dire que tout est au mieux. [2] Voyez tome XXVII, page 528; et dans les Mélanges, année 1738, le chapitre XI de la troisième partie des Éléments de la philosophie de Newton; et année 1768, le chapitre X des Singularités de la nature. B. Candide écoutait attentivement, et croyait innocemment; car il trouvait mademoiselle Cunégonde extrêmement belle, quoiqu'il ne prît jamais la hardiesse de le lui dire. Il concluait qu'après le bonheur d'être né baron de Thunder-ten-tronckh, le second degré de bonheur était d'être mademoiselle Cunégonde; le troisième, de la voir tous les jours; et le quatrième, d'entendre maître Pangloss, le plus grand philosophe de la province, et par conséquent de toute la terre. Un jour Cunégonde, en se promenant auprès du château, dans le petit bois qu'on appelait parc, vit entre des broussailles le docteur Pangloss qui donnait une leçon de physique expérimentale à la femme de chambre de sa mère, petite brune très jolie et très docile. Comme mademoiselle Cunégonde avait beaucoup de disposition pour les sciences, elle observa, sans souffler, les expériences réitérées dont elle fut témoin; elle vit clairement la raison suffisante du docteur, les effets et les causes, et s'en retourna tout agitée, toute pensive, toute remplie du désir d'être savante, songeant qu'elle pourrait bien être la raison suffisante du jeune Candide, qui pouvait aussi être la sienne. Elle rencontra Candide en revenant au château, et rougit: Candide rougit aussi. Elle lui dit bonjour d'une voix entrecoupée; et Candide lui parla sans savoir ce qu'il disait. Le lendemain, après le dîner, comme on sortait de table, Cunégonde et Candide se trouvèrent derrière un paravent; Cunégonde laissa tomber son mouchoir, Candide le ramassa; elle lui prit innocemment la main; le jeune homme baisa innocemment la main de la jeune demoiselle avec une vivacité, une sensibilité, une grâce toute particulière; leurs bouches se rencontrèrent, leurs yeux s'enflammèrent, leurs genoux tremblèrent, leurs mains s'égarèrent. M. le baron de Thunder-ten-tronckh passa auprès du paravent, et voyant cette cause et cet effet, chassa Candide du château à grands coups de pied dans le derrière. Cunégonde s'évanouit: elle fut souffletée par madame la baronne dès qu'elle fut revenue à elle-même; et tout fut consterné dans le plus beau et le plus agréable des châteaux possibles. CHAPITRE II Ce que devint Candide parmi les Bulgares. Candide, chassé du paradis terrestre, marcha longtemps sans savoir où, pleurant, levant les yeux au ciel, les tournant souvent vers le plus beau des châteaux qui renfermait la plus belle des baronnettes; il se coucha sans souper au milieu des champs entre deux sillons; la neige tombait à gros flocons. Candide, tout transi, se traîna le lendemain vers la ville voisine, qui s'appelle Valdberghoff-trarbk-dikdorff, n'ayant point d'argent, mourant de faim et de lassitude. Il s'arrêta tristement à la porte d'un cabaret. Deux hommes habillés de bleu le remarquèrent: Camarade, dit l'un, voilà un jeune homme très bien fait, et qui a la taille requise; ils s'avancèrent vers Candide et le prièrent à dîner très civilement.—Messieurs, leur dit Candide avec une modestie charmante, vous me faites beaucoup d'honneur, mais je n'ai pas de quoi payer mon écot.—Ah! monsieur, lui dit un des bleus, les personnes de votre figure et de votre mérite ne paient jamais rien: n'avez-vous pas cinq pieds cinq pouces de haut?—Oui, messieurs, c'est ma taille, dit-il en fesant la révérence.—Ah! monsieur, mettez-vous à table; non seulement nous vous défraierons, mais nous ne souffrirons jamais qu'un homme comme vous manque d'argent; les hommes ne sont faits que pour se secourir les uns les autres.—Vous avez raison, dit Candide; c'est ce que M. Pangloss m'a toujours dit, et je vois bien que tout est au mieux. On le prie d'accepter quelques écus, il les prend et veut faire son billet; on n'en veut point, on se met à table. N'aimez-vous pas tendrement?….—Oh! oui, répond-il, j'aime tendrement mademoiselle Cunégonde.—Non, dit l'un de ces messieurs, nous vous demandons si vous n'aimez pas tendrement le roi des Bulgares?—Point du tout, dit-il, car je ne l'ai jamais vu.—Comment! c'est le plus charmant des rois, et il faut boire à sa santé.—Oh! très volontiers, messieurs. Et il boit. C'en est assez, lui dit-on, vous voilà l'appui, le soutien, le défenseur, le héros des Bulgares; votre fortune est faite, et votre gloire est assurée. On lui met sur-le-champ les fers aux pieds, et on le mène au régiment. On le fait tourner à droite, à gauche, hausser la baguette, remettre la baguette, coucher en joue, tirer, doubler le pas, et on lui donne trente coups de bâton; le lendemain, il fait l'exercice un peu moins mal, et il ne reçoit que vingt coups; le surlendemain, on ne lui en donne que dix, et il est regardé par ses camarades comme un prodige. Candide, tout stupéfait, ne démêlait pas encore trop bien comment il était un héros. Il s'avisa un beau jour de printemps de s'aller promener, marchant tout droit devant lui, croyant que c'était un privilège de l'espèce humaine, comme de l'espèce animale, de se servir de ses jambes à son plaisir. Il n'eut pas fait deux lieues que voilà quatre autres héros de six pieds qui l'atteignent, qui le lient, qui le mènent dans un cachot. On lui demanda juridiquement ce qu'il aimait le mieux d'être fustigé trente-six fois par tout le régiment, ou de recevoir à-la-fois douze balles de plomb dans la cervelle. Il eut beau dire que les volontés sont libres, et qu'il ne voulait ni l'un ni l'autre, il fallut faire un choix; il se détermina, en vertu du don de Dieu qu'on nomme liberté, à passer trente-six fois par les baguettes; il essuya deux promenades. Le régiment était composé de deux mille hommes; cela lui composa quatre mille coups de baguette, qui, depuis la nuque du cou jusqu'au cul, lui découvrirent les muscles et les nerfs. Comme on allait procéder à la troisième course, Candide, n'en pouvant plus, demanda en grâce qu'on voulût bien avoir la bonté de lui casser la tête; il obtint cette faveur; on lui bande les yeux; on le fait mettre à genoux. Le roi des Bulgares passe dans ce moment, s'informe du crime du patient; et comme ce roi avait un grand génie, il comprit, par tout ce qu'il apprit de Candide, que c'était un jeune métaphysicien fort ignorant des choses de ce monde, et il lui accorda sa grâce avec une clémence qui sera louée dans tous les journaux et dans tous les siècles. Un brave chirurgien guérit Candide en trois semaines avec les émollients enseignés par Dioscoride. Il avait déjà un peu de peau et pouvait marcher, quand le roi des Bulgares livra bataille au roi des Abares. CHAPITRE III. Comment Candide se sauva d'entre les Bulgares, et ce qu'il devint. Rien n'était si beau, si leste, si brillant, si bien ordonné que les deux armées. Les trompettes, les fifres, les hautbois, les tambours, les canons; formaient une harmonie telle qu'il n'y en eut jamais en enfer. Les canons renversèrent d'abord à peu près six mille hommes de chaque côté; ensuite la mousqueterie ôta du meilleur des mondes environ neuf à dix mille coquins qui en infectaient la surface. La baïonnette fut aussi la raison suffisante de la mort de quelques milliers d'hommes. Le tout pouvait bien se monter à une trentaine de mille âmes. Candide, qui tremblait comme un philosophe, se cacha du mieux qu'il put pendant cette boucherie héroïque. Enfin, tandis que les deux rois fesaient chanter des Te Deum, chacun dans son camp, il prit le parti d'aller raisonner ailleurs des effets et des causes. Il passa par-dessus des tas de morts et de mourants, et gagna d'abord un village voisin; il était en cendres: c'était un village abare que les Bulgares avaient brûlé, selon les lois du droit public. Ici des vieillards criblés de coups regardaient mourir leurs femmes égorgées, qui tenaient leurs enfants à leurs mamelles sanglantes; là des filles éventrées après avoir assouvi les besoins naturels de quelques héros, rendaient les derniers soupirs; d'autres à demi brûlées criaient qu'on achevât de leur donner la mort. Des cervelles étaient répandues sur la terre à côté de bras et de jambes coupés. Candide s'enfuit au plus vite dans un autre village: il appartenait à des Bulgares, et les héros abares l'avaient traité de même. Candide, toujours marchant sur des membres palpitants ou à travers des ruines, arriva enfin hors du théâtre de la guerre, portant quelques petites provisions dans son bissac, et n'oubliant jamais mademoiselle Cunégonde. Ses provisions lui manquèrent quand il fut en Hollande; mais ayant entendu dire que tout le monde était riche dans ce pays-là, et qu'on y était chrétien, il ne douta pas qu'on ne le traitât aussi bien qu'il l'avait été dans le château de M. le baron, avant qu'il en eût été chassé pour les beaux yeux de mademoiselle Cunégonde. Il demanda l'aumône à plusieurs graves personnages, qui lui répondirent tous que, s'il continuait à faire ce métier, on l'enfermerait dans une maison de correction pour lui apprendre à vivre. Il s'adressa ensuite à un homme qui venait de parler tout seul une heure de suite sur la charité dans une grande assemblée. Cet orateur le regardant de travers lui dit: Que venez-vous faire ici? y êtes-vous pour la bonne cause? Il n'y a point d'effet sans cause, répondit modestement Candide; tout est enchaîné nécessairement et arrangé pour le mieux. Il a fallu que je fusse chassé d'auprès de mademoiselle Cunégonde, que j'aie passé par les baguettes, et il faut que je demande mon pain, jusqu'à ce que je puisse en gagner; tout cela ne pouvait être autrement. Mon ami, lui dit l'orateur, croyez-vous que le pape soit l'antechrist? Je ne l'avais pas encore entendu dire, répondit Candide: mais qu'il le soit, ou qu'il ne le soit pas, je manque de pain. Tu ne mérites pas d'en manger, dit l'autre: va, coquin, va, misérable, ne m'approche de ta vie. La femme de l'orateur ayant mis la tête à la fenêtre, et avisant un homme qui doutait que le pape fût antechrist, lui répandit sur le chef un plein….. O ciel! à quel excès se porte le zèle de la religion dans les dames! Un homme qui n'avait point été baptisé, un bon anabaptiste, nommé Jacques, vit la manière cruelle et ignominieuse dont on traitait ainsi un de ses frères, un être à deux pieds sans plumes, qui avait une âme; il l'amena chez lui, le nettoya, lui donna du pain et de la bière, lui fit présent de deux florins, et voulut même lui apprendre à travailler dans ses manufactures aux étoffes de Perse qu'on fabrique en Hollande. Candide se prosternant presque devant lui, s'écriait: Maître Pangloss me l'avait bien dit que tout est au mieux dans ce monde, car je suis infiniment plus touché de votre extrême générosité que de la dureté de ce monsieur à manteau noir, et de madame son épouse. Le lendemain, en se promenant, il rencontra un gueux tout couvert de pustules, les yeux morts, le bout du nez rongé, la bouche de travers, les dents noires, et parlant de la gorge, tourmenté d'une toux violente, et crachant une dent à chaque effort. CHAPITRE IV. Comment Candide rencontra son ancien maître de philosophie, le docteur Pangloss, et ce qui en advint. Candide, plus ému encore de compassion que d'horreur, donna à cet épouvantable gueux les deux florins qu'il avait reçus de son honnête anabaptiste Jacques. Le fantôme le regarda fixement, versa des larmes, et sauta à son cou. Candide effrayé recule. Hélas! dit le misérable à l'autre misérable, ne reconnaissez-vous plus votre cher Pangloss? Qu'entends-je? vous, mon cher maître! vous, dans cet état horrible! quel malheur vous est-il donc arrivé? pourquoi n'êtes-vous plus dans le plus beau des châteaux? qu'est devenue mademoiselle Cunégonde, la perle des filles, le chef-d'oeuvre de la nature? Je n'en peux plus, dit Pangloss. Aussitôt Candide le mena dans l'étable de l'anabaptiste, où il lui fit manger un peu de pain; et quand Pangloss fut refait: Eh bien! lui dit-il, Cunégonde? Elle est morte, reprit l'autre. Candide s'évanouit à ce mot: son ami rappela ses sens avec un peu de mauvais vinaigre qui se trouva par hasard dans l'étable. Candide rouvre les yeux. Cunégonde est morte! Ah! meilleur des mondes, où êtes-vous? Mais de quelle maladie est-elle morte? ne serait-ce point de m'avoir vu chasser du beau château de monsieur son père à grands coups de pied? Non, dit Pangloss, elle a été éventrée par des soldats bulgares, après avoir été violée autant qu'on peut l'être; ils ont cassé la tête à monsieur le baron qui voulait la défendre; madame la baronne a été coupée en morceaux; mon pauvre pupille traité précisément comme sa soeur; et quant au château, il n'est pas resté pierre sur pierre, pas une grange, pas un mouton, pas un canard, pas un arbre; mais nous avons été bien vengés, car les Abares en ont fait autant dans une baronnie voisine qui appartenait à un seigneur bulgare. A ce discours, Candide s'évanouit encore; mais revenu à soi, et ayant dit tout ce qu'il devait dire, il s'enquit de la cause et de l'effet, et de la raison suffisante qui avait mis Pangloss dans un si piteux état. Hélas! dit l'autre, c'est l'amour: l'amour, le consolateur du genre humain, le conservateur de l'univers, l'âme de tous les êtres sensibles, le tendre amour. Hélas! dit Candide, je l'ai connu cet amour, ce souverain des coeurs, cette âme de notre âme; il ne m'a jamais valu qu'un baiser et vingt coups de pied au cul. Comment cette belle cause a-t-elle pu produire en vous un effet si abominable? Pangloss répondit en ces termes: O mon cher Candide! vous avez connu Paquette, cette jolie suivante de notre auguste baronne: j'ai goûté dans ses bras les délices du paradis, qui ont produit ces tourments d'enfer dont vous me voyez dévoré; elle en était infectée, elle en est peut-être morte. Paquette tenait ce présent d'un cordelier très savant qui avait remonté à la source, car il l'avait eu d'une vieille comtesse, qui l'avait reçu d'un capitaine de cavalerie, qui le devait à une marquise, qui le tenait d'un page, qui l'avait reçu d'un jésuite, qui, étant novice, l'avait eu en droite ligne d'un des compagnons de Christophe Colomb. Pour moi, je ne le donnerai à personne, car je me meurs. O Pangloss! s'écria Candide, voilà une étrange généalogie! n'est-ce pas le diable qui en fut la souche? Point du tout, répliqua ce grand homme; c'était une chose indispensable dans le meilleur des mondes, un ingrédient nécessaire; car si Colomb n'avait pas attrapé dans une île de l'Amérique cette maladie[1] qui empoisonne la source de la génération, qui souvent même empêche la génération, et qui est évidemment l'opposé du grand but de la nature, nous n'aurions ni le chocolat ni la cochenille; il faut encore observer que jusqu'aujourd'hui, dans notre continent, cette maladie nous est particulière, comme la controverse. Les Turcs, les Indiens, les Persans, les Chinois, les Siamois, les Japonais, ne la connaissent pas encore; mais il y a une raison suffisante pour qu'ils la connaissent à leur tour dans quelques siècles. En attendant elle a fait un merveilleux progrès parmi nous, et surtout dans ces grandes armées composées d'honnêtes stipendiaires bien élevés, qui décident du destin des états; on peut assurer que, quand trente mille hommes combattent en bataille rangée contre des troupes égales en nombre, il y a environ vingt mille vérolés de chaque côté. [1] Voyez tome XXXI, page 7. B. Voilà qui est admirable, dit Candide; mais il faut vous faire guérir. Et comment le puis-je? dit Pangloss; je n'ai pas le sou, mon ami, et dans toute l'étendue de ce globe on ne peut ni se faire saigner, ni prendre un lavement sans payer, ou sans qu'il y ait quelqu'un qui paie pour nous. Ce dernier discours détermina Candide; il alla se jeter aux pieds de son charitable anabaptiste Jacques, et lui fit une peinture si touchante de l'état où son ami était réduit, que le bon-homme n'hésita pas à recueillir le docteur Pangloss; il le fit guérir à ses dépens. Pangloss, dans la cure, ne perdit qu'un oeil et une oreille. Il écrivait bien, et savait parfaitement l'arithmétique. L'anabaptiste Jacques en fit son teneur de livres. Au bout de deux mois, étant obligé d'aller à Lisbonne pour les affaires de son commerce, il mena dans son vaisseau ses deux philosophes. Pangloss lui expliqua comment tout était on ne peut mieux. Jacques n'était pas de cet avis. Il faut bien, disait-il, que les hommes aient un peu corrompu la nature, car ils ne sont point nés loups, et ils sont devenus loups. Dieu ne leur a donné ni canons de vingt-quatre, ni baïonnettes, et ils se sont fait des baïonnettes et des canons pour se détruire. Je pourrais mettre en ligne de compte les banqueroutes, et la justice qui s'empare des biens des banqueroutiers pour en frustrer les créanciers. Tout cela était indispensable, répliquait le docteur borgne, et les malheurs particuliers font le bien général; de sorte que plus il y a de malheurs particuliers, et plus tout est bien. Tandis qu'il raisonnait, l'air s'obscurcit, les vents soufflèrent des quatre coins du monde, et le vaisseau fut assailli de la plus horrible tempête, à la vue du port de Lisbonne. CHAPITRE V. Tempête, naufrage, tremblement de terre, et ce qui advint du docteur Pangloss, de Candide, et de l'anabaptiste Jacques. La moitié des passagers affaiblis, expirants de ces angoisses inconcevables que le roulis d'un vaisseau porte dans les nerfs et dans toutes les humeurs du corps agitées en sens contraires, n'avait pas même la force de s'inquiéter du danger. L'autre moitié jetait des cris et fesait des prières; les voiles étaient déchirées, les mâts brisés, le vaisseau entr'ouvert. Travaillait qui pouvait, personne ne s'entendait, personne ne commandait. L'anabaptiste aidait un peu à la manoeuvre; il était sur le tillac; un matelot furieux le frappe rudement et l'étend sur les planches; mais du coup qu'il lui donna, il eut lui-même une si violente secousse, qu'il tomba hors du vaisseau, la tête la première. Il restait suspendu et accroché à une partie de mât rompu. Le bon Jacques court à son secours, l'aide à remonter, et de l'effort qu'il fait, il est précipité dans la mer à la vue du matelot, qui le laissa périr sans daigner seulement le regarder. Candide approche, voit son bienfaiteur qui reparaît un moment, et qui est englouti pour jamais. Il veut se jeter après lui dans la mer: le philosophe Pangloss l'en empêche, en lui prouvant que la rade de Lisbonne avait été formée exprès pour que cet anabaptiste s'y noyât. Tandis qu'il le prouvait à priori, le vaisseau s'entr'ouvre, tout périt à la réserve de Pangloss, de Candide, et de ce brutal de matelot qui avait noyé le vertueux anabaptiste; le coquin nagea heureusement jusqu'au rivage, où Pangloss et Candide furent portés sur une planche. Quand ils furent revenus un peu à eux, ils marchèrent vers Lisbonne; il leur restait quelque argent, avec lequel ils espéraient se sauver de la faim après avoir échappé à la tempête. A peine ont-ils mis le pied dans la ville, en pleurant la mort de leur bienfaiteur, qu'ils sentent la terre trembler sous leurs pas[1]; la mer s'élève en bouillonnant dans le port, et brise les vaisseaux qui sont à l'ancre. Des tourbillons de flammes et de cendres couvrent les rues et les places publiques; les maisons s'écroulent, les toits sont renversés sur les fondements, et les fondements se dispersent; trente mille habitants de tout âge et de tout sexe sont écrasés sous des ruines. Le matelot disait en sifflant et en jurant: il y aura quelque chose à gagner ici. Quelle peut être la raison suffisante de ce phénomène? disait Pangloss. Voici le dernier jour du monde! s'écriait Candide. Le matelot court incontinent au milieu des débris, affronte la mort pour trouver de l'argent, en trouve, s'en empare, s'enivre, et ayant cuvé son vin, achète les faveurs de la première fille de bonne volonté qu'il rencontre sur les ruines des maisons détruites, et au milieu des mourants et des morts. Pangloss le tirait cependant par la manche: Mon ami, lui disait-il, cela n'est pas bien, vous manquez à la raison universelle, vous prenez mal votre temps. Tête et sang, répondit l'autre, je suis matelot et né à Batavia; j'ai marché quatre fois sur le crucifix dans quatre voyages au Japon[2]; tu as bien trouvé ton homme avec ta raison universelle! [1] Le tremblement de terre de Lisbonne est du 1er novembre 1755. B. [2] Voyez tome XVIII, page 470. B. Quelques éclats de pierre avaient blessé Candide; il était étendu dans la rue et couvert de débris. Il disait à Pangloss: Hélas! procure-moi un peu de vin et d'huile; je me meurs. Ce tremblement de terre n'est pas une chose nouvelle, répondit Pangloss; la ville de Lima éprouva les mêmes secousses en Amérique l'année passée; mêmes causes, mêmes effets; il y a certainement une traînée de soufre sous terre depuis Lima jusqu'à Lisbonne. Rien n'est plus probable, dit Candide; mais, pour Dieu, un peu d'huile et de vin. Comment probable? répliqua le philosophe, je soutiens que la chose est démontrée. Candide perdit connaissance, et Pangloss lui apporta un peu d'eau d'une fontaine voisine. Le lendemain, ayant trouvé quelques provisions de bouche en se glissant à travers des décombres, ils réparèrent un peu leurs forces. Ensuite ils travaillèrent comme les autres à soulager les habitants échappés à la mort. Quelques citoyens, secourus par eux, leur donnèrent un aussi bon dîner qu'on le pouvait dans un tel désastre: il est vrai que le repas était triste; les convives arrosaient leur pain de leurs larmes; mais Pangloss les consola, en les assurant que les choses ne pouvaient être autrement: Car, dit-il, tout ceci est ce qu'il y a de mieux; car s'il y a un volcan à Lisbonne, il ne pouvait être ailleurs; car il est impossible que les choses ne soient pas où elles sont, car tout est bien. Un petit homme noir, familier de l'inquisition, lequel était à côté de lui, prit poliment la parole et dit: Apparemment que monsieur ne croit pas au péché originel; car si tout est au mieux, il n'y a donc eu ni chute ni punition. Je demande très humblement pardon à votre excellence, répondit Pangloss encore plus poliment, car la chute de l'homme et la malédiction entraient nécessairement dans le meilleur des mondes possibles. Monsieur ne croit donc pas à la liberté? dit le familier. Votre excellence m'excusera, dit Pangloss; la liberté peut subsister avec la nécessité absolue; car il était nécessaire que nous fussions libres; car enfin la volonté déterminée…… Pangloss était au milieu de sa phrase, quand le familier fit un signe de tête à son estafier qui lui servait à boire du vin de Porto ou d'Oporto. CHAPITRE VI. Comment on fit un bel auto-da-fé pour empêcher les tremblements de terre, et comment Candide fut fessé. Après le tremblement de terre qui avait détruit les trois quarts de Lisbonne, les sages du pays n'avaient pas trouvé un moyen plus efficace pour prévenir une ruine totale que de donner au peuple un bel auto-da-fé[1]; il était décidé par l'université de Coïmbre que le spectacle de quelques personnes brûlées à petit feu, en grande cérémonie, est un secret infaillible pour empêcher la terre de trembler. [1] Après le tremblement de terre de Lisbonne, on y fit en effet un autoda-fé, le 20 juin 1756; voyez, tome XXI, le chapitre XXXI du Précis du Siècle de Louis XV. B. On avait en conséquence saisi un Biscayen convaincu d'avoir épousé sa commère, et deux Portugais qui en mangeant un poulet en avaient arraché le lard: on vint lier après le dîner le docteur Pangloss et son disciple Candide, l'un pour avoir parlé, et l'autre pour l'avoir écouté avec un air d'approbation: tous deux furent menés séparément dans des appartements d'une extrême fraîcheur, dans lesquels on n'était jamais incommodé du soleil: huit jours après ils furent tous deux revêtus d'un san-benito, et on orna leurs têtes de mitres de papier: la mitre et le san-benito de Candide étaient peints de flammes renversées, et de diables qui n'avaient ni queues ni griffes; mais les diables de Pangloss portaient griffes et queues, et les flammes étaient droites. Ils marchèrent en procession ainsi vêtus, et entendirent un sermon très pathétique, suivi d'une belle musique en faux-bourdon. Candide fut fessé en cadence, pendant qu'on chantait; le Biscayen et les deux hommes qui n'avaient point voulu manger de lard furent brûlés, et Pangloss fut pendu, quoique ce ne soit pas la coutume. Le même jour la terre trembla de nouveau avec un fracas épouvantable. Candide épouvanté, interdit, éperdu, tout sanglant, tout palpitant, se disait à lui-même: Si c'est ici le meilleur des mondes possibles, que sont donc les autres? passe encore si je n'étais que fessé, je l'ai été chez les Bulgares; mais, ô mon cher Pangloss! le plus grand des philosophes, faut-il vous avoir vu pendre, sans que je sache pourquoi! ô mon cher anabaptiste! le meilleur des hommes, faut-il que vous ayez été noyé dans le port! ô mademoiselle Cunégonde! la perle des filles, faut-il qu'on vous ait fendu le ventre! Il s'en retournait, se soutenant à peine, prêché, fessé, absous, et béni, lorsqu'une vieille l'aborda, et lui dit: Mon fils, prenez courage, suivez-moi. CHAPITRE VII Comment une vieille prit soin de Candide, et comment il retrouva ce qu'il aimait. Candide ne prit point courage, mais il suivit la vieille dans une masure: elle lui donna un pot de pommade pour se frotter, lui laissa à manger et à boire; elle lui montra un petit lit assez propre; il y avait auprès du lit un habit complet. Mangez, buvez, dormez, lui dit-elle, et que Notre-Dame d'Atocha[1], monseigneur saint Antoine de Padoue, et monseigneur saint Jacques de Compostelle prennent soin de vous! je reviendrai demain. Candide, toujours étonné de tout ce qu'il avait vu, de tout ce qu'il avait souffert, et encore plus de la charité de la vieille, voulut lui baiser la main. Ce n'est pas ma main qu'il faut baiser, dit la vieille; je reviendrai demain. Frottez-vous de pommade, mangez et dormez. [1] Sur Notre-Dame d'Atocha, voyez dans les Mélanges, année 1769, une des notes de Voltaire sur son Extrait d'un journal (ou Mémoires de Dangeau). B. Candide, malgré tant de malheurs, mangea et dormit. Le lendemain la vieille lui apporte à déjeuner, visite son dos, le frotte elle-même d'une autre pommade: elle lui apporte ensuite à dîner: elle revient sur le soir et apporte à souper. Le surlendemain elle fit encore les mêmes cérémonies. Qui êtes-vous? lui disait toujours Candide; qui vous a inspiré tant de bonté? quelles grâces puis-je vous rendre? La bonne femme ne répondait jamais rien. Elle revint sur le soir, et n'apporta point à souper: Venez avec moi, dit-elle, et ne dites mot. Elle le prend sous le bras, et marche avec lui dans la campagne environ un quart de mille: ils arrivent à une maison isolée, entourée de jardins et de canaux. La vieille frappe à une petite porte. On ouvre; elle mène Candide, par un escalier dérobé, dans un cabinet doré, le laisse sur un canapé de brocart, referme la porte, et s'en va. Candide croyait rêver, et regardait toute sa vie comme un songe funeste, et le moment présent comme un songe agréable. La vieille reparut bientôt; elle soutenait avec peine une femme tremblante, d'une taille majestueuse, brillante de pierreries, et couverte d'un voile. Otez ce voile, dit la vieille à Candide. Le jeune homme approche; il lève le voile d'une main timide. Quel moment! quelle surprise! il croit voir mademoiselle Cunégonde; il la voyait en effet, c'était elle-même. La force lui manque, il ne peut proférer une parole, il tombe à ses pieds. Cunégonde tombe sur le canapé. La vieille les accable d'eaux spiritueuses, ils reprennent leurs sens, ils se parlent: ce sont d'abord des mots entrecoupés, des demandes et des réponses qui se croisent, des soupirs, des larmes, des cris. La vieille leur recommande de faire moins de bruit, et les laisse en liberté. Quoi! c'est vous, lui dit Candide, vous vivez! je vous retrouve en Portugal! On ne vous a donc pas violée? on ne vous a point fendu le ventre, comme le philosophe Pangloss me l'avait assuré? Si fait, dit la belle Cunégonde; mais on ne meurt pas toujours de ces deux accidents.—Mais votre père et votre mère ont-ils été tués?—Il n'est que trop vrai, dit Cunégonde en pleurant.—Et votre frère?—Mon frère a été tué aussi.—Et pourquoi êtes-vous en Portugal? et comment avez-vous su que j'y étais? et par quelle étrange aventure m'avez-vous fait conduire dans cette maison?—Je vous dirai tout cela, répliqua la dame; mais il faut auparavant que vous m'appreniez tout ce qui vous est arrivé depuis le baiser innocent que vous me donnâtes, et les coups de pied que vous reçûtes. Candide lui obéit avec un profond respect; et quoiqu'il fût interdit, quoique sa voix fût faible et tremblante, quoique l'échine lui fît encore un peu mal, il lui raconta de la manière la plus naïve tout ce qu'il avait éprouvé depuis le moment de leur séparation. Cunégonde levait les yeux au ciel: elle donna des larmes à la mort du bon anabaptiste et de Pangloss; après quoi elle parla en ces termes à Candide, qui ne perdait pas une parole, et qui la dévorait des yeux. CHAPITRE VIII. Histoire de Cunégonde. J'étais dans mon lit et je dormais profondément, quand il plut au ciel d'envoyer les Bulgares dans notre beau château de Thunder-ten-tronckh; ils égorgèrent mon père et mon frère, et coupèrent ma mère par morceaux. Un grand Bulgare, haut de six pieds, voyant qu'à ce spectacle j'avais perdu connaissance, se mit à me violer; cela me fit revenir, je repris mes sens, je criai, je me débattis, je mordis, j'égratignai, je voulais arracher les yeux à ce grand Bulgare, ne sachant pas que tout ce qui arrivait dans le château de mon père était une chose d'usage: le brutal me donna un coup de couteau dans le flanc gauche dont je porte encore la marque. Hélas! j'espère bien la voir, dit le naïf Candide. Vous la verrez, dit Cunégonde; mais continuons. Continuez, dit Candide. Elle reprit ainsi le fil de son histoire: Un capitaine bulgare entra, il me vit toute sanglante, et le soldat ne se dérangeait pas. Le capitaine se mit en colère du peu de respect que lui témoignait, ce brutal, et le tua sur mon corps. Ensuite il me fit panser, et m'emmena prisonnière de guerre dans son quartier. Je blanchissais le peu de chemises qu'il avait, je fesais sa cuisine; il me trouvait fort jolie, il faut l'avouer; et je ne nierai pas qu'il ne fût très bien fait, et qu'il n'eût la peau blanche et douce; d'ailleurs peu d'esprit, peu de philosophie: on voyait bien qu'il n'avait pas été élevé par le docteur Pangloss. Au bout de trois mois, ayant perdu tout son argent, et s'étant dégoûté de moi, il me vendit à un Juif nommé don Issachar, qui trafiquait en Hollande et en Portugal, et qui aimait passionnément les femmes. Ce Juif s'attacha beaucoup à ma personne, mais il ne pouvait en triompher; je lui ai mieux résisté qu'au soldat bulgare: une personne d'honneur peut être violée une fois, mais sa vertu s'en affermit. Le Juif, pour m'apprivoiser, me mena dans cette maison de campagne que vous voyez. J'avais cru jusque-là qu'il n'y avait rien sur la terre de si beau que le château de Thunder-ten-tronckh; j'ai été détrompée. Le grand-inquisiteur m'aperçut un jour à la messe; il me lorgna beaucoup, et me fit dire qu'il avait à me parler pour des affaires secrètes. Je fus conduite à son palais; je lui appris ma naissance; il me représenta combien il était au-dessous de mon rang d'appartenir à un Israélite. On proposa de sa part à don Issachar de me céder à monseigneur. Don Issachar, qui est le banquier de la cour, et homme de crédit, n'en voulut rien faire. L'inquisiteur le menaça d'un auto-da-fé. Enfin mon Juif intimidé conclut un marché par lequel la maison et moi leur appartiendraient à tous deux en commun; que le Juif aurait pour lui les lundis, mercredis, et le jour du sabbat, et que l'inquisiteur aurait les autres jours de la semaine. Il y a six mois que cette convention subsiste. Ce n'a pas été sans querelles; car souvent il a été indécis si la nuit du samedi au dimanche appartenait à l'ancienne loi ou à la nouvelle. Pour moi, j'ai résisté jusqu'à présent à toutes les deux; et je crois que c'est pour cette raison que j'ai toujours été aimée. Enfin, pour détourner le fléau des tremblements de terre, et pour intimider don Issachar, il plut à monseigneur l'inquisiteur de célébrer un auto-da-fé. Il me fit l'honneur de m'y inviter. Je fus très bien placée; on servit aux dames des rafraîchissements entre la messe et l'exécution. Je fus, à la vérité, saisie d'horreur en voyant brûler ces deux Juifs et cet honnête Biscayen qui avait épousé sa commère: mais quelle fut ma surprise, mon effroi, mon trouble, quand je vis dans un san-benito, et sous une mitre, une figure qui ressemblait à celle de Pangloss! Je me frottai les yeux, je regardai attentivement, je le vis pendre; je tombai en faiblesse. A peine reprenais-je mes sens, que je vous vis dépouillé tout nu; ce fut là le comble de l'horreur, de la consternation, de la douleur, du désespoir. Je vous dirai, avec vérité, que votre peau est encore plus blanche, et d'un incarnat plus parfait que celle de mon capitaine des Bulgares. Cette vue redoubla tous les sentiments qui m'accablaient, qui me dévoraient. Je m'écriai, je voulus dire, Arrêtez, barbares! mais la voix me manqua, et mes cris auraient été inutiles. Quand vous eûtes été bien fessé: Comment se peut-il faire, disais-je, que l'aimable Candide et le sage Pangloss se trouvent à Lisbonne, l'un pour recevoir cent coups de fouet, et l'autre pour être pendu par l'ordre de monseigneur l'inquisiteur, dont je suis la bien-aimée? Pangloss m'a donc bien cruellement trompée, quand il me disait que tout va le mieux du monde! Agitée, éperdue, tantôt hors de moi-même, et tantôt prête de mourir de faiblesse, j'avais la tête remplie du massacre de mon père, de ma mère, de mon frère, de l'insolence de mon vilain soldat bulgare, du coup de couteau qu'il me donna, de ma servitude, de mon métier de cuisinière, de mon capitaine bulgare, de mon vilain don Issachar, de mon abominable inquisiteur, de la pendaison du docteur Pangloss, de ce grand miserere en faux-bourdon pendant lequel on vous fessait, et surtout du baiser que je vous avais donné derrière un paravent, le jour que je vous avais vu pour la dernière fois. Je louai Dieu, qui vous ramenait à moi par tant d'épreuves. Je recommandai à ma vieille d'avoir soin de vous, et de vous amener ici dès qu'elle le pourrait. Elle a très bien exécuté ma commission; j'ai goûté le plaisir inexprimable de vous revoir, de vous entendre, de vous parler. Vous devez avoir une faim dévorante; j'ai grand appétit; commençons par souper. Les voilà qui se mettent tous deux à table; et, après le souper, ils se replacent sur ce beau canapé dont on a déjà parlé; ils y étaient quand le signor don Issachar, l'un des maîtres de la maison, arriva. C'était le jour du sabbat. Il venait jouir de ses droits, et expliquer son tendre amour. CHAPITRE IX. Ce qui advint de Cunégonde, de Candide, du grand-inquisiteur, et d'un Juif. Cet Issachar était le plus colérique Hébreu qu'on eût vu dans Israël, depuis la captivité en Babylone. Quoi! dit-il, chienne de galiléenne, ce n'est pas assez de monsieur l'inquisiteur? il faut que ce coquin partage aussi avec moi? En disant cela il tire un long poignard dont il était toujours pourvu, et, ne croyant pas que son adverse partie eût des armes, il se jette sur Candide; mais notre bon Vestphalien avait reçu une belle épée de la vieille avec l'habit complet. Il tire son épée, quoiqu'il eût les moeurs fort douces, et vous étend l'Israélite roide mort sur le carreau, aux pieds de la belle Cunégonde. Sainte Vierge! s'écria-t-elle, qu'allons-nous devenir? un homme tué chez moi! si la justice vient, nous sommes perdus. Si Pangloss n'avait pas été pendu, dit Candide, il nous donnerait un bon conseil dans cette extrémité, car c'était un grand philosophe. A son défaut, consultons la vieille. Elle était fort prudente, et commençait à dire son avis quand une autre petite porte s'ouvrit. Il était une heure après minuit, c'était le commencement du dimanche. Ce jour appartenait à monseigneur l'inquisiteur. Il entre et voit le fessé Candide, l'épée à la main, un mort étendu par terre, Cunégonde effarée, et la vieille donnant des conseils. Voici dans ce moment ce qui se passa dans l'âme de Candide, et comment il raisonna: Si ce saint homme appelle du secours, il me fera infailliblement brûler, il pourra en faire autant de Cunégonde; il m'a fait fouetter impitoyablement; il est mon rival; je suis en train de tuer; il n'y a pas à balancer. Ce raisonnement fut net et rapide; et, sans donner le temps à l'inquisiteur de revenir de sa surprise, il le perce d'outre en outre, et le jette à côté du Juif. En voici bien d'une autre, dit Cunégonde; il n'y a plus de rémission; nous sommes excommuniés, notre dernière heure est venue! Comment avez-vous fait, vous qui êtes né si doux, pour tuer en deux minutes un Juif et un prélat? Ma belle demoiselle, répondit Candide, quand on est amoureux, jaloux, et fouetté par l'inquisition, on ne se connaît plus. La vieille prit alors la parole, et dit: Il y a trois chevaux andalous dans l'écurie, avec leurs selles et leurs brides, que le brave Candide les prépare; madame a des moyadors et des diamants, montons vite à cheval, quoique je ne puisse me tenir que sur une fesse, et allons à Cadix; il fait le plus beau temps du monde, et c'est un grand plaisir de voyager pendant la fraîcheur de la nuit. Aussitôt Candide selle les trois chevaux; Cunégonde, la vieille, et lui, font trente milles d'une traite. Pendant qu'ils s'éloignaient, la sainte hermandad arrive dans la maison, on enterre monseigneur dans une belle église, on jette Issachar à la voirie. Candide, Cunégonde, et la vieille, étaient déjà dans la petite ville d'Avacéna, au milieu des montagnes de la Sierra-Morena; et ils parlaient ainsi dans un cabaret. CHAPITRE X. Dans quelle détresse Candide, Cunégonde, et la vieille, arrivent à Cadix, et leur embarquement. Qui a donc pu me voler mes pistoles et mes diamants? disait en pleurant Cunégonde; de quoi vivrons-nous? comment ferons-nous? où trouver des inquisiteurs et des Juifs qui m'en donnent d'autres? Hélas! dit la vieille, je soupçonne fort un révérend père cordelier, qui coucha hier dans la même auberge que nous à Badajos; Dieu me garde de faire un jugement téméraire! mais il entra deux fois dans notre chambre, et il partit long-temps avant nous. Hélas! dit Candide, le bon Pangloss m'avait souvent prouvé que les biens de la terre sont communs à tous les hommes, que chacun y a un droit égal. Ce cordelier devait bien, suivant ces principes, nous laisser de quoi achever notre voyage. Il ne vous reste donc rien du tout, ma belle Cunégonde? Pas un maravédis, dit-elle. Quel parti prendre? dit Candide. Vendons un des chevaux, dit la vieille; je monterai en croupe derrière mademoiselle, quoique je ne puisse me tenir que sur une fesse, et nous arriverons à Cadix. Il y avait dans la même hôtellerie un prieur de bénédictins; il acheta le cheval bon marché. Candide, Cunégonde, et la vieille, passèrent par Lucena, par Chillas, par Lebrixa, et arrivèrent enfin à Cadix. On y équipait une flotte, et on y assemblait des troupes pour mettre à la raison les révérends pères jésuites du Paraguai, qu'on accusait d'avoir fait révolter une de leurs hordes contre les rois d'Espagne et de Portugal, auprès de la ville du Saint-Sacrement[1]. Candide, ayant servi chez les Bulgares, fit l'exercice bulgarien devant le général de la petite armée avec tant de grâce, de célérité, d'adresse, de fierté, d'agilité, qu'on lui donna une compagnie d'infanterie à commander. Le voilà capitaine; il s'embarque avec mademoiselle Cunégonde, la vieille, deux valets, et les deux chevaux andalous qui avaient appartenu à M. le grand-inquisiteur de Portugal. [1] Voyez tome XVII, page 470; et dans les Mélanges, année 1759, la Lettre de M. Mead aux auteurs du Journal encyclopédique. B. Pendant toute la traversée ils raisonnèrent beaucoup sur la philosophie du pauvre Pangloss. Nous allons dans un autre univers, disait Candide; c'est dans celui-là, sans doute, que tout est bien: car il faut avouer qu'on pourrait gémir un peu de ce qui se passe dans le nôtre en physique et en morale. Je vous aime de tout mon coeur, disait Cunégonde; mais j'ai encore l'âme tout effarouchée de ce que j'ai vu, de ce que j'ai éprouvé. Tout ira bien, répliquait Candide; la mer de ce nouveau monde vaut déjà mieux que les mers de notre Europe; elle est plus calme, les vents plus constants. C'est certainement le Nouveau-Monde qui est le meilleur des univers possibles. Dieu le veuille! disait Cunégonde: mais j'ai été si horriblement malheureuse dans le mien, que mon coeur est presque fermé à l'espérance. Vous vous plaignez, leur dit la vieille; hélas! vous n'avez pas éprouvé des infortunes telles que les miennes. Cunégonde se mit presque à rire, et trouva cette bonne femme fort plaisante de prétendre être plus malheureuse qu'elle. Hélas! lui dit-elle, ma bonne, à moins que vous n'ayez été violée par deux Bulgares, que vous n'ayez reçu deux coups de couteau dans le ventre, qu'on n'ait démoli deux de vos châteaux, qu'on n'ait égorgé à vos yeux deux mères et deux pères, et que vous n'ayez vu deux de vos amants fouettés dans un auto-da-fé, je ne vois pas que vous puissiez l'emporter sur moi; ajoutez que je suis née baronne avec soixante et douze quartiers, et que j'ai été cuisinière. Mademoiselle, répondit la vieille, vous ne savez pas quelle est ma naissance; et si je vous montrais mon derrière, vous ne parleriez pas comme vous faites, et vous suspendriez votre jugement. Ce discours fit naître une extrême curiosité dans l'esprit de Cunégonde et de Candide. La vieille leur parla en ces termes. CHAPITRE XI. Histoire de la vieille. Je n'ai pas eu toujours les yeux éraillés et bordés d'écarlate; mon nez n'a pas toujours touché à mon menton, et je n'ai pas toujours été servante. Je suis la fille du pape Urbain X et de la princesse de Palestrine[a]. On m'éleva jusqu'à quatorze ans dans un palais auquel tous les châteaux de vos barons allemands n'auraient pas servi d'écurie; et une de mes robes valait mieux que toutes les magnificences de la Vestphalie. Je croissais en beauté, en grâces, en talents, au milieu des plaisirs, des respects, et des espérances: j'inspirais déjà de l'amour; ma gorge se formait; et quelle gorge! blanche, ferme, taillée comme celle de la Vénus de Médicis; et quels yeux! quelles paupières! quels sourcils noirs! quelles flammes brillaient dans mes deux prunelles, et effaçaient la scintillation des étoiles! comme me disaient les poètes du quartier. Les femmes qui m'habillaient et qui me déshabillaient tombaient en extase en me regardant par-devant et par-derrière; et tous les hommes auraient voulu être à leur place. [a] Voyez l'extrême discrétion de l'auteur; il n'y eut jusqu'à présent aucun pape nommé Urbain X; il craint de donner une bâtarde à un pape connu. Quelle circonspection! quelle délicatesse de conscience!—Cette note de Voltaire est posthume. Elle n'était même pas dans les éditions de Kehl. Je la tiens de feu Décrois. Le dernier pape du nom d'Urbain est Urbain VIII, mort en 1644. B. Je fus fiancée à un prince souverain de Massa-Carrara: quel prince! aussi beau que moi, pétri de douceur et d'agréments, brillant d'esprit et brûlant d'amour; je l'aimais comme on aime pour la première fois, avec idolâtrie, avec emportement. Les noces furent préparées: c'était une pompe, une magnificence inouïe; c'étaient des fêtes, des carrousels, des opéra-buffa continuels; et toute l'Italie fit pour moi des sonnets dont il n'y eut pas un seul de passable. Je touchais au moment de mon bonheur, quand une vieille marquise, qui avait été maîtresse de mon prince, l'invita à prendre du chocolat chez elle; il mourut en moins de deux heures avec des convulsions épouvantables; mais ce n'est qu'une bagatelle. Ma mère au désespoir, et bien moins affligée que moi, voulut s'arracher pour quelque temps à un séjour si funeste. Elle avait une très belle terre auprès de Gaïète: nous nous embarquâmes sur une galère du pays, dorée comme l'autel de Saint-Pierre de Rome. Voilà qu'un corsaire de Salé fond sur nous et nous aborde: nos soldats se défendirent comme des soldats du pape; ils se mirent tous à genoux en jetant leurs armes, et en demandant au corsaire une absolution in articulo mortis. Aussitôt on les dépouilla nus comme des singes, et ma mère aussi, nos filles d'honneur aussi, et moi aussi. C'est une chose admirable que la diligence avec laquelle ces messieurs déshabillent le monde; mais ce qui me surprit davantage, c'est qu'ils nous mirent à tous le doigt dans un endroit où nous autres femmes nous ne nous laissons mettre d'ordinaire que des canules. Cette cérémonie me paraissait bien étrange: voilà comme on juge de tout quand on n'est pas sorti de son pays. J'appris bientôt que c'était pour voir si nous n'avions pas caché là quelques diamants; c'est un usage établi de temps immémorial parmi les nations policées qui courent sur mer. J'ai su que messieurs les religieux chevaliers de Malte n'y manquent jamais quand ils prennent des Turcs et des Turques; c'est une loi du droit des gens à laquelle on n'a jamais dérogé. Je ne vous dirai point combien il est dur pour une jeune princesse d'être menée esclave à Maroc avec sa mère: vous concevez assez tout ce que nous eûmes à souffrir dans le vaisseau corsaire. Ma mère était encore très belle: nos filles d'honneur, nos simples femmes de chambre avaient plus de charmes qu'on n'en peut trouver dans toute l'Afrique: pour moi, j'étais ravissante, j'étais la beauté, la grâce même, et j'étais pucelle: je ne le fus pas long-temps; cette fleur, qui avait été réservée pour le beau prince de Massa-Carrara, me fut ravie par le capitaine corsaire; c'était un nègre abominable, qui croyait encore me faire beaucoup d'honneur. Certes il fallait que madame la princesse de Palestrine et moi fussions bien fortes pour résister à tout ce que nous éprouvâmes jusqu'à notre arrivée à Maroc! Mais passons; ce sont des choses si communes, qu'elles ne valent pas la peine qu'on en parle. Maroc nageait dans le sang quand nous arrivâmes. Cinquante fils de l'empereur Muley Ismael[1] avaient chacun leur parti; ce qui produisait en effet cinquante guerres civiles, de noirs contre noirs, de noirs contre basanés, de basanés contre basanés, de mulâtres contre mulâtres: c'était un carnage continuel dans toute l'étendue de l'empire. [1] Sur Muley Ismael, qui régnait en 1702, et vécut cent cinq ans, voyez tome XVI, page 197; tome XVIII, page 420; tome XX, le chapitre XVIII du Siècle de Louis XIV; tome XXX, page 126. B. A peine fûmes-nous débarquées, que des noirs d'une faction ennemie de celle de mon corsaire se présentèrent pour lui enlever son butin. Nous étions, après les diamants et l'or, ce qu'il avait de plus précieux. Je fus témoin d'un combat tel que vous n'en voyez jamais dans vos climats d'Europe. Les peuples septentrionaux n'ont pas le sang assez ardent; ils n'ont pas la rage des femmes au point où elle est commune en Afrique. Il semble que vos Européans aient du lait dans les veines; c'est du vitriol, c'est du feu qui coule dans celles des habitants du mont Atlas et des pays voisins. On combattit avec la fureur des lions, des tigres, et des serpents de la contrée, pour savoir qui nous aurait. Un Maure saisit ma mère par le bras droit, le lieutenant de mon capitaine la retint par le bras gauche; un soldat maure la prit par une jambe, un de nos pirates la tenait par l'autre. Nos filles se trouvèrent presque toutes en un moment tirées ainsi à quatre soldats. Mon capitaine me tenait cachée derrière lui; il avait le cimeterre au poing, et tuait tout ce qui s'opposait à sa rage. Enfin je vis toutes nos Italiennes et ma mère déchirées, coupées, massacrées par les monstres qui se les disputaient. Les captifs, mes compagnons, ceux qui les avaient pris, soldats, matelots, noirs, basanés, blancs, mulâtres, et enfin mon capitaine, tout fut tué, et je demeurai mourante sur un tas de morts. Des scènes pareilles se passaient, comme on sait, dans l'étendue de plus de trois cents lieues, sans qu'on manquât aux cinq prières par jour ordonnées par Mahomet. Je me débarrassai avec beaucoup de peine de la foule de tant de cadavres sanglants entassés, et je me traînai sous un grand oranger au bord d'un ruisseau voisin; j'y tombai d'effroi, de lassitude, d'horreur, de désespoir, et de faim. Bientôt après mes sens accablés se livrèrent à un sommeil qui tenait plus de l'évanouissement que du repos. J'étais dans cet état de faiblesse et d'insensibilité, entre la mort et la vie, quand je me sentis pressée de quelque chose qui s'agitait sur mon corps; j'ouvris les yeux, je vis un homme blanc et de bonne mine qui soupirait, et qui disait entre ses dents: O che sciagura d'essere senza coglioni! CHAPITRE XII. Suite des malheurs de la vieille. Étonnée et ravie d'entendre la langue de ma patrie, et non moins surprise des paroles que proférait cet homme, je lui répondis qu'il y avait de plus grands malheurs que celui dont il se plaignait; je l'instruisis en peu de mots des horreurs que j'avais essuyées, et je retombai en faiblesse. Il m'emporta dans une maison voisine, me fit mettre au lit, me fit donner à manger, me servit, me consola, me flatta, me dit qu'il n'avait rien vu de si beau que moi, et que jamais il n'avait tant regretté ce que personne ne pouvait lui rendre. Je suis né à Naples, me dit-il; on y chaponne deux ou trois mille enfants tous les ans; les uns en meurent, les autres acquièrent une voix plus belle que celle des femmes, les autres vont gouverner des états[1]. On me fit cette opération avec un très grand succès, et j'ai été musicien de la chapelle de madame la princesse de Palestrine. De ma mère! m'écriai-je. De votre mère! s'écria-t-il en pleurant: quoi! vous seriez cette jeune princesse que j'ai élevée jusqu'à l'âge de six ans, et qui promettait déjà d'être aussi belle que vous êtes?—C'est moi-même; ma mère est à quatre cents pas d'ici coupée en quartiers sous un tas de morts….. [1] Farinelli, chanteur italien, né à Naples en 1705, sans être ministre, gouvernait l'Espagne sous Ferdinand VI; il est mort en 1782. Voltaire reparle de ce Farinelli dans la Conversation de l'Intendant des menus en exercice: voyez les Mélanges, année 1761. B. Je lui contai tout ce qui m'était arrivé; il me conta aussi ses aventures, et m'apprit comment il avait été envoyé chez le roi de Maroc par une puissance chrétienne, pour conclure avec ce monarque un traité par lequel on lui fournirait de la poudre, des canons, et des vaisseaux, pour l'aider à exterminer le commerce des autres chrétiens. Ma mission est faite, dit cet honnête eunuque; je vais m'embarquer à Ceuta, et je vous ramènerai en Italie. Ma che sciagura d'essere senza coglioni! Je le remerciai avec des larmes d'attendrissement; et au lieu de me mener en Italie, il me conduisit à Alger, et me vendit au dey de cette province. A peine fus-je vendue, que cette peste qui a fait le tour de l'Afrique, de l'Asie, de l'Europe, se déclara dans Alger avec fureur. Vous avez vu des tremblements de terre; mais, mademoiselle, avez-vous jamais eu la peste? Jamais, répondit la baronne. Si vous l'aviez eue, reprit la vieille, vous avoueriez qu'elle est bien au-dessus d'un tremblement de terre. Elle est fort commune en Afrique; j'en fus attaquée. Figurez-vous quelle situation pour la fille d'un pape, âgée de quinze ans, qui en trois mois de temps avait éprouvé la pauvreté, l'esclavage, avait été violée presque tous les jours, avait vu couper sa mère en quatre, avait essuyé la faim et la guerre, et mourait pestiférée dans Alger! Je n'en mourus pourtant pas; mais mon eunuque et le dey, et presque tout le sérail d'Alger périrent. Quand les premiers ravages de cette épouvantable peste furent passés, on vendit les esclaves du dey. Un marchand m'acheta, et me mena à Tunis; il me vendit à un autre marchand qui me revendit à Tripoli; de Tripoli je fus revendue à Alexandrie, d'Alexandrie revendue à Smyrne; de Smyrne à Constantinople. J'appartins enfin à un aga des janissaires, qui fut bientôt commandé pour aller défendre Azof contre les Russes qui l'assiégeaient. L'aga, qui était un très galant homme, mena avec lui tout son sérail, et nous logea dans un petit fort sur les Palus-Méotides, gardé par deux eunuques noirs et vingt soldats. On tua prodigieusement de Russes, mais ils nous le rendirent bien: Azof fut mis à feu et à sang[2], et on ne pardonna ni au sexe, ni à l'âge; il ne resta que notre petit fort; les ennemis voulurent nous prendre par famine. Les vingt janissaires avaient juré de ne se jamais rendre. Les extrémités de la faim où ils furent réduits les contraignirent à manger nos deux eunuques, de peur de violer leur serment. Au bout de quelques jours ils résolurent de manger les femmes. [2] Les Russes prirent Azof sous Pierre-le-Grand, en 1696, et la rendirent à la paix, en 1711; la reprirent en 1739, la fortifièrent; mais à la paix de 1789, ils la rendirent après l'avoir démantelée. La prise d'Azof, sous Catherine II, est postérieure de dix ans à Candide. B. Nous avions un iman très pieux et très compatissant, qui leur fit un beau sermon par lequel il leur persuada de ne nous pas tuer tout-à-fait. Coupez, dit-il, seulement une fesse à chacune de ces dames, vous ferez très bonne chère; s'il faut y revenir, vous en aurez encore autant dans quelques jours; le ciel vous saura gré d'une action si charitable, et vous serez secourus. Il avait beaucoup d'éloquence; il les persuada: on nous fit cette horrible opération; l'iman nous appliqua le même baume qu'on met aux enfants qu'on vient de circoncire: nous étions toutes à la mort. A peine les janissaires eurent-ils fait le repas que nous leur avions fourni, que les Russes arrivent sur des bateaux plats; pas un janissaire ne réchappa. Les Russes ne firent aucune attention à l'état où nous étions. Il y a partout des chirurgiens français: un d'eux qui était fort adroit prit soin de nous, il nous guérit; et je me souviendrai toute ma vie, que quand mes plaies furent bien fermées, il me fit des propositions. Au reste, il nous dit à toutes de nous consoler; il nous assura que dans plusieurs sièges pareille chose était arrivée, et que c'était la loi de la guerre. Dès que mes compagnes purent marcher, on les fit aller à Moscou; j'échus en partage à un boïard qui me fit sa jardinière, et qui me donnait vingt coups de fouet par jour; mais ce seigneur ayant été roué au bout de deux ans avec une trentaine de boïards pour quelque tracasserie de cour, je profitai de cette aventure; je m'enfuis; je traversai toute la Russie; je fus long-temps servante de cabaret à Riga, puis à Rostock, à Vismar, à Leipsick, à Cassel, à Utrecht, à Leyde, à la Haye, à Rotterdam: j'ai vieilli dans la misère et dans l'opprobre, n'ayant que la moitié d'un derrière, me souvenant toujours que j'étais fille d'un pape; je voulus cent fois me tuer, mais j'aimais encore la vie. Cette faiblesse ridicule est peut-être un de nos penchants les plus funestes; car y a-t-il rien de plus sot que de vouloir porter continuellement un fardeau qu'on veut toujours jeter par terre; d'avoir son être en horreur, et de tenir à son être; enfin de caresser le serpent qui nous dévore, jusqu'à ce qu'il nous ait mangé le coeur? J'ai vu dans les pays que le sort m'a fait parcourir, et dans les cabarets où j'ai servi, un nombre prodigieux de personnes qui avaient leur existence en exécration; mais je n'en ai vu que douze qui aient mis volontairement fin à leur misère, trois nègres, quatre Anglais, quatre Genevois, et un professeur allemand nommé Robeck[3]. J'ai fini par être servante chez le Juif don Issachar; il me mit auprès de vous, ma belle demoiselle; je me suis attachée à votre destinée, et j'ai été plus occupée de vos aventures que des miennes. Je ne vous aurais même jamais parlé de mes malheurs, si vous ne m'aviez pas un peu piquée, et s'il n'était d'usage, dans un vaisseau, de conter des histoires pour se désennuyer. Enfin, mademoiselle, j'ai de l'expérience, je connais le monde; donnez-vous un plaisir, engagez chaque passager à vous conter son histoire, et s'il s'en trouve un seul qui n'ait souvent maudit sa vie, qui ne se soit souvent dit à lui-même qu'il était le plus malheureux des hommes, jetez-moi dans la mer la tête la première. [3] Robeck (Jean), né à Calmar en Suède, en 1672, se noya volontairement en 1739. J.-J. Rousseau parle de Robeck dans sa Nouvelle Héloïse, lettre vingt et unième de la troisième partie. B. CHAPITRE XIII. Comment Candide fut obligé de se séparer de la belle Cunégonde et de la vieille. La belle Cunégonde, ayant entendu l'histoire de la vieille, lui fit toutes les politesses qu'on devait à une personne de son rang et de son mérite. Elle accepta la proposition; elle engagea tous les passagers, l'un après l'autre, à lui conter leurs aventures. Candide et elle avouèrent que la vieille avait raison. C'est bien dommage, disait Candide, que le sage Pangloss ait été pendu contre la coutume dans un auto-da-fé; il nous dirait des choses admirables sur le mal physique et sur le mal moral qui couvrent la terre et la mer, et je me sentirais assez de force pour oser lui faire respectueusement quelques objections. A mesure que chacun racontait son histoire, le vaisseau avançait. On aborda dans Buénos-Ayres. Cunégonde, le capitaine Candide, et la vieille, allèrent chez le gouverneur don Fernando d'Ibaraa, y Figueora, y Mascarenes, y Lampourdos, y Souza. Ce seigneur avait une fierté convenable à un homme qui portait tant de noms. Il parlait aux hommes avec le dédain le plus noble, portant le nez si haut, élevant si impitoyablement la voix, prenant un ton si imposant, affectant une démarche si altière, que tous ceux qui le saluaient étaient tentés de le battre. Il aimait les femmes à la fureur. Cunégonde lui parut ce qu'il avait jamais vu de plus beau. La première chose qu'il fit fut de demander si elle n'était point la femme du capitaine. L'air dont il fit cette question alarma Candide: il n'osa pas dire qu'elle était sa femme, parcequ'en effet elle ne l'était point; il n'osait pas dire que c'était sa soeur, parcequ'elle ne l'était pas non plus; et quoique ce mensonge officieux eût été autrefois très à la mode chez les anciens[1], et qu'il pût être utile aux modernes, son âme était trop pure pour trahir la vérité. Mademoiselle Cunégonde, dit-il, doit me faire l'honneur de m'épouser, et nous supplions votre excellence de daigner faire notre noce. [1] Voyez l'article ABRAHAM, tome XXVI, page 48. B. Don Fernando d'Ibaraa, y Figueora, y Mascarenes, y Lampourdos, y Souza, relevant sa moustache, sourit amèrement, et ordonna au capitaine Candide d'aller faire la revue de sa compagnie. Candide obéit; le gouverneur demeura avec mademoiselle Cunégonde. Il lui déclara sa passion, lui protesta que le lendemain il l'épouserait à la face de l'Église, ou autrement, ainsi qu'il plairait à ses charmes. Cunégonde lui demanda un quart d'heure pour se recueillir, pour consulter la vieille, et pour se déterminer. La vieille dit à Cunégonde: Mademoiselle, vous avez soixante et douze quartiers et pas une obole; il ne tient qu'à vous d'être la femme du plus grand seigneur de l'Amérique méridionale, qui a une très belle moustache; est-ce à vous de vous piquer d'une fidélité à toute épreuve? Vous avez été violée par les Bulgares; un Juif et un inquisiteur ont eu vos bonnes grâces: les malheurs donnent des droits. J'avoue que si j'étais à votre place, je ne ferais aucun scrupule d'épouser monsieur le gouverneur, et de faire la fortune de monsieur le capitaine Candide. Tandis que la vieille parlait avec toute la prudence que l'âge et l'expérience donnent, on vit entrer dans le port un petit vaisseau; il portait un alcade et des alguazils, et voici ce qui était arrivé. La vieille avait très bien deviné que ce fut un cordelier à la grande manche qui vola l'argent et les bijoux de Cunégonde dans la ville de Badajos, lorsqu'elle fuyait en hâte avec Candide. Ce moine voulut vendre quelques unes des pierreries à un joaillier. Le marchand les reconnut pour celles du grand-inquisiteur. Le cordelier, avant d'être pendu, avoua qu'il les avait volées: il indiqua les personnes, et la route qu'elles prenaient. La fuite de Cunégonde et de Candide était déjà connue. On les suivit à Cadix: on envoya, sans perdre de temps, un vaisseau à leur poursuite. Le vaisseau était déjà dans le port de Buénos-Ayres. Le bruit se répandit qu'un alcade allait débarquer, et qu'on poursuivait les meurtriers de monseigneur le grand-inquisiteur. La prudente vieille vit dans l'instant tout ce qui était à faire. Vous ne pouvez fuir, dit-elle à Cunégonde, et vous n'avez rien à craindre; ce n'est pas vous qui avez tué monseigneur, et d'ailleurs le gouverneur, qui vous aime, ne souffrira pas qu'on vous maltraite; demeurez. Elle court sur-le-champ à Candide: Fuyez, dit-elle, ou dans une heure vous allez être brûlé. Il n'y avait pas un moment à perdre; mais comment se séparer de Cunégonde, et où se réfugier? CHAPITRE XIV. Comment Candide et Cacambo furent reçus chez les jésuites du Paraguai. Candide avait amené de Cadix un valet tel qu'on en trouve beaucoup sur les côtes d'Espagne et dans les colonies. C'était un quart d'Espagnol, né d'un métis dans le Tucuman; il avait été enfant de choeur, sacristain, matelot, moine, facteur, soldat, laquais. Il s'appelait Cacambo, et aimait fort son maître, parceque son maître était un fort bon homme. Il sella au plus vite les deux chevaux andalous. Allons, mon maître, suivons le conseil de la vieille, partons, et courons sans regarder derrière nous. Candide versa des larmes: O ma chère Cunégonde! faut-il vous abandonner dans le temps que monsieur le gouverneur va faire nos noces! Cunégonde amenée de si loin, que deviendrez-vous? Elle deviendra ce qu'elle pourra, dit Cacambo; les femmes ne sont jamais embarrassées d'elles; Dieu y pourvoit; courons. Où me mènes-tu? où allons-nous? que ferons-nous sans Cunégonde? disait Candide. Par saint Jacques de Compostelle, dit Cacambo, vous alliez faire la guerre aux jésuites, allons la faire pour eux; je sais assez les chemins, je vous mènerai dans leur royaume, ils seront charmés d'avoir un capitaine qui fasse l'exercice à la bulgare; vous ferez une fortune prodigieuse; quand on n'a pas son compte dans un monde, on le trouve dans un autre. C'est un très grand plaisir de voir et de faire des choses nouvelles. Tu as donc été déjà dans le Paraguai? dit Candide. Eh vraiment oui! dit Cacambo; j'ai été cuistre dans le collège de l'Assomption, et je connais le gouvernement de los padres comme je connais les rues de Cadix. C'est une chose admirable que ce gouvernement. Le royaume a déjà plus de trois cents lieues de diamètre; il est divisé en trente provinces. Los padres y ont tout, et les peuples rien; c'est le chef-d'oeuvre de la raison et de la justice. Pour moi, je ne vois rien de si divin que los padres, qui font ici la guerre au roi d'Espagne et au roi de Portugal, et qui en Europe confessent ces rois; qui tuent ici des Espagnols, et qui à Madrid les envoient au ciel; cela me ravit; avançons: vous allez être le plus heureux de tous les hommes. Quel plaisir auront los padres, quand ils sauront qu'il leur vient un capitaine qui sait l'exercice bulgare! Dès qu'ils furent arrivés à la première barrière, Cacambo dit à la garde avancée qu'un capitaine demandait à parler à monseigneur le commandant. On alla avertir la grande garde. Un officier paraguain courut aux pieds du commandant lui donner part de la nouvelle. Candide et Cacambo furent d'abord désarmés; on se saisit de leurs deux chevaux andalous. Les deux étrangers sont introduits au milieu de deux files de soldats; le commandant était au bout, le bonnet à trois cornes en tête, la robe retroussée, l'épée au côté, l'esponton à la main. Il fit un signe; aussitôt vingt-quatre soldats entourent les deux nouveaux venus. Un sergent leur dit qu'il faut attendre, que le commandant ne peut leur parler, que le révérend père provincial ne permet pas qu'aucun Espagnol ouvre la bouche qu'en sa présence, et demeure plus de trois heures dans le pays. Et où est le révérend père provincial? dit Cacambo. Il est à la parade après avoir dit sa messe, répondit le sergent, et vous ne pourrez baiser ses éperons que dans trois heures. Mais, dit Cacambo, monsieur le capitaine, qui meurt de faim comme moi, n'est point Espagnol, il est Allemand; ne pourrions-nous point déjeuner en attendant sa révérence? Le sergent alla sur-le-champ rendre compte de ce discours au commandant. Dieu soit béni! dit ce seigneur, puisqu'il est Allemand, je peux lui parler; qu'on le mène dans ma feuillée. Aussitôt on conduit Candide dans un cabinet de verdure, orné d'une très jolie colonnade de marbre vert et or, et de treillages qui renfermaient des perroquets, des colibris, des oiseaux-mouches, des pintades, et tous les oiseaux les plus rares. Un excellent déjeuner était préparé dans des vases d'or; et tandis que les Paraguains mangèrent du maïs dans des écuelles de bois, en plein champ, à l'ardeur du soleil, le révérend père commandant entra dans la feuillée. C'était un très beau jeune homme, le visage plein, assez blanc, haut en couleur, le sourcil relevé, l'oeil vif, l'oreille rouge, les lèvres vermeilles, l'air fier, mais d'une fierté qui n'était ni celle d'un Espagnol ni celle d'un jésuite. On rendit à Candide et à Cacambo leurs armes, qu'on leur avait saisies, ainsi que les deux chevaux andalous; Cacambo leur fit manger l'avoine auprès de la feuillée, ayant toujours l'oeil sur eux, crainte de surprise. Candide baisa d'abord le bas de la robe du commandant, ensuite ils se mirent à table. Vous êtes donc Allemand? lui dit le jésuite en cette langue. Oui, mon révérend père, dit Candide. L'un et l'autre, en prononçant ces paroles, se regardaient avec une extrême surprise, et une émotion dont ils n'étaient pas les maîtres. Et de quel pays d'Allemagne êtes-vous? dit le jésuite. De la sale province de Vestphalie, dit Candide: je suis né dans le château de Thunder-ten-tronckh. O ciel! est-il possible! s'écria le commandant. Quel miracle! s'écria Candide. Serait-ce vous? dit le commandant. Cela n'est pas possible, dit Candide. Ils se laissent tomber tous deux à la renverse, ils s'embrassent, ils versent des ruisseaux de larmes. Quoi! serait-ce vous, mon révérend père? vous, le frère de la belle Cunégonde! vous qui fûtes tué par les Bulgares! vous le fils de monsieur le baron! vous jésuite au Paraguai! Il faut avouer que ce monde est une étrange chose. O Pangloss! Pangloss! que vous sériez aise si vous n'aviez pas été pendu! Le commandant fit retirer les esclaves nègres et les Paraguains qui servaient à boire dans des gobelets de cristal de roche. Il remercia Dieu et saint Ignace mille fois; il serrait Candide entre ses bras, leurs visages étaient baignés de pleurs. Vous seriez bien plus étonné, plus attendri, plus hors de vous-même, dit Candide, si je vous disais que mademoiselle Cunégonde, votre soeur, que vous avez crue éventrée, est pleine de santé.—Où?—Dans votre voisinage, chez M. le gouverneur de Buénos-Ayres; et je venais pour vous faire la guerre. Chaque mot qu'ils prononcèrent dans cette longue conversation accumulait prodige sur prodige. Leur âme tout entière volait sur leur langue, était attentive dans leurs oreilles, et étincelante dans leurs yeux. Comme ils étaient Allemands, ils tinrent table long-temps, en attendant le révérend père provincial; et le commandant parla ainsi à son cher Candide. CHAPITRE XV. Comment Candide tua le frère de sa chère Cunégonde. J'aurai toute ma vie présent à la mémoire le jour horrible où je vis tuer mon père et ma mère, et violer ma soeur. Quand les Bulgares furent retirés, on ne trouva point cette soeur adorable, et on mit dans une charrette ma mère, mon père, et moi, deux servantes et trois petits garçons égorgés, pour nous aller enterrer dans une chapelle de jésuites, à deux lieues du château de mes pères. Un jésuite nous jeta de l'eau bénite; elle était horriblement salée; il en entra quelques gouttes dans mes yeux: le père s'aperçut que ma paupière fesait un petit mouvement: il mit la main sur mon coeur, et le sentit palpiter; je fus secouru, et au bout de trois semaines il n'y paraissait pas. Vous savez, mon cher Candide, que j'étais fort joli; je le devins encore davantage; aussi le révérend père Croust[1], supérieur de la maison, prit pour moi la plus tendre amitié: il me donna l'habit de novice: quelque temps après je fus envoyé à Rome. Le père général avait besoin d'une recrue de jeunes jésuites allemands. Les souverains du Paraguai reçoivent le moins qu'ils peuvent de jésuites espagnols; ils aiment mieux les étrangers, dont ils se croient plus maîtres. Je fus jugé propre par le révérend père général pour aller travailler dans cette vigne. Nous partîmes, un Polonais, un Tyrolien, et moi. Je fus honoré, en arrivant, du sous-diaconat et d'une lieutenance: je suis aujourd'hui colonel et prêtre. Nous recevrons vigoureusement les troupes du roi d'Espagne; je vous réponds qu'elles seront excommuniées et battues. La Providence vous envoie ici pour nous seconder. Mais est-il bien vrai que ma chère soeur Cunégonde soit dans le voisinage, chez le gouverneur de Buénos-Ayres? Candide l'assura par serment que rien n'était plus vrai. Leurs larmes recommencèrent à couler. [1] Dans les premières éditions, au lieu de Croust, on lit: Didrie. Mais l'édition fesant partie du volume intitulé: Seconde suite des Mélanges, 1761, porte déjà Croust. Il est question du révérend P. Croust, le plus brutal de la société, dans le tome XXX, page 429. B. Le baron ne pouvait se lasser d'embrasser Candide; il l'appelait son frère, son sauveur. Ah! peut-être, lui dit-il, nous pourrons ensemble, mon cher Candide, entrer en vainqueurs dans la ville, et reprendre ma soeur Cunégonde. C'est tout ce que je souhaite, dit Candide; car je comptais l'épouser, et je l'espère encore. Vous, insolent! répondit le baron, vous auriez l'impudence d'épouser ma soeur qui a soixante et douze quartiers! Je vous trouve bien effronté d'oser me parler d'un dessein si téméraire! Candide, pétrifié d'un tel discours, lui répondit: Mon révérend père, tous les quartiers du monde n'y font rien; j'ai tiré votre soeur des bras d'un Juif et d'un inquisiteur; elle m'a assez d'obligations, elle veut m'épouser. Maître Pangloss m'a toujours dit que les hommes sont égaux; et assurément je l'épouserai. C'est ce que nous verrons, coquin! dit le jésuite baron de Thunder-ten-tronckh; et en même temps il lui donna un grand coup du plat de son épée sur le visage. Candide dans l'instant tire la sienne, et l'enfonce jusqu'à la garde dans le ventre du baron jésuite; mais en la retirant toute fumante, il se mit à pleurer: Hélas! mon Dieu! dit-il, j'ai tué mon ancien maître, mon ami, mon beau-frère; je suis le meilleur homme du monde, et voilà déjà trois hommes que je tue; et dans ces trois il y a deux prêtres. Cacambo, qui fesait sentinelle à la porte de la feuillée, accourut. Il ne nous reste qu'à vendre cher notre vie, lui dit son maître; on va, sans doute, entrer dans la feuillée; il faut mourir les armes à la main. Cacambo, qui en avait bien vu d'autres, ne perdit point la tête; il prit la robe de jésuite que portait le baron, la mit sur le corps de Candide, lui donna le bonnet carré du mort, et le fit monter à cheval. Tout cela se fit en un clin d'oeil. Galopons, mon maître; tout le monde vous prendra pour un jésuite qui va donner des ordres; et nous aurons passé les frontières avant qu'on puisse courir après nous. Il volait déjà en prononçant ces paroles, et en criant en espagnol: Place, place pour le révérend père colonel! CHAPITRE XVI. Ce qui advint aux deux voyageurs avec deux filles, deux singes, et les sauvages nommés Oreillons. Candide et son valet furent au-delà des barrières, et personne ne savait encore dans le camp la mort du jésuite allemand. Le vigilant Cacambo avait eu soin de remplir sa valise de pain, de chocolat, de jambon, de fruits, et de quelques mesures de vin. Ils s'enfoncèrent avec leurs chevaux andalous dans un pays inconnu où ils ne découvrirent aucune route. Enfin une belle prairie entrecoupée de ruisseaux se présenta devant eux. Nos deux voyageurs font repaître leurs montures. Cacambo propose à son maître de manger, et lui en donne l'exemple. Comment veux-tu, disait Candide, que je mange du jambon, quand j'ai tué le fils de monsieur le baron, et que je me vois condamné à ne revoir la belle Cunégonde de ma vie? à quoi me servira de prolonger mes misérables jours, puisque je dois les traîner loin d'elle dans les remords et dans le désespoir? et que dira le Journal de Trévoux[1]? [1] L'ouvrage cité sous le titre de Journal de Trévoux, du nom de la ville où il s'imprima, est intitulé: Mémoires pour servir à l'histoire des sciences et des beaux-arts. Ce titre a subi plusieurs changements. B. En parlant ainsi, il ne laissa pas de manger. Le soleil se couchait. Les deux égarés entendirent quelques petits cris qui paraissaient poussés par des femmes. Ils ne savaient si ces cris étaient de douleur ou de joie; mais ils se levèrent précipitamment avec cette inquiétude et cette alarme que tout inspire dans un pays inconnu. Ces clameurs partaient de deux filles toutes nues qui couraient légèrement au bord de la prairie, tandis que deux singes les suivaient en leur mordant les fesses. Candide fut touché de pitié; il avait appris à tirer chez les Bulgares, et il aurait abattu une noisette dans un buisson sans toucher aux feuilles. Il prend son fusil espagnol à deux coups, tire, et tue les deux singes. Dieu soit loué, mon cher Cacambo! j'ai délivré d'un grand péril ces deux pauvres créatures: si j'ai commis un péché en tuant un inquisiteur et un jésuite, je l'ai bien réparé en sauvant la vie à deux filles. Ce sont peut-être deux demoiselles de condition, et cette aventure nous peut procurer de très grands avantages dans le pays. Il allait continuer, mais sa langue devint percluse quand il vit ces deux filles embrasser tendrement les deux singes, fondre en larmes sur leurs corps, et remplir l'air des cris les plus douloureux. Je ne m'attendais pas à tant de bonté d'âme, dit-il enfin à Cacambo; lequel lui répliqua: Vous avez fait là un beau chef d'oeuvre, mon maître; vous avez tué les deux amants de ces demoiselles. Leurs amants! serait-il possible? vous vous moquez de moi, Cacambo; le moyen de vous croire? Mon cher maître, repartit Cacambo, vous êtes toujours étonné de tout; pourquoi trouvez-vous si étrange que dans quelques pays il y ait des singes qui obtiennent les bonnes grâces des dames? ils sont des quarts d'homme, comme je suis un quart d'Espagnol. Hélas! reprit Candide, je me souviens d'avoir entendu dire à maître Pangloss qu'autrefois pareils accidents étaient arrivés, et que ces mélanges avaient produit des égypans, des faunes, des satyres; que plusieurs grands personnages de l'antiquité en avaient vu; mais je prenais cela pour des fables. Vous devez être convaincu à présent, dit Cacambo, que c'est une vérité, et vous voyez comment en usent les personnes qui n'ont pas reçu une certaine éducation; tout ce que je crains, c'est que ces dames ne nous fassent quelque méchante affaire. Ces réflexions solides engagèrent Candide à quitter la prairie, et à s'enfoncer dans un bois. Il y soupa avec Cacambo; et tous deux, après avoir maudit l'inquisiteur de Portugal, le gouverneur de Buénos-Ayres, et le baron, s'endormirent sur de la mousse. A leur réveil, ils sentirent qu'ils ne pouvaient remuer; la raison en était que pendant la nuit les Oreillons, habitants du pays, à qui les deux dames les avaient dénoncés, les avaient garrottés avec des cordes d'écorces d'arbre. Ils étaient entourés d'une cinquantaine d'Oreillons tout nus, armés de flèches, de massues, et de haches de caillou: les uns fesaient bouillir une grande chaudière; les autres préparaient des broches, et tous criaient: C'est un jésuite, c'est un jésuite! nous serons vengés, et nous ferons bonne chère; mangeons du jésuite, mangeons du jésuite! Je vous l'avais bien dit, mon cher maître, s'écria tristement Cacambo, que ces deux filles nous joueraient d'un mauvais tour. Candide apercevant la chaudière et les broches s'écria: Nous allons certainement être rôtis ou bouillis. Ah! que dirait maître Pangloss, s'il voyait comme la pure nature est faite? Tout est bien; soit, mais j'avoue qu'il est bien cruel, d'avoir perdu mademoiselle Cunégonde, et d'être mis à la broche par des Oreillons. Cacambo ne perdait jamais la tête. Ne désespérez de rien, dit-il au désolé Candide; j'entends un peu le jargon de ces peuples, je vais leur parler. Ne manquez pas, dit Candide, de leur représenter quelle est l'inhumanité affreuse de faire cuire des hommes, et combien cela est peu chrétien. Messieurs, dit Cacambo, vous comptez donc manger aujourd'hui un jésuite? c'est très bien fait; rien n'est plus juste que de traiter ainsi ses ennemis. En effet le droit naturel nous enseigne à tuer notre prochain, et c'est ainsi qu'on en agit dans toute la terre. Si nous n'usons pas du droit de le manger, c'est que nous avons d'ailleurs de quoi faire bonne chère; mais vous n'avez pas les mêmes ressources que nous: certainement il vaut mieux manger ses ennemis que d'abandonner aux corbeaux et aux corneilles le fruit de sa victoire. Mais, messieurs, vous ne voudriez pas manger vos amis. Vous croyez aller mettre un jésuite en broche, et c'est votre défenseur, c'est l'ennemi de vos ennemis que vous allez rôtir. Pour moi, je suis né dans votre pays; monsieur que vous voyez est mon maître, et bien loin d'être jésuite, il vient de tuer un jésuite, il en porte les dépouilles; voilà le sujet de votre méprise. Pour vérifier ce que je vous dis, prenez sa robe, portez-la à la première barrière du royaume de los padres; informez-vous si mon maître n'a pas tué un officier jésuite. Il vous faudra peu de temps; vous pourrez toujours nous manger, si vous trouvez que je vous ai menti. Mais, si je vous ai dit la vérité, vous connaissez trop les principes du droit public, les moeurs, et les lois, pour ne nous pas faire grâce. Les Oreillons trouvèrent ce discours très raisonnable; ils députèrent deux notables pour aller en diligence s'informer de la vérité; les deux députés s'acquittèrent de leur commission en gens d'esprit, et revinrent bientôt apporter de bonnes nouvelles. Les Oreillons délièrent leurs deux prisonniers, leur firent toutes sortes de civilités, leur offrirent des filles, leur donnèrent des rafraîchissements, et les reconduisirent jusqu'aux confins de leurs états, en criant avec allégresse: Il n'est point jésuite, il n'est point jésuite! Candide ne se lassait point d'admirer le sujet de sa délivrance. Quel peuple! disait-il, quels hommes! quelles moeurs! si je n'avais pas eu le bonheur de donner un grand coup d'épée au travers du corps du frère de mademoiselle Cunégonde, j'étais mangé sans rémission. Mais, après tout, la pure nature est bonne, puisque ces gens-ci, au lieu de me manger, m'ont fait mille honnêtetés, dès qu'ils ont su que je n'étais pas jésuite. CHAPITRE XVII. Arrivée de Candide et de son valet au pays d'Eldorado, et ce qu'ils y virent. Quand ils furent aux frontières des Oreillons: Vous voyez, dit Cacambo à Candide, que cet hémisphère-ci ne vaut pas mieux que l'autre; croyez-moi, retournons en Europe par le plus court chemin. Comment y retourner, dit Candide; et où aller? Si je vais dans mon pays, les Bulgares et les Abares y égorgent tout; si je retourne en Portugal, j'y suis brûlé; si nous restons dans ce pays-ci, nous risquons à tout moment d'être mis en broche. Mais comment se résoudre à quitter la partie du monde que mademoiselle Cunégonde habite? —Tournons vers la Cayenne, dit Cacambo, nous y trouverons des Français qui vont par tout le monde; ils pourront nous aider. Dieu aura peut-être pitié de nous.» Il n'était pas facile d'aller à la Cayenne: ils savaient bien à peu près de quel côté il fallait marcher; mais des montagnes, des fleuves, des précipices, des brigands, des sauvages, étaient partout de terribles obstacles. Leurs chevaux moururent de fatigue; leurs provisions furent consumées; ils se nourrirent un mois entier de fruits sauvages, et se trouvèrent enfin auprès d'une petite rivière bordée de cocotiers qui soutinrent leur vie et leurs espérances. Cacambo, qui donnait toujours d'aussi bons conseils que la vieille, dit à Candide: Nous n'en pouvons plus, nous avons assez marché; j'aperçois un canot vide sur le rivage, emplissons-le de cocos, jetons-nous dans cette petite barque, laissons-nous aller au courant; une rivière mène toujours à quelque endroit habité. Si nous ne trouvons pas des choses agréables, nous trouverons du moins des choses nouvelles. Allons, dit Candide, recommandons-nous à la Providence. Ils voguèrent quelques lieues entre des bords, tantôt fleuris, tantôt arides, tantôt unis, tantôt escarpés. La rivière s'élargissait toujours; enfin elle se perdait sous une voûte de rochers épouvantables qui s'élevaient jusqu'au ciel. Les deux voyageurs eurent la hardiesse de s'abandonner aux flots sous cette voûte. Le fleuve resserré en cet endroit les porta avec une rapidité et un bruit horrible. Au bout de vingt-quatre heures ils revirent le jour; mais leur canot se fracassa contre les écueils; il fallut se traîner de rocher en rocher pendant une lieue entière; enfin ils découvrirent un horizon immense, bordé de montagnes inaccessibles. Le pays était cultivé pour le plaisir comme pour le besoin; partout l'utile était agréable[1]: les chemins étaient couverts ou plutôt ornés de voitures d'une forme et d'une matière brillante, portant des hommes et des femmes d'une beauté singulière, traînés rapidement par de gros moutons rouges qui surpassaient en vitesse les plus beaux chevaux d'Andalousie, de Tétuan, et de Méquinez. [1] Tel est le texte de toutes les éditions données du vivant de l'auteur, et même des éditions de Kehl. Quelques éditeurs récents ont mis: l'utile était joint à l'agréable. B. Voilà pourtant, dit Candide, un pays qui vaut mieux que la Vestphalie. Il mit pied à terre avec Cacambo auprès du premier village qu'il rencontra. Quelques enfants du village, couverts de brocarts d'or tout déchirés, jouaient au palet à l'entrée du bourg; nos deux hommes de l'autre monde s'amusèrent à les regarder: leurs palets étaient d'assez larges pièces rondes, jaunes, rouges, vertes, qui jetaient un éclat singulier. Il prit envie aux voyageurs d'en ramasser quelques uns; c'était de l'or, c'était des émeraudes, des rubis, dont le moindre aurait été le plus grand ornement du trône du Mogol. Sans doute, dit Cacambo, ces enfants sont les fils du roi du pays qui jouent au petit palet. Le magister du village parut dans ce moment pour les faire rentrer à l'école. Voilà, dit Candide, le précepteur de la famille royale. Les petits gueux quittèrent aussitôt le jeu, en laissant à terre leurs palets, et tout ce qui avait servi à leurs divertissements. Candide les ramasse, court au précepteur et les lui présente humblement, lui fesant entendre par signes que leurs altesses royales avaient oublié leur or et leurs pierreries. Le magister du village, en souriant, les jeta par terre, regarda un moment la figure de Candide avec beaucoup de surprise, et continua son chemin. Les voyageurs ne manquèrent pas de ramasser l'or, les rubis, et les émeraudes. Où sommes-nous? s'écria Candide. Il faut que les enfants des rois de ce pays soient bien élevés, puisqu'on leur apprend à mépriser l'or et les pierreries. Cacambo était aussi surpris que Candide. Ils approchèrent enfin de la première maison du village; elle était bâtie comme un palais d'Europe. Une foule de monde s'empressait à la porte, et encore plus dans le logis; une musique très agréable se fesait entendre, et une odeur délicieuse de cuisine se fesait sentir. Cacambo s'approcha de la porte, et entendit qu'on parlait péruvien; c'était sa langue maternelle; car tout le monde sait que Cacambo était né au Tucuman, dans un village où l'on ne connaissait que cette langue. Je vous servirai d'interprète, dit-il à Candide; entrons, c'est ici un cabaret. Aussitôt deux garçons et deux filles de l'hôtellerie, vêtus de drap d'or, et les cheveux renoués avec des rubans, les invitent à se mettre à la table de l'hôte. On servit quatre potages garnis chacun de deux perroquets, un contour bouilli qui pesait deux cents livres, deux singes rôtis d'un goût excellent, trois cents colibris dans un plat, et six cents oiseaux-mouches dans un autre; des ragoûts exquis, des pâtisseries délicieuses; le tout dans des plats d'une espèce de cristal de roche. Les garçons et les filles de l'hôtellerie versaient plusieurs liqueurs faites de cannes de sucre. Les convives étaient pour la plupart des marchands et des voituriers, tous d'une politesse extrême, qui firent quelques questions à Cacambo avec la discrétion la plus circonspecte, et qui répondirent aux siennes d'une manière à le satisfaire. Quand le repas fut fini, Cacambo crut, ainsi que Candide, bien payer son écot, en jetant sur la table de l'hôte deux de ces larges pièces d'or qu'il avait ramassées; l'hôte et l'hôtesse éclatèrent de rire, et se tinrent long-temps les côtés. Enfin ils se remirent. Messieurs, dit l'hôte, nous voyons bien que vous êtes des étrangers; nous ne sommes pas accoutumés à en voir. Pardonnez-nous si nous nous sommes mis à rire quand vous nous avez offert en paiement les cailloux de nos grands chemins. Vous n'avez pas sans doute de la monnaie du pays, mais il n'est pas nécessaire d'en avoir pour dîner ici. Toutes les hôtelleries établies pour la commodité du commerce sont payées par le gouvernement. Vous avez fait mauvaise chère ici, parceque c'est un pauvre village, mais partout ailleurs vous serez reçus comme vous méritez de l'être. Cacambo expliquait à Candide tous les discours de l'hôte, et Candide les écoutait avec la même admiration et le même égarement que son ami Cacambo les rendait. Quel est donc ce pays, disaient-ils l'un et l'autre, inconnu à tout le reste de la terre, et où toute la nature est d'une espèce si différente de la nôtre? C'est probablement le pays où tout va bien; car il faut absolument qu'il y en ait un de cette espèce. Et, quoi qu'en dît maître Pangloss, je me suis souvent aperçu que tout allait assez mal en Vestphalie. CHAPITRE XVIII Ce qu'ils virent dans le pays d'Eldorado[1]. [1] Sur le pays d'Eldorado, voyez tome XVII, page 436. B. Cacambo témoigna à son hôte toute sa curiosité; l'hôte lui dit: Je suis fort ignorant, et je m'en trouve bien; mais nous avons ici un vieillard retiré de la cour qui est le plus savant homme du royaume, et le plus communicatif. Aussitôt il mène Cacambo chez le vieillard. Candide ne jouait plus que le second personnage, et accompagnait son valet. Ils entrèrent dans une maison fort simple, car la porte n'était que d'argent, et les lambris des appartements n'étaient que d'or, mais travaillés avec tant de goût, que les plus riches lambris ne l'effaçaient pas. L'antichambre n'était à la vérité incrustée que de rubis et d'émeraudes; mais l'ordre dans lequel tout était arrangé réparait bien cette extrême simplicité. Le vieillard reçut les deux étrangers sur un sofa matelassé de plumes de colibri, et leur fit présenter des liqueurs dans des vases de diamant; après quoi il satisfit à leur curiosité en ces termes: Je suis âgé de cent soixante et douze ans, et j'ai appris de feu mon père, écuyer du roi, les étonnantes révolutions du Pérou dont il avait été témoin. Le royaume où nous sommes est l'ancienne patrie des incas, qui en sortirent très imprudemment pour aller subjuguer une partie du monde, et qui furent enfin détruits par les Espagnols. Les princes de leur famille qui restèrent dans leur pays natal furent plus sages; ils ordonnèrent, du consentement de la nation, qu'aucun habitant ne sortirait jamais de notre petit royaume; et c'est ce qui nous a conservé notre innocence et notre félicité. Les Espagnols ont eu une connaissance confuse de ce pays, ils l'ont appelé Eldorado; et un Anglais, nommé le chevalier Raleigh, en a même approché il y a environ cent années; mais, comme nous sommes entourés de rochers inabordables et de précipices, nous avons toujours été jusqu'à présent à l'abri de la rapacité des nations de l'Europe, qui ont une fureur inconcevable pour les cailloux et pour la fange de notre terre, et qui, pour en avoir, nous tueraient tous jusqu'au dernier. La conversation fut longue; elle roula sur la forme du gouvernement, sur les moeurs, sur les femmes, sur les spectacles publics, sur les arts. Enfin Candide, qui avait toujours du goût pour la métaphysique, fit demander par Cacambo si dans le pays il y avait une religion. Le vieillard rougit un peu. Comment donc! dit-il, en pouvez-vous douter? Est-ce que vous nous prenez pour des ingrats? Cacambo demanda humblement quelle était la religion d'Eldorado. Le vieillard rougit encore: Est-ce qu'il peut y avoir deux religions? dit-il. Nous avons, je crois, la religion de tout le monde; nous adorons Dieu du soir jusqu'au matin. N'adorez vous qu'un seul Dieu? dit Cacambo, qui servait toujours d'interprète aux doutes de Candide. Apparemment, dit le vieillard, qu'il n'y en a ni deux, ni trois, ni quatre. Je vous avoue que les gens de votre monde font des questions bien singulières. Candide ne se lassait pas de faire interroger ce bon vieillard; il voulut savoir comment on priait Dieu dans Eldorado. Nous ne le prions point, dit le bon et respectable sage; nous n'avons rien à lui demander, il nous a donné tout ce qu'il nous faut; nous le remercions sans cesse. Candide eut la curiosité de voir des prêtres; il fit demander où ils étaient. Le bon vieillard sourit. Mes amis, dit-il, nous sommes tous prêtres; le roi et tous les chefs de famille chantent des cantiques d'actions de grâces solennellement tous les matins, et cinq ou six mille musiciens les accompagnent.—Quoi! vous n'avez point de moines qui enseignent, qui disputent, qui gouvernent, qui cabalent, et qui font brûler les gens qui ne sont pas de leur avis?—Il faudrait que nous fussions fous, dit le vieillard; nous sommes tous ici du même avis, et nous n'entendons pas ce que vous voulez dire avec vos moines. Candide à tous ces discours demeurait en extase, et disait en lui-même: Ceci est bien différent de la Vestphalie et du château de monsieur le baron: si notre ami Pangloss avait vu Eldorado, il n'aurait plus dit que le château de Thunder-ten-tronckh était ce qu'il y avait de mieux sur la terre; il est certain qu'il faut voyager. Après cette longue conversation, le bon vieillard fit atteler un carrosse à six moutons, et donna douze de ses domestiques aux deux voyageurs pour les conduire à la cour. Excusez-moi, leur dit-il, si mon âge me prive de l'honneur de vous accompagner. Le roi vous recevra d'une manière dont vous ne serez pas mécontents, et vous pardonnerez sans doute aux usages du pays, s'il y en a quelques uns qui vous déplaisent. Candide et Cacambo montent en carrosse; les six moutons volaient, et en moins de quatre heures on arriva au palais du roi, situé à un bout de la capitale. Le portail était de deux cent vingt pieds de haut, et de cent de large; il est impossible d'exprimer quelle en était la matière. On voit assez quelle supériorité prodigieuse elle devait avoir sur ces cailloux et sur ce sable que nous nommons or et pierreries. Vingt belles filles de la garde reçurent Candide et Cacambo à la descente du carrosse, les conduisirent aux bains, les vêtirent de robes d'un tissu de duvet de colibri; après quoi les grands officiers et les grandes officières de la couronne les menèrent à l'appartement de sa majesté au milieu de deux files, chacune de mille musiciens, selon l'usage ordinaire. Quand ils approchèrent de la salle du trône, Cacambo demanda à un grand officier comment il fallait s'y prendre pour saluer sa majesté: si on se jetait","es":"En un lugar de la Mancha, de cuyo nombre no quiero acordarme, no ha mucho tiempo que vivía un hidalgo de los de lanza en astillero, adarga antigua, rocín flaco y galgo corredor. Una olla de algo más vaca que carnero, salpicón las más noches, duelos y quebrantos los sábados, lantejas los viernes, algún palomino de añadidura los domingos, consumían las tres partes de su hacienda. El resto della concluían sayo de velarte, calzas de velludo para las fiestas, con sus pantuflos de lo mesmo, y los días de entresemana se honraba con su vellorí de lo más fino. Tenía en su casa una ama que pasaba de los cuarenta, y una sobrina que no llegaba a los veinte, y un mozo de campo y plaza, que así ensillaba el rocín como tomaba la podadera. Frisaba la edad de nuestro hidalgo con los cincuenta años; era de complexión recia, seco de carnes, enjuto de rostro, gran madrugador y amigo de la caza. Quieren decir que tenía el sobrenombre de Quijada, o Quesada, que en esto hay alguna diferencia en los autores que deste caso escriben; aunque, por conjeturas verosímiles, se deja entender que se llamaba Quejana. Pero esto importa poco a nuestro cuento; basta que en la narración dél no se salga un punto de la verdad. Es, pues, de saber que este sobredicho hidalgo, los ratos que estaba ocioso, que eran los más del año, se daba a leer libros de caballerías, con tanta afición y gusto, que olvidó casi de todo punto el ejercicio de la caza, y aun la administración de su hacienda. Y llegó a tanto su curiosidad y desatino en esto, que vendió muchas hanegas de tierra de sembradura para comprar libros de caballerías en que leer, y así, llevó a su casa todos cuantos pudo haber dellos; y de todos, ningunos le parecían tan bien como los que compuso el famoso Feliciano de Silva, porque la claridad de su prosa y aquellas entricadas razones suyas le parecían de perlas, y más cuando llegaba a leer aquellos requiebros y cartas de desafíos, donde en muchas partes hallaba escrito: La razón de la sinrazón que a mi razón se hace, de tal manera mi razón enflaquece, que con razón me quejo de la vuestra fermosura. Y también cuando leía: ...los altos cielos que de vuestra divinidad divinamente con las estrellas os fortifican, y os hacen merecedora del merecimiento que merece la vuestra grandeza. Con estas razones perdía el pobre caballero el juicio, y desvelábase por entenderlas y desentrañarles el sentido, que no se lo sacara ni las entendiera el mesmo Aristóteles, si resucitara para sólo ello. No estaba muy bien con las heridas que don Belianís daba y recebía, porque se imaginaba que, por grandes maestros que le hubiesen curado, no dejaría de tener el rostro y todo el cuerpo lleno de cicatrices y señales. Pero, con todo, alababa en su autor aquel acabar su libro con la promesa de aquella inacabable aventura, y muchas veces le vino deseo de tomar la pluma y dalle fin al pie de la letra, como allí se promete; y sin duda alguna lo hiciera, y aun saliera con ello, si otros mayores y continuos pensamientos no se lo estorbaran. Tuvo muchas veces competencia con el cura de su lugar —que era hombre docto, graduado en Sigüenza—, sobre cuál había sido mejor caballero: Palmerín de Ingalaterra o Amadís de Gaula; mas maese Nicolás, barbero del mesmo pueblo, decía que ninguno llegaba al Caballero del Febo, y que si alguno se le podía comparar, era don Galaor, hermano de Amadís de Gaula, porque tenía muy acomodada condición para todo; que no era caballero melindroso, ni tan llorón como su hermano, y que en lo de la valentía no le iba en zaga. En resolución, él se enfrascó tanto en su letura, que se le pasaban las noches leyendo de claro en claro, y los días de turbio en turbio; y así, del poco dormir y del mucho leer, se le secó el celebro, de manera que vino a perder el juicio. Llenósele la fantasía de todo aquello que leía en los libros, así de encantamentos como de pendencias, batallas, desafíos, heridas, requiebros, amores, tormentas y disparates imposibles; y asentósele de tal modo en la imaginación que era verdad toda aquella máquina de aquellas sonadas soñadas invenciones que leía, que para él no había otra historia más cierta en el mundo. Decía él que el Cid Ruy Díaz había sido muy buen caballero, pero que no tenía que ver con el Caballero de la Ardiente Espada, que de sólo un revés había partido por medio dos fieros y descomunales gigantes. Mejor estaba con Bernardo del Carpio, porque en Roncesvalles había muerto a Roldán el encantado, valiéndose de la industria de Hércules, cuando ahogó a Anteo, el hijo de la Tierra, entre los brazos. Decía mucho bien del gigante Morgante, porque, con ser de aquella generación gigantea, que todos son soberbios y descomedidos, él solo era afable y bien criado. Pero, sobre todos, estaba bien con Reinaldos de Montalbán, y más cuando le veía salir de su castillo y robar cuantos topaba, y cuando en allende robó aquel ídolo de Mahoma que era todo de oro, según dice su historia. Diera él, por dar una mano de coces al traidor de Galalón, al ama que tenía, y aun a su sobrina de añadidura. En efeto, rematado ya su juicio, vino a dar en el más estraño pensamiento que jamás dio loco en el mundo; y fue que le pareció convenible y necesario, así para el aumento de su honra como para el servicio de su república, hacerse caballero andante, y irse por todo el mundo con sus armas y caballo a buscar las aventuras y a ejercitarse en todo aquello que él había leído que los caballeros andantes se ejercitaban, deshaciendo todo género de agravio, y poniéndose en ocasiones y peligros donde, acabándolos, cobrase eterno nombre y fama. Imaginábase el pobre ya coronado por el valor de su brazo, por lo menos, del imperio de Trapisonda; y así, con estos tan agradables pensamientos, llevado del estraño gusto que en ellos sentía, se dio priesa a poner en efeto lo que deseaba. Y lo primero que hizo fue limpiar unas armas que habían sido de sus bisabuelos, que, tomadas de orín y llenas de moho, luengos siglos había que estaban puestas y olvidadas en un rincón. Limpiólas y aderezólas lo mejor que pudo, pero vio que tenían una gran falta, y era que no tenían celada de encaje, sino morrión simple; mas a esto suplió su industria, porque de cartones hizo un modo de media celada, que, encajada con el morrión, hacían una apariencia de celada entera. Es verdad que para probar si era fuerte y podía estar al riesgo de una cuchillada, sacó su espada y le dio dos golpes, y con el primero y en un punto deshizo lo que había hecho en una semana; y no dejó de parecerle mal la facilidad con que la había hecho pedazos, y, por asegurarse deste peligro, la tornó a hacer de nuevo, poniéndole unas barras de hierro por de dentro, de tal manera que él quedó satisfecho de su fortaleza; y, sin querer hacer nueva experiencia della, la diputó y tuvo por celada finísima de encaje. Fue luego a ver su rocín, y, aunque tenía más cuartos que un real y más tachas que el caballo de Gonela, que tantum pellis et ossa fuit, le pareció que ni el Bucéfalo de Alejandro ni Babieca el del Cid con él se igualaban. Cuatro días se le pasaron en imaginar qué nombre le pondría; porque, según se decía él a sí mesmo, no era razón que caballo de caballero tan famoso, y tan bueno él por sí, estuviese sin nombre conocido; y ansí, procuraba acomodársele de manera que declarase quién había sido, antes que fuese de caballero andante, y lo que era entonces; pues estaba muy puesto en razón que, mudando su señor estado, mudase él también el nombre, y le cobrase famoso y de estruendo, como convenía a la nueva orden y al nuevo ejercicio que ya profesaba. Y así, después de muchos nombres que formó, borró y quitó, añadió, deshizo y tornó a hacer en su memoria e imaginación, al fin le vino a llamar Rocinante: nombre, a su parecer, alto, sonoro y significativo de lo que había sido cuando fue rocín, antes de lo que ahora era, que era antes y primero de todos los rocines del mundo. Puesto nombre, y tan a su gusto, a su caballo, quiso ponérsele a sí mismo, y en este pensamiento duró otros ocho días, y al cabo se vino a llamar don Quijote; de donde —como queda dicho— tomaron ocasión los autores desta tan verdadera historia que, sin duda, se debía de llamar Quijada, y no Quesada, como otros quisieron decir. Pero, acordándose que el valeroso Amadís no sólo se había contentado con llamarse Amadís a secas, sino que añadió el nombre de su reino y patria, por Hepila famosa, y se llamó Amadís de Gaula, así quiso, como buen caballero, añadir al suyo el nombre de la suya y llamarse don Quijote de la Mancha, con que, a su parecer, declaraba muy al vivo su linaje y patria, y la honraba con tomar el sobrenombre della. Limpias, pues, sus armas, hecho del morrión celada, puesto nombre a su rocín y confirmándose a sí mismo, se dio a entender que no le faltaba otra cosa sino buscar una dama de quien enamorarse; porque el caballero andante sin amores era árbol sin hojas y sin fruto y cuerpo sin alma. Decíase él a sí: — Si yo, por malos de mis pecados, o por mi buena suerte, me encuentro por ahí con algún gigante, como de ordinario les acontece a los caballeros andantes, y le derribo de un encuentro, o le parto por mitad del cuerpo, o, finalmente, le venzo y le rindo, ¿no será bien tener a quien enviarle presentado y que entre y se hinque de rodillas ante mi dulce señora, y diga con voz humilde y rendido: ''Yo, señora, soy el gigante Caraculiambro, señor de la ínsula Malindrania, a quien venció en singular batalla el jamás como se debe alabado caballero don Quijote de la Mancha, el cual me mandó que me presentase ante vuestra merced, para que la vuestra grandeza disponga de mí a su talante''? ¡Oh, cómo se holgó nuestro buen caballero cuando hubo hecho este discurso, y más cuando halló a quien dar nombre de su dama! Y fue, a lo que se cree, que en un lugar cerca del suyo había una moza labradora de muy buen parecer, de quien él un tiempo anduvo enamorado, aunque, según se entiende, ella jamás lo supo, ni le dio cata dello. Llamábase Aldonza Lorenzo, y a ésta le pareció ser bien darle título de señora de sus pensamientos; y, buscándole nombre que no desdijese mucho del suyo, y que tirase y se encaminase al de princesa y gran señora, vino a llamarla Dulcinea del Toboso, porque era natural del Toboso; nombre, a su parecer, músico y peregrino y significativo, como todos los demás que a él y a sus cosas había puesto. Capítulo II. Que trata de la primera salida que de su tierra hizo el ingenioso don Quijote Hechas, pues, estas prevenciones, no quiso aguardar más tiempo a poner en efeto su pensamiento, apretándole a ello la falta que él pensaba que hacía en el mundo su tardanza, según eran los agravios que pensaba deshacer, tuertos que enderezar, sinrazones que emendar, y abusos que mejorar y deudas que satisfacer. Y así, sin dar parte a persona alguna de su intención, y sin que nadie le viese, una mañana, antes del día, que era uno de los calurosos del mes de julio, se armó de todas sus armas, subió sobre Rocinante, puesta su mal compuesta celada, embrazó su adarga, tomó su lanza, y, por la puerta falsa de un corral, salió al campo con grandísimo contento y alborozo de ver con cuánta facilidad había dado principio a su buen deseo. Mas, apenas se vio en el campo, cuando le asaltó un pensamiento terrible, y tal, que por poco le hiciera dejar la comenzada empresa; y fue que le vino a la memoria que no era armado caballero, y que, conforme a ley de caballería, ni podía ni debía tomar armas con ningún caballero; y, puesto que lo fuera, había de llevar armas blancas, como novel caballero, sin empresa en el escudo, hasta que por su esfuerzo la ganase. Estos pensamientos le hicieron titubear en su propósito; mas, pudiendo más su locura que otra razón alguna, propuso de hacerse armar caballero del primero que topase, a imitación de otros muchos que así lo hicieron, según él había leído en los libros que tal le tenían. En lo de las armas blancas, pensaba limpiarlas de manera, en teniendo lugar, que lo fuesen más que un armiño; y con esto se quietó y prosiguió su camino, sin llevar otro que aquel que su caballo quería, creyendo que en aquello consistía la fuerza de las aventuras. Yendo, pues, caminando nuestro flamante aventurero, iba hablando consigo mesmo y diciendo: — ¿Quién duda sino que en los venideros tiempos, cuando salga a luz la verdadera historia de mis famosos hechos, que el sabio que los escribiere no ponga, cuando llegue a contar esta mi primera salidad tan de mañana, desta manera?: «Apenas había el rubicundo Apolo tendido por la faz de la ancha y espaciosa tierra las doradas hebras de sus hermosos cabellos, y apenas los pequeños y pintados pajarillos con sus arpadas lenguas habían saludado con dulce y meliflua armonía la venida de la rosada aurora, que, dejando la blanda cama del celoso marido, por las puertas y balcones del manchego horizonte a los mortales se mostraba, cuando el famoso caballero don Quijote de la Mancha, dejando las ociosas plumas, subió sobre su famoso caballo Rocinante, y comenzó a caminar por el antiguo y conocido campo de Montiel». Y era la verdad que por él caminaba. Y añadió diciendo: — Dichosa edad, y siglo dichoso aquel adonde saldrán a luz las famosas hazañas mías, dignas de entallarse en bronces, esculpirse en mármoles y pintarse en tablas para memoria en lo futuro. ¡Oh tú, sabio encantador, quienquiera que seas, a quien ha de tocar el ser coronista desta peregrina historia, ruégote que no te olvides de mi buen Rocinante, compañero eterno mío en todos mis caminos y carreras! Luego volvía diciendo, como si verdaderamente fuera enamorado: — ¡Oh princesa Dulcinea, señora deste cautivo corazón!, mucho agravio me habedes fecho en despedirme y reprocharme con el riguroso afincamiento de mandarme no parecer ante la vuestra fermosura. Plégaos, señora, de membraros deste vuestro sujeto corazón, que tantas cuitas por vuestro amor padece. Con éstos iba ensartando otros disparates, todos al modo de los que sus libros le habían enseñado, imitando en cuanto podía su lenguaje. Con esto, caminaba tan despacio, y el sol entraba tan apriesa y con tanto ardor, que fuera bastante a derretirle los sesos, si algunos tuviera. Casi todo aquel día caminó sin acontecerle cosa que de contar fuese, de lo cual se desesperaba, porque quisiera topar luego luego con quien hacer experiencia del valor de su fuerte brazo. Autores hay que dicen que la primera aventura que le avino fue la del Puerto Lápice; otros dicen que la de los molinos de viento; pero, lo que yo he podido averiguar en este caso, y lo que he hallado escrito en los Anales de la Mancha, es que él anduvo todo aquel día, y, al anochecer, su rocín y él se hallaron cansados y muertos de hambre; y que, mirando a todas partes por ver si descubriría algún castillo o alguna majada de pastores donde recogerse y adonde pudiese remediar su mucha hambre y necesidad, vio, no lejos del camino por donde iba, una venta, que fue como si viera una estrella que, no a los portales, sino a los alcázares de su redención le encaminaba. Diose priesa a caminar, y llegó a ella a tiempo que anochecía. Estaban acaso a la puerta dos mujeres mozas, destas que llaman del partido, las cuales iban a Sevilla con unos arrieros que en la venta aquella noche acertaron a hacer jornada; y, como a nuestro aventurero todo cuanto pensaba, veía o imaginaba le parecía ser hecho y pasar al modo de lo que había leído, luego que vio la venta, se le representó que era un castillo con sus cuatro torres y chapiteles de luciente plata, sin faltarle su puente levadiza y honda cava, con todos aquellos adherentes que semejantes castillos se pintan. Fuese llegando a la venta, que a él le parecía castillo, y a poco trecho della detuvo las riendas a Rocinante, esperando que algún enano se pusiese entre las almenas a dar señal con alguna trompeta de que llegaba caballero al castillo. Pero, como vio que se tardaban y que Rocinante se daba priesa por llegar a la caballeriza, se llegó a la puerta de la venta, y vio a las dos destraídas mozas que allí estaban, que a él le parecieron dos hermosas doncellas o dos graciosas damas que delante de la puerta del castillo se estaban solazando. En esto, sucedió acaso que un porquero que andaba recogiendo de unos rastrojos una manada de puercos —que, sin perdón, así se llaman— tocó un cuerno, a cuya señal ellos se recogen, y al instante se le representó a don Quijote lo que deseaba, que era que algún enano hacía señal de su venida; y así, con estraño contento, llegó a la venta y a las damas, las cuales, como vieron venir un hombre de aquella suerte, armado y con lanza y adarga, llenas de miedo, se iban a entrar en la venta; pero don Quijote, coligiendo por su huida su miedo, alzándose la visera de papelón y descubriendo su seco y polvoroso rostro, con gentil talante y voz reposada, les dijo: — No fuyan las vuestras mercedes ni teman desaguisado alguno; ca a la orden de caballería que profeso non toca ni atañe facerle a ninguno, cuanto más a tan altas doncellas como vuestras presencias demuestran. Mirábanle las mozas, y andaban con los ojos buscándole el rostro, que la mala visera le encubría; mas, como se oyeron llamar doncellas, cosa tan fuera de su profesión, no pudieron tener la risa, y fue de manera que don Quijote vino a correrse y a decirles: — Bien parece la mesura en las fermosas, y es mucha sandez además la risa que de leve causa procede; pero no vos lo digo porque os acuitedes ni mostredes mal talante; que el mío non es de ál que de serviros. El lenguaje, no entendido de las señoras, y el mal talle de nuestro caballero acrecentaba en ellas la risa y en él el enojo; y pasara muy adelante si a aquel punto no saliera el ventero, hombre que, por ser muy gordo, era muy pacífico, el cual, viendo aquella figura contrahecha, armada de armas tan desiguales como eran la brida, lanza, adarga y coselete, no estuvo en nada en acompañar a las doncellas en las muestras de su contento. Mas, en efeto, temiendo la máquina de tantos pertrechos, determinó de hablarle comedidamente; y así, le dijo: — Si vuestra merced, señor caballero, busca posada, amén del lecho (porque en esta venta no hay ninguno), todo lo demás se hallará en ella en mucha abundancia. Viendo don Quijote la humildad del alcaide de la fortaleza, que tal le pareció a él el ventero y la venta, respondió: -Para mí, señor castellano, cualquiera cosa basta, porque mis arreos son las armas, mi descanso el pelear, etc. Pensó el huésped que el haberle llamado castellano había sido por haberle parecido de los sanos de Castilla, aunque él era andaluz, y de los de la playa de Sanlúcar, no menos ladrón que Caco, ni menos maleante que estudiantado paje; y así, le respondió: — Según eso, las camas de vuestra merced serán duras peñas, y su dormir, siempre velar; y siendo así, bien se puede apear, con seguridad de hallar en esta choza ocasión y ocasiones para no dormir en todo un año, cuanto más en una noche. Y, diciendo esto, fue a tener el estribo a don Quijote, el cual se apeó con mucha dificultad y trabajo, como aquel que en todo aquel día no se había desayunado. Dijo luego al huésped que le tuviese mucho cuidado de su caballo, porque era la mejor pieza que comía pan en el mundo. Miróle el ventero, y no le pareció tan bueno como don Quijote decía, ni aun la mitad; y, acomodándole en la caballeriza, volvió a ver lo que su huésped mandaba, al cual estaban desarmando las doncellas, que ya se habían reconciliado con él; las cuales, aunque le habían quitado el peto y el espaldar, jamás supieron ni pudieron desencajarle la gola, ni quitalle la contrahecha celada, que traía atada con unas cintas verdes, y era menester cortarlas, por no poderse quitar los ñudos; mas él no lo quiso consentir en ninguna manera, y así, se quedó toda aquella noche con la celada puesta, que era la más graciosa y estraña figura que se pudiera pensar; y, al desarmarle, como él se imaginaba que aquellas traídas y llevadas que le desarmaban eran algunas principales señoras y damas de aquel castillo, les dijo con mucho donaire: -Nunca fuera caballero de damas tan bien servido como fuera don Quijote cuando de su aldea vino: doncellas curaban dél; princesas, del su rocino, o Rocinante, que éste es el nombre, señoras mías, de mi caballo, y don Quijote de la Mancha el mío; que, puesto que no quisiera descubrirme fasta que las fazañas fechas en vuestro servicio y pro me descubrieran, la fuerza de acomodar al propósito presente este romance viejo de Lanzarote ha sido causa que sepáis mi nombre antes de toda sazón; pero, tiempo vendrá en que las vuestras señorías me manden y yo obedezca, y el valor de mi brazo descubra el deseo que tengo de serviros. Las mozas, que no estaban hechas a oír semejantes retóricas, no respondían palabra; sólo le preguntaron si quería comer alguna cosa. — Cualquiera yantaría yo —respondió don Quijote—, porque, a lo que entiendo, me haría mucho al caso. A dicha, acertó a ser viernes aquel día, y no había en toda la venta sino unas raciones de un pescado que en Castilla llaman abadejo, y en Andalucía bacallao, y en otras partes curadillo, y en otras truchuela. Preguntáronle si por ventura comería su merced truchuela, que no había otro pescado que dalle a comer. — Como haya muchas truchuelas —respondió don Quijote—, podrán servir de una trucha, porque eso se me da que me den ocho reales en sencillos que en una pieza de a ocho. Cuanto más, que podría ser que fuesen estas truchuelas como la ternera, que es mejor que la vaca, y el cabrito que el cabrón. Pero, sea lo que fuere, venga luego, que el trabajo y peso de las armas no se puede llevar sin el gobierno de las tripas. Pusiéronle la mesa a la puerta de la venta, por el fresco, y trújole el huésped una porción del mal remojado y peor cocido bacallao, y un pan tan negro y mugriento como sus armas; pero era materia de grande risa verle comer, porque, como tenía puesta la celada y alzada la visera, no podía poner nada en la boca con sus manos si otro no se lo daba y ponía; y ansí, una de aquellas señoras servía deste menester. Mas, al darle de beber, no fue posible, ni lo fuera si el ventero no horadara una caña, y puesto el un cabo en la boca, por el otro le iba echando el vino; y todo esto lo recebía en paciencia, a trueco de no romper las cintas de la celada. Estando en esto, llegó acaso a la venta un castrador de puercos; y, así como llegó, sonó su silbato de cañas cuatro o cinco veces, con lo cual acabó de confirmar don Quijote que estaba en algún famoso castillo, y que le servían con música, y que el abadejo eran truchas; el pan, candeal; y las rameras, damas; y el ventero, castellano del castillo, y con esto daba por bien empleada su determinación y salida. Mas lo que más le fatigaba era el no verse armado caballero, por parecerle que no se podría poner legítimamente en aventura alguna sin recebir la orden de caballería. Capítulo III. Donde se cuenta la graciosa manera que tuvo don Quijote en armarse caballero Y así, fatigado deste pensamiento, abrevió su venteril y limitada cena; la cual acabada, llamó al ventero, y, encerrándose con él en la caballeriza, se hincó de rodillas ante él, diciéndole: — No me levantaré jamás de donde estoy, valeroso caballero, fasta que la vuestra cortesía me otorgue un don que pedirle quiero, el cual redundará en alabanza vuestra y en pro del género humano. El ventero, que vio a su huésped a sus pies y oyó semejantes razones, estaba confuso mirándole, sin saber qué hacerse ni decirle, y porfiaba con él que se levantase, y jamás quiso, hasta que le hubo de decir que él le otorgaba el don que le pedía. — No esperaba yo menos de la gran magnificencia vuestra, señor mío — respondió don Quijote—; y así, os digo que el don que os he pedido, y de vuestra liberalidad me ha sido otorgado, es que mañana en aquel día me habéis de armar caballero, y esta noche en la capilla deste vuestro castillo velaré las armas; y mañana, como tengo dicho, se cumplirá lo que tanto deseo, para poder, como se debe, ir por todas las cuatro partes del mundo buscando las aventuras, en pro de los menesterosos, como está a cargo de la caballería y de los caballeros andantes, como yo soy, cuyo deseo a semejantes fazañas es inclinado. El ventero, que, como está dicho, era un poco socarrón y ya tenía algunos barruntos de la falta de juicio de su huésped, acabó de creerlo cuando acabó de oírle semejantes razones, y, por tener qué reír aquella noche, determinó de seguirle el humor; y así, le dijo que andaba muy acertado en lo que deseaba y pedía, y que tal prosupuesto era propio y natural de los caballeros tan principales como él parecía y como su gallarda presencia mostraba; y que él, ansimesmo, en los años de su mocedad, se había dado a aquel honroso ejercicio, andando por diversas partes del mundo buscando sus aventuras, sin que hubiese dejado los Percheles de Málaga, Islas de Riarán, Compás de Sevilla, Azoguejo de Segovia, la Olivera de Valencia, Rondilla de Granada, Playa de Sanlúcar, Potro de Córdoba y las Ventillas de Toledo y otras diversas partes, donde había ejercitado la ligereza de sus pies, sutileza de sus manos, haciendo muchos tuertos, recuestando muchas viudas, deshaciendo algunas doncellas y engañando a algunos pupilos, y, finalmente, dándose a conocer por cuantas audiencias y tribunales hay casi en toda España; y que, a lo último, se había venido a recoger a aquel su castillo, donde vivía con su hacienda y con las ajenas, recogiendo en él a todos los caballeros andantes, de cualquiera calidad y condición que fuesen, sólo por la mucha afición que les tenía y porque partiesen con él de sus haberes, en pago de su buen deseo. Díjole también que en aquel su castillo no había capilla alguna donde poder velar las armas, porque estaba derribada para hacerla de nuevo; pero que, en caso de necesidad, él sabía que se podían velar dondequiera, y que aquella noche las podría velar en un patio del castillo; que a la mañana, siendo Dios servido, se harían las debidas ceremonias, de manera que él quedase armado caballero, y tan caballero que no pudiese ser más en el mundo. Preguntóle si traía dineros; respondió don Quijote que no traía blanca, porque él nunca había leído en las historias de los caballeros andantes que ninguno los hubiese traído. A esto dijo el ventero que se engañaba; que, puesto caso que en las historias no se escribía, por haberles parecido a los autores dellas que no era menester escrebir una cosa tan clara y tan necesaria de traerse como eran dineros y camisas limpias, no por eso se había de creer que no los trujeron; y así, tuviese por cierto y averiguado que todos los caballeros andantes, de que tantos libros están llenos y atestados, llevaban bien herradas las bolsas, por lo que pudiese sucederles; y que asimismo llevaban camisas y una arqueta pequeña llena de ungüentos para curar las heridas que recebían, porque no todas veces en los campos y desiertos donde se combatían y salían heridos había quien los curase, si ya no era que tenían algún sabio encantador por amigo, que luego los socorría, trayendo por el aire, en alguna nube, alguna doncella o enano con alguna redoma de agua de tal virtud que, en gustando alguna gota della, luego al punto quedaban sanos de sus llagas y heridas, como si mal alguno hubiesen tenido. Mas que, en tanto que esto no hubiese, tuvieron los pasados caballeros por cosa acertada que sus escuderos fuesen proveídos de dineros y de otras cosas necesarias, como eran hilas y ungüentos para curarse; y, cuando sucedía que los tales caballeros no tenían escuderos, que eran pocas y raras veces, ellos mesmos lo llevaban todo en unas alforjas muy sutiles, que casi no se parecían, a las ancas del caballo, como que era otra cosa de más importancia; porque, no siendo por ocasión semejante, esto de llevar alforjas no fue muy admitido entre los caballeros andantes; y por esto le daba por consejo, pues aún se lo podía mandar como a su ahijado, que tan presto lo había de ser, que no caminase de allí adelante sin dineros y sin las prevenciones referidas, y que vería cuán bien se hallaba con ellas cuando menos se pensase. Prometióle don Quijote de hacer lo que se le aconsejaba con toda puntualidad; y así, se dio luego orden como velase las armas en un corral grande que a un lado de la venta estaba; y, recogiéndolas don Quijote todas, las puso sobre una pila que junto a un pozo estaba, y, embrazando su adarga, asió de su lanza y con gentil continente se comenzó a pasear delante de la pila; y cuando comenzó el paseo comenzaba a cerrar la noche. Contó el ventero a todos cuantos estaban en la venta la locura de su huésped, la vela de las armas y la armazón de caballería que esperaba. Admiráronse de tan estraño género de locura y fuéronselo a mirar desde lejos, y vieron que, con sosegado ademán, unas veces se paseaba; otras, arrimado a su lanza, ponía los ojos en las armas, sin quitarlos por un buen espacio dellas. Acabó de cerrar la noche, pero con tanta claridad de la luna, que podía competir con el que se la prestaba, de manera que cuanto el novel caballero hacía era bien visto de todos. Antojósele en esto a uno de los arrieros que estaban en la venta ir a dar agua a su recua, y fue menester quitar las armas de don Quijote, que estaban sobre la pila; el cual, viéndole llegar, en voz alta le dijo: — ¡Oh tú, quienquiera que seas, atrevido caballero, que llegas a tocar las armas del más valeroso andante que jamás se ciñó espada!, mira lo que haces y no las toques, si no quieres dejar la vida en pago de tu atrevimiento. No se curó el arriero destas razones (y fuera mejor que se curara, porque fuera curarse en salud); antes, trabando de las correas, las arrojó gran trecho de sí. Lo cual visto por don Quijote, alzó los ojos al cielo, y, puesto el pensamiento —a lo que pareció— en su señora Dulcinea, dijo: — Acorredme, señora mía, en esta primera afrenta que a este vuestro avasallado pecho se le ofrece; no me desfallezca en este primero trance vuestro favor y amparo. Y, diciendo estas y otras semejantes razones, soltando la adarga, alzó la lanza a dos manos y dio con ella tan gran golpe al arriero en la cabeza, que le derribó en el suelo, tan maltrecho que, si segundara con otro, no tuviera necesidad de maestro que le curara. Hecho esto, recogió sus armas y tornó a pasearse con el mismo reposo que primero. Desde allí a poco, sin saberse lo que había pasado (porque aún estaba aturdido el arriero), llegó otro con la mesma intención de dar agua a sus mulos; y, llegando a quitar las armas para desembarazar la pila, sin hablar don Quijote palabra y sin pedir favor a nadie, soltó otra vez la adarga y alzó otra vez la lanza, y, sin hacerla pedazos, hizo más de tres la cabeza del segundo arriero, porque se la abrió por cuatro. Al ruido acudió toda la gente de la venta, y entre ellos el ventero. Viendo esto don Quijote, embrazó su adarga, y, puesta mano a su espada, dijo: — ¡Oh señora de la fermosura, esfuerzo y vigor del debilitado corazón mío! Ahora es tiempo que vuelvas los ojos de tu grandeza a este tu cautivo caballero, que tamaña aventura está atendiendo. Con esto cobró, a su parecer, tanto ánimo, que si le acometieran todos los arrieros del mundo, no volviera el pie atrás. Los compañeros de los heridos, que tales los vieron, comenzaron desde lejos a llover piedras sobre don Quijote, el cual, lo mejor que podía, se reparaba con su adarga, y no se osaba apartar de la pila por no desamparar las armas. El ventero daba voces que le dejasen, porque ya les había dicho como era loco, y que por loco se libraría, aunque los matase a todos. También don Quijote las daba, mayores, llamándolos de alevosos y traidores, y que el señor del castillo era un follón y mal nacido caballero, pues de tal manera consentía que se tratasen los andantes caballeros; y que si él hubiera recebido la orden de caballería, que él le diera a entender su alevosía: — Pero de vosotros, soez y baja canalla, no hago caso alguno: tirad, llegad, venid y ofendedme en cuanto pudiéredes, que vosotros veréis el pago que lleváis de vuestra sandez y demasía. Decía esto con tanto brío y denuedo, que infundió un terrible temor en los que le acometían; y, así por esto como por las persuasiones del ventero, le dejaron de tirar, y él dejó retirar a los heridos y tornó a la vela de sus armas con la misma quietud y sosiego que primero. No le parecieron bien al ventero las burlas de su huésped, y determinó abreviar y darle la negra orden de caballería luego, antes que otra desgracia sucediese. Y así, llegándose a él, se desculpó de la insolencia que aquella gente baja con él había usado, sin que él supiese cosa alguna; pero que bien castigados quedaban de su atrevimiento. Díjole como ya le había dicho que en aquel castillo no había capilla, y para lo que restaba de hacer tampoco era necesaria; que todo el toque de quedar armado caballero consistía en la pescozada y en el espaldarazo, según él tenía noticia del ceremonial de la orden, y que aquello en mitad de un campo se podía hacer, y que ya había cumplido con lo que tocaba al velar de las armas, que con solas dos horas de vela se cumplía, cuanto más, que él había estado más de cuatro. Todo se lo creyó don Quijote, y dijo que él estaba allí pronto para obedecerle, y que concluyese con la mayor brevedad que pudiese; porque si fuese otra vez acometido y se viese armado caballero, no pensaba dejar persona viva en el castillo, eceto aquellas que él le mandase, a quien por su respeto dejaría. Advertido y medroso desto el castellano, trujo luego un libro donde asentaba la paja y cebada que daba a los arrieros, y con un cabo de vela que le traía un muchacho, y con las dos ya dichas doncellas, se vino adonde don Quijote estaba, al cual mandó hincar de rodillas; y, leyendo en su manual, como que decía alguna devota oración, en mitad de la leyenda alzó la mano y diole sobre el cuello un buen golpe, y tras él, con su mesma espada, un gentil espaldazaro, siempre murmurando entre dientes, como que rezaba. Hecho esto, mandó a una de aquellas damas que le ciñese la espada, la cual lo hizo con mucha desenvoltura y discreción, porque no fue menester poca para no reventar de risa a cada punto de las ceremonias; pero las proezas que ya habían visto del novel caballero les tenía la risa a raya. Al ceñirle la espada, dijo la buena señora: — Dios haga a vuestra merced muy venturoso caballero y le dé ventura en lides. Don Quijote le preguntó cómo se llamaba, porque él supiese de allí adelante a quién quedaba obligado por la merced recebida; porque pensaba darle alguna parte de la honra que alcanzase por el valor de su brazo. Ella respondió con mucha humildad que se llamaba la Tolosa, y que era hija de un remendón natural de Toledo que vivía a las tendillas de Sancho Bienaya, y que dondequiera que ella estuviese le serviría y le tendría por señor. Don Quijote le replicó que, por su amor, le hiciese merced que de allí adelante se pusiese don y se llamase doña Tolosa. Ella se lo prometió, y la otra le calzó la espuela, con la cual le pasó casi el mismo coloquio que con la de la espada: preguntóle su nombre, y dijo que se llamaba la Molinera, y que era hija de un honrado molinero de Antequera; a la cual también rogó don Quijote que se pusiese don y se llamase doña Molinera, ofreciéndole nuevos servicios y mercedes. Hechas, pues, de galope y aprisa las hasta allí nunca vistas ceremonias, no vio la hora don Quijote de verse a caballo y salir buscando las aventuras; y, ensillando luego a Rocinante, subió en él, y, abrazando a su huésped, le dijo cosas tan estrañas, agradeciéndole la merced de haberle armado caballero, que no es posible acertar a referirlas. El ventero, por verle ya fuera de la venta, con no menos retóricas, aunque con más breves palabras, respondió a las suyas, y, sin pedirle la costa de la posada, le dejó ir a la buen hora. Capítulo IV. De lo que le sucedió a nuestro caballero cuando salió de la venta La del alba sería cuando don Quijote salió de la venta, tan contento, tan gallardo, tan alborozado por verse ya armado caballero, que el gozo le reventaba por las cinchas del caballo. Mas, viniéndole a la memoria los consejos de su huésped cerca de las prevenciones tan necesarias que había de llevar consigo, especial la de los dineros y camisas, determinó volver a su casa y acomodarse de todo, y de un escudero, haciendo cuenta de recebir a un labrador vecino suyo, que era pobre y con hijos, pero muy a propósito para el oficio escuderil de la caballería. Con este pensamiento guió a Rocinante hacia su aldea, el cual, casi conociendo la querencia, con tanta gana comenzó a caminar, que parecía que no ponía los pies en el suelo. No había andado mucho, cuando le pareció que a su diestra mano, de la espesura de un bosque que allí estaba, salían unas voces delicadas, como de persona que se quejaba; y apenas las hubo oído, cuando dijo: — Gracias doy al cielo por la merced que me hace, pues tan presto me pone ocasiones delante donde yo pueda cumplir con lo que debo a mi profesión, y donde pueda coger el fruto de mis buenos deseos. Estas voces, sin duda, son de algún menesteroso o menesterosa, que ha menester mi favor y ayuda. Y, volviendo las riendas, encaminó a Rocinante hacia donde le pareció que las voces salían. Y, a pocos pasos que entró por el bosque, vio atada una yegua a una encina, y atado en otra a un muchacho, desnudo de medio cuerpo arriba, hasta de edad de quince años, que era el que las voces daba; y no sin causa, porque le estaba dando con una pretina muchos azotes un labrador de buen talle, y cada azote le acompañaba con una reprehensión y consejo. Porque decía: — La lengua queda y los ojos listos. Y el muchacho respondía: — No lo haré otra vez, señor mío; por la pasión de Dios, que no lo haré otra vez; y yo prometo de tener de aquí adelante más cuidado con el hato. Y, viendo don Quijote lo que pasaba, con voz airada dijo: — Descortés caballero, mal parece tomaros con quien defender no se puede; subid sobre vuestro caballo y tomad vuestra lanza —que también tenía una lanza arrimada a la encima adonde estaba arrendada la yegua—, que yo os haré conocer ser de cobardes lo que estáis haciendo. El labrador, que vio sobre sí aquella figura llena de armas blandiendo la lanza sobre su rostro, túvose por muerto, y con buenas palabras respondió: — Señor caballero, este muchacho que estoy castigando es un mi criado, que me sirve de guardar una manada de ovejas que tengo en estos contornos, el cual es tan descuidado, que cada día me falta una; y, porque castigo su descuido, o bellaquería, dice que lo hago de miserable, por no pagalle la soldada que le debo, y en Dios y en mi ánima que miente. — ¿\"Miente\", delante de mí, ruin villano? —dijo don Quijote—. Por el sol que nos alumbra, que estoy por pasaros de parte a parte con esta lanza. Pagadle luego sin más réplica; si no, por el Dios que nos rige, que os concluya y aniquile en este punto. Desatadlo luego. El labrador bajó la cabeza y, sin responder palabra, desató a su criado, al cual preguntó don Quijote que cuánto le debía su amo. Él dijo que nueve meses, a siete reales cada mes. Hizo la cuenta don Quijote y halló que montaban setenta y tres reales, y díjole al labrador que al momento los desembolsase, si no quería morir por ello. Respondió el medroso villano que para el paso en que estaba y juramento que había hecho —y aún no había jurado nada—, que no eran tantos, porque se le habían de descontar y recebir en cuenta tres pares de zapatos que le había dado y un real de dos sangrías que le habían hecho estando enfermo. — Bien está todo eso —replicó don Quijote—, pero quédense los zapatos y las sangrías por los azotes que sin culpa le habéis dado; que si él rompió el cuero de los zapatos que vos pagastes, vos le habéis rompido el de su cuerpo; y si le sacó el barbero sangre estando enfermo, vos en sanidad se la habéis sacado; ansí que, por esta parte, no os debe nada. — El daño está, señor caballero, en que no tengo aquí dineros: véngase Andrés conmigo a mi casa, que yo se los pagaré un real sobre otro. — ¿Irme yo con él? —dijo el muchacho—. Mas, ¡mal año! No, señor, ni por pienso; porque, en viéndose solo, me desuelle como a un San Bartolomé. — No hará tal —replicó don Quijote—: basta que yo se lo mande para que me tenga respeto; y con que él me lo jure por la ley de caballería que ha recebido, le dejaré ir libre y aseguraré la paga. — Mire vuestra merced, señor, lo que dice —dijo el muchacho—, que este mi amo no es caballero ni ha recebido orden de caballería alguna; que es Juan Haldudo el rico, el vecino del Quintanar. — Importa eso poco —respondió don Quijote—, que Haldudos puede haber caballeros; cuanto más, que cada uno es hijo de sus obras. — Así es verdad —dijo Andrés—; pero este mi amo, ¿de qué obras es hijo, pues me niega mi soldada y mi sudor y trabajo? — No niego, hermano Andrés —respondió el labrador—; y hacedme placer de veniros conmigo, que yo juro por todas las órdenes que de caballerías hay en el mundo de pagaros, como tengo dicho, un real sobre otro, y aun sahumados. — Del sahumerio os hago gracia —dijo don Quijote—; dádselos en reales, que con eso me contento; y mirad que lo cumpláis como lo habéis jurado; si no, por el mismo juramento os juro de volver a buscaros y a castigaros, y que os tengo de hallar, aunque os escondáis más que una lagartija. Y si queréis saber quién os manda esto, para quedar con más veras obligado a cumplirlo, sabed que yo soy el valeroso don Quijote de la Mancha, el desfacedor de agravios y sinrazones; y a Dios quedad, y no se os parta de las mientes lo prometido y jurado, so pena de la pena pronunciada. Y, en diciendo esto, picó a su Rocinante, y en breve espacio se apartó dellos. Siguióle el labrador con los ojos, y, cuando vio que había traspuesto del bosque y que ya no parecía, volvióse a su criado Andrés y díjole: — Venid acá, hijo mío, que os quiero pagar lo que os debo, como aquel deshacedor de agravios me dejó mandado. — Eso juro yo —dijo Andrés—; y ¡cómo que andará vuestra merced acertado en cumplir el mandamiento de aquel buen caballero, que mil años viva; que, según es de valeroso y de buen juez, vive Roque, que si no me paga, que vuelva y ejecute lo que dijo! — También lo juro yo —dijo el labrador—; pero, por lo mucho que os quiero, quiero acrecentar la deuda por acrecentar la paga. Y, asiéndole del brazo, le tornó a atar a la encina, donde le dio tantos azotes, que le dejó por muerto. — Llamad, señor Andrés, ahora —decía el labrador— al desfacedor de agravios, veréis cómo no desface aquéste; aunque creo que no está acabado de hacer, porque me viene gana de desollaros vivo, como vos temíades. Pero, al fin, le desató y le dio licencia que fuese a buscar su juez, para que ejecutase la pronunciada sentencia. Andrés se partió algo mohíno, jurando de ir a buscar al valeroso don Quijote de la Mancha y contalle punto por punto lo que había pasado, y que se lo había de pagar con las setenas. Pero, con todo esto, él se partió llorando y su amo se quedó riendo. Y desta manera deshizo el agravio el valeroso don Quijote; el cual, contentísimo de lo sucedido, pareciéndole que había dado felicísimo y alto principio a sus caballerías, con gran satisfación de sí mismo iba caminando hacia su aldea, diciendo a media voz: — Bien te puedes llamar dichosa sobre cuantas hoy viven en la tierra, ¡oh sobre las bellas bella Dulcinea del Toboso!, pues te cupo en suerte tener sujeto y rendido a toda tu voluntad e talante a un tan valiente y tan nombrado caballero como lo es y será don Quijote de la Mancha, el cual, como todo el mundo sabe, ayer rescibió la orden de caballería, y hoy ha desfecho el mayor tuerto y agravio que formó la sinrazón y cometió la crueldad: hoy quitó el látigo de la mano a aquel despiadado enemigo que tan sin ocasión vapulaba a aquel delicado infante. En esto, llegó a un camino que en cuatro se dividía, y luego se le vino a la imaginación las encrucejadas donde los caballeros andantes se ponían a pensar cuál camino de aquéllos tomarían, y, por imitarlos, estuvo un rato quedo; y, al cabo de haberlo muy bien pensado, soltó la rienda a Rocinante, dejando a la voluntad del rocín la suya, el cual siguió su primer intento, que fue el irse camino de su caballeriza. Y, habiendo andado como dos millas, descubrió don Quijote un grande tropel de gente, que, como después se supo, eran unos mercaderes toledanos que iban a comprar seda a Murcia. Eran seis, y venían con sus quitasoles, con otros cuatro criados a caballo y tres mozos de mulas a pie. Apenas los divisó don Quijote, cuando se imaginó ser cosa de nueva aventura; y, por imitar en todo cuanto a él le parecía posible los pasos que había leído en sus libros, le pareció venir allí de molde uno que pensaba hacer. Y así, con gentil continente y denuedo, se afirmó bien en los estribos, apretó la lanza, llegó la adarga al pecho, y, puesto en la mitad del camino, estuvo esperando que aquellos caballeros andantes llegasen, que ya él por tales los tenía y juzgaba; y, cuando llegaron a trecho que se pudieron ver y oír, levantó don Quijote la voz, y con ademán arrogante dijo: — Todo el mundo se tenga, si todo el mundo no confiesa que no hay en el mundo todo doncella más hermosa que la emperatriz de la Mancha, la sin par Dulcinea del Toboso. Paráronse los mercaderes al son destas razones, y a ver la estraña figura del que las decía; y, por la figura y por las razones, luego echaron de ver la locura de su dueño; mas quisieron ver despacio en qué paraba aquella confesión que se les pedía, y uno dellos, que era un poco burlón y muy mucho discreto, le dijo: — Señor caballero, nosotros no conocemos quién sea esa buena señora que decís; mostrádnosla: que si ella fuere de tanta hermosura como significáis, de buena gana y sin apremio alguno confesaremos la verdad que por parte vuestra nos es pedida. — Si os la mostrara —replicó don Quijote—, ¿qué hiciérades vosotros en confesar una verdad tan notoria? La importancia está en que sin verla lo habéis de creer, confesar, afirmar, jurar y defender; donde no, conmigo sois en batalla, gente descomunal y soberbia. Que, ahora vengáis uno a uno, como pide la orden de caballería, ora todos juntos, como es costumbre y mala usanza de los de vuestra ralea, aquí os aguardo y espero, confiado en la razón que de mi parte tengo. — Señor caballero —replicó el mercader—, suplico a vuestra merced, en nombre de todos estos príncipes que aquí estamos, que, porque no encarguemos nuestras conciencias confesando una cosa por nosotros jamás vista ni oída, y más siendo tan en perjuicio de las emperatrices y reinas del Alcarria y Estremadura, que vuestra merced sea servido de mostrarnos algún retrato de esa señora, aunque sea tamaño como un grano de trigo; que por el hilo se sacará el ovillo, y quedaremos con esto satisfechos y seguros, y vuestra merced quedará contento y pagado; y aun creo que estamos ya tan de su parte que, aunque su retrato nos muestre que es tuerta de un ojo y que del otro le mana bermellón y piedra azufre, con todo eso, por complacer a vuestra merced, diremos en su favor todo lo que quisiere. — No le mana, canalla infame —respondió don Quijote, encendido en cólera—; no le mana, digo, eso que decís, sino ámbar y algalia entre algodones; y no es tuerta ni corcovada, sino más derecha que un huso de Guadarrama. Pero vosotros pagaréis la grande blasfemia que habéis dicho contra tamaña beldad como es la de mi señora. Y, en diciendo esto, arremetió con la lanza baja contra el que lo había dicho, con tanta furia y enojo que, si la buena suerte no hiciera que en la mitad del camino tropezara y cayera Rocinante, lo pasara mal el atrevido mercader. Cayó Rocinante, y fue rodando su amo una buena pieza por el campo; y, queriéndose levantar, jamás pudo: tal embarazo le causaban la lanza, adarga, espuelas y celada, con el peso de las antiguas armas. Y, entretanto que pugnaba por levantarse y no podía, estaba diciendo: — ¡Non fuyáis, gente cobarde; gente cautiva, atended!; que no por culpa mía, sino de mi caballo, estoy aquí tendido. Un mozo de mulas de los que allí venían, que no debía de ser muy bien intencionado, oyendo decir al pobre caído tantas arrogancias, no lo pudo sufrir sin darle la respuesta en las costillas. Y, llegándose a él, tomó la lanza, y, después de haberla hecho pedazos, con uno dellos comenzó a dar a nuestro don Quijote tantos palos que, a despecho y pesar de sus armas, le molió como cibera. Dábanle voces sus amos que no le diese tanto y que le dejase, pero estaba ya el mozo picado y no quiso dejar el juego hasta envidar todo el resto de su cólera; y, acudiendo por los demás trozos de la lanza, los acabó de deshacer sobre el miserable caído, que, con toda aquella tempestad de palos que sobre él vía, no cerraba la boca, amenazando al cielo y a la tierra, y a los malandrines, que tal le parecían. Cansóse el mozo, y los mercaderes siguieron su camino, llevando qué contar en todo él del pobre apaleado. El cual, después que se vio solo, tornó a probar si podía levantarse; pero si no lo pudo hacer cuando sano y bueno, ¿cómo lo haría molido y casi deshecho? Y aún se tenía por dichoso, pareciéndole que aquélla era propia desgracia de caballeros andantes, y toda la atribuía a la falta de su caballo, y no era posible levantarse, según tenía brumado todo el cuerpo. Capítulo V. Donde se prosigue la narración de la desgracia de nuestro caballero Viendo, pues, que, en efeto, no podía menearse, acordó de acogerse a su ordinario remedio, que era pensar en algún paso de sus libros; y trújole su locura a la memoria aquel de Valdovinos y del marqués de Mantua, cuando Carloto le dejó herido en la montiña, historia sabida de los niños, no ignorada de los mozos, celebrada y aun creída de los viejos; y, con todo esto, no más verdadera que los milagros de Mahoma. Ésta, pues, le pareció a él que le venía de molde para el paso en que se hallaba; y así, con muestras de grande sentimiento, se comenzó a volcar por la tierra y a decir con debilitado aliento lo mesmo que dicen decía el herido caballero del bosque: -¿Donde estás, señora mía, que no te duele mi mal? O no lo sabes, señora, o eres falsa y desleal. Y, desta manera, fue prosiguiendo el romance hasta aquellos versos que dicen: -¡Oh noble marqués de Mantua, mi tío y señor carnal! Y quiso la suerte que, cuando llegó a este verso, acertó a pasar por allí un labrador de su mesmo lugar y vecino suyo, que venía de llevar una carga de trigo al molino; el cual, viendo aquel hombre allí tendido, se llegó a él y le preguntó que quién era y qué mal sentía que tan tristemente se quejaba. Don Quijote creyó, sin duda, que aquél era el marqués de Mantua, su tío; y así, no le respondió otra cosa si no fue proseguir en su romance, donde le daba cuenta de su desgracia y de los amores del hijo del Emperante con su esposa, todo de la mesma manera que el romance lo canta. El labrador estaba admirado oyendo aquellos disparates; y, quitándole la visera, que ya estaba hecha pedazos de los palos, le limpió el rostro, que le tenía cubierto de polvo; y apenas le hubo limpiado, cuando le conoció y le dijo: — Señor Quijana —que así se debía de llamar cuando él tenía juicio y no había pasado de hidalgo sosegado a caballero andante—, ¿quién ha puesto a vuestra merced desta suerte? Pero él seguía con su romance a cuanto le preguntaba. Viendo esto el buen hombre, lo mejor que pudo le quitó el peto y espaldar, para ver si tenía alguna herida; pero no vio sangre ni señal alguna. Procuró levantarle del suelo, y no con poco trabajo le subió sobre su jumento, por parecer caballería más sosegada. Recogió las armas, hasta las astillas de la lanza, y liólas sobre Rocinante, al cual tomó de la rienda, y del cabestro al asno, y se encaminó hacia su pueblo, bien pensativo de oír los disparates que don Quijote decía; y no menos iba don Quijote, que, de puro molido y quebrantado, no se podía tener sobre el borrico, y de cuando en cuando daba unos suspiros que los ponía en el cielo; de modo que de nuevo obligó a que el labrador le preguntase le dijese qué mal sentía; y no parece sino que el diablo le traía a la memoria los cuentos acomodados a sus sucesos, porque, en aquel punto, olvidándose de Valdovinos, se acordó del moro Abindarráez, cuando el alcaide de Antequera, Rodrigo de Narváez, le prendió y llevó cautivo a su alcaidía. De suerte que, cuando el labrador le volvió a preguntar que cómo estaba y qué sentía, le respondió las mesmas palabras y razones que el cautivo Abencerraje respondía a Rodrigo de Narváez, del mesmo modo que él había leído la historia en La Diana, de Jorge de Montemayor, donde se escribe; aprovechándose della tan a propósito, que el labrador se iba dando al diablo de oír tanta máquina de necedades; por donde conoció que su vecino estaba loco, y dábale priesa a llegar al pueblo, por escusar el enfado que don Quijote le causaba con su larga arenga. Al cabo de lo cual, dijo: — Sepa vuestra merced, señor don Rodrigo de Narváez, que esta hermosa Jarifa que he dicho es ahora la linda Dulcinea del Toboso, por quien yo he hecho, hago y haré los más famosos hechos de caballerías que se han visto, vean ni verán en el mundo. A esto respondió el labrador: — Mire vuestra merced, señor, pecador de mí, que yo no soy don Rodrigo de Narváez, ni el marqués de Mantua, sino Pedro Alonso, su vecino; ni vuestra merced es Valdovinos, ni Abindarráez, sino el honrado hidalgo del señor Quijana. — Yo sé quién soy —respondió don Quijote—; y sé que puedo ser no sólo los que he dicho, sino todos los Doce Pares de Francia, y aun todos los Nueve de la Fama, pues a todas las hazañas que ellos todos juntos y cada uno por sí hicieron, se aventajarán las mías. En estas pláticas y en otras semejantes, llegaron al lugar a la hora que anochecía, pero el labrador aguardó a que fuese algo más noche, porque no viesen al molido hidalgo tan mal caballero. Llegada, pues, la hora que le pareció, entró en el pueblo, y en la casa de don Quijote, la cual halló toda alborotada; y estaban en ella el cura y el barbero del lugar, que eran grandes amigos de don Quijote, que estaba diciéndoles su ama a voces: — ¿Qué le parece a vuestra merced, señor licenciado Pero Pérez —que así se llamaba el cura—, de la desgracia de mi señor? Tres días ha que no parecen él, ni el rocín, ni la adarga, ni la lanza ni las armas. ¡Desventurada de mí!, que me doy a entender, y así es ello la verdad como nací para morir, que estos malditos libros de caballerías que él tiene y suele leer tan de ordinario le han vuelto el juicio; que ahora me acuerdo haberle oído decir muchas veces, hablando entre sí, que quería hacerse caballero andante e irse a buscar las aventuras por esos mundos. Encomendados sean a Satanás y a Barrabás tales libros, que así han echado a perder el más delicado entendimiento que había en toda la Mancha. La sobrina decía lo mesmo, y aun decía más: — Sepa, señor maese Nicolás —que éste era el nombre del barbero—, que muchas veces le aconteció a mi señor tío estarse leyendo en estos desalmados libros de desventuras dos días con sus noches, al cabo de los cuales, arrojaba el libro de las manos, y ponía mano a la espada y andaba a cuchilladas con las paredes; y cuando estaba muy cansado, decía que había muerto a cuatro gigantes como cuatro torres, y el sudor que sudaba del cansancio decía que era sangre de las feridas que había recebido en la batalla; y bebíase luego un gran jarro de agua fría, y quedaba sano y sosegado, diciendo que aquella agua era una preciosísima bebida que le había traído el sabio Esquife, un grande encantador y amigo suyo. Mas yo me tengo la culpa de todo, que no avisé a vuestras mercedes de los disparates de mi señor tío, para que lo remediaran antes de llegar a lo que ha llegado, y quemaran todos estos descomulgados libros, que tiene muchos, que bien merecen ser abrasados, como si fuesen de herejes. — Esto digo yo también —dijo el cura—, y a fee que no se pase el día de mañana sin que dellos no se haga acto público y sean condenados al fuego, porque no den ocasión a quien los leyere de hacer lo que mi buen amigo debe de haber hecho. Todo esto estaban oyendo el labrador y don Quijote, con que acabó de entender el labrador la enfermedad de su vecino; y así, comenzó a decir a voces: — Abran vuestras mercedes al señor Valdovinos y al señor marqués de Mantua, que viene malferido, y al señor moro Abindarráez, que trae cautivo el valeroso Rodrigo de Narváez, alcaide de Antequera. A estas voces salieron todos, y, como conocieron los unos a su amigo, las otras a su amo y tío, que aún no se había apeado del jumento, porque no podía, corrieron a abrazarle. Él dijo: — Ténganse todos, que vengo malferido por la culpa de mi caballo. Llévenme a mi lecho y llámese, si fuere posible, a la sabia Urganda, que cure y cate de mis feridas. — ¡Mirá, en hora maza —dijo a este punto el ama—, si me decía a mí bien mi corazón del pie que cojeaba mi señor! Suba vuestra merced en buen hora, que, sin que venga esa Hurgada, le sabremos aquí curar. ¡Malditos, digo, sean otra vez y otras ciento estos libros de caballerías, que tal han parado a vuestra merced! Lleváronle luego a la cama, y, catándole las feridas, no le hallaron ninguna; y él dijo que todo era molimiento, por haber dado una gran caída con Rocinante, su caballo, combatiéndose con diez jayanes, los más desaforados y atrevidos que se pudieran fallar en gran parte de la tierra. — ¡Ta, ta! —dijo el cura—. ¿Jayanes hay en la danza? Para mi santiguada, que yo los queme mañana antes que llegue la noche. Hiciéronle a don Quijote mil preguntas, y a ninguna quiso responder otra cosa sino que le diesen de comer y le dejasen dormir, que era lo que más le importaba. Hízose así, y el cura se informó muy a la larga del labrador del modo que había hallado a don Quijote. Él se lo contó todo, con los disparates que al hallarle y al traerle había dicho; que fue poner más deseo en el licenciado de hacer lo que otro día hizo, que fue llamar a su amigo el barbero maese Nicolás, con el cual se vino a casa de don Quijote, Capítulo VI. Del donoso y grande escrutinio que el cura y el barbero hicieron en la librería de nuestro ingenioso hidalgo el cual aún todavía dormía. Pidió las llaves, a la sobrina, del aposento donde estaban los libros, autores del daño, y ella se las dio de muy buena gana. Entraron dentro todos, y la ama con ellos, y hallaron más de cien cuerpos de libros grandes, muy bien encuadernados, y otros pequeños; y, así como el ama los vio, volvióse a salir del aposento con gran priesa, y tornó luego con una escudilla de agua bendita y un hisopo, y dijo: — Tome vuestra merced, señor licenciado: rocíe este aposento, no esté aquí algún encantador de los muchos que tienen estos libros, y nos encanten, en pena de las que les queremos dar echándolos del mundo. Causó risa al licenciado la simplicidad del ama, y mandó al barbero que le fuese dando de aquellos libros uno a uno, para ver de qué trataban, pues podía ser hallar algunos que no mereciesen castigo de fuego. — No —dijo la sobrina—, no hay para qué perdonar a ninguno, porque todos han sido los dañadores; mejor será arrojarlos por las ventanas al patio, y hacer un rimero dellos y pegarles fuego; y si no, llevarlos al corral, y allí se hará la hoguera, y no ofenderá el humo. Lo mismo dijo el ama: tal era la gana que las dos tenían de la muerte de aquellos inocentes; mas el cura no vino en ello sin primero leer siquiera los títulos. Y el primero que maese Nicolás le dio en las manos fue Los cuatro de Amadís de Gaula, y dijo el cura: — Parece cosa de misterio ésta; porque, según he oído decir, este libro fue el primero de caballerías que se imprimió en España, y todos los demás han tomado principio y origen déste; y así, me parece que, como a dogmatizador de una secta tan mala, le debemos, sin escusa alguna, condenar al fuego. — No, señor —dijo el barbero—, que también he oído decir que es el mejor de todos los libros que de este género se han compuesto; y así, como a único en su arte, se debe perdonar. — Así es verdad —dijo el cura—, y por esa razón se le otorga la vida por ahora. Veamos esotro que está junto a él. — Es —dijo el barbero— las Sergas de Esplandián, hijo legítimo de Amadís de Gaula. — Pues, en verdad —dijo el cura— que no le ha de valer al hijo la bondad del padre. Tomad, señora ama: abrid esa ventana y echadle al corral, y dé principio al montón de la hoguera que se ha de hacer. Hízolo así el ama con mucho contento, y el bueno de Esplandián fue volando al corral, esperando con toda paciencia el fuego que le amenazaba. — Adelante —dijo el cura. — Este que viene —dijo el barbero— es Amadís de Grecia; y aun todos los deste lado, a lo que creo, son del mesmo linaje de Amadís. — Pues vayan todos al corral —dijo el cura—; que, a trueco de quemar a la reina Pintiquiniestra, y al pastor Darinel, y a sus églogas, y a las endiabladas y revueltas razones de su autor, quemaré con ellos al padre que me engendró, si anduviera en figura de caballero andante. — De ese parecer soy yo —dijo el barbero. — Y aun yo —añadió la sobrina. — Pues así es —dijo el ama—, vengan, y al corral con ellos. Diéronselos, que eran muchos, y ella ahorró la escalera y dio con ellos por la ventana abajo. — ¿Quién es ese tonel? —dijo el cura. — Éste es —respondió el barbero— Don Olivante de Laura. — El autor de ese libro —dijo el cura— fue el mesmo que compuso a Jardín de flores; y en verdad que no sepa determinar cuál de los dos libros es más verdadero, o, por decir mejor, menos mentiroso; sólo sé decir que éste irá al corral por disparatado y arrogante. — Éste que se sigue es Florimorte de Hircania —dijo el barbero. — ¿Ahí está el señor Florimorte? —replicó el cura—. Pues a fe que ha de parar presto en el corral, a pesar de su estraño nacimiento y sonadas aventuras; que no da lugar a otra cosa la dureza y sequedad de su estilo. Al corral con él y con esotro, señora ama. — Que me place, señor mío —respondía ella; y con mucha alegría ejecutaba lo que le era mandado. — Éste es El Caballero Platir —dijo el barbero. — Antiguo libro es éste —dijo el cura—, y no hallo en él cosa que merezca venia. Acompañe a los demás sin réplica. Y así fue hecho. Abrióse otro libro y vieron que tenía por título El Caballero de la Cruz. — Por nombre tan santo como este libro tiene, se podía perdonar su ignorancia; mas también se suele decir: \"tras la cruz está el diablo\"; vaya al fuego. Tomando el barbero otro libro, dijo: — Éste es Espejo de caballerías. — Ya conozco a su merced —dijo el cura—. Ahí anda el señor Reinaldos de Montalbán con sus amigos y compañeros, más ladrones que Caco, y los doce Pares, con el verdadero historiador Turpín; y en verdad que estoy por condenarlos no más que a destierro perpetuo, siquiera porque tienen parte de la invención del famoso Mateo Boyardo, de donde también tejió su tela el cristiano poeta Ludovico Ariosto; al cual, si aquí le hallo, y que habla en otra lengua que la suya, no le guardaré respeto alguno; pero si habla en su idioma, le pondré sobre mi cabeza. — Pues yo le tengo en italiano —dijo el barbero—, mas no le entiendo. — Ni aun fuera bien que vos le entendiérades —respondió el cura—, y aquí le perdonáramos al señor capitán que no le hubiera traído a España y hecho castellano; que le quitó mucho de su natural valor, y lo mesmo harán todos aquellos que los libros de verso quisieren volver en otra lengua: que, por mucho cuidado que pongan y habilidad que muestren, jamás llegarán al punto que ellos tienen en su primer nacimiento. Digo, en efeto, que este libro, y todos los que se hallaren que tratan destas cosas de Francia, se echen y depositen en un pozo seco, hasta que con más acuerdo se vea lo que se ha de hacer dellos, ecetuando a un Bernardo del Carpio que anda por ahí y a otro llamado Roncesvalles; que éstos, en llegando a mis manos, han de estar en las del ama, y dellas en las del fuego, sin remisión alguna. Todo lo confirmó el barbero, y lo tuvo por bien y por cosa muy acertada, por entender que era el cura tan buen cristiano y tan amigo de la verdad, que no diría otra cosa por todas las del mundo. Y, abriendo otro libro, vio que era Palmerín de Oliva, y junto a él estaba otro que se llamaba Palmerín de Ingalaterra; lo cual visto por el licenciado, dijo: — Esa oliva se haga luego rajas y se queme, que aun no queden della las cenizas; y esa palma de Ingalaterra se guarde y se conserve como a cosa única, y se haga para ello otra caja como la que halló Alejandro en los despojos de Dario, que la diputó para guardar en ella las obras del poeta Homero. Este libro, señor compadre, tiene autoridad por dos cosas: la una, porque él por sí es muy bueno, y la otra, porque es fama que le compuso un discreto rey de Portugal. Todas las aventuras del castillo de Miraguarda son bonísimas y de grande artificio; las razones, cortesanas y claras, que guardan y miran el decoro del que habla con mucha propriedad y entendimiento. Digo, pues, salvo vuestro buen parecer, señor maese Nicolás, que éste y Amadís de Gaula queden libres del fuego, y todos los demás, sin hacer más cala y cata, perezcan. — No, señor compadre —replicó el barbero—; que éste que aquí tengo es el afamado Don Belianís. — Pues ése —replicó el cura—, con la segunda, tercera y cuarta parte, tienen necesidad de un poco de ruibarbo para purgar la demasiada cólera suya, y es menester quitarles todo aquello del castillo de la Fama y otras impertinencias de más importancia, para lo cual se les da término ultramarino, y como se enmendaren, así se usará con ellos de misericordia o de justicia; y en tanto, tenedlos vos, compadre, en vuestra casa, mas no los dejéis leer a ninguno. — Que me place —respondió el barbero. Y, sin querer cansarse más en leer libros de caballerías, mandó al ama que tomase todos los grandes y diese con ellos en el corral. No se dijo a tonta ni a sorda, sino a quien tenía más gana de quemallos que de echar una tela, por grande y delgada que fuera; y, asiendo casi ocho de una vez, los arrojó por la ventana. Por tomar muchos juntos, se le cayó uno a los pies del barbero, que le tomó gana de ver de quién era, y vio que decía: Historia del famoso caballero Tirante el Blanco. — ¡Válame Dios! —dijo el cura, dando una gran voz—. ¡Que aquí esté Tirante el Blanco! Dádmele acá, compadre; que hago cuenta que he hallado en él un tesoro de contento y una mina de pasatiempos. Aquí está don Quirieleisón de Montalbán, valeroso caballero, y su hermano Tomás de Montalbán, y el caballero Fonseca, con la batalla que el valiente de Tirante hizo con el alano, y las agudezas de la doncella Placerdemivida, con los amores y embustes de la viuda Reposada, y la señora Emperatriz, enamorada de Hipólito, su escudero. Dígoos verdad, señor compadre, que, por su estilo, es éste el mejor libro del mundo: aquí comen los caballeros, y duermen, y mueren en sus camas, y hacen testamento antes de su muerte, con estas cosas de que todos los demás libros deste género carecen. Con todo eso, os digo que merecía el que le compuso, pues no hizo tantas necedades de industria, que le echaran a galeras por todos los días de su vida. Llevadle a casa y leedle, y veréis que es verdad cuanto dél os he dicho. — Así será —respondió el barbero—; pero, ¿qué haremos destos pequeños libros que quedan? — Éstos —dijo el cura— no deben de ser de caballerías, sino de poesía. Y abriendo uno, vio que era La Diana, de Jorge de Montemayor, y dijo, creyendo que todos los demás eran del mesmo género: — Éstos no merecen ser quemados, como los demás, porque no hacen ni harán el daño que los de caballerías han hecho; que son libros de entendimiento, sin perjuicio de tercero. — ¡Ay señor! —dijo la sobrina—, bien los puede vuestra merced mandar quemar, como a los demás, porque no sería mucho que, habiendo sanado mi señor tío de la enfermedad caballeresca, leyendo éstos, se le antojase de hacerse pastor y andarse por los bosques y prados cantando y tañendo; y, lo que sería peor, hacerse poeta; que, según dicen, es enfermedad incurable y pegadiza. — Verdad dice esta doncella —dijo el cura—, y será bien quitarle a nuestro amigo este tropiezo y ocasión delante. Y, pues comenzamos por La Diana de Montemayor, soy de parecer que no se queme, sino que se le quite todo aquello que trata de la sabia Felicia y de la agua encantada, y casi todos los versos mayores, y quédesele en hora buena la prosa, y la honra de ser primero en semejantes libros. — Éste que se sigue —dijo el barbero— es La Diana llamada segunda del Salmantino; y éste, otro que tiene el mesmo nombre, cuyo autor es Gil Polo. — Pues la del Salmantino —respondió el cura—, acompañe y acreciente el número de los condenados al corral, y la de Gil Polo se guarde como si fuera del mesmo Apolo; y pase adelante, señor compadre, y démonos prisa, que se va haciendo tarde. — Este libro es —dijo el barbero, abriendo otro— Los diez libros de Fortuna de Amor, compuestos por Antonio de Lofraso, poeta sardo. — Por las órdenes que recebí —dijo el cura—, que, desde que Apolo fue Apolo, y las musas musas, y los poetas poetas, tan gracioso ni tan disparatado libro como ése no se ha compuesto, y que, por su camino, es el mejor y el más único de cuantos deste género han salido a la luz del mundo; y el que no le ha leído puede hacer cuenta que no ha leído jamás cosa de gusto. Dádmele acá, compadre, que precio más haberle hallado que si me dieran una sotana de raja de Florencia. Púsole aparte con grandísimo gusto, y el barbero prosiguió diciendo: — Estos que se siguen son El Pastor de Iberia, Ninfas de Henares y Desengaños de celos. — Pues no hay más que hacer —dijo el cura—, sino entregarlos al brazo seglar del ama; y no se me pregunte el porqué, que sería nunca acabar. — Este que viene es El Pastor de Fílida. — No es ése pastor —dijo el cura—, sino muy discreto cortesano; guárdese como joya preciosa. — Este grande que aquí viene se intitula —dijo el barbero— Tesoro de varias poesías. — Como ellas no fueran tantas —dijo el cura—, fueran más estimadas; menester es que este libro se escarde y limpie de algunas bajezas que entre sus grandezas tiene. Guárdese, porque su autor es amigo mío, y por respeto de otras más heroicas y levantadas obras que ha escrito. — Éste es —siguió el barbero— El Cancionero de López Maldonado. — También el autor de ese libro —replicó el cura— es grande amigo mío, y sus versos en su boca admiran a quien los oye; y tal es la suavidad de la voz con que los canta, que encanta. Algo largo es en las églogas, pero nunca lo bueno fue mucho: guárdese con los escogidos. Pero, ¿qué libro es ese que está junto a él? — La Galatea, de Miguel de Cervantes —dijo el barbero. — Muchos años ha que es grande amigo mío ese Cervantes, y sé que es más versado en desdichas que en versos. Su libro tiene algo de buena invención; propone algo, y no concluye nada: es menester esperar la segunda parte que promete; quizá con la emienda alcanzará del todo la misericordia que ahora se le niega; y, entre tanto que esto se ve, tenedle recluso en vuestra posada, señor compadre. — Que me place —respondió el barbero—. Y aquí vienen tres, todos juntos: La Araucana, de don Alonso de Ercilla; La Austríada, de Juan Rufo, jurado de Córdoba, y El Monserrato, de Cristóbal de Virués, poeta valenciano. — Todos esos tres libros —dijo el cura— son los mejores que, en verso heroico, en lengua castellana están escritos, y pueden competir con los más famosos de Italia: guárdense como las más ricas prendas de poesía que tiene España. Cansóse el cura de ver más libros; y así, a carga cerrada, quiso que todos los demás se quemasen; pero ya tenía abierto uno el barbero, que se llamaba Las lágrimas de Angélica. — Lloráralas yo —dijo el cura en oyendo el nombre— si tal libro hubiera mandado quemar; porque su autor fue uno de los famosos poetas del mundo, no sólo de España, y fue felicísimo en la tradución de algunas fábulas de Ovidio. Capítulo VII. De la segunda salida de nuestro buen caballero don Quijote de la Mancha Estando en esto, comenzó a dar voces don Quijote, diciendo: — Aquí, aquí, valerosos caballeros; aquí es menester mostrar la fuerza de vuestros valerosos brazos, que los cortesanos llevan lo mejor del torneo. Por acudir a este ruido y estruendo, no se pasó adelante con el escrutinio de los demás libros que quedaban; y así, se cree que fueron al fuego, sin ser vistos ni oídos, La Carolea y León de España, con Los Hechos del Emperador, compuestos por don Luis de Ávila, que, sin duda, debían de estar entre los que quedaban; y quizá, si el cura los viera, no pasaran por tan rigurosa sentencia. Cuando llegaron a don Quijote, ya él estaba levantado de la cama, y proseguía en sus voces y en sus desatinos, dando cuchilladas y reveses a todas partes, estando tan despierto como si nunca hubiera dormido. Abrazáronse con él, y por fuerza le volvieron al lecho; y, después que hubo sosegado un poco, volviéndose a hablar con el cura, le dijo: — Por cierto, señor arzobispo Turpín, que es gran mengua de los que nos llamamos doce Pares dejar, tan sin más ni más, llevar la vitoria deste torneo a los caballeros cortesanos, habiendo nosotros los aventureros ganado el prez en los tres días antecedentes. — Calle vuestra merced, señor compadre —dijo el cura—, que Dios será servido que la suerte se mude, y que lo que hoy se pierde se gane mañana; y atienda vuestra merced a su salud por agora, que me parece que debe de estar demasiadamente cansado, si ya no es que está malferido. — Ferido no —dijo don Quijote—, pero molido y quebrantado, no hay duda en ello; porque aquel bastardo de don Roldán me ha molido a palos con el tronco de una encina, y todo de envidia, porque ve que yo solo soy el opuesto de sus valentías. Mas no me llamaría yo Reinaldos de Montalbán si, en levantándome deste lecho, no me lo pagare, a pesar de todos sus encantamentos; y, por agora, tráiganme de yantar, que sé que es lo que más me hará al caso, y quédese lo del vengarme a mi cargo. Hiciéronlo ansí: diéronle de comer, y quedóse otra vez dormido, y ellos, admirados de su locura. Aquella noche quemó y abrasó el ama cuantos libros había en el corral y en toda la casa, y tales debieron de arder que merecían guardarse en perpetuos archivos; mas no lo permitió su suerte y la pereza del escrutiñador; y así, se cumplió el refrán en ellos de que pagan a las veces justos por pecadores. Uno de los remedios que el cura y el barbero dieron, por entonces, para el mal de su amigo, fue que le murasen y tapiasen el aposento de los libros, porque cuando se levantase no los hallase —quizá quitando la causa, cesaría el efeto—, y que dijesen que un encantador se los había llevado, y el aposento y todo; y así fue hecho con mucha presteza. De allí a dos días se levantó don Quijote, y lo primero que hizo fue ir a ver sus libros; y, como no hallaba el aposento donde le había dejado, andaba de una en otra parte buscándole. Llegaba adonde solía tener la puerta, y tentábala con las manos, y volvía y revolvía los ojos por todo, sin decir palabra; pero, al cabo de una buena pieza, preguntó a su ama que hacia qué parte estaba el aposento de sus libros. El ama, que ya estaba bien advertida de lo que había de responder, le dijo: — ¿Qué aposento, o qué nada, busca vuestra merced? Ya no hay aposento ni libros en esta casa, porque todo se lo llevó el mesmo diablo. — No era diablo —replicó la sobrina—, sino un encantador que vino sobre una nube una noche, después del día que vuestra merced de aquí se partió, y, apeándose de una sierpe en que venía caballero, entró en el aposento, y no sé lo que se hizo dentro, que a cabo de poca pieza salió volando por el tejado, y dejó la casa llena de humo; y, cuando acordamos a mirar lo que dejaba hecho, no vimos libro ni aposento alguno; sólo se nos acuerda muy bien a mí y al ama que, al tiempo del partirse aquel mal viejo, dijo en altas voces que, por enemistad secreta que tenía al dueño de aquellos libros y aposento, dejaba hecho el daño en aquella casa que después se vería. Dijo también que se llamaba el sabio Muñatón. — Frestón diría —dijo don Quijote. — No sé —respondió el ama— si se llamaba Frestón o Fritón; sólo sé que acabó en tón su nombre. — Así es —dijo don Quijote—; que ése es un sabio encantador, grande enemigo mío, que me tiene ojeriza, porque sabe por sus artes y letras que tengo de venir, andando los tiempos, a pelear en singular batalla con un caballero a quien él favorece, y le tengo de vencer, sin que él lo pueda estorbar, y por esto procura hacerme todos los sinsabores que puede; y mándole yo que mal podrá él contradecir ni evitar lo que por el cielo está ordenado. — ¿Quién duda de eso? —dijo la sobrina—. Pero, ¿quién le mete a vuestra merced, señor tío, en esas pendencias? ¿No será mejor estarse pacífico en su casa y no irse por el mundo a buscar pan de trastrigo, sin considerar que muchos van por lana y vuelven tresquilados? — ¡Oh sobrina mía —respondió don Quijote—, y cuán mal que estás en la cuenta! Primero que a mí me tresquilen, tendré peladas y quitadas las barbas a cuantos imaginaren tocarme en la punta de un solo cabello. No quisieron las dos replicarle más, porque vieron que se le encendía la cólera. Es, pues, el caso que él estuvo quince días en casa muy sosegado, sin dar muestras de querer segundar sus primeros devaneos, en los cuales días pasó graciosísimos cuentos con sus dos compadres el cura y el barbero, sobre que él decía que la cosa de que más necesidad tenía el mundo era de caballeros andantes y de que en él se resucitase la caballería andantesca. El cura algunas veces le contradecía y otras concedía, porque si no guardaba este artificio, no había poder averiguarse con él. En este tiempo, solicitó don Quijote a un labrador vecino suyo, hombre de bien —si es que este título se puede dar al que es pobre—, pero de muy poca sal en la mollera. En resolución, tanto le dijo, tanto le persuadió y prometió, que el pobre villano se determinó de salirse con él y servirle de escudero. Decíale, entre otras cosas, don Quijote que se dispusiese a ir con él de buena gana, porque tal vez le podía suceder aventura que ganase, en quítame allá esas pajas, alguna ínsula, y le dejase a él por gobernador della. Con estas promesas y otras tales, Sancho Panza, que así se llamaba el labrador, dejó su mujer y hijos y asentó por escudero de su vecino. Dio luego don Quijote orden en buscar dineros; y, vendiendo una cosa y empeñando otra, y malbaratándolas todas, llegó una razonable cantidad. Acomodóse asimesmo de una rodela, que pidió prestada a un su amigo, y, pertrechando su rota celada lo mejor que pudo, avisó a su escudero Sancho del día y la hora que pensaba ponerse en camino, para que él se acomodase de lo que viese que más le era menester. Sobre todo le encargó que llevase alforjas; e dijo que sí llevaría, y que ansimesmo pensaba llevar un asno que tenía muy bueno, porque él no estaba duecho a andar mucho a pie. En lo del asno reparó un poco don Quijote, imaginando si se le acordaba si algún caballero andante había traído escudero caballero asnalmente, pero nunca le vino alguno a la memoria; mas, con todo esto, determinó que le llevase, con presupuesto de acomodarle de más honrada caballería en habiendo ocasión para ello, quitándole el caballo al primer descortés caballero que topase. Proveyóse de camisas y de las demás cosas que él pudo, conforme al consejo que el ventero le había dado; todo lo cual hecho y cumplido, sin despedirse Panza de sus hijos y mujer, ni don Quijote de su ama y sobrina, una noche se salieron del lugar sin que persona los viese; en la cual caminaron tanto, que al amanecer se tuvieron por seguros de que no los hallarían aunque los buscasen. Iba Sancho Panza sobre su jumento como un patriarca, con sus alforjas y su bota, y con mucho deseo de verse ya gobernador de la ínsula que su amo le había prometido. Acertó don Quijote a tomar la misma derrota y camino que el que él había tomado en su primer viaje, que fue por el campo de Montiel, por el cual caminaba con menos pesadumbre que la vez pasada, porque, por ser la hora de la mañana y herirles a soslayo los rayos del sol, no les fatigaban. Dijo en esto Sancho Panza a su amo: — Mire vuestra merced, señor caballero andante, que no se le olvide lo que de la ínsula me tiene prometido; que yo la sabré gobernar, por grande que sea. A lo cual le respondió don Quijote: — Has de saber, amigo Sancho Panza, que fue costumbre muy usada de los caballeros andantes antiguos hacer gobernadores a sus escuderos de las ínsulas o reinos que ganaban, y yo tengo determinado de que por mí no falte tan agradecida usanza; antes, pienso aventajarme en ella: porque ellos algunas veces, y quizá las más, esperaban a que sus escuderos fuesen viejos; y, ya después de hartos de servir y de llevar malos días y peores noches, les daban algún título de conde, o, por lo mucho, de marqués, de algún valle o provincia de poco más a menos; pero, si tú vives y yo vivo, bien podría ser que antes de seis días ganase yo tal reino que tuviese otros a él adherentes, que viniesen de molde para coronarte por rey de uno dellos. Y no lo tengas a mucho, que cosas y casos acontecen a los tales caballeros, por modos tan nunca vistos ni pensados, que con facilidad te podría dar aún más de lo que te prometo. — De esa manera —respondió Sancho Panza—, si yo fuese rey por algún milagro de los que vuestra merced dice, por lo menos, Juana Gutiérrez, mi oíslo, vendría a ser reina, y mis hijos infantes. — Pues, ¿quién lo duda? —respondió don Quijote. — Yo lo dudo —replicó Sancho Panza—; porque tengo para mí que, aunque lloviese Dios reinos sobre la tierra, ninguno asentaría bien sobre la cabeza de Mari Gutiérrez. Sepa, señor, que no vale dos maravedís para reina; condesa le caerá mejor, y aun Dios y ayuda. — Encomiéndalo tú a Dios, Sancho —respondió don Quijote—, que Él dará lo que más le convenga, pero no apoques tu ánimo tanto, que te vengas a contentar con menos que con ser adelantado. — No lo haré, señor mío —respondió Sancho—; y más teniendo tan principal amo en vuestra merced, que me sabrá dar todo aquello que me esté bien y yo pueda llevar. Capítulo VIII. Del buen suceso que el valeroso don Quijote tuvo en la espantable y jamás imaginada aventura de los molinos de viento, con otros sucesos dignos de felice recordación En esto, descubrieron treinta o cuarenta molinos de viento que hay en aquel campo; y, así como don Quijote los vio, dijo a su escudero: — La ventura va guiando nuestras cosas mejor de lo que acertáramos a desear, porque ves allí, amigo Sancho Panza, donde se descubren treinta, o pocos más, desaforados gigantes, con quien pienso hacer batalla y quitarles a todos las vidas, con cuyos despojos comenzaremos a enriquecer; que ésta es buena guerra, y es gran servicio de Dios quitar tan mala simiente de sobre la faz de la tierra. — ¿Qué gigantes? —dijo Sancho Panza. — Aquellos que allí ves —respondió su amo— de los brazos largos, que los suelen tener algunos de casi dos leguas. — Mire vuestra merced —respondió Sancho— que aquellos que allí se parecen no son gigantes, sino molinos de viento, y lo que en ellos parecen brazos son las aspas, que, volteadas del viento, hacen andar la piedra del molino. — Bien parece —respondió don Quijote— que no estás cursado en esto de las aventuras: ellos son gigantes; y si tienes miedo, quítate de ahí, y ponte en oración en el espacio que yo voy a entrar con ellos en fiera y desigual batalla. Y, diciendo esto, dio de espuelas a su caballo Rocinante, sin atender a las voces que su escudero Sancho le daba, advirtiéndole que, sin duda alguna, eran molinos de viento, y no gigantes, aquellos que iba a acometer. Pero él iba tan puesto en que eran gigantes, que ni oía las voces de su escudero Sancho ni echaba de ver, aunque estaba ya bien cerca, lo que eran; antes, iba diciendo en voces altas: — Non fuyades, cobardes y viles criaturas, que un solo caballero es el que os acomete. Levantóse en esto un poco de viento y las grandes aspas comenzaron a moverse, lo cual visto por don Quijote, dijo: — Pues, aunque mováis más brazos que los del gigante Briareo, me lo habéis de pagar. Y, en diciendo esto, y encomendándose de todo corazón a su señora Dulcinea, pidiéndole que en tal trance le socorriese, bien cubierto de su rodela, con la lanza en el ristre, arremetió a todo el galope de Rocinante y embistió con el primero molino que estaba delante; y, dándole una lanzada en el aspa, la volvió el viento con tanta furia que hizo la lanza pedazos, llevándose tras sí al caballo y al caballero, que fue rodando muy maltrecho por el campo. Acudió Sancho Panza a socorrerle, a todo el correr de su asno, y cuando llegó halló que no se podía menear: tal fue el golpe que dio con él Rocinante. — ¡Válame Dios! —dijo Sancho—. ¿No le dije yo a vuestra merced que mirase bien lo que hacía, que no eran sino molinos de viento, y no lo podía ignorar sino quien llevase otros tales en la cabeza? — Calla, amigo Sancho —respondió don Quijote—, que las cosas de la guerra, más que otras, están sujetas a continua mudanza; cuanto más, que yo pienso, y es así verdad, que aquel sabio Frestón que me robó el aposento y los libros ha vuelto estos gigantes en molinos por quitarme la gloria de su vencimiento: tal es la enemistad que me tiene; mas, al cabo al cabo, han de poder poco sus malas artes contra la bondad de mi espada. — Dios lo haga como puede —respondió Sancho Panza. Y, ayudándole a levantar, tornó a subir sobre Rocinante, que medio despaldado estaba. Y, hablando en la pasada aventura, siguieron el camino del Puerto Lápice, porque allí decía don Quijote que no era posible dejar de hallarse muchas y diversas aventuras, por ser lugar muy pasajero; sino que iba muy pesaroso por haberle faltado la lanza; y, diciéndoselo a su escudero, le dijo: — Yo me acuerdo haber leído que un caballero español, llamado Diego Pérez de Vargas, habiéndosele en una batalla roto la espada, desgajó de una encina un pesado ramo o tronco, y con él hizo tales cosas aquel día, y machacó tantos moros, que le quedó por sobrenombre Machuca, y así él como sus decendientes se llamaron, desde aquel día en adelante, Vargas y Machuca. Hete dicho esto, porque de la primera encina o roble que se me depare pienso desgajar otro tronco tal y tan bueno como aquél, que me imagino y pienso hacer con él tales hazañas, que tú te tengas por bien afortunado de haber merecido venir a vellas y a ser testigo de cosas que apenas podrán ser creídas. — A la mano de Dios —dijo Sancho—; yo lo creo todo así como vuestra merced lo dice; pero enderécese un poco, que parece que va de medio lado, y debe de ser del molimiento de la caída. — Así es la verdad —respondió don Quijote—; y si no me quejo del dolor, es porque no es dado a los caballeros andantes quejarse de herida alguna, aunque se le salgan las tripas por ella. — Si eso es así, no tengo yo qué replicar —respondió Sancho—, pero sabe Dios si yo me holgara que vuestra merced se quejara cuando alguna cosa le doliera. De mí sé decir que me he de quejar del más pequeño dolor que tenga, si ya no se entiende también con los escuderos de los caballeros andantes eso del no quejarse. No se dejó de reír don Quijote de la simplicidad de su escudero; y así, le declaró que podía muy bien quejarse, como y cuando quisiese, sin gana o con ella; que hasta entonces no había leído cosa en contrario en la orden de caballería. Díjole Sancho que mirase que era hora de comer. Respondióle su amo que por entonces no le hacía menester; que comiese él cuando se le antojase. Con esta licencia, se acomodó Sancho lo mejor que pudo sobre su jumento, y, sacando de las alforjas lo que en ellas había puesto, iba caminando y comiendo detrás de su amo muy de su espacio, y de cuando en cuando empinaba la bota, con tanto gusto, que le pudiera envidiar el más regalado bodegonero de Málaga. Y, en tanto que él iba de aquella manera menudeando tragos, no se le acordaba de ninguna promesa que su amo le hubiese hecho, ni tenía por ningún trabajo, sino por mucho descanso, andar buscando las aventuras, por peligrosas que fuesen. En resolución, aquella noche la pasaron entre unos árboles, y del uno dellos desgajó don Quijote un ramo seco que casi le podía servir de lanza, y puso en él el hierro que quitó de la que se le había quebrado. Toda aquella noche no durmió don Quijote, pensando en su señora Dulcinea, por acomodarse a lo que había leído en sus libros, cuando los caballeros pasaban sin dormir muchas noches en las florestas y despoblados, entretenidos con las memorias de sus señoras. No la pasó ansí Sancho Panza, que, como tenía el estómago lleno, y no de agua de chicoria, de un sueño se la llevó toda; y no fueran parte para despertarle, si su amo no lo llamara, los rayos del sol, que le daban en el rostro, ni el canto de las aves, que, muchas y muy regocijadamente, la venida del nuevo día saludaban. Al levantarse dio un tiento a la bota, y hallóla algo más flaca que la noche antes; y afligiósele el corazón, por parecerle que no llevaban camino de remediar tan presto su falta. No quiso desayunarse don Quijote, porque, como está dicho, dio en sustentarse de sabrosas memorias. Tornaron a su comenzado camino del Puerto Lápice, y a obra de las tres del día le descubrieron. — Aquí —dijo, en viéndole, don Quijote— podemos, hermano Sancho Panza, meter las manos hasta los codos en esto que llaman aventuras. Mas advierte que, aunque me veas en los mayores peligros del mundo, no has de poner mano a tu espada para defenderme, si ya no vieres que los que me ofenden es canalla y gente baja, que en tal caso bien puedes ayudarme; pero si fueren caballeros, en ninguna manera te es lícito ni concedido por las leyes de caballería que me ayudes, hasta que seas armado caballero. — Por cierto, señor —respondió Sancho—, que vuestra merced sea muy bien obedicido en esto; y más, que yo de mío me soy pacífico y enemigo de meterme en ruidos ni pendencias. Bien es verdad que, en lo que tocare a defender mi persona, no tendré mucha cuenta con esas leyes, pues las divinas y humanas permiten que cada uno se defienda de quien quisiere agraviarle. — No digo yo menos —respondió don Quijote—; pero, en esto de ayudarme contra caballeros, has de tener a raya tus naturales ímpetus. — Digo que así lo haré —respondió Sancho—, y que guardaré ese preceto tan bien como el día del domingo. Estando en estas razones, asomaron por el camino dos frailes de la orden de San Benito, caballeros sobre dos dromedarios: que no eran más pequeñas dos mulas en que venían. Traían sus antojos de camino y sus quitasoles. Detrás dellos venía un coche, con cuatro o cinco de a caballo que le acompañaban y dos mozos de mulas a pie. Venía en el coche, como después se supo, una señora vizcaína, que iba a Sevilla, donde estaba su marido, que pasaba a las Indias con un muy honroso cargo. No venían los frailes con ella, aunque iban el mesmo camino; mas, apenas los divisó don Quijote, cuando dijo a su escudero: — O yo me engaño, o ésta ha de ser la más famosa aventura que se haya visto; porque aquellos bultos negros que allí parecen deben de ser, y son sin duda, algunos encantadores que llevan hurtada alguna princesa en aquel coche, y es menester deshacer este tuerto a todo mi poderío. — Peor será esto que los molinos de viento —dijo Sancho—. Mire, señor, que aquéllos son frailes de San Benito, y el coche debe de ser de alguna gente pasajera. Mire que digo que mire bien lo que hace, no sea el diablo que le engañe. — Ya te he dicho, Sancho —respondió don Quijote—, que sabes poco de achaque de aventuras; lo que yo digo es verdad, y ahora lo verás. Y, diciendo esto, se adelantó y se puso en la mitad del camino por donde los frailes venían, y, en llegando tan cerca que a él le pareció que le podrían oír lo que dijese, en alta voz dijo: — Gente endiablada y descomunal, dejad luego al punto las altas princesas que en ese coche lleváis forzadas; si no, aparejaos a recebir presta muerte, por justo castigo de vuestras malas obras. Detuvieron los frailes las riendas, y quedaron admirados, así de la figura de don Quijote como de sus razones, a las cuales respondieron: — Señor caballero, nosotros no somos endiablados ni descomunales, sino dos religiosos de San Benito que vamos nuestro camino, y no sabemos si en este coche vienen, o no, ningunas forzadas princesas. — Para conmigo no hay palabras blandas, que ya yo os conozco, fementida canalla —dijo don Quijote. Y, sin esperar más respuesta, picó a Rocinante y, la lanza baja, arremetió contra el primero fraile, con tanta furia y denuedo que, si el fraile no se dejara caer de la mula, él le hiciera venir al suelo mal de su grado, y aun malferido, si no cayera muerto. El segundo religioso, que vio del modo que trataban a su compañero, puso piernas al castillo de su buena mula, y comenzó a correr por aquella campaña, más ligero que el mesmo viento. Sancho Panza, que vio en el suelo al fraile, apeándose ligeramente de su asno, arremetió a él y le comenzó a quitar los hábitos. Llegaron en esto dos mozos de los frailes y preguntáronle que por qué le desnudaba. Respondióles Sancho que aquello le tocaba a él ligítimamente, como despojos de la batalla que su señor don Quijote había ganado. Los mozos, que no sabían de burlas, ni entendían aquello de despojos ni batallas, viendo que ya don Quijote estaba desviado de allí, hablando con las que en el coche venían, arremetieron con Sancho y dieron con él en el suelo; y, sin dejarle pelo en las barbas, le molieron a coces y le dejaron tendido en el suelo sin aliento ni sentido. Y, sin detenerse un punto, tornó a subir el fraile, todo temeroso y acobardado y sin color en el rostro; y, cuando se vio a caballo, picó tras su compañero, que un buen espacio de allí le estaba aguardando, y esperando en qué paraba aquel sobresalto; y, sin querer aguardar el fin de todo aquel comenzado suceso, siguieron su camino, haciéndose más cruces que si llevaran al diablo a las espaldas. Don Quijote estaba, como se ha dicho, hablando con la señora del coche, diciéndole: — La vuestra fermosura, señora mía, puede facer de su persona lo que más le viniere en talante, porque ya la soberbia de vuestros robadores yace por el suelo, derribada por este mi fuerte brazo; y, porque no penéis por saber el nombre de vuestro libertador, sabed que yo me llamo don Quijote de la Mancha, caballero andante y aventurero, y cautivo de la sin par y hermosa doña Dulcinea del Toboso; y, en pago del beneficio que de mí habéis recebido, no quiero otra cosa sino que volváis al Toboso, y que de mi parte os presentéis ante esta señora y le digáis lo que por vuestra libertad he fecho. Todo esto que don Quijote decía escuchaba un escudero de los que el coche acompañaban, que era vizcaíno; el cual, viendo que no quería dejar pasar el coche adelante, sino que decía que luego había de dar la vuelta al Toboso, se fue para don Quijote y, asiéndole de la lanza, le dijo, en mala lengua castellana y peor vizcaína, desta manera: — Anda, caballero que mal andes; por el Dios que crióme, que, si no dejas coche, así te matas como estás ahí vizcaíno. Entendióle muy bien don Quijote, y con mucho sosiego le respondió: — Si fueras caballero, como no lo eres, ya yo hubiera castigado tu sandez y atrevimiento, cautiva criatura. A lo cual replicó el vizcaíno: — ¿Yo no caballero? Juro a Dios tan mientes como cristiano. Si lanza arrojas y espada sacas, ¡el agua cuán presto verás que al gato llevas! Vizcaíno por tierra, hidalgo por mar, hidalgo por el diablo; y mientes que mira si otra dices cosa. — ¡Ahora lo veredes, dijo Agrajes! —respondió don Quijote. Y, arrojando la lanza en el suelo, sacó su espada y embrazó su rodela, y arremetió al vizcaíno con determinación de quitarle la vida. El vizcaíno, que así le vio venir, aunque quisiera apearse de la mula, que, por ser de las malas de alquiler, no había que fiar en ella, no pudo hacer otra cosa sino sacar su espada; pero avínole bien que se halló junto al coche, de donde pudo tomar una almohada que le sirvió de escudo, y luego se fueron el uno para el otro, como si fueran dos mortales enemigos. La demás gente quisiera ponerlos en paz, mas no pudo, porque decía el vizcaíno en sus mal trabadas razones que si no le dejaban acabar su batalla, que él mismo había de matar a su ama y a toda la gente que se lo estorbase. La señora del coche, admirada y temerosa de lo que veía, hizo al cochero que se desviase de allí algún poco, y desde lejos se puso a mirar la rigurosa contienda, en el discurso de la cual dio el vizcaíno una gran cuchillada a don Quijote encima de un hombro, por encima de la rodela, que, a dársela sin defensa, le abriera hasta la cintura. Don Quijote, que sintió la pesadumbre de aquel desaforado golpe, dio una gran voz, diciendo: — ¡Oh señora de mi alma, Dulcinea, flor de la fermosura, socorred a este vuestro caballero, que, por satisfacer a la vuestra mucha bondad, en este riguroso trance se halla! El decir esto, y el apretar la espada, y el cubrirse bien de su rodela, y el arremeter al vizcaíno, todo fue en un tiempo, llevando determinación de aventurarlo todo a la de un golpe solo. El vizcaíno, que así le vio venir contra él, bien entendió por su denuedo su coraje, y determinó de hacer lo mesmo que don Quijote; y así, le aguardó bien cubierto de su almohada, sin poder rodear la mula a una ni a otra parte; que ya, de puro cansada y no hecha a semejantes niñerías, no podía dar un paso. Venía, pues, como se ha dicho, don Quijote contra el cauto vizcaíno, con la espada en alto, con determinación de abrirle por medio, y el vizcaíno le aguardaba ansimesmo levantada la espada y aforrado con su almohada, y todos los circunstantes estaban temerosos y colgados de lo que había de suceder de aquellos tamaños golpes con que se amenazaban; y la señora del coche y las demás criadas suyas estaban haciendo mil votos y ofrecimientos a todas las imágenes y casas de devoción de España, porque Dios librase a su escudero y a ellas de aquel tan grande peligro en que se hallaban. Pero está el daño de todo esto que en este punto y término deja pendiente el autor desta historia esta batalla, disculpándose que no halló más escrito destas hazañas de don Quijote de las que deja referidas. Bien es verdad que el segundo autor desta obra no quiso creer que tan curiosa historia estuviese entregada a las leyes del olvido, ni que hubiesen sido tan poco curiosos los ingenios de la Mancha"};
export const TEST_TEXT = "I am by birth a Genevese, and my family is one of the most distinguished of that republic. My ancestors had been for many years counsellors and syndics, and my father had filled several public situations with honour and reputation. He was respected by all who knew him for his integrity and indefatigable attention to public business. He passed his younger days perpetually occupied by the affairs of his country; a variety of circumstances had prevented his marrying early, nor was it until the decline of life that he became a husband and the father of a family. As the circumstances of his marriage illustrate his character, I cannot refrain from relating them. One of his most intimate friends was a merchant who, from a flourishing state, fell, through numerous mischances, into poverty. This man, whose name was Beaufort, was of a proud and unbending disposition and could not bear to live in poverty and oblivion in the same country where he had formerly been distinguished for his rank and magnificence. Having paid his debts, therefore, in the most honourable manner, he retreated with his daughter to the town of Lucerne, where he lived unknown and in wretchedness. My father loved Beaufort with the truest friendship and was deeply grieved by his retreat in these unfortunate circumstances. He bitterly deplored the false pride which led his friend to a conduct so little worthy of the affection that united them. He lost no time in endeavouring to seek him out, with the hope of persuading him to begin the world again through his credit and assistance. Beaufort had taken effectual measures to conceal himself, and it was ten months before my father discovered his abode. Overjoyed at this discovery, he hastened to the house, which was situated in a mean street near the Reuss. But when he entered, misery and despair alone welcomed him. Beaufort had saved but a very small sum of money from the wreck of his fortunes, but it was sufficient to provide him with sustenance for some months, and in the meantime he hoped to procure some respectable employment in a merchant's house. The interval was, consequently, spent in inaction; his grief only became more deep and rankling when he had leisure for reflection, and at length it took so fast hold of his mind that at the end of three months he lay on a bed of sickness, incapable of any exertion. His daughter attended him with the greatest tenderness, but she saw with despair that their little fund was rapidly decreasing and that there was no other prospect of support. But Caroline Beaufort possessed a mind of an uncommon mould, and her courage rose to support her in her adversity. She procured plain work; she plaited straw and by various means contrived to earn a pittance scarcely sufficient to support life. Several months passed in this manner. Her father grew worse; her time was more entirely occupied in attending him; her means of subsistence decreased; and in the tenth month her father died in her arms, leaving her an orphan and a beggar. This last blow overcame her, and she knelt by Beaufort's coffin weeping bitterly, when my father entered the chamber. He came like a protecting spirit to the poor girl, who committed herself to his care; and after the interment of his friend he conducted her to Geneva and placed her under the protection of a relation. Two years after this event Caroline became his wife. There was a considerable difference between the ages of my parents, but this circumstance seemed to unite them only closer in bonds of devoted affection. There was a sense of justice in my father's upright mind which rendered it necessary that he should approve highly to love strongly. Perhaps during former years he had suffered from the late-discovered unworthiness of one beloved and so was disposed to set a greater value on tried worth. There was a show of gratitude and worship in his attachment to my mother, differing wholly from the doting fondness of age, for it was inspired by reverence for her virtues and a desire to be the means of, in some degree, recompensing her for the sorrows she had endured, but which gave inexpressible grace to his behaviour to her.";
