// ------------------------------------------------------------------ cached corpora (key = a TEXTS key, or 'mine' with the reader's own text)
const _corp = {};
export function corpus(key, mine = '') {
  const k = key === 'mine' ? 'mine:' + mine : key;
  if (!_corp[k]) { const tokens = tokenize(key === 'mine' ? mine : TEXTS[key]); _corp[k] = { tokens, rf: rankFreq(tokens), key }; }
  return _corp[k];
}
export const TEXT_OPTS = [...Object.keys(TEXT_SHORT).map((k) => ({ value: k, label: TEXT_SHORT[k] })), { value: 'mine', label: 'Your text' }];
/** About `n` log-spaced ranks in 1..m (all of 1..60), for plotting long tails. */
export function logRanks(m, n = 500) {
  const s = new Set(); for (let r = 1; r <= Math.min(60, m); r++) s.add(r);
  for (let k = 0; k < n; k++) s.add(Math.min(m, Math.max(1, Math.round(Math.exp(Math.log(m) * k / (n - 1))))));
  return [...s].sort((a, b) => a - b);
}
